(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pausanias-1-e", [{"sp": "HDR", "t": "Ἑλλάδος Περιήγησις"}, {"sp": "HDR", "t": "Βιβλίον Αʹ — Ἀττικά", "st": "1"}, {"sp": "N", "t": "τῆς ἠπείρου τῆς Ἑλληνικῆς κατὰ νήσους τὰς Κυκλάδας καὶ πέλαγος τὸ Αἰγαῖον ἄκρα Σούνιον πρόκειται γῆς τῆς Ἀττικῆς· καὶ λιμήν τε παραπλεύσαντι τὴν ἄκραν ἐστὶ καὶ ναὸς Ἀθηνᾶς Σουνιάδος ἐπὶ κορυφῇ τῆς ἄκρας. πλέοντι δὲ ἐς τὸ πρόσω Λαύριόν τέ ἐστιν, ἔνθα ποτὲ Ἀθηναίοις ἦν ἀργύρου μέταλλα, καὶ νῆσος ἔρημος οὐ μεγάλη Πατρόκλου καλουμένη· τεῖχος γὰρ ᾠκοδομήσατο ἐν αὐτῇ καὶ χάρακα ἐβάλετο Πάτροκλος, ὃς τριήρεσιν ὑπέπλει ναύαρχος Αἰγυπτίαις, ἃς Πτολεμαῖος ὁ ⟨Πτολεμαίου⟩ τοῦ Λάγου τιμωρεῖν ἔστειλεν Ἀθηναίοις, ὅτε σφίσιν Ἀντίγονος ὁ Δημητρίου στρατιᾷ τε αὐτὸς ἐσβεβληκὼς ἔφθειρε τὴν χώραν καὶ ναυσὶν ἅμα ἐκ θαλάσσης κατεῖργεν.", "st": "1.1"}, {"sp": "N", "t": "ὁ δὲ Πειραιεὺς δῆμος μὲν ἦν ἐκ παλαιοῦ, πρότερον δὲ πρὶν ἢ Θεμιστοκλῆς Ἀθηναίοις ἦρξεν ἐπίνειον οὐκ ἦν· Φαληρὸν δέ—ταύτῃ γὰρ ἐλάχιστον ἀπέχει τῆς πόλεως ἡ θάλασσα—, τοῦτό σφισιν ἐπίνειον ἦν, καὶ Μενεσθέα φασὶν αὐτόθεν ταῖς ναυσὶν ἐς Τροίαν ἀναχθῆναι καὶ τούτου πρότερον Θησέα δώσοντα Μίνῳ δίκας τῆς Ἀνδρόγεω τελευτῆς. Θεμιστοκλῆς δὲ ὡς ἦρξε—τοῖς τε γὰρ πλέουσιν ἐπιτηδειότερος ὁ Πειραιεὺς ἐφαίνετό οἱ προκεῖσθαι καὶ λιμένας τρεῖς ἀνθ’ ἑνὸς ἔχειν τοῦ Φαληροῖ—τοῦτό σφισιν ἐπίνειον εἶναι κατεσκευάσατο· καὶ νεὼς καὶ ἐς ἐμὲ ἦσαν οἶκοι καὶ πρὸς τῷ μεγίστῳ λιμένι τάφος Θεμιστοκλέους. φασὶ γὰρ μεταμελῆσαι τῶν ἐς Θεμιστοκλέα Ἀθηναίοις καὶ ὡς οἱ προσήκοντες τὰ ὀστᾶ κομίσαιεν ἐκ Μαγνησίας ἀνελόντες· φαίνονται δὲ οἱ παῖδες οἱ Θεμιστοκλέους καὶ κατελθόντες καὶ γραφὴν ἐς τὸν Παρθενῶνα ἀναθέντες, ἐν ᾗ Θεμιστοκλῆς ἐστι γεγραμμένος.", "st": "1.1"}, {"sp": "N", "t": "θέας δὲ ἄξιον τῶν ἐν Πειραιεῖ μάλιστα Ἀθηνᾶς ἐστι καὶ Διὸς τέμενος· χαλκοῦ μὲν ἀμφότερα τὰ ἀγάλματα, ἔχει δὲ ὁ μὲν σκῆπτρον καὶ Νίκην, ἡ δὲ Ἀθηνᾶ δόρυ. ἐνταῦθα Λεωσθένην, ὃς Ἀθηναίοις καὶ τοῖς πᾶσιν Ἕλλησιν ἡγούμενος Μακεδόνας ἔν τε Βοιωτοῖς ἐκράτησε μάχῃ καὶ αὖθις ἔξω Θερμοπυλῶν καὶ βιασάμενος ἐς Λάμιαν κατέκλεισε τὴν ἀπαντικρὺ τῆς Οἴτης, τοῦτον τὸν Λεωσθένην καὶ τοὺς παῖδας ἔγραψεν Ἀρκεσίλαος. ἔστι δὲ τῆς στοᾶς τῆς μακρᾶς, ἔνθα καθέστηκεν ἀγορὰ τοῖς ἐπὶ θαλάσσης—καὶ γὰρ τοῖς ἀπωτέρω τοῦ λιμένος ἐστὶν ἑτέρα—, τῆς δὲ ἐπὶ θαλάσσης στοᾶς ὄπισθεν ἑστᾶσι Ζεὺς καὶ Δῆμος, Λεωχάρους ἔργον. πρὸς δὲ τῇ θαλάσσῃ Κόνων ᾠκοδόμησεν Ἀφροδίτης ἱερόν, τριήρεις Λακεδαιμονίων κατεργασάμενος περὶ Κνίδον τὴν ἐν τῇ Καρικῇ χερρονήσῳ. Κνίδιοι γὰρ τιμῶσιν Ἀφροδίτην μάλιστα, καί σφισιν ἔστιν ἱερὰ τῆς θεοῦ· τὸ μὲν γὰρ ἀρχαιότατον Δωρίτιδος, μετὰ δὲ τὸ Ἀκραίας, νεώτατον δὲ ἣν Κνιδίαν οἱ πολλοί, Κνίδιοι δὲ αὐτοὶ καλοῦσιν Εὔπλοιαν.", "st": "1.1"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος Ἀθηναίοις ὁ μὲν ἐπὶ Μουνυχίᾳ λιμὴν καὶ Μουνυχίας ναὸς Ἀρτέμιδος, ὁ δὲ ἐπὶ Φαληρῷ, καθὰ καὶ πρότερον εἴρηταί μοι, καὶ πρὸς αὐτῷ Δήμητρος ἱερόν. ἐνταῦθα καὶ Σκιράδος Ἀθηνᾶς ναός ἐστι καὶ Διὸς ἀπωτέρω, βωμοὶ δὲ θεῶν τε ὀνομαζομένων Ἀγνώστων καὶ ἡρώων καὶ παίδων τῶν Θησέως καὶ Φαληροῦ· τοῦτον γὰρ τὸν Φαληρὸν Ἀθηναῖοι πλεῦσαι μετὰ Ἰάσονός φασιν ἐς Κόλχους. ἔστι δὲ καὶ Ἀνδρόγεω βωμὸς τοῦ Μίνω, καλεῖται δὲ Ἥρωος· Ἀνδρόγεω δὲ ὄντα ἴσασιν οἷς ἐστιν ἐπιμελὲς τὰ ἐγχώρια σαφέστερον ἄλλων ἐπίστασθαι.", "st": "1.1"}, {"sp": "N", "t": "ἀπέχει δὲ σταδίους εἴκοσιν ἄκρα Κωλιάς· ἐς ταύτην φθαρέντος τοῦ ναυτικοῦ τοῦ Μήδων κατήνεγκεν ὁ κλύδων τὰ ναυάγια. Κωλιάδος δέ ἐστιν ἐνταῦθα Ἀφροδίτης ἄγαλμα καὶ Γενετυλλίδες ὀνομαζόμεναι θεαί· δοκῶ δὲ καὶ Φωκαεῦσι τοῖς ἐν Ἰωνίᾳ θεάς, ἃς καλοῦσι Γενναΐδας, εἶναι ταῖς ἐπὶ Κωλιάδι τὰς αὐτάς. —ἔστι δὲ κατὰ τὴν ὁδὸν τὴν ἐς Ἀθήνας ἐκ Φαληροῦ ναὸς Ἥρας οὔτε θύρας ἔχων οὔτε ὄροφον· Μαρδόνιόν φασιν αὐτὸν ἐμπρῆσαι τὸν Γωβρύου. τὸ δὲ ἄγαλμα τὸ νῦν δή, καθὰ λέγουσιν, Ἀλκαμένους ἐστὶν ἔργον· οὐκ ἂν τοῦτό γε ὁ Μῆδος εἴη λελωβημένος.", "st": "1.1"}, {"sp": "N", "t": "ἐσελθόντων δὲ ἐς τὴν πόλιν ἐστὶν Ἀντιόπης μνῆμα Ἀμαζόνος. ταύτην τὴν Ἀντιόπην Πίνδαρος μέν φησιν ὑπὸ Πειρίθου καὶ Θησέως ἁρπασθῆναι, Τροιζηνίῳ δὲ Ἡγίᾳ τοιάδε ἐς αὐτὴν πεποίηται· Ἡρακλέα Θεμίσκυραν πολιορκοῦντα τὴν ἐπὶ Θερμώδοντι ἑλεῖν μὴ δύνασθαι, Θησέως δὲ ἐρασθεῖσαν Ἀντιόπην— στρατεῦσαι γὰρ ἅμα Ἡρακλεῖ καὶ Θησέα—παραδοῦναι [τε] τὸ χωρίον. τάδε μὲν Ἡγίας πεποίηκεν· Ἀθηναῖοι δέ φασιν, ἐπεί τε ἦλθον Ἀμαζόνες, Ἀντιόπην μὲν ὑπὸ Μολπαδίας τοξευθῆναι, Μολπαδίαν δὲ ἀποθανεῖν ὑπὸ Θησέως. καὶ μνῆμά ἐστι καὶ Μολπαδίας Ἀθηναίοις.", "st": "1.2"}, {"sp": "N", "t": "ἀνιόντων δὲ ἐκ Πειραιῶς ἐρείπια τῶν τειχῶν ἐστιν, ἃ Κόνων ὕστερον τῆς πρὸς Κνίδῳ ναυμαχίας ἀνέστησε· τὰ γὰρ Θεμιστοκλέους μετὰ τὴν ἀναχώρησιν οἰκοδομηθέντα τὴν Μήδων ἐπὶ τῆς ἀρχῆς καθῃρέθη τῶν τριάκοντα ὀνομαζομένων. εἰσὶ δὲ τάφοι κατὰ τὴν ὁδὸν γνωριμώτατοι Μενάνδρου τοῦ Διοπείθους καὶ μνῆμα Εὐριπίδου κενόν· τέθαπται δὲ Εὐριπίδης ἐν Μακεδονίᾳ παρὰ τὸν βασιλέα ἐλθὼν Ἀρχέλαον, ὁ δέ οἱ τοῦ θανάτου τρόπος—πολλοῖς γάρ ἐστιν εἰρημένος—ἐχέτω καθὰ λέγουσιν.", "st": "1.2"}, {"sp": "N", "t": "συνῆσαν δὲ ἄρα καὶ τότε τοῖς βασιλεῦσι ποιηταὶ καὶ πρότερον ἔτι καὶ Πολυκράτει Σάμου τυραννοῦντι Ἀνακρέων παρῆν καὶ ἐς Συρακούσας πρὸς Ἱέρωνα Αἰσχύλος καὶ Σιμωνίδης ἐστάλησαν· Διονυσίῳ δέ, ὃς ὕστερον ἐτυράννησεν ἐν Σικελίᾳ, Φιλόξενος παρῆν καὶ Ἀντιγόνῳ Μακεδόνων ἄρχοντι Ἀνταγόρας Ῥόδιος καὶ Σολεὺς Ἄρατος. Ἡσίοδος δὲ καὶ Ὅμηρος ἢ συγγενέσθαι βασιλεῦσιν ἠτύχησαν ἢ καὶ ἑκόντες ὠλιγώρησαν, ὁ μὲν ἀγροικίᾳ καὶ ὄκνῳ πλάνης, Ὅμηρος δὲ ἀποδημήσας ἐπὶ μακρότατον καὶ τὴν ὠφέλειαν ⟨τὴν⟩ ἐς χρήματα παρὰ τῶν δυνατῶν ὑστέραν θέμενος τῆς παρὰ τοῖς πολλοῖς δόξης, ἐπεὶ καὶ Ὁμήρῳ πεποιημένα ἐστὶν Ἀλκίνῳ παρεῖναι Δημόδοκον καὶ ὡς Ἀγαμέμνων καταλείποι τινὰ παρὰ τῇ γυναικὶ ποιητήν. —ἔστι δὲ τάφος οὐ πόρρω τῶν πυλῶν, ἐπίθημα ἔχων στρατιώτην ἵππῳ παρεστηκότα· ὅντινα μέν, οὐκ οἶδα, Πραξιτέλης δὲ καὶ τὸν ἵππον καὶ τὸν στρατιώτην ἐποίησεν.", "st": "1.2"}, {"sp": "N", "t": "ἐσελθόντων δὲ ἐς τὴν πόλιν οἰκοδόμημα ἐς παρασκευήν ἐστι τῶν πομπῶν, ἃς πέμπουσι τὰς μὲν ἀνὰ πᾶν ἔτος, τὰς δὲ καὶ χρόνον διαλείποντες. καὶ πλησίον ναός ἐστι Δήμητρος, ἀγάλματα δὲ αὐτή τε καὶ ἡ παῖς καὶ δᾷδα ἔχων Ἴακχος· γέγραπται δὲ ἐπὶ τῷ τοίχῳ γράμμασιν Ἀττικοῖς ἔργα εἶναι Πραξιτέλους. τοῦ ναοῦ δὲ οὐ πόρρω Ποσειδῶν ἐστιν ἐφ’ ἵππου, δόρυ ἀφιεὶς ἐπὶ γίγαντα Πολυβώτην, ἐς ὃν Κῴοις ὁ μῦθος ⟨ὁ⟩ περὶ τῆς ἄκρας ἔχει τῆς Χελώνης· τὸ δὲ ἐπίγραμμα τὸ ἐφ’ ἡμῶν τὴν εἰκόνα ἄλλῳ δίδωσι καὶ οὐ Ποσειδῶνι. στοαὶ δέ εἰσιν ἀπὸ τῶν πυλῶν ἐς τὸν Κεραμεικὸν καὶ εἰκόνες πρὸ αὐτῶν χαλκαῖ καὶ γυναικῶν καὶ ἀνδρῶν, ὅσοις τι ὑπῆρχεν [ὧν τις λόγος] ἐς δόξαν.", "st": "1.2"}, {"sp": "N", "t": "ἡ δὲ ἑτέρα τῶν στοῶν ἔχει μὲν ἱερὰ θεῶν, ἔχει δὲ γυμνάσιον Ἑρμοῦ καλούμενον· ἔστι δὲ ἐν αὐτῇ Πουλυτίωνος οἰκία, καθ’ ἣν παρὰ τὴν ἐν Ἐλευσῖνι δρᾶσαι τελετὴν Ἀθηναίων φασὶν οὐ τοὺς ἀφανεστάτους· ἐπ’ ἐμοῦ δὲ ἀνεῖτο Διονύσῳ. Διόνυσον δὲ τοῦτον καλοῦσι Μελπόμενον ἐπὶ λόγῳ τοιῷδε ἐφ’ ὁποίῳ περ Ἀπόλλωνα Μουσηγέτην. ἐνταῦθά ἐστιν Ἀθηνᾶς ἄγαλμα Παιωνίας καὶ Διὸς καὶ Μνημοσύνης καὶ Μουσῶν, Ἀπόλλων τε ἀνάθημα καὶ ἔργον Εὐβουλίδου, καὶ δαίμων τῶν ἀμφὶ Διόνυσον Ἄκρατος· πρόσωπόν ἐστίν οἱ μόνον ἐνῳκοδομημένον τοίχῳ. μετὰ δὲ τὸ τοῦ Διονύσου τέμενός ἐστιν οἴκημα ἀγάλματα ἔχον ἐκ πηλοῦ, βασιλεὺς Ἀθηναίων Ἀμφικτύων ἄλλους τε θεοὺς ἑστιῶν καὶ Διόνυσον. ἐνταῦθα καὶ Πήγασός ἐστιν Ἐλευθερεύς, ὃς Ἀθηναίοις ⟨τὸν⟩ θεὸν ἐσήγαγε· συνεπελάβετο δέ οἱ τὸ ἐν Δελφοῖς μαντεῖον ἀναμνῆσαν τὴν ἐπὶ Ἰκαρίου ποτὲ ἐπιδημίαν τοῦ θεοῦ.", "st": "1.2"}, {"sp": "N", "t": "τὴν δὲ βασιλείαν Ἀμφικτύων ἔσχεν οὕτως. Ἀκταῖον λέγουσιν ἐν τῇ νῦν Ἀττικῇ βασιλεῦσαι πρῶτον· ἀποθανόντος δὲ Ἀκταίου Κέκροψ ἐκδέχεται τὴν ἀρχὴν θυγατρὶ συνοικῶν Ἀκταίου, καί οἱ γίνονται θυγατέρες μὲν Ἕρση καὶ Ἄγλαυρος καὶ Πάνδροσος, υἱὸς δὲ Ἐρυσίχθων· οὗτος οὐκ ἐβασίλευσεν Ἀθηναίων, ἀλλά οἱ τοῦ πατρὸς ζῶντος τελευτῆσαι συνέβη, καὶ τὴν ἀρχὴν τὴν Κέκροπος Κραναὸς ἐξεδέξατο, Ἀθηναίων δυνάμει προύχων. Κραναῷ δὲ θυγατέρας καὶ ἄλλας καὶ Ἀτθίδα γενέσθαι λέγουσιν· ἀπὸ ταύτης ὀνομάζουσιν Ἀττικὴν τὴν χώραν, πρότερον καλουμένην Ἀκταίαν. Κραναῷ δὲ Ἀμφικτύων ἐπαναστάς, θυγατέρα ὅμως ἔχων αὐτοῦ, παύει τῆς ἀρχῆς· καὶ αὐτὸς ὕστερον ὑπὸ Ἐριχθονίου καὶ τῶν συνεπαναστάντων ἐκπίπτει· πατέρα δὲ Ἐριχθονίῳ λέγουσιν ἀνθρώπων μὲν οὐδένα εἶναι, γονέας δὲ Ἥφαιστον καὶ Γῆν.", "st": "1.2"}, {"sp": "N", "t": "τὸ δὲ χωρίον ὁ Κεραμεικὸς τὸ μὲν ὄνομα ἔχει ἀπὸ ἥρωος Κεράμου, Διονύσου τε εἶναι καὶ Ἀριάδνης καὶ τούτου λεγομένου· πρώτη δέ ἐστιν ἐν δεξιᾷ καλουμένη στοὰ βασίλειος, ἔνθα καθίζει βασιλεὺς ἐνιαυσίαν ἄρχων ἀρχὴν καλουμένην βασιλείαν. ταύτης ἔπεστι τῷ κεράμῳ τῆς στοᾶς ἀγάλματα ὀπτῆς γῆς, ἀφιεὶς Θησεὺς ἐς θάλασσαν Σκίρωνα καὶ φέρουσα Ἡμέρα Κέφαλον, ὃν κάλλιστον γενόμενόν φασιν ὑπὸ Ἡμέρας ἐρασθείσης ἁρπασθῆναι· καί οἱ παῖδα γενέσθαι Φαέθοντα, ⟨ὃν ὕστερον ἡ Ἀφροδίτη ἥρπασε⟩ … καὶ φύλακα ἐποίησε τοῦ ναοῦ. ταῦτα ἄλλοι τε καὶ Ἡσίοδος εἴρηκεν ἐν ἔπεσι τοῖς ἐς τὰς γυναῖκας.", "st": "1.3"}, {"sp": "N", "t": "πλησίον δὲ τῆς στοᾶς Κόνων ἕστηκε καὶ Τιμόθεος υἱὸς Κόνωνος καὶ βασιλεὺς Κυπρίων Εὐαγόρας, ὃς καὶ τὰς τριήρεις τὰς Φοινίσσας ἔπραξε παρὰ βασιλέως Ἀρταξέρξου δοθῆναι Κόνωνι· ἔπραξε δὲ ὡς Ἀθηναῖος καὶ τὸ ἀνέκαθεν ἐκ Σαλαμῖνος, ἐπεὶ καὶ γενεαλογῶν ἐς προγόνους ἀνέβαινε Τεῦκρον καὶ Κινύρου θυγατέρα. ἐνταῦθα ἕστηκε Ζεὺς ὀνομαζόμενος Ἐλευθέριος καὶ βασιλεὺς Ἀδριανός, ἐς ἄλλους τε ὧν ἦρχεν εὐεργεσίας καὶ ἐς τὴν πόλιν μάλιστα ἀποδειξάμενος τὴν Ἀθηναίων.", "st": "1.3"}, {"sp": "N", "t": "στοὰ δὲ ὄπισθεν ᾠκοδόμηται γραφὰς ἔχουσα θεοὺς ⟨τοὺς⟩ δώδεκα καλουμένους· ἐπὶ δὲ τῷ τοίχῳ τῷ πέραν Θησεύς ἐστι γεγραμμένος καὶ Δημοκρατία τε καὶ Δῆμος. δηλοῖ δὲ ἡ γραφὴ Θησέα εἶναι τὸν καταστήσαντα Ἀθηναίοις ἐξ ἴσου πολιτεύεσθαι· κεχώρηκε δὲ φήμη καὶ ἄλλως ἐς τοὺς πολλούς, ὡς Θησεὺς παραδοίη τὰ πράγματα τῷ δήμῳ καὶ ὡς ἐξ ἐκείνου δημοκρατούμενοι διαμείναιεν, πρὶν ἢ Πεισίστρατος ἐτυράννησεν ἐπαναστάς. λέγεται μὲν δὴ καὶ ἄλλα οὐκ ἀληθῆ παρὰ τοῖς πολλοῖς οἷα ἱστορίας ἀνηκόοις οὖσι καὶ ὁπόσα ἤκουον εὐθὺς ἐκ παίδων ἔν τε χοροῖς καὶ τραγῳδίαις πιστὰ ἡγουμένοις, λέγεται δὲ καὶ ἐς τὸν Θησέα, ὃς αὐτός τε ἐβασίλευσε καὶ ὕστερον Μενεσθέως τελευτήσαντος καὶ ἐς τετάρτην οἱ Θησεῖδαι γενεὰν διέμειναν ἄρχοντες. εἰ δέ μοι γενεαλογεῖν ἤρεσκε, καὶ τοὺς ἀπὸ Μελάνθου βασιλεύσαντας ἐς Κλείδικον τὸν Αἰσιμίδου καὶ τούτους ἂν ἀπηριθμησάμην.", "st": "1.3"}, {"sp": "N", "t": "ἐνταῦθά ἐστι γεγραμμένον καὶ τὸ περὶ Μαντίνειαν Ἀθηναίων ἔργον, οἳ βοηθήσοντες Λακεδαιμονίοις ἐπέμφθησαν. συνέγραψαν δὲ ἄλλοι τε καὶ Ξενοφῶν τὸν πάντα πόλεμον, κατάληψίν τε τῆς Καδμείας καὶ τὸ πταῖσμα Λακεδαιμονίων ⟨τὸ⟩ ἐν Λεύκτροις καὶ ὡς ἐς Πελοπόννησον ἐσέβαλον Βοιωτοὶ καὶ τὴν συμμαχίαν Λακεδαιμονίοις τὴν παρ’ Ἀθηναίων ἐλθοῦσαν· ἐν δὲ τῇ γραφῇ τῶν ἱππέων ἐστὶ μάχη, ἐν ᾗ γνωριμώτατοι Γρύλος τε ὁ Ξενοφῶντος ἐν τοῖς Ἀθηναίοις καὶ κατὰ τὴν ἵππον τὴν Βοιωτίαν Ἐπαμινώνδας ὁ Θηβαῖος. ταύτας τὰς γραφὰς Εὐφράνωρ ἔγραψεν Ἀθηναίοις καὶ πλησίον ἐποίησεν ἐν τῷ ναῷ τὸν Ἀπόλλωνα Πατρῷον ἐπίκλησιν· πρὸ δὲ τοῦ νεὼ τὸν μὲν Λεωχάρης, ὃν δὲ καλοῦσιν Ἀλεξίκακον Κάλαμις ἐποίησε. τὸ δὲ ὄνομα τῷ θεῷ γενέσθαι λέγουσιν, ὅτι τὴν λοιμώδη σφίσι νόσον ὁμοῦ τῷ Πελοποννησίων πολέμῳ πιέζουσαν κατὰ μάντευμα ἔπαυσε⟨ν ἐκ⟩ Δελφῶν.", "st": "1.3"}, {"sp": "N", "t": "ᾠκοδόμηται δὲ καὶ Μητρὸς θεῶν ἱερόν, ἣν Φειδίας εἰργάσατο, καὶ πλησίον τῶν πεντακοσίων καλουμένων βουλευτήριον, οἳ βουλεύουσιν ἐνιαυτὸν Ἀθηναίοις· Βουλαίου δὲ ἐν αὐτῷ κεῖται ξόανον Διὸς καὶ Ἀπόλλων τέχνη Πεισίου καὶ Δῆμος ἔργον Λύσωνος. τοὺς δὲ θεσμοθέτας ἔγραψε Πρωτογένης Καύνιος, Ὀλβιάδης δὲ Κάλλιππον, ὃς Ἀθηναίους ἐς Θερμοπύλας ἤγαγε φυλάξοντας τὴν ἐς τὴν Ἑλλάδα Γαλατῶν ἐσβολήν.", "st": "1.3"}, {"sp": "N", "t": "οἱ δὲ Γαλάται οὗτοι νέμονται τῆς Εὐρώπης τὰ ἔσχατα ἐπὶ θαλάσσῃ πολλῇ καὶ ἐς τὰ πέρατα οὐ πλωίμῳ, παρέχεται δὲ ἄμπωτιν καὶ ῥαχίαν καὶ θηρία οὐδὲν ἐοικότα τοῖς ἐν θαλάσσῃ τῇ λοιπῇ· καί σφισι διὰ τῆς χώρας ῥεῖ ποταμὸς Ἠριδανός, ἐφ’ ᾧ τὰς θυγατέρας τὰς Ἡλίου ὀδύρεσθαι νομίζουσι τὸ περὶ τὸν Φαέθοντα τὸν ἀδελφὸν πάθος. ὀψὲ δέ ποτε αὐτοὺς καλεῖσθαι Γαλάτας ἐξενίκησεν· Κελτοὶ γὰρ κατά τε σφᾶς τὸ ἀρχαῖον καὶ παρὰ τοῖς ἄλλοις ὠνομάζοντο. συλλεγεῖσα δέ σφισι στρατιὰ τρέπεται τὴν ἐπὶ Ἰονίου, καὶ τό τε Ἰλλυριῶν ἔθνος καὶ πᾶν ὅσον ἄχρι Μακεδόνων ᾤκει καὶ Μακεδόνας αὐτοὺς ἀναστάτους ἐποίησε Θεσσαλίαν τε ἐπέδραμε. καὶ ὡς ἐγγὺς Θερμοπυλῶν ἐγίνοντο, ἐνταῦθα οἱ πολλοὶ τῶν Ἑλλήνων ἐς τὴν ἔφοδον ἡσύχαζον τῶν βαρβάρων, ἅτε ὑπὸ Ἀλεξάνδρου μεγάλως καὶ Φιλίππου κακωθέντες πρότερον· καθεῖλε δὲ καὶ Ἀντίπατρος καὶ Κάσσανδρος ὕστερον τὸ Ἑλληνικόν, ὥστε ἕκαστοι δι’ ἀσθένειαν οὐδὲν αἰσχρὸν ἐνόμιζον ἀπεῖναι τὸ κατὰ σφᾶς τῆς βοηθείας.", "st": "1.4"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ μάλιστα μὲν τῶν Ἑλλήνων ἀπειρήκεσαν μήκει τοῦ Μακεδονικοῦ πολέμου καὶ προσπταίοντες τὰ πολλὰ ἐν ταῖς μάχαις, ἐξιέναι δὲ ὅμως ὥρμηντο ἐς τὰς Θερμοπύλας σὺν τοῖς ἐλθοῦσι τῶν Ἑλλήνων, ἑλόμενοι σφίσι τὸν Κάλλιππον τοῦτον ἡγεῖσθαι. καταλαβόντες δὲ ᾗ στενώτατον ἦν, τῆς ἐσόδου τῆς ἐς τὴν Ἑλλάδα εἶργον τοὺς βαρβάρους· ἀνευρόντες δὲ οἱ Κελτοὶ τὴν ἀτραπόν, ἣν καὶ Μήδοις ποτὲ Ἐφιάλτης ἡγήσατο ὁ Τραχίνιος, καὶ βιασάμενοι Φωκέων τοὺς τεταγμένους ἐπ’ αὐτῇ λανθάνουσι τοὺς Ἕλληνας ὑπερβαλόντες τὴν Οἴτην.", "st": "1.4"}, {"sp": "N", "t": "ἔνθα δὴ πλείστου παρέσχοντο αὑτοὺς Ἀθηναῖοι τοῖς Ἕλλησιν ἀξίους, ἀμφοτέρωθεν ὡς ἐκυκλώθησαν ἀμυνόμενοι τοὺς βαρβάρους· οἱ δέ σφισιν ἐπὶ τῶν νεῶν μάλιστα ἐταλαιπώρουν ἅτε τοῦ κόλπου τοῦ Λαμιακοῦ τέλματος πρὸς ταῖς Θερμοπύλαις ὄντος· αἴτιον δὲ ἐμοὶ δοκεῖν τὸ ὕδωρ ταύτῃ τὸ θερμὸν ἐκρέον ἐς τὴν θάλασσαν. μείζονα οὖν εἶχον οὗτοι πόνον· ἀναλαβόντες γὰρ ἐπὶ τὰ καταστρώματα τοὺς Ἕλληνας ναυσὶν ὑπό τε ὅπλων βαρείαις καὶ ἀνδρῶν ἐβιάζοντο κατὰ τοῦ πηλοῦ πλεῖν.", "st": "1.4"}, {"sp": "N", "t": "οὗτοι μὲν δὴ τοὺς Ἕλληνας τρόπον τὸν εἰρημένον ἔσωζον, οἱ δὲ Γαλάται Πυλῶν τε ἐντὸς ἦσαν καὶ τὰ πολίσματα ἑλεῖν ἐν οὐδενὶ τὰ λοιπὰ ποιησάμενοι Δελφοὺς καὶ τὰ χρήματα. τοῦ θεοῦ διαρπάσαι μάλιστα εἶχον σπουδήν. καί σφισιν αὐτοί τε Δελφοὶ καὶ Φωκέων ἀντετάχθησαν οἱ τὰς πόλεις περὶ τὸν Παρνασσὸν οἰκοῦντες, ἀφίκετο δὲ καὶ δύναμις Αἰτωλῶν· τὸ γὰρ Αἰτωλικὸν προεῖχεν ἀκμῇ νεότητος τὸν χρόνον τοῦτον. ὡς δὲ ἐς χεῖρας συνῄεσαν, ἐνταῦθα κεραυνοί τε ἐφέροντο ἐς τοὺς Γαλάτας καὶ ἀπορραγεῖσαι πέτραι τοῦ Παρνασσοῦ, δείματά τε ἄνδρες ἐφίσταντο ὁπλῖται τοῖς βαρβάροις· τούτων τοὺς μὲν ἐξ Ὑπερβορέων λέγουσιν ἐλθεῖν, Ὑπέροχον καὶ Ἀμάδοκον, τὸν δὲ τρίτον Πύρρον εἶναι τὸν Ἀχιλλέως· ἐναγίζουσι δὲ ἀπὸ ταύτης Δελφοὶ τῆς συμμαχίας Πύρρῳ, πρότερον ἔχοντες ἅτε ἀνδρὸς πολεμίου καὶ τὸ μνῆμα ἐν ἀτιμίᾳ.", "st": "1.4"}, {"sp": "N", "t": "Γαλατῶν δὲ οἱ πολλοὶ ναυσὶν ἐς τὴν Ἀσίαν διαβάντες τὰ παραθαλάσσια αὐτῆς ἐλεηλάτουν· χρόνῳ δὲ ὕστερον οἱ Πέργαμον ἔχοντες, πάλαι δὲ Τευθρανίαν καλουμένην, ἐς ταύτην Γαλάτας ἐλαύνουσιν ἀπὸ θαλάσσης. οὗτοι μὲν δὴ τὴν ἐκτὸς Σαγγαρίου χώραν ἔσχον Ἄγκυραν πόλιν ἑλόντες Φρυγῶν, ἣν Μίδας ὁ Γορδίου πρότερον ᾤκισεν—ἄγκυρα δέ, ἣν ὁ Μίδας ἀνεῦρεν, ἦν ἔτι καὶ ἐς ἐμὲ ἐν ἱερῷ Διὸς καὶ κρήνη Μίδου καλουμένη· ταύτην οἴνῳ κεράσαι Μίδαν φασὶν ἐπὶ τὴν θήραν τοῦ Σιληνοῦ—, ταύτην τε δὴ τὴν Ἄγκυραν εἷλον καὶ Πεσσινοῦντα ⟨τὴν⟩ ὑπὸ τὸ ὄρος τὴν Ἄγδιστιν, ἔνθα καὶ τὸν Ἄττην τεθάφθαι λέγουσι.", "st": "1.4"}, {"sp": "N", "t": "Περγαμηνοῖς δὲ ἔστι μὲν σκῦλα ἀπὸ Γαλατῶν, ἔστι δὲ γραφὴ τὸ ἔργον ⟨τὸ⟩ πρὸς Γαλάτας ἔχουσα. ἣν δὲ νέμονται οἱ Περγαμηνοί, Καβείρων ἱεράν φασιν εἶναι τὸ ἀρχαῖον· αὐτοὶ δὲ Ἀρκάδες ἐθέλουσιν εἶναι τῶν ὁμοῦ Τηλέφῳ διαβάντων ἐς τὴν Ἀσίαν. πολέμων δὲ τῶν μὲν ἄλλων, εἰ δή τινας ἐπολέμησαν, οὐκ ἐς ἅπαντας κεχώρηκεν ἡ φήμη· τρία δὲ γνωριμώτατα ἐξείργασταί σφισι, τῆς τε Ἀσίας ἀρχὴ τῆς κάτω καὶ ἡ Γαλατῶν ἀπ’ αὐτῆς ἀναχώρησις καὶ τὸ ἐς τοὺς σὺν Ἀγαμέμνονι Τηλέφου τόλμημα, ὅτε Ἕλληνες ἁμαρτόντες Ἰλίου τὸ πεδίον ἐλεηλάτουν τὸ Μήιον ὡς γῆν [τὴν] Τρῳάδα. ἐπάνειμι δὲ ἐς τὴν ἀρχὴν ὅθεν ἐξέβην τοῦ λόγου.", "st": "1.4"}, {"sp": "N", "t": "τοῦ βουλευτηρίου τῶν πεντακοσίων πλησίον Θόλος ἐστὶ καλουμένη, καὶ θύουσί τε ἐνταῦθα οἱ πρυτάνεις καί τινα καὶ ἀργύρου πεποιημένα ἐστὶν ἀγάλματα οὐ μεγάλα. ἀνωτέρω δὲ ἀνδριάντες ἑστήκασιν ἡρώων, ἀφ’ ὧν Ἀθηναίοις ὕστερον τὰ ὀνόματα ἔσχον αἱ φυλαί· ὅστις δὲ κατεστήσατο δέκα ἀντὶ τεσσάρων φυλὰς εἶναι καὶ μετέθετό σφισι τὰ ὀνόματα ἀντὶ τῶν ἀρχαίων, Ἡροδότῳ καὶ ταῦτά ἐστιν εἰρημένα.", "st": "1.5"}, {"sp": "N", "t": "τῶν δὲ ἐπωνύμων—καλοῦσι γὰρ οὕτω σφᾶς—ἔστι μὲν Ἱπποθόων Ποσειδῶνος καὶ Ἀλόπης θυγατρὸς Κερκυόνος, ἔστι δὲ Ἀντίοχος τῶν παίδων τῶν Ἡρακλέους, γενόμενος ἐκ Μήδας Ἡρακλεῖ τῆς Φύλαντος, καὶ τρίτος Αἴας ὁ Τελαμῶνος, ἐκ δὲ Ἀθηναίων Λεώς· δοῦναι δὲ ἐπὶ σωτηρίᾳ λέγεται κοινῇ τὰς θυγατέρας τοῦ θεοῦ χρήσαντος. Ἐρεχθεύς τέ ἐστιν ἐν τοῖς ἐπωνύμοις, ὃς ἐνίκησεν Ἐλευσινίους μάχῃ καὶ τὸν ἡγούμενον ἀπέκτεινεν Ἰμμάραδον τὸν Εὐμόλπου· Αἰγεύς τέ ἐστι καὶ Οἰνεὺς Πανδίονος υἱὸς νόθος καὶ τῶν Θησέως παίδων Ἀκάμας.", "st": "1.5"}, {"sp": "N", "t": "Κέκροπα δὲ καὶ Πανδίονα—εἶδον γὰρ καὶ τούτων ἐν τοῖς ἐπωνύμοις εἰκόνας—οὐκ οἶδα οὓς ἄγουσιν ἐν τιμῇ· πρότερός τε γὰρ ἦρξε Κέκροψ, ὃς τὴν Ἀκταίου θυγατέρα ἔσχε, καὶ ὕστερος, ὃς δὴ καὶ μετῴκησεν ἐς Εὔβοιαν, Ἐρεχθέως υἱὸς τοῦ Πανδίονος τοῦ Ἐριχθονίου. καὶ δὴ καὶ Πανδίων ἐβασίλευσεν ὅ τε Ἐριχθονίου καὶ ὁ Κέκροπος τοῦ δευτέρου· τοῦτον Μητιονίδαι τῆς ἀρχῆς ἐξελαύνουσι, καί οἱ φυγόντι ἐς Μέγαρα—θυγατέρα γὰρ εἶχε Πύλα τοῦ βασιλεύσαντος ἐν Μεγάροις—συνεκπίπτουσιν οἱ παῖδες. καὶ Πανδίονα μὲν αὐτοῦ λέγεται νοσήσαντα ἀποθανεῖν, καί οἱ πρὸς θαλάσσῃ μνῆμά ἐστιν ἐν τῇ Μεγαρίδι ἐν Ἀθηνᾶς Αἰθυίας καλουμένῳ σκοπέλῳ·", "st": "1.5"}, {"sp": "N", "t": "οἱ δὲ παῖδες κατίασί τε ἐκ τῶν Μεγάρων ἐκβαλόντες Μητιονίδας, καὶ τὴν ἀρχὴν τῶν Ἀθηναίων Αἰγεὺς πρεσβύτατος ὢν ἔσχεν. θυγατέρας δὲ οὐ σὺν ἀγαθῷ δαίμονι ἔθρεψεν ὁ Πανδίων, οὐδέ οἱ τιμωροὶ παῖδες ἀπ’ αὐτῶν ἐλείφθησαν· καίτοι δυνάμεώς γε ἕνεκα πρὸς τὸν Θρᾷκα τὸ κῆδος ἐποιήσατο. ἀλλ’ οὐδεὶς πόρος ἐστὶν ἀνθρώπῳ παραβῆναι τὸ καθῆκον ἐκ τοῦ θεοῦ· λέγουσιν ὡς Τηρεὺς συνοικῶν Πρόκνῃ Φιλομήλαν ᾔσχυνεν, οὐ κατὰ νόμον δράσας τὸν Ἑλλήνων, καὶ τὸ σῶμα ἔτι λωβησάμενος τῇ παιδὶ ἤγαγεν ἐς ἀνάγκην δίκης τὰς γυναῖκας. Πανδίονι δὲ καὶ ἄλλος ἀνδριάς ἐστιν ἐν ἀκροπόλει θέας ἄξιος.", "st": "1.5"}, {"sp": "N", "t": "οἵδε μέν εἰσιν Ἀθηναίοις ἐπώνυμοι τῶν ἀρχαίων· ὕστερον δὲ καὶ ἀπὸ τῶνδε φυλὰς ἔχουσιν, Ἀττάλου τοῦ Μυσοῦ καὶ Πτολεμαίου τοῦ Αἰγυπτίου καὶ κατ’ ἐμὲ ἤδη βασιλέως Ἀδριανοῦ τῆς τε ἐς τὸ θεῖον τιμῆς ἐπὶ πλεῖστον ἐλθόντος καὶ τῶν ἀρχομένων ἐς εὐδαιμονίαν τὰ μέγιστα ἑκάστοις παρασχομένου. καὶ ἐς μὲν πόλεμον οὐδένα ἑκούσιος κατέστη, Ἑβραίους δὲ τοὺς ὑπὲρ Σύρων ἐχειρώσατο ἀποστάντας· ὁπόσα δὲ θεῶν ἱερὰ τὰ μὲν ᾠκοδόμησεν ἐξ ἀρχῆς, τὰ δὲ καὶ ἐπεκόσμησεν ἀναθήμασι καὶ κατασκευαῖς ἢ δωρεὰς πόλεσιν ἔδωκεν Ἑλληνίσι, τὰς δὲ καὶ τῶν βαρβάρων τοῖς δεηθεῖσιν, ἔστιν οἱ πάντα γεγραμμένα Ἀθήνῃσιν ἐν τῷ κοινῷ τῶν θεῶν ἱερῷ.", "st": "1.5"}, {"sp": "N", "t": "τὰ δὲ ἐς Ἄτταλον καὶ Πτολεμαῖον ἡλικίᾳ τε ἦν ἀρχαιότερα, ὡς μὴ μένειν ἔτι τὴν φήμην αὐτῶν, καὶ οἱ συγγενόμενοι τοῖς βασιλεῦσιν ἐπὶ συγγραφῇ τῶν ἔργων καὶ πρότερον ἔτι ἠμελήθησαν· τούτων ἕνεκά μοι καὶ τὰ τῶνδε ἐπῆλθε δηλῶσαι ἔργα τε ὁποῖα ἔπραξαν καὶ ὡς ἐς τοὺς πατέρας αὐτῶν περιεχώρησεν Αἰγύπτου καὶ ἡ Μυσῶν καὶ τῶν προσοίκων ἀρχή.", "st": "1.6"}, {"sp": "N", "t": "Πτολεμαῖον Μακεδόνες Φιλίππου παῖδα εἶναι τοῦ Ἀμύντου, λόγῳ δὲ Λάγου νομίζουσι· τὴν γάρ οἱ μητέρα ἔχουσαν ἐν γαστρὶ δοθῆναι γυναῖκα ὑπὸ Φιλίππου Λάγῳ. Πτολεμαῖον δὲ λέγουσιν ἄλλα τε ἐν τῇ Ἀσίᾳ λαμπρὰ ἀποδείξασθαι καὶ Ἀλεξάνδρῳ κινδύνου ξυμβάντος ἐν Ὀξυδράκαις μάλιστά οἱ τῶν ἑταίρων ἀμῦναι. τελευτήσαντος δὲ Ἀλεξάνδρου τοῖς ἐς Ἀριδαῖον τὸν Φιλίππου τὴν πᾶσαν ἄγουσιν ἀρχὴν ἀντιστὰς αὐτὸς μάλιστα ἐγένετο ἐς τὰς βασιλείας αἴτιος τὰ ἔθνη νεμηθῆναι.", "st": "1.6"}, {"sp": "N", "t": "αὐτὸς δὲ ἐς Αἴγυπτον διαβὰς Κλεομένην τε ἀπέκτεινεν, ὃν σατραπεύειν Αἰγύπτου κατέστησεν Ἀλέξανδρος, Περδίκκᾳ νομίζων εὔνουν καὶ δι’ αὐτὸ οὐ πιστὸν αὑτῷ, καὶ Μακεδόνων τοὺς ταχθέντας τὸν Ἀλεξάνδρου νεκρὸν ἐς Αἰγὰς κομίζειν ἀνέπεισεν αὑτῷ παραδοῦναι· καὶ τὸν μὲν νόμῳ τῷ Μακεδόνων ἔθαπτεν ἐν Μέμφει, οἷα δὲ ἐπιστάμενος πολεμήσοντα Περδίκκαν Αἴγυπτον εἶχεν ἐν φυλακῇ. Περδίκκας δὲ ἐς μὲν τὸ εὐπρεπὲς τῆς στρατείας ἐπήγετο Ἀριδαῖον τὸν Φιλίππου καὶ παῖδα Ἀλέξανδρον ἐκ Ῥωξάνης τῆς Ὀξυάρτου γεγονότα καὶ Ἀλεξάνδρου, τῷ δὲ ἔργῳ Πτολεμαῖον ἐπεβούλευεν ἀφελέσθαι τὴν ἐν Αἰγύπτῳ βασιλείαν· ἐξωσθεὶς δὲ Αἰγύπτου καὶ τὰ ἐς πόλεμον ἔτι οὐχ ὁμοίως θαυμαζόμενος, διαβεβλημένος δὲ καὶ ἄλλως ἐς τοὺς Μακεδόνας, ἀπέθανεν ὑπὸ τῶν σωματοφυλάκων.", "st": "1.6"}, {"sp": "N", "t": "Πτολεμαῖον δὲ αὐτίκα ἐς τὰ πράγματα ὁ Περδίκκου θάνατος ἐπέστησε· καὶ τοῦτο μὲν Σύρους καὶ Φοινίκην εἷλε, τοῦτο δὲ ἐκπεσόντα ὑπὸ Ἀντιγόνου καὶ φεύγοντα ὑπεδέξατο Σέλευκον τὸν Ἀντιόχου, καὶ αὐτὸς παρεσκευάζετο ὡς ἀμυνούμενος Ἀντίγονον. καὶ Κάσσανδρον τὸν Ἀντιπάτρου καὶ Λυσίμαχον βασιλεύοντα ἐν Θρᾴκῃ μετασχεῖν ἔπεισε τοῦ πολέμου, φυγὴν λέγων τὴν Σελεύκου καὶ τὸν Ἀντίγονον φοβερόν σφισιν εἶναι πᾶσιν αὐξηθέντα.", "st": "1.6"}, {"sp": "N", "t": "Ἀντίγονος δὲ τέως μὲν ἦν ἐν παρασκευῇ πολέμου καὶ τὸν κίνδυνον οὐ παντάπασιν ἐθάρρει· ἐπεὶ δὲ ἐς Λιβύην ἐπύθετο στρατεύειν Πτολεμαῖον ἀφεστηκότων Κυρηναίων, αὐτίκα Σύρους καὶ Φοίνικας εἷλεν ἐξ ἐπιδρομῆς, παραδοὺς δὲ Δημητρίῳ τῷ παιδί, ἡλικίαν μὲν νέῳ φρονεῖν δὲ ἤδη δοκοῦντι, καταβαίνει ἐπὶ τὸν Ἑλλήσποντον. πρὶν δὲ ἢ διαβῆναι πάλιν ἦγεν ὀπίσω τὴν στρατιάν, Δημήτριον ἀκούων ὑπὸ Πτολεμαίου μάχῃ κεκρατῆσθαι· Δημήτριος δὲ οὔτε παντάπασιν ἐξειστήκει Πτολεμαίῳ τῆς χώρας καί τινας τῶν Αἰγυπτίων λοχήσας διέφθειρεν οὐ πολλούς. τότε δὲ ἥκοντα Ἀντίγονον οὐχ ὑπομείνας Πτολεμαῖος ἀνεχώρησεν ἐς Αἴγυπτον.", "st": "1.6"}, {"sp": "N", "t": "διελθόντος δὲ τοῦ χειμῶνος Δημήτριος πλεύσας ἐς Κύπρον Μενέλαον σατράπην Πτολεμαίου ναυμαχίᾳ καὶ αὖθις αὐτὸν Πτολεμαῖον ἐπιδιαβάντα ἐνίκησε· φυγόντα δὲ αὐτὸν ἐς Αἴγυπτον Ἀντίγονός τε κατὰ γῆν καὶ ναυσὶν ἅμα ἐπολιόρκει [καὶ] Δημήτριος. Πτολεμαῖος δὲ ἐς πᾶν ἀφικόμενος κινδύνου διέσωσεν ὅμως τὴν ἀρχὴν στρατιᾷ τε ἀντικαθήμενος ἐπὶ Πηλουσίῳ καὶ τριήρεσιν ἀμυνόμενος ἅμα ἐκ τοῦ ποταμοῦ. Ἀντίγονος δὲ Αἴγυπτον μὲν αἱρήσειν ἐκ τῶν παρόντων οὐδεμίαν ἔτι εἶχεν ἐλπίδα, Δημήτριον δὲ ἐπὶ Ῥοδίους στρατιᾷ πολλῇ καὶ ναυσὶν ἔστειλεν, ὡς εἴ οἱ προσγένοιτο ἡ νῆσος ὁρμητηρίῳ χρήσεσθαι πρὸς τοὺς Αἰγυπτίους ἐλπίζων· ἀλλὰ αὐτοί τε οἱ Ῥόδιοι τολμήματα καὶ ἐπιτεχνήσεις παρέσχοντο ἐς τοὺς πολιορκοῦντας καὶ Πτολεμαῖός σφισιν ἐς ὅσον δυνάμεως ἧκε συνήρατο ἐς τὸν πόλεμον.", "st": "1.6"}, {"sp": "N", "t": "Ἀντίγονος δὲ Ῥόδου τε ἁμαρτὼν καὶ Αἰγύπτου πρότερον, οὐ πολλῷ τούτων ὕστερον ἀντιτάξασθαι Λυσιμάχῳ τολμήσας καὶ Κασσάνδρῳ τε καὶ τῇ Σελεύκου στρατιᾷ, τῆς δυνάμεως ἀπώλεσε τὸ πολὺ καὶ αὐτὸς ἀπέθανε ταλαιπωρήσας μάλιστα τῷ μήκει τοῦ πρὸς Εὐμένη πολέμου. τῶν δὲ βασιλέων τῶν καθελόντων Ἀντίγονον ἀνοσιώτατον κρίνω γενέσθαι Κάσσανδρον, ὃς δι’ Ἀντιγόνου τὴν Μακεδόνων ἀρχὴν ἀνασωσάμενος πολεμήσων ἦλθεν ἐπ’ ἄνδρα εὐεργέτην.", "st": "1.6"}, {"sp": "N", "t": "ἀποθανόντος δὲ Ἀντιγόνου Πτολεμαῖος Σύρους τε αὖθις καὶ Κύπρον εἷλε, κατήγαγε δὲ καὶ Πύρρον ἐς τὴν Θεσπρωτίδα ἤπειρον· Κυρήνης δὲ ἀποστάσης Μάγας Βερενίκης υἱὸς Πτολεμαίῳ τότε συνοικούσης ἔτει πέμπτῳ μετὰ τὴν ἀπόστασιν εἷλε Κυρήνην. —εἰ δὲ ὁ Πτολεμαῖος οὗτος ἀληθεῖ λόγῳ Φιλίππου τοῦ Ἀμύντου παῖς ἦν, ἴστω τὸ ἐπιμανὲς ἐς τὰς γυναῖκας κατὰ τὸν πατέρα κεκτημένος, ὃς Εὐρυδίκῃ τῇ Ἀντιπάτρου συνοικῶν ὄντων οἱ παίδων Βερενίκης ἐς ἔρωτα ἦλθεν, ἣν Ἀντίπατρος Εὐρυδίκῃ συνέπεμψεν ἐς Αἴγυπτον. ταύτης τῆς γυναικὸς ἐρασθεὶς παῖδας ἐξ αὐτῆς ἐποιήσατο, καὶ ὡς ἦν οἱ πλησίον ἡ τελευτή, Πτολεμαῖον ἀπέλιπεν Αἰγύπτου βασιλεύειν, ἀφ’ οὗ καὶ Ἀθηναίοις ἐστὶν ἡ φυλή, γεγονότα ἐκ Βερενίκης ἀλλ’ οὐκ ἐκ τῆς Ἀντιπάτρου θυγατρός.", "st": "1.6"}, {"sp": "N", "t": "οὗτος ὁ Πτολεμαῖος Ἀρσινόης ἀδελφῆς ἀμφοτέρωθεν ἐρασθεὶς ἔγημεν αὐτήν, Μακεδόσιν οὐδαμῶς ποιῶν νομιζόμενα, Αἰγυπτίοις μέντοι ὧν ἦρχε. δεύτερα δὲ ἀδελφὸν ἀπέκτεινεν Ἀργαῖον ἐπιβουλεύοντα, ὡς λέγεται, καὶ τὸν Ἀλεξάνδρου νεκρὸν οὗτος ὁ καταγαγὼν ἦν ἐκ Μέμφιδος· ἀπέκτεινε δὲ καὶ ἄλλον ἀδελφὸν γεγονότα ἐξ Εὐρυδίκης, Κυπρίους ἀφιστάντα αἰσθόμενος. Μάγας δὲ ἀδελφὸς ὁμομήτριος Πτολεμαίου παρὰ Βερενίκης τῆς μητρὸς ἀξιωθεὶς ἐπιτροπεύειν Κυρήνην— ἐγεγόνει δὲ ἐκ Φιλίππου τῇ Βερενίκῃ Μακεδόνος μέν, ἄλλως δὲ ἀγνώστου καὶ ἑνὸς τοῦ δήμου—, τότε δὴ οὗτος ὁ Μάγας ἀποστήσας Πτολεμαίου Κυρηναίους ἤλαυνεν ἐπ’ Αἴγυπτον.", "st": "1.7"}, {"sp": "N", "t": "καὶ Πτολεμαῖος μὲν τὴν ἐσβολὴν φραξάμενος ὑπέμενεν ἐπιόντας Κυρηναίους, Μάγᾳ δὲ ἀπαγγέλλεται καθ’ ὁδὸν ἀφεστηκέναι Μαρμαρίδας· εἰσὶ δὲ Λιβύων οἱ Μαρμαρίδαι τῶν νομάδων. καὶ τότε μὲν ἐς Κυρήνην ἀπηλλάσσετο· Πτολεμαῖον δὲ ὡρμημένον διώκειν αἰτία τοιάδε ἐπέσχεν. ἡνίκα παρεσκευάζετο ἐπιόντα ἀμύνεσθαι Μάγαν, ξένους ἐπηγάγετο καὶ ἄλλους καὶ Γαλάτας ἐς τετρακισχιλίους· τούτους λαβὼν ἐπιβουλεύοντας κατασχεῖν Αἴγυπτον, ἀνήγαγε σφᾶς ἐς νῆσον ἔρημον διὰ τοῦ ποταμοῦ. καὶ οἱ μὲν ἐνταῦθα ἀπώλοντο ὑπό τε ἀλλήλων καὶ τοῦ λιμοῦ·", "st": "1.7"}, {"sp": "N", "t": "Μάγας δὲ ἤδη γυναῖκα ἔχων Ἀπάμην Ἀντιόχου τοῦ Σελεύκου θυγατέρα, ἔπεισεν Ἀντίοχον παραβάντα ἃς ὁ πατήρ οἱ Σέλευκος ἐποιήσατο συνθήκας πρὸς Πτολεμαῖον, ἐλαύνειν ἐπ’ Αἴγυπτον. ὡρμημένου δὲ Ἀντιόχου στρατεύειν, Πτολεμαῖος διέπεμψεν ἐς ἅπαντας ὧν ἦρχεν Ἀντίοχος, τοῖς μὲν ἀσθενεστέροις λῃστὰς κατατρέχειν τὴν γῆν, οἳ δὲ ἦσαν δυνατώτεροι στρατιᾷ κατεῖργεν, ὥστε Ἀντιόχῳ μήποτε ἐγγενέσθαι στρατεύειν ἐπ’ Αἴγυπτον. οὗτος ὁ Πτολεμαῖος καὶ πρότερον εἴρηταί μοι ὡς ναυτικὸν ἔστειλεν ἐς τὴν Ἀθηναίων συμμαχίαν ἐπ’ Ἀντίγονον καὶ Μακεδόνας· ἀλλὰ γὰρ ἀπ’ αὐτοῦ οὐδὲν μέγα ἐγένετο ἐς σωτηρίαν Ἀθηναίοις. οἱ δέ οἱ παῖδες ἐγένοντο ἐξ Ἀρσινόης, οὐ τῆς ἀδελφῆς, Λυσιμάχου δὲ θυγατρός· τὴν δέ οἱ συνοικήσασαν ἀδελφὴν κατέλαβεν ἔτι πρότερον ἀποθανεῖν ἄπαιδα, καὶ νομός ἐστιν ἀπ’ αὐτῆς Ἀρσινοΐτης Αἰγυπτίοις.", "st": "1.7"}, {"sp": "N", "t": "ἀπαιτεῖ δὲ ὁ λόγος δηλῶσαι καὶ τὰ ἐς Ἄτταλον ἔχοντα, ὅτι καὶ οὗτος τῶν ἐπωνύμων ἐστὶν Ἀθηναίοις. ἀνὴρ Μακεδὼν Δόκιμος ὄνομα, στρατηγὸς Ἀντιγόνου, Λυσιμάχῳ παραδοὺς ὕστερον αὑτὸν καὶ τὰ χρήματα, Φιλέταιρον Παφλαγόνα εἶχεν εὐνοῦχον. ὅσα μὲν δὴ Φιλεταίρῳ πεπραγμένα ἐς τὴν ἀπόστασίν ἐστι τὴν ἀπὸ Λυσιμάχου καὶ ὡς Σέλευκον ἐπηγάγετο, ἔσται μοι τῶν ἐς Λυσίμαχον παρενθήκη· ὁ δὲ Ἄτταλος Ἀττάλου μὲν παῖς ὤν, ἀδελφιδοῦς δὲ Φιλεταίρου, τὴν ἀρχὴν Εὐμένους παραδόντος ἔσχεν ἀνεψιοῦ. μέγιστον δέ ἐστίν οἱ τῶν ἔργων· Γαλάτας γὰρ ἐς τὴν γῆν, ἣν ἔτι καὶ νῦν ἔχουσιν, ἀναφυγεῖν ἠνάγκασεν ἀπὸ θαλάσσης.", "st": "1.8"}, {"sp": "N", "t": "μετὰ δὲ τὰς εἰκόνας τῶν ἐπωνύμων ἐστὶν ἀγάλματα θεῶν, Ἀμφιάραος καὶ Εἰρήνη φέρουσα Πλοῦτον παῖδα. ἐνταῦθα Λυκοῦργός τε κεῖται χαλκοῦς ὁ Λυκόφρονος καὶ Καλλίας, ὃς πρὸς Ἀρταξέρξην τὸν Ξέρξου τοῖς Ἕλλησιν, ὡς Ἀθηναίων οἱ πολλοὶ λέγουσιν, ἔπραξε τὴν εἰρήνην· ἔστι δὲ καὶ Δημοσθένης, ὃν ἐς Καλαυρείαν Ἀθηναῖοι τὴν πρὸ Τροιζῆνος νῆσον ἠνάγκασαν ἀποχωρῆσαι, δεξάμενοι δὲ ὕστερον διώκουσιν αὖθις μετὰ τὴν ἐν Λαμίᾳ πληγήν.", "st": "1.8"}, {"sp": "N", "t": "Δημοσθένης δέ ὡς τὸ δεύτερον ἔφυγε, περαιοῦται καὶ τότε ἐς τὴν Καλαυρείαν, ἔνθα δὴ πιὼν φάρμακον ἐτελεύτησεν· φυγάδα τε Ἕλληνα μόνον τοῦτον Ἀντιπάτρῳ καὶ Μακεδόσιν οὐκ ἀνήγαγεν Ἀρχίας. ὁ δὲ Ἀρχίας οὗτος Θούριος ὢν ἔργον ἤρατο ἀνόσιον· ὅσοι Μακεδόσιν ἔπραξαν ἐναντία πρὶν ἢ τοῖς Ἕλλησι τὸ πταῖσμα ⟨τὸ⟩ ἐν Θεσσαλίᾳ γενέσθαι, τούτους ἦγεν Ἀρχίας Ἀντιπάτρῳ δώσοντας δίκην. Δημοσθένει μὲν ἡ πρὸς Ἀθηναίους ἄγαν εὔνοια ἐς τοῦτο ἐχώρησεν· εὖ δέ μοι λελέχθαι δοκεῖ ἄνδρα ἀφειδῶς ἐκπεσόντα ἐς πολιτείαν καὶ πιστὰ ἡγησάμενον τὰ τοῦ δήμου μήποτε καλῶς τελευτῆσαι.", "st": "1.8"}, {"sp": "N", "t": "τῆς δὲ τοῦ Δημοσθένους εἰκόνος πλησίον Ἄρεώς ἐστιν ἱερόν, ἔνθα ἀγάλματα δύο μὲν Ἀφροδίτης κεῖται, τὸ δὲ τοῦ Ἄρεως ἐποίησεν Ἀλκαμένης, τὴν δὲ Ἀθηνᾶν ἀνὴρ Πάριος, ὄνομα δὲ αὐτῷ Λόκρος. ἐνταῦθα καὶ Ἐνυοῦς ἄγαλμά ἐστιν, ἐποίησαν δὲ οἱ παῖδες οἱ Πραξιτέλους· περὶ δὲ τὸν ναὸν ἑστᾶσιν Ἡρακλῆς καὶ Θησεὺς καὶ Ἀπόλλων ἀναδούμενος ταινίᾳ τὴν κόμην, ἀνδριάντες δὲ Καλάδης Ἀθηναίοις ὡς λέγεται νόμους γράψας καὶ Πίνδαρος ἄλλα τε εὑρόμενος παρὰ Ἀθηναίων καὶ τὴν εἰκόνα, ὅτι σφᾶς ἐπῄνεσεν ᾆσμα ποιήσας.", "st": "1.8"}, {"sp": "N", "t": "οὐ πόρρω δὲ ἑστᾶσιν Ἁρμόδιος καὶ Ἀριστογείτων οἱ κτείναντες Ἵππαρχον· αἰτία δὲ ἥτις ἐγένετο καὶ τὸ ἔργον ὅντινα τρόπον ἔπραξαν, ἑτέροις ἐστὶν εἰρημένα. τῶν δὲ ἀνδριάντων οἱ μέν εἰσι Κριτίου τέχνη, τοὺς δὲ ἀρχαίους ἐποίησεν Ἀντήνωρ· Ξέρξου δέ, ὡς εἷλεν Ἀθήνας ἐκλιπόντων τὸ ἄστυ Ἀθηναίων, ἀπαγαγομένου καὶ τούτους ἅτε λάφυρα, κατέπεμψεν ὕστερον Ἀθηναίοις Ἀντίοχος.", "st": "1.8"}, {"sp": "N", "t": "τοῦ θεάτρου δὲ ὃ καλοῦσιν Ὠιδεῖον ἀνδριάντες πρὸ τῆς ἐσόδου βασιλέων εἰσὶν Αἰγυπτίων. ὀνόματα μὲν δὴ κατὰ τὰ αὐτὰ Πτολεμαῖοί σφισιν, ἄλλη δὲ ἐπίκλησις ἄλλῳ· καὶ γὰρ Φιλομήτορα καλοῦσι καὶ Φιλάδελφον ἕτερον, τὸν δὲ τοῦ Λάγου Σωτῆρα παραδόντων Ῥοδίων τὸ ὄνομα. τῶν δὲ ἄλλων ὁ μὲν Φιλάδελφός ἐστιν οὗ καὶ πρότερον μνήμην ἐν τοῖς ἐπωνύμοις ἐποιησάμην, πλησίον δέ οἱ καὶ Ἀρσινόης τῆς ἀδελφῆς ἐστιν εἰκών.", "st": "1.8"}, {"sp": "N", "t": "ὁ δὲ Φιλομήτωρ καλούμενος ὄγδοος μέν ἐστιν ἀπόγονος Πτολεμαίου τοῦ Λάγου, τὴν δὲ ἐπίκλησιν ἔσχεν ἐπὶ χλευασμῷ. οὐ γάρ τινα τῶν βασιλέων μισηθέντα ἴσμεν ἐς τοσόνδε ὑπὸ μητρός, ὃν πρεσβύτατον ὄντα τῶν παίδων ἡ μήτηρ οὐκ εἴα καλεῖν ἐπὶ τὴν ἀρχήν, πρότερον δὲ ἐς Κύπρον ὑπὸ τοῦ πατρὸς πεμφθῆναι πράξασα· τῆς δὲ ἐς τὸν παῖδα τῇ Κλεοπάτρᾳ δυσνοίας λέγουσιν ἄλλας τε αἰτίας καὶ ὅτι Ἀλέξανδρον τὸν νεώτερον τῶν παίδων κατήκοον ἔσεσθαι μᾶλλον ἤλπιζε. καὶ διὰ τοῦτο ἑλέσθαι βασιλέα Ἀλέξανδρον ἔπειθεν Αἰγυπτίους·", "st": "1.9"}, {"sp": "N", "t": "ἐναντιουμένου δέ οἱ τοῦ πλήθους, δεύτερα ἐς τὴν Κύπρον ἔστειλεν Ἀλέξανδρον, στρατηγὸν μὲν τῷ λόγῳ, τῷ δὲ ἔργῳ δι’ αὐτοῦ Πτολεμαίῳ θέλουσα εἶναι φοβερωτέρα, τέλος δὲ κατατρώσασα οὓς μάλιστα τῶν εὐνούχων ἐνόμιζεν εὔνους, ἐπήγετο σφᾶς ἐς τὸ πλῆθος ὡς αὐτή τε ἐπιβουλευθεῖσα ὑπὸ Πτολεμαίου καὶ τοὺς εὐνούχους τοιαῦτα ὑπ’ ἐκείνου παθόντας. οἱ δὲ Ἀλεξανδρεῖς ὥρμησαν μὲν ὡς ἀποκτενοῦντες τὸν Πτολεμαῖον, ὡς δὲ σφᾶς ἔφθασεν ἐπιβὰς νεώς, Ἀλέξανδρον ἥκοντα ἐκ Κύπρου ποιοῦνται βασιλέα.", "st": "1.9"}, {"sp": "N", "t": "Κλεοπάτραν δὲ περιῆλθεν ἡ δίκη τῆς Πτολεμαίου φυγῆς ἀποθανοῦσαν ὑπὸ Ἀλεξάνδρου, ὃν αὐτὴ βασιλεύειν ἔπραξεν Αἰγυπτίων. τοῦ δὲ ἔργου φωραθέντος καὶ Ἀλεξάνδρου φόβῳ τῶν πολιτῶν φεύγοντος, οὕτω Πτολεμαῖος κατῆλθε καὶ τὸ δεύτερον ἔσχεν Αἴγυπτον· καὶ Θηβαίοις ἐπολέμησεν ἀποστᾶσι, παραστησάμενος δὲ ἔτει τρίτῳ μετὰ τὴν ἀπόστασιν ἐκάκωσεν, ὡς μηδὲ ὑπόμνημα λειφθῆναι Θηβαίοις τῆς ποτε εὐδαιμονίας προελθούσης ἐς τοσοῦτον ὡς ὑπερβαλέσθαι πλούτῳ τοὺς Ἑλλήνων πολυχρημάτους, τό τε ἱερὸν τὸ ἐν Δελφοῖς καὶ Ὀρχομενίους. Πτολεμαῖον μὲν οὖν ὀλίγῳ τούτων ὕστερον ἐπέλαβε μοῖρα ἡ καθήκουσα· Ἀθηναῖοι δὲ ὑπ’ αὐτοῦ παθόντες εὖ πολλά τε καὶ οὐκ ἄξια ἐξηγήσεως χαλκοῦν καὶ αὐτὸν καὶ Βερενίκην ἀνέθηκαν, ἣ μόνη γνησία οἱ τῶν παίδων ἦν.", "st": "1.9"}, {"sp": "N", "t": "μετὰ δὲ τοὺς Αἰγυπτίους Φίλιππός τε καὶ Ἀλέξανδρος ὁ Φιλίππου κεῖνται· τούτοις μείζονα ὑπῆρχέ πως ἢ ἄλλου πάρεργα εἶναι λόγου. τοῖς μὲν οὖν ἀπ’ Αἰγύπτου τιμῇ τε ἀληθεῖ καὶ εὐεργέταις οὖσι γεγόνασιν αἱ δωρεαί, Φιλίππῳ δὲ καὶ Ἀλεξάνδρῳ κολακείᾳ μᾶλλον ἐς αὐτοὺς τοῦ πλήθους, ἐπεὶ καὶ Λυσίμαχον οὐκ εὐνοίᾳ τοσοῦτον ὡς ἐς τὰ παρόντα χρήσιμον νομίζοντες ἀνέθηκαν.", "st": "1.9"}, {"sp": "N", "t": "ὁ δὲ Λυσίμαχος οὗτος γένος τε ἦν Μακεδὼν καὶ Ἀλεξάνδρου δορυφόρος, ὃν Ἀλέξανδρός ποτε ὑπ’ ὀργῆς λέοντι ὁμοῦ καθείρξας ἐς οἴκημα κεκρατηκότα εὗρε τοῦ θηρίου· τά τε οὖν ἄλλα ἤδη διετέλει θαυμάζων καὶ Μακεδόνων ὁμοίως τοῖς ἀρίστοις ἦγεν ἐν τιμῇ. τελευτήσαντος δὲ Ἀλεξάνδρου Θρᾳκῶν ἐβασίλευεν ὁ Λυσίμαχος τῶν προσοίκων Μακεδόσιν, ὅσων ἦρχεν Ἀλέξανδρος καὶ ἔτι πρότερον Φίλιππος· εἶεν δ’ ἂν οὗτοι τοῦ Θρᾳκίου μοῖρα οὐ μεγάλη. Θρᾳκῶν δὲ τῶν πάντων οὐδένες πλείους εἰσὶ τῶν ἀνθρώπων ὅτι μὴ Κελτοὶ πρὸς ἄλλο ἔθνος ἓν ἀντεξετάζοντι, καὶ διὰ τοῦτο οὐδείς πω πρότερος Θρᾷκας Ῥωμαίων κατεστρέψατο ἀθρόους· Ῥωμαίοις δὲ Θρᾴκη τε πᾶσά ἐστιν ὑποχείριος, καὶ Κελτῶν ὅσον μὲν ἀχρεῖον νομίζουσι διά τε ὑπερβάλλον ψῦχος καὶ γῆς φαυλότητα, ἑκουσίως παρῶπταί σφισι, τὰ δὲ ἀξιόκτητα ἔχουσι καὶ τούτων.", "st": "1.9"}, {"sp": "N", "t": "τότε δὲ ὁ Λυσίμαχος πρώτοις τῶν περιοίκων ἐπολέμησεν Ὀδρύσαις, δεύτερα δὲ ἐπὶ Δρομιχαίτην καὶ Γέτας ἐστράτευσεν· οἷα δὲ ἀνδράσι συμβαλὼν οὐκ ἀπείροις πολέμων, ἀριθμῷ δὲ καὶ πολὺ ὑπερβεβληκόσιν, αὐτὸς μὲν ἐς τὸ ἔσχατον ἐλθὼν κινδύνου διέφυγεν, ὁ δέ οἱ παῖς Ἀγαθοκλῆς συστρατευόμενος τότε πρῶτον ὑπὸ τῶν Γετῶν ἑάλω. Λυσίμαχος δὲ καὶ ὕστερον προσπταίσας μάχαις καὶ τὴν ἅλωσιν τοῦ παιδὸς οὐκ ἐν παρέργῳ ποιούμενος συνέθετο πρὸς Δρομιχαίτην εἰρήνην, τῆς τε ἀρχῆς τῆς αὑτοῦ τὰ πέραν Ἴστρου παρεὶς τῷ Γέτῃ καὶ θυγατέρα συνοικίσας ἀνάγκῃ τὸ πλέον· οἱ δὲ οὐκ Ἀγαθοκλέα, Λυσίμαχον δὲ αὐτὸν ἁλῶναι λέγουσιν, ἀνασωθῆναι δὲ Ἀγαθοκλέους τὰ πρὸς τὸν Γέτην ὑπὲρ αὐτοῦ πράξαντος. ὡς δὲ ἐπανῆλθεν, Ἀγαθοκλεῖ Λυσάνδραν γυναῖκα ἠγάγετο, Πτολεμαίου τε τοῦ Λάγου καὶ Εὐρυδίκης οὖσαν.", "st": "1.9"}, {"sp": "N", "t": "διέβη δὲ καὶ ναυσὶν ἐπὶ τὴν Ἀσίαν καὶ τὴν ἀρχὴν τὴν Ἀντιγόνου συγκαθεῖλε. συνῴκισε δὲ καὶ Ἐφεσίων ἄχρι θαλάσσης τὴν νῦν πόλιν, ἐπαγαγόμενος ἐς αὐτὴν Λεβεδίους τε οἰκήτορας καὶ Κολοφωνίους, τὰς δὲ ἐκείνων ἀνελὼν πόλεις, ὡς Φοίνικα ἰάμβων ποιητὴν Κολοφωνίων θρηνῆσαι τὴν ἅλωσιν. Ἑρμησιάναξ δὲ ὁ τὰ ἐλεγεῖα γράψας οὐκέτι ἐμοὶ δοκεῖν περιῆν· πάντως γάρ που καὶ αὐτὸς ἂν ἐπὶ ἁλούσῃ Κολοφῶνι ὠδύρατο. Λυσίμαχος δὲ καὶ ἐς πόλεμον πρὸς Πύρρον κατέστη τὸν Αἰακίδου· φυλάξας δὲ ἐξ Ἠπείρου ἀπιόντα, οἷα δὴ τὰ πολλὰ ἐκεῖνος ἐπλανᾶτο, τήν τε ἄλλην ἐλεηλάτησεν Ἤπειρον καὶ ἐπὶ τὰς θήκας ἦλθε τῶν βασιλέων.", "st": "1.9"}, {"sp": "N", "t": "τὰ δὲ ἐντεῦθεν ἐμοί ἐστιν οὐ πιστά, Ἱερώνυμος δὲ ἔγραψε Καρδιανὸς Λυσίμαχον τὰς θήκας τῶν νεκρῶν ἀνελόντα τὰ ὀστᾶ ἐκρῖψαι. ὁ δὲ Ἱερώνυμος οὗτος ἔχει μὲν καὶ ἄλλως δόξαν πρὸς ἀπέχθειαν γράψαι τῶν βασιλέων πλὴν Ἀντιγόνου, τούτῳ δὲ οὐ δικαίως χαρίζεσθαι· τὰ δὲ ἐπὶ τοῖς τάφοις τῶν Ἠπειρωτῶν παντάπασίν ἐστι φανερὸς ἐπηρείᾳ συνθείς, ἄνδρα Μακεδόνα θήκας νεκρῶν ἀνελεῖν. χωρὶς δὲ ἠπίστατο δή που καὶ Λυσίμαχος οὐ Πύρρου σφᾶς προγόνους μόνον ἀλλὰ καὶ Ἀλεξάνδρου τοὺς αὐτοὺς τούτους ὄντας· καὶ γὰρ Ἀλέξανδρος Ἠπειρώτης τε ἦν καὶ τῶν Αἰακιδῶν τὰ πρὸς μητρός, ἥ τε ὕστερον Πύρρου πρὸς Λυσίμαχον συμμαχία δηλοῖ καὶ πολεμήσασιν ἀδιάλλακτόν γε οὐδὲν πρὸς ἀλλήλους γενέσθαι σφίσι. τῷ δὲ Ἱερωνύμῳ τάχα μέν που καὶ ἄλλα ἦν ἐς Λυσίμαχον ἐγκλήματα, μέγιστον δὲ ὅτι τὴν Καρδιανῶν πόλιν ἀνελὼν Λυσιμάχειαν ἀντ’ αὐτῆς ᾤκισεν ἐπὶ τῷ ἰσθμῷ τῆς Θρᾳκίας χερρονήσου.", "st": "1.9"}, {"sp": "N", "t": "Λυσιμάχῳ δὲ ἐπὶ μὲν Ἀριδαίου βασιλεύοντος καὶ ὕστερον Κασσάνδρου καὶ τῶν παίδων φιλία διέμεινε πρὸς Μακεδόνας· περιελθούσης δὲ ἐς Δημήτριον τὸν Ἀντιγόνου τῆς ἀρχῆς, ἐνταῦθα ἤδη Λυσίμαχος πολεμήσεσθαι ἤλπιζεν ὑπὸ Δημητρίου καὶ αὐτὸς ἄρχειν ἠξίου πολέμου, πατρῷον ἐπιστάμενος ὂν Δημητρίῳ προσπεριβάλλεσθαί τι ἐθέλειν καὶ ἅμα ὁρῶν αὐτὸν παρελθόντα ἐς Μακεδονίαν μετάπεμπτον ὑπὸ Ἀλεξάνδρου τοῦ Κασσάνδρου, ὡς δὲ ἀφίκετο, αὐτόν τε Ἀλέξανδρον φονεύσαντα καὶ ἔχοντα ἀντ’ ἐκείνου τὴν Μακεδόνων ἀρχήν.", "st": "1.10"}, {"sp": "N", "t": "τούτων ἕνεκα Δημητρίῳ συμβαλὼν πρὸς Ἀμφιπόλει παρ’ ὀλίγον μὲν ἦλθεν ἐκπεσεῖν Θρᾴκης, ἀμύναντος δέ οἱ Πύρρου τήν τε Θρᾴκην κατέσχε καὶ ὕστερον ἐπῆρξε Νεστίων καὶ Μακεδόνων· τὸ δὲ πολὺ Μακεδονίας αὐτὸς Πύρρος κατεῖχε, δυνάμει τε ἥκων ἐξ Ἠπείρου καὶ πρὸς Λυσίμαχον ἐν τῷ παρόντι ἔχων ἐπιτηδείως. Δημητρίου δὲ διαβάντος ἐς τὴν Ἀσίαν καὶ Σελεύκῳ πολεμοῦντος, ὅσον μὲν χρόνον ἀντεῖχε τὰ Δημητρίου, διέμεινεν ἡ Πύρρου καὶ Λυσιμάχου συμμαχία· γενομένου δὲ ἐπὶ Σελεύκῳ Δημητρίου Λυσιμάχῳ καὶ Πύρρῳ διελύθη ἡ φιλία, καὶ καταστάντων ἐς πόλεμον Λυσίμαχος Ἀντιγόνῳ τε τῷ Δημητρίου καὶ αὐτῷ Πύρρῳ πολεμήσας ἐκράτησε παρὰ πολὺ καὶ Μακεδονίαν ἔσχεν, ἀναχωρῆσαι Πύρρον βιασάμενος ἐς τὴν Ἤπειρον.", "st": "1.10"}, {"sp": "N", "t": "εἰώθασι δὲ ἀνθρώποις φύεσθαι δι’ ἔρωτα πολλαὶ συμφοραί. Λυσίμαχος γὰρ ἡλικίᾳ τε ἤδη προήκων καὶ ἐς τοὺς παῖδας αὐτός τε νομιζόμενος εὐδαίμων καὶ Ἀγαθοκλεῖ παίδων ὄντων ἐκ Λυσάνδρας Ἀρσινόην ἔγημεν ἀδελφὴν Λυσάνδρας. ταύτην τὴν Ἀρσινόην φοβουμένην ἐπὶ τοῖς παισί, μὴ Λυσιμάχου τελευτήσαντος ἐπ’ Ἀγαθοκλεῖ γένωνται, τούτων ἕνεκα Ἀγαθοκλεῖ ἐπιβουλεῦσαι λέγεται. ἤδη δὲ ἔγραψαν καὶ ὡς Ἀγαθοκλέους ἀφίκοιτο ἐς ἔρωτα ἡ Ἀρσινόη, ἀποτυγχάνουσα δὲ †ἐπὶ τῷ βουλεῦσαι λέγουσιν Ἀγαθοκλεῖ θάνατον. λέγουσι δὲ καὶ ὡς Λυσίμαχος αἴσθοιτο ὕστερον τὰ τολμηθέντα ὑπὸ τῆς γυναικός, εἶναι δὲ οὐδὲν ἔτι οἱ πλέον ἠρημωμένῳ φίλων ἐς τὸ ἔσχατον.", "st": "1.10"}, {"sp": "N", "t": "ὡς γὰρ δὴ τότε ὁ Λυσίμαχος ἀνελεῖν τὸν Ἀγαθοκλέα Ἀρσινόῃ παρῆκε, Λυσάνδρα παρὰ Σέλευκον ἐκδιδράσκει τούς τε παῖδας ἅμα ἀγομένη καὶ τοὺς ἀδελφοὺς τοὺς αὑτῆς, †οἷ περιελθὸν τοῦτο ἐς Πτολεμαῖον καταφεύγουσι. τούτοις ἐκδιδράσκουσι παρὰ Σέλευκον καὶ Ἀλέξανδρος ἠκολούθησεν, υἱὸς μὲν Λυσιμάχου, γεγονὼς δὲ ἐξ Ὀδρυσιάδος γυναικός. οὗτοί τε οὖν ἐς Βαβυλῶνα ἀναβεβηκότες ἱκέτευον Σέλευκον ἐς πόλεμον πρὸς Λυσίμαχον καταστῆναι· καὶ Φιλέταιρος ἅμα, ᾧ τὰ χρήματα ἐπετέτραπτο Λυσιμάχου, τῇ τε Ἀγαθοκλέους τελευτῇ χαλεπῶς φέρων καὶ τὰ παρὰ τῆς Ἀρσινόης ὕποπτα ἡγούμενος καταλαμβάνει Πέργαμον τὴν ὑπὲρ Καΐκου, πέμψας δὲ κήρυκα τά τε χρήματα καὶ αὑτὸν ἐδίδου Σελεύκῳ.", "st": "1.10"}, {"sp": "N", "t": "Λυσίμαχος δὲ ταῦτα πάντα πυνθανόμενος ἔφθη διαβὰς ἐς τὴν Ἀσίαν καὶ ἄρξας αὐτὸς πολέμου συμβαλών τε Σελεύκῳ παρὰ πολύ τε ἐκρατήθη καὶ αὐτὸς ἀπέθανεν. Ἀλέξανδρος δέ, ὃς ἐκ τῆς γυναικὸς Ὀδρυσίδος ἐγεγόνει οἱ, πολλὰ Λυσάνδραν παραιτησάμενος ἀναιρεῖταί τε καὶ ὕστερον τούτων ἐς Χερρόνησον κομίσας ἔθαψεν, ἔνθα ἔτι καὶ νῦν ἐστίν οἱ φανερὸς ὁ τάφος Καρδίας τε μεταξὺ κώμης καὶ Πακτύης.", "st": "1.10"}, {"sp": "N", "t": "τὰ μὲν οὖν Λυσιμάχου τοιαῦτα ἐγένετο· Ἀθηναίοις δὲ εἰκών ἐστι καὶ Πύρρου. οὗτος ὁ Πύρρος Ἀλεξάνδρῳ προσῆκεν οὐδέν, εἰ μὴ ὅσα κατὰ γένος· Αἰακίδου γὰρ τοῦ Ἀρύββου Πύρρος ἦν, Ὀλυμπιάδος δὲ Ἀλέξανδρος τῆς Νεοπτολέμου, Νεοπτολέμῳ δὲ καὶ Ἀρύββᾳ πατὴρ ἦν Ἀλκέτας ὁ Θαρύπου. ἀπὸ δὲ Θαρύπου ἐς Πύρρον τὸν Ἀχιλλέως πέντε ἀνδρῶν καὶ δέκα εἰσὶ γενεαί· πρῶτος γὰρ δὴ οὗτος ἁλούσης Ἰλίου τὴν μὲν ἐς Θεσσαλίαν ὑπερεῖδεν ἀναχώρησιν, ἐς δὲ τὴν Ἤπειρον κατάρας ἐνταῦθα ἐκ τῶν Ἑλένου χρησμῶν ᾤκησε. καί οἱ παῖς ἐκ μὲν Ἑρμιόνης ἐγένετο οὐδείς, ἐξ Ἀνδρομάχης δὲ Μολοσσὸς καὶ Πίελος καὶ νεώτατος ὁ Πέργαμος. ἐγένετο δὲ καὶ Ἑλένῳ Κεστρῖνος· τούτῳ γὰρ Ἀνδρομάχη συνῴκησεν ἀποθανόντος ἐν Δελφοῖς Πύρρου.", "st": "1.11"}, {"sp": "N", "t": "Ἑλένου δὲ ὡς ἐτελεύτα Μολοσσῷ τῷ Πύρρου παραδόντος τὴν ἀρχὴν Κεστρῖνος μὲν σὺν τοῖς ἐθέλουσιν Ἠπειρωτῶν τὴν ὑπὲρ Θύαμιν ποταμὸν χώραν ἔσχε, Πέργαμος δὲ διαβὰς ἐς τὴν Ἀσίαν Ἄρειον δυναστεύοντα ἐν τῇ Τευθρανίᾳ κτείνει μονομαχήσαντά οἱ περὶ τῆς ἀρχῆς καὶ τῇ πόλει τὸ ὄνομα ἔδωκε τὸ νῦν ἀφ’ αὑτοῦ· καὶ Ἀνδρομάχης—ἠκολούθει γάρ οἱ—καὶ νῦν ἐστιν ἡρῷον ἐν τῇ πόλει. Πίελος δὲ αὐτοῦ κατέμεινεν ἐν Ἠπείρῳ, καὶ ἐς πρόγονον τοῦτον ἀνέβαινε Πύρρος τε ὁ Αἰακίδου καὶ οἱ πατέρες, ἀλλ’ οὐκ ἐς Μολοσσόν.", "st": "1.11"}, {"sp": "N", "t": "ἦν δὲ ἄχρι μὲν Ἀλκέτου τοῦ Θαρύπου ἐφ’ ἑνὶ βασιλεῖ καὶ τὰ Ἠπειρωτῶν· οἱ δὲ Ἀλκέτου παῖδες, ὥς σφισι στασιάσασι μετέδοξεν ἐπ’ ἴσης ἄρχειν, αὐτοί τε πιστῶς ἔχοντες διέμειναν ἐς ἀλλήλους καὶ ὕστερον Ἀλεξάνδρου τοῦ Νεοπτολέμου τελευτήσαντος ἐν Λευκανοῖς, Ὀλυμπιάδος δὲ διὰ τὸν Ἀντιπάτρου φόβον ἐπανελθούσης ἐς Ἤπειρον, Αἰακίδης ὁ Ἀρύββου τά τε ἄλλα διετέλει κατήκοος ὢν Ὀλυμπιάδι καὶ συνεστράτευσε πολεμήσων Ἀριδαίῳ καὶ Μακεδόσιν, οὐκ ἐθελόντων ἕπεσθαι τῶν Ἠπειρωτῶν.", "st": "1.11"}, {"sp": "N", "t": "Ὀλυμπιάδος δὲ ὡς ἐπεκράτησεν ἀνόσια μὲν ἐργασαμένης καὶ ἐς τὸν Ἀριδαίου θάνατον, πολλῷ δὲ ἔτι ἀνοσιώτερα ἐς ἄνδρας Μακεδόνας, καὶ διὰ ταῦτα οὐκ ἀνάξια ὕστερον ὑπὸ Κασσάνδρου παθεῖν νομισθείσης, Αἰακίδην [οὖν] κατ’ ἀρχὰς μὲν οὐδ’ αὐτοὶ διὰ τὸ Ὀλυμπιάδος ἔχθος ἐδέχοντο Ἠπειρῶται, εὑρομένου δὲ ἀνὰ χρόνον παρὰ τούτων συγγνώμην δεύτερα ἠναντιοῦτο Κάσσανδρος μὴ κατελθεῖν ἐς Ἤπειρον. γενομένης δὲ Φιλίππου τε ἀδελφοῦ Κασσάνδρου καὶ Αἰακίδου μάχης πρὸς Οἰνιάδαις, Αἰακίδην μὲν τρωθέντα κατέλαβε μετ’ οὐ πολὺ τὸ χρεών·", "st": "1.11"}, {"sp": "N", "t": "Ἠπειρῶται δὲ Ἀλκέταν ἐπὶ βασιλείᾳ κατεδέξαντο, Ἀρύββου μὲν παῖδα καὶ ἀδελφὸν Αἰακίδου πρεσβύτερον, ἀκρατῆ δὲ ἄλλως θυμοῦ καὶ δι’ αὐτὸ ἐξελασθέντα ὑπὸ τοῦ πατρός. καὶ τότε ἥκων ἐξεμαίνετο εὐθὺς ἐς τοὺς Ἠπειρώτας, ἐς ὃ νύκτωρ αὐτόν τε καὶ τοὺς παῖδας ἐπαναστάντες ἔκτειναν. ἀποκτείναντες δὲ τοῦτον Πύρρον τὸν Αἰακίδου κατάγουσιν· ἥκοντι δὲ εὐθὺς ἐπεστράτευε Κάσσανδρος, νέῳ τε ἡλικίᾳ ὄντι καὶ τὴν ἀρχὴν οὐ κατεσκευασμένῳ βεβαίως. Πύρρος δὲ ἐπιόντων Μακεδόνων ἐς Αἴγυπτον παρὰ Πτολεμαῖον ἀναβαίνει τὸν Λάγου· καί οἱ Πτολεμαῖος γυναῖκά τ’ ἔδωκεν ἀδελφὴν ὁμομητρίαν τῶν αὑτοῦ παίδων καὶ στόλῳ κατήγαγεν Αἰγυπτίων.", "st": "1.11"}, {"sp": "N", "t": "Πύρρος δὲ βασιλεύσας πρώτοις ἐπέθετο Ἑλλήνων Κορκυραίοις, κειμένην τε ὁρῶν τὴν νῆσον πρὸ τῆς αὑτοῦ χώρας καὶ ἄλλοις ὁρμητήριον ἐφ’ αὑτὸν οὐκ ἐθέλων εἶναι. μετὰ δὲ ἁλοῦσαν Κόρκυραν ὅσα μὲν Λυσιμάχῳ πολεμήσας ἔπαθε καὶ ὡς Δημήτριον ἐκβαλὼν Μακεδονίας ἦρξεν ἐς ὃ αὖθις ἐξέπεσεν ὑπὸ Λυσιμάχου, τάδε μὲν τοῦ Πύρρου μέγιστα ἐς ἐκεῖνον τὸν καιρὸν δεδήλωκεν ἤδη μοι τὰ ἐς Λυσίμαχον ἔχοντα·", "st": "1.11"}, {"sp": "N", "t": "Ῥωμαίοις δὲ οὐδένα Πύρρου πρότερον πολεμήσαντα ἴσμεν Ἕλληνα. Διομήδει μὲν γὰρ καὶ Ἀργείων τοῖς σὺν αὐτῷ οὐδεμίαν ἔτι γενέσθαι πρὸς Αἰνείαν λέγεται μάχην· Ἀθηναίοις δὲ ἄλλα τε πολλὰ ἐλπίσασι καὶ Ἰταλίαν πᾶσαν καταστρέψασθαι τὸ ἐν Συρακούσαις πταῖσμα ἐμποδὼν ἐγένετο μὴ καὶ Ῥωμαίων λαβεῖν πεῖραν· Ἀλέξανδρος δὲ ὁ Νεοπτολέμου, γένους τε ὢν Πύρρῳ τοῦ αὐτοῦ καὶ ἡλικίᾳ πρεσβύτερος, ἀποθανὼν ἐν Λευκανοῖς ἔφθη πρὶν ἐς χεῖρας ἐλθεῖν Ῥωμαίοις.", "st": "1.11"}, {"sp": "N", "t": "οὕτω Πύρρος ἐστὶν ὁ πρῶτος ἐκ τῆς Ἑλλάδος τῆς πέραν Ἰονίου διαβὰς ἐπὶ Ῥωμαίους· διέβη δὲ καὶ οὗτος ἐπαγαγομένων Ταραντίνων. τούτοις γὰρ πρότερον ἔτι πρὸς Ῥωμαίους συνειστήκει πόλεμος· ἀδύνατοι δὲ κατὰ σφᾶς ὄντες ἀντισχεῖν, προϋπαρχούσης μὲν ἐς αὐτὸν εὐεργεσίας, ὅτι οἱ πολεμοῦντι τὸν πρὸς Κόρκυραν πόλεμον ναυσὶ συνήραντο, μάλιστα δὲ οἱ πρέσβεις τῶν Ταραντίνων ἀνέπεισαν τὸν Πύρρον, τήν τε Ἰταλίαν διδάσκοντες ὡς εὐδαιμονίας ἕνεκα ἀντὶ πάσης εἴη τῆς Ἑλλάδος καὶ ὡς οὐχ ὅσιον αὐτῷ παραπέμψαι σφᾶς φίλους τε καὶ ἱκέτας ἐν τῷ παρόντι ἥκοντας. ταῦτα λεγόντων τῶν πρέσβεων μνήμη τὸν Πύρρον τῆς ἁλώσεως ἐσῆλθε τῆς Ἰλίου, καί οἱ κατὰ ταὐτὰ ἤλπιζε χωρήσειν πολεμοῦντι· στρατεύειν γὰρ ἐπὶ Τρώων ἀποίκους Ἀχιλλέως ὢν ἀπόγονος.", "st": "1.12"}, {"sp": "N", "t": "ὡς δέ οἱ ταῦτα ἤρεσκε —διέμελλε γὰρ ἐπ’ οὐδενὶ ὧν ἕλοιτο—, αὐτίκα ναῦς τε ἐπλήρου μακρὰς καὶ πλοῖα στρογγύλα εὐτρέπιζεν ἵππους καὶ ἄνδρας ὁπλίτας ἄγειν. ἔστι δὲ ἀνδράσι βιβλία οὐκ ἐπιφανέσιν ἐς συγγραφήν, ἔχοντα ἐπίγραμμα ἔργων ὑπομνήματα εἶναι. ταῦτα ἐπιλεγομένῳ μοι μάλιστα ἐπῆλθε θαυμάσαι Πύρρου τόλμαν τε, ἣν μαχόμενος αὐτὸς [τε] παρείχετο, καὶ τὴν ἐπὶ τοῖς ἀεὶ μέλλουσιν ἀγῶσι πρόνοιαν· ὃς καὶ τότε περαιούμενος ναυσὶν ἐς Ἰταλίαν Ῥωμαίους ἐλελήθει καὶ ἥκων οὐκ εὐθὺς ἦν σφισι φανερός, γινομένης δὲ Ῥωμαίων πρὸς Ταραντίνους συμβολῆς τότε δὴ πρῶτον ἐπιφαίνεται σὺν τῷ στρατῷ καὶ παρ’ ἐλπίδα σφίσι προσπεσών, ὡς τὸ εἰκός, ἐτάραξεν.", "st": "1.12"}, {"sp": "N", "t": "ἅτε δὲ ἄριστα ἐπιστάμενος ὡς οὐκ ἀξιόμαχος εἴη πρὸς Ῥωμαίους, παρεσκευάζετο ὡς τοὺς ἐλέφαντας ἐπαφήσων σφίσιν. ἐλέφαντας δὲ πρῶτος μὲν τῶν ἐκ τῆς Εὐρώπης Ἀλέξανδρος ἐκτήσατο Πῶρον καὶ τὴν δύναμιν καθελὼν τὴν Ἰνδῶν, ἀποθανόντος δὲ Ἀλεξάνδρου καὶ ἄλλοι τῶν βασιλέων καὶ πλείστους ἔσχεν Ἀντίγονος, Πύρρῳ δὲ ἐκ τῆς μάχης ἐγεγόνει τῆς πρὸς Δημήτριον τὰ θηρία αἰχμάλωτα· τότε δὲ ἐπιφανέντων αὐτῶν δεῖμα ἔλαβε Ῥωμαίους ἄλλο τι καὶ οὐ ζῷα εἶναι νομίσαντας.", "st": "1.12"}, {"sp": "N", "t": "ἐλέφαντα γάρ, ὅσος μὲν ἐς ἔργα καὶ ἀνδρῶν χεῖρας, εἰσὶν ἐκ παλαιοῦ δῆλοι πάντες εἰδότες· αὐτὰ δὲ τὰ θηρία, πρὶν ἢ διαβῆναι Μακεδόνας ἐπὶ τὴν Ἀσίαν, οὐδὲ ἑωράκεσαν ἀρχὴν πλὴν Ἰνδῶν τε αὐτῶν καὶ Λιβύων καὶ ὅσοι πλησιόχωροι τούτοις. δηλοῖ δὲ Ὅμηρος, ὃς βασιλεῦσι κλίνας μὲν καὶ οἰκίας τοῖς εὐδαιμονεστέροις αὐτῶν ἐλέφαντι ἐποίησε κεκοσμημένας, θηρίου δὲ ἐλέφαντος μνήμην οὐδεμίαν ἐποιήσατο· θεασάμενος δὲ ἢ πεπυσμένος ἐμνημόνευσεν ἂν πολύ γε πρότερον ἐμοὶ δοκεῖν ἢ Πυγμαίων τε ἀνδρῶν καὶ γεράνων μάχης.", "st": "1.12"}, {"sp": "N", "t": "Πύρρον δὲ ἐς Σικελίαν ἀπήγαγε πρεσβεία Συρακουσίων· Καρχηδόνιοι γὰρ διαβάντες τὰς Ἑλληνίδας τῶν πόλεων ἐποίουν ἀναστάτους, ἣ δὲ ἦν λοιπή, Συρακούσαις πολιορκοῦντες προσεκάθηντο. ἃ τῶν πρέσβεων Πύρρος ἀκούων Τάραντα μὲν εἴα καὶ τοὺς τὴν ἀκτὴν ἔχοντας Ἰταλιωτῶν, ἐς δὲ τὴν Σικελίαν διαβὰς Καρχηδονίους ἠνάγκασεν ἀπαναστῆναι Συρακουσῶν. φρονήσας δὲ ἐφ’ αὑτῷ Καρχηδονίων, οἳ θαλάσσης τῶν τότε βαρβάρων μάλιστα εἶχον ἐμπείρως Τύριοι Φοίνικες τὸ ἀρχαῖον ὄντες, τούτων ἐναντία ἐπήρθη ναυμαχῆσαι τοῖς Ἠπειρώταις χρώμενος, οἳ μηδὲ ἁλούσης Ἰλίου θάλασσαν οἱ πολλοὶ μηδὲ ἁλσὶν ἠπίσταντό πω χρῆσθαι. μαρτυρεῖ δέ μοι καὶ Ὁμήρου ἔπος ἐν Ὀδυσσείᾳ·<br>οἳ οὐκ ἴσασι θάλασσαν<br>ἀνέρες, οὐδέ θ’ ἅλεσσι μεμιγμένον εἶδαρ ἔδουσιν.", "st": "1.12"}, {"sp": "N", "t": "τότε δὲ ὁ Πύρρος, ὡς ἡττήθη, ταῖς ναυσὶν ἐς Τάραντα ἀνήγετο ταῖς λοιπαῖς· ἐνταῦθα προσέπταισε μεγάλως καὶ τὴν ἀναχώρησιν—οὐ γὰρ ἀμαχεὶ Ῥωμαίους ἠπίστατο ἀφήσοντας—πορίζεται τρόπον τοῦτον. ὡς ἐπανήκων ἐκ Σικελίας ἡττήθη, πρῶτον διέπεμπε γράμματα ἔς τε τὴν Ἀσίαν καὶ πρὸς Ἀντίγονον, τοὺς μὲν στρατιὰν τῶν βασιλέων, τοὺς δὲ χρήματα, Ἀντίγονον δὲ καὶ ἀμφότερα αἰτῶν· ἀφικομένων δὲ τῶν ἀγγέλων, ὥς οἱ γράμματα ἀπεδόθη, συναγαγὼν τοὺς ἐν τέλει τῶν τε ἐξ Ἠπείρου καὶ τῶν Ταραντίνων, ὧν μὲν εἶχε τὰ βιβλία ἀνεγίνωσκεν οὐδέν, ὁ δὲ ἥξειν συμμαχίαν ἔλεγε. ταχὺ δὲ καὶ ἐς τοὺς Ῥωμαίους ἦλθε φήμη Μακεδόνας καὶ ἄλλα ἔθνη περαιοῦσθαι τῶν Ἀσιανῶν ἐς τὴν Πύρρου βοήθειαν· Ῥωμαῖοι μὲν δὴ ταῦτα ἀκούοντες ἡσύχαζον, Πύρρος δὲ ὑπὸ τὴν ἐπιοῦσαν περαιοῦται νύκτα πρὸς τὰ ἄκρα τῶν ὀρῶν, ἃ Κεραύνια ὀνομάζουσι.", "st": "1.13"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐν Ἰταλίᾳ πληγὴν ἀναπαύσας τὴν δύναμιν προεῖπεν Ἀντιγόνῳ πόλεμον, ἄλλα τε ποιούμενος ἐγκλήματα καὶ μάλιστα τῆς ἐς Ἰταλίαν βοηθείας διαμαρτίαν. κρατήσας δὲ τήν τε ἰδίαν παρασκευὴν Ἀντιγόνου καὶ τὸ παρ’ αὐτῷ Γαλατῶν ξενικὸν ἐδίωξεν ἐς τὰς ἐπὶ θαλάσσῃ πόλεις, αὐτὸς δὲ Μακεδονίας τε τῆς ἄνω καὶ Θεσσαλῶν ἐπεκράτησε. δηλοῖ δὲ μάλιστα τὸ μέγεθος τῆς μάχης καὶ τὴν Πύρρου νίκην, ὡς παρὰ πολὺ γένοιτο, ⟨τὰ⟩ ἀνατεθέντα ὅπλα τῶν Κελτῶν ἐς [τε] τὸ τῆς Ἀθηνᾶς ἱερὸν τῆς Ἰτωνίας Φερῶν μεταξὺ καὶ Λαρίσης καὶ τὸ ἐπίγραμμα τὸ ἐπ’ αὐτοῖς·<br>τοὺς θυρεοὺς ὁ Μολοσσὸς Ἰτωνίδι δῶρον Ἀθάνᾳ", "st": "1.13"}, {"sp": "N", "t": "Πύρρος ἀπὸ θρασέων ἐκρέμασεν Γαλατᾶν,<br>πάντα τὸν Ἀντιγόνου καθελὼν στρατόν. οὐ μέγα θαῦμα·<br>αἰχματαὶ καὶ νῦν καὶ πάρος Αἰακίδαι.<br>τούτους μὲν δὴ ἐνταῦθα, τῷ δὲ ἐν Δωδώνῃ Διὶ Μακεδόνων ἀνέθηκεν αὐτῶν τὰς ἀσπίδας. ἐπιγέγραπται δὲ καὶ ταύταις·<br>αἵδε ποτ’ Ἀσίδα γαῖαν ἐπόρθησαν πολύχρυσον,<br>αἵδε καὶ Ἕλλασι⟨ν⟩ δουλοσύναν ἔπορον.<br>νῦν δὲ Διὸς ναῶ ποτὶ κίονας ὀρφανὰ κεῖται<br>τᾶς μεγαλαυχήτω σκῦλα Μακεδονίας.<br>Πύρρῳ δὲ Μακεδόνας ἐς ἅπαν μὴ καταστρέψασθαι παρ’ ὀλίγον ὅμως ἥκοντι ἐγένετο Κλεώνυμος αἴτιος,", "st": "1.13"}, {"sp": "N", "t": "ἑτοιμοτέρῳ καὶ ἄλλως ὄντι ἑλέσθαι τὰ ἐν χερσίν. Κλεώνυμος δὲ οὗτος, ὁ τὸν Πύρρον ἀπολιπόντα τὰ Μακεδόνων πείσας ἐς Πελοπόννησον ἐλθεῖν, Λακεδαιμόνιος ὢν Λακεδαιμονίοις στρατὸν ἐς τὴν χώραν πολέμιον ἐπῆγε δι’ αἰτίαν, ἣν ἐγὼ τοῦ γένους ὕστερον τοῦ Κλεωνύμου δηλώσω. Παυσανίου τοῦ περὶ Πλάταιαν τοῖς Ἕλλησιν ἡγησαμένου Πλειστοάναξ υἱὸς ἐγένετο, τοῦ δὲ Παυσανίας, τοῦ δὲ Κλεόμβροτος, ὃς ἐναντία Ἐπαμινώνδᾳ καὶ Θηβαίοις μαχόμενος ἀπέθανεν ἐν Λέκτροις· Κλεομβρότου δὲ Ἀγησίπολις ἦν καὶ Κλεομένης, Ἀγησιπόλιδος δὲ ἄπαιδος τελευτήσαντος Κλεομένης τὴν βασιλείαν ἔσχε.", "st": "1.13"}, {"sp": "N", "t": "Κλεομένει δὲ παῖδες γίνονται πρεσβύτερος μὲν Ἀκρότατος, νεώτερος δὲ Κλεώνυμος. Ἀκρότατον μὲν οὖν πρότερον κατέλαβεν ἡ τελευτή· Κλεομένους δὲ ἀποθανόντος ὕστερον ἐς ἀμφισβήτησιν κατέστη περὶ τῆς ἀρχῆς Ἀρεὺς ὁ Ἀκροτάτου, καὶ Κλεώνυμος ὅτῳ δὴ τρόπῳ μετελθὼν ἐπάγει Πύρρον ἐς τὴν χώραν. Λακεδαιμονίοις δὲ πρὸ μὲν τοῦ ἐν Λεύκτροις οὐδὲν ἐγεγόνει πταῖσμα, ὥστε οὐδὲ συνεχώρουν ἀγῶνί πω κεκρατῆσθαι πεζῷ· Λεωνίδᾳ μὲν γὰρ νικῶντι οὐκ ἔφασαν τοὺς ἑπομένους ἐς τελέαν ἐξαρκέσαι φθορὰν τῶν Μήδων, τὸ δὲ Ἀθηναίων καὶ Δημοσθένους ἔργον πρὸς τῇ νήσῳ Σφακτηρίᾳ κλοπὴν εἶναι πολέμου καὶ οὐ νίκην.", "st": "1.13"}, {"sp": "N", "t": "πρώτης δὲ γενομένης σφίσι συμφορᾶς ἐν Βοιωτοῖς, ὕστερον Ἀντιπάτρῳ καὶ Μακεδόσι μεγάλως προσέπταισαν· τρίτος δὲ ὁ Δημητρίου πόλεμος κακὸν ἀνέλπιστον ἦλθεν ἐς τὴν γῆν. Πύρρου δὲ ἐσβαλόντος τέταρτον δὴ τότε στρατὸν ὁρῶντες πολέμιον αὐτοί τε παρετάσσοντο καὶ Ἀργείων ἥκοντες καὶ Μεσσηνίων σύμμαχοι· Πύρρος δὲ ὡς ἐπεκράτησεν, ὀλίγου μὲν ἦλθεν ἑλεῖν αὐτοβοεὶ τὴν πόλιν, δῃώσας δὲ τὴν γῆν καὶ λείαν ἐλάσας μικρὸν ἡσύχαζεν. οἱ δὲ ἐς πολιορκίαν εὐτρεπίζοντο, πρότερον ἔτι τῆς Σπάρτης ἐπὶ τοῦ πολέμου τοῦ πρὸς Δημήτριον τάφροις τε βαθείαις καὶ σταυροῖς τετειχισμένης ἰσχυροῖς, τὰ δὲ ἐπιμαχώτατα καὶ οἰκοδομήμασιν.", "st": "1.13"}, {"sp": "N", "t": "ὑπὸ δὲ τοῦτον τὸν χρόνον καὶ τὴν τοῦ πολέμου τοῦ Λακωνικοῦ τριβὴν Ἀντίγονος τὰς πόλεις τῶν Μακεδόνων ἀνασωσάμενος ἠπείγετο ἐς Πελοπόννησον οἷα ἐπιστάμενος Πύρρον, ἢν Λακεδαίμονα καταστρέψηται καὶ Πελοποννήσου ⟨τὰ⟩ πολλά, οὐκ ἐς Ἤπειρον ἀλλ’ ἐπί τε Μακεδονίαν αὖθις καὶ τὸν ἐκεῖ πόλεμον ἥξοντα· μέλλοντος δὲ Ἀντιγόνου τὸν στρατὸν ἐξ Ἄργους ἐς τὴν Λακωνικὴν ἄγειν, αὐτὸς ἐς τὸ Ἄργος ἐληλύθει Πύρρος. κρατῶν δὲ καὶ τότε συνεσπίπτει τοῖς φεύγουσιν ἐς τὴν πόλιν καί οἱ διαλύεται κατὰ τὸ εἰκὸς ἡ τάξις·", "st": "1.13"}, {"sp": "N", "t": "μαχομένων δὲ πρὸς ἱεροῖς ἤδη καὶ οἰκίαις καὶ κατὰ τοὺς στενωποὺς καὶ κατ’ ἄλλο ἄλλων τῆς πόλεως, ἐνταῦθα ὁ Πύρρος ἐμονώθη καὶ τιτρώσκεται τὴν κεφαλήν. κεράμῳ δὲ βληθέντα ὑπὸ γυναικὸς τεθνάναι φασὶ Πύρρον· Ἀργεῖοι δὲ οὐ γυναῖκα τὴν ἀποκτείνασαν, Δήμητρα δέ φασιν εἶναι γυναικὶ εἰκασμένην. ταῦτα ἐς τὴν Πύρρου τελευτὴν αὐτοὶ λέγουσιν Ἀργεῖοι καὶ ὁ τῶν ἐπιχωρίων ἐξηγητὴς Λυκέας ἐν ἔπεσιν εἴρηκε· καί σφισιν ἔστι τοῦ θεοῦ χρήσαντος, ἔνθα ὁ Πύρρος ἐτελεύτησεν, ἱερὸν Δήμητρος·", "st": "1.13"}, {"sp": "N", "t": "ἐν δὲ αὐτῷ καὶ ὁ Πύρρος τέθαπται. θαῦμα δὴ ποιοῦμαι τῶν καλουμένων Αἰακιδῶν τρισὶ κατὰ τὰ αὐτὰ ἐκ τοῦ θεοῦ συμβῆναι τὴν τελευτήν, εἴ γε Ἀχιλλέα μὲν Ὅμηρος ὑπὸ Ἀλεξάνδρου φησὶ τοῦ Πριάμου καὶ Ἀπόλλωνος ἀπολέσθαι, Πύρρον δὲ τὸν Ἀχιλλέως ἡ Πυθία προσέταξεν ἀποκτεῖναι Δελφοῖς, τῷ δὲ Αἰακίδου συνέβη τὰ ἐς τὴν τελευτὴν οἷα Ἀργεῖοί τε λέγουσι καὶ Λυκέας ἐποίησε. διάφορα δὲ ὅμως ἐστὶ καὶ ταῦτα ὧν Ἱερώνυμος ὁ Καρδιανὸς ἔγραψεν· ἀνδρὶ γὰρ βασιλεῖ συνόντα ἀνάγκη πᾶσα ἐς χάριν συγγράφειν. εἰ δὲ καὶ Φίλιστος αἰτίαν δικαίαν εἴληφεν, ἐπελπίζων τὴν ἐν Συρακούσαις κάθοδον, ἀποκρύψασθαι τῶν Διονυσίου τὰ ἀνοσιώτατα, ἦ που πολλή γε Ἱερωνύμῳ συγγνώμη τὰ ἐς ἡδονὴν Ἀντιγόνου γράφειν.", "st": "1.13"}, {"sp": "N", "t": "ἡ μὲν Ἠπειρωτῶν ἀκμὴ κατέστρεψεν ἐς τοῦτο· ἐς δὲ τὸ Ἀθήνῃσιν ἐσελθοῦσιν Ὠιδεῖον ἄλλα τε καὶ Διόνυσος κεῖται θέας ἄξιος. πλησίον δέ ἐστι κρήνη, καλοῦσι δὲ αὐτὴν Ἐννεάκρουνον, οὕτω κοσμηθεῖσαν ὑπὸ Πεισιστράτου· φρέατα μὲν γὰρ καὶ διὰ πάσης τῆς πόλεώς ἐστι, πηγὴ δὲ αὕτη μόνη. ναοὶ δὲ ὑπὲρ τὴν κρήνην ὁ μὲν Δήμητρος πεποίηται καὶ Κόρης, ἐν δὲ τῷ Τριπτολέμου κείμενόν ἐστιν ἄγαλμα· τὰ δὲ ἐς αὐτὸν ὁποῖα λέγεται γράψω, παρεὶς ὁπόσον ἐς Δηιόπην ἔχει τοῦ λόγου.", "st": "1.14"}, {"sp": "N", "t": "Ἑλλήνων οἱ μάλιστα ἀμφισβητοῦντες Ἀθηναίοις ἐς ἀρχαιότητα καὶ δῶρα, ⟨ἃ⟩ παρὰ θεῶν φασὶν ἔχειν, εἰσὶν Ἀργεῖοι, καθάπερ βαρβάρων Φρυξὶν Αἰγύπτιοι. λέγεται οὖν ὡς Δήμητρα ἐς Ἄργος ἐλθοῦσαν Πελασγὸς δέξαιτο οἴκῳ καὶ ὡς Χρυσανθὶς τὴν ἁρπαγὴν ἐπισταμένη τῆς Κόρης διηγήσαιτο· ὕστερον δὲ Τροχίλον ἱεροφάντην φυγόντα ἐξ Ἄργους κατὰ ἔχθος Ἀγήνορος ἐλθεῖν φασιν ἐς τὴν Ἀττικὴν καὶ γυναῖκά τε ἐξ Ἐλευσῖνος γῆμαι καὶ γενέσθαι οἱ παῖδας Εὐβουλέα καὶ Τριπτόλεμον. ὅδε μὲν Ἀργείων ἐστὶ λόγος Ἀθηναῖοι δὲ καὶ ὅσοι παρὰ τούτοις … ἴσασι Τριπτόλεμον τὸν Κελεοῦ πρῶτον σπεῖραι καρπὸν ἥμερον.", "st": "1.14"}, {"sp": "N", "t": "ἔπη δὲ ᾄδεται Μουσαίου μέν, εἰ δὴ Μουσαίου καὶ ταῦτα, Τριπτόλεμον παῖδα Ὠκεανοῦ καὶ Γῆς εἶναι, Ὀρφέως δέ, οὐδὲ ταῦτα Ὀρφέως ἐμοὶ δοκεῖν ὄντα, Εὐβουλεῖ καὶ Τριπτολέμῳ Δυσαύλην πατέρα εἶναι, μηνύσασι δέ σφισι περὶ τῆς παιδὸς δοθῆναι παρὰ Δήμητρος σπεῖραι τοὺς καρπούς· Χοιρίλῳ δὲ Ἀθηναίῳ δρᾶμα ποιήσαντι Ἀλόπην ἔστ⟨ιν⟩ εἰρημένα Κερκυόνα εἶναι καὶ Τριπτόλεμον ἀδελφούς, τεκεῖν δὲ σφᾶς θυγατέρα[ς] Ἀμφικτύονος, εἶναι δὲ πατέρα Τριπτολέμῳ μὲν Ῥᾶρον, Κερκυόνι δὲ Ποσειδῶνα. πρόσω δὲ ἰέναι με ὡρμημένον τοῦδε τοῦ λόγου καὶ †ὁπόσα ἐξήγησιν †ἔχει τὸ Ἀθήνῃσιν ἱερόν, καλούμενον δὲ Ἐλευσίνιον, ἐπέσχεν ὄψις ὀνείρατος· ἃ δὲ ἐς πάντας ὅσιον γράφειν, ἐς ταῦτα ἀποτρέψομαι.", "st": "1.14"}, {"sp": "N", "t": "πρὸ τοῦ ναοῦ τοῦδε, ἔνθα καὶ τοῦ Τριπτολέμου τὸ ἄγαλμα, ἔστι βοῦς χαλκοῦς οἷα ἐς θυσίαν ἀγόμενος, πεποίηται δὲ καθήμενος Ἐπιμενίδης Κνώσσιος, ὃν ἐλθόντα ἐς ἀγρὸν κοιμᾶσθαι λέγουσιν ἐσελθόντα ἐς σπήλαιον· ὁ δὲ ὕπνος οὐ πρότερον ἀνῆκεν αὐτὸν πρὶν ἤ οἱ τεσσαρακοστὸν ἔτος γενέσθαι καθεύδοντι, καὶ ὕστερον ἔπη τε ἐποίει καὶ πόλεις ἐκάθηρεν ἄλλας τε καὶ τὴν Ἀθηναίων. Θάλης δὲ ὁ Λακεδαιμονίοις τὴν νόσον παύσας οὔτε ἄλλως προσήκων οὔτε πόλεως ἦν Ἐπιμενίδῃ τῆς αὐτῆς· ἀλλ’ ὁ μὲν Κνώσσιος, Θάλητα δὲ εἶναί φησι Γορτύνιον Πολύμναστος Κολοφώνιος ἔπη Λακεδαιμονίοις ἐς αὐτὸν ποιήσας.", "st": "1.14"}, {"sp": "N", "t": "—ἔτι δὲ ἀπωτέρω ναὸς Εὐκλείας, ἀνάθημα καὶ τοῦτο ἀπὸ Μήδων, οἳ τῆς χώρας Μαραθῶνι ἔσχον. φρονῆσαι δὲ Ἀθηναίους ἐπὶ τῇ νίκῃ ταύτῃ μάλιστα εἰκάζω· καὶ δὴ καὶ Αἰσχύλος, ὥς οἱ τοῦ βίου προσεδοκᾶτο ἡ τελευτή, τῶν μὲν ἄλλων ἐμνημόνευσεν οὐδενός, δόξης ἐς τ⟨οσ⟩οῦτο ἥκων ἐπὶ ποιήσει καὶ πρὸ Ἀρτεμισίου καὶ ἐν Σαλαμῖνι ναυμαχήσας· ὁ δὲ τό τε ὄνομα πατρόθεν καὶ τὴν πόλιν ἔγραψε καὶ ὡς τῆς ἀνδρίας μάρτυρας ἔχοι τὸ Μαραθῶνι ἄλσος καὶ Μήδων τοὺς ἐς αὐτὸ ἀποβάντας.", "st": "1.14"}, {"sp": "N", "t": "ὑπὲρ δὲ τὸν Κεραμεικὸν καὶ στοὰν τὴν καλουμένην Βασίλειον ναός ἐστιν Ἡφαίστου. καὶ ὅτι μὲν ἄγαλμά οἱ παρέστηκεν Ἀθηνᾶς, οὐδὲν θαῦμα ἐποιούμην τὸν ἐπὶ Ἐριχθονίῳ ἐπιστάμενος λόγον· τὸ δὲ ἄγαλμα ὁρῶν τῆς Ἀθηνᾶς γλαυκοὺς ἔχον τοὺς ὀφθαλμοὺς Λιβύων τὸν μῦθον ὄντα εὕρισκον· τούτοις γάρ ἐστιν εἰρημένον Ποσειδῶνος καὶ λίμνης Τριτωνίδος θυγατέρα εἶναι καὶ διὰ τοῦτο γλαυκοὺς εἶναι ὥσπερ καὶ τῷ Ποσειδῶνι ⟨τοὺς⟩ ὀφθαλμούς.", "st": "1.14"}, {"sp": "N", "t": "πλησίον δὲ ἱερόν ἐστιν Ἀφροδίτης Οὐρανίας. πρώτοις δὲ ἀνθρώπων Ἀσσυρίοις κατέστη σέβεσθαι τὴν Οὐρανίαν, μετὰ δὲ Ἀσσυρίους Κυπρίων Παφίοις καὶ Φοινίκων τοῖς Ἀσκάλωνα ἔχουσιν ἐν τῇ Παλαιστίνῃ, παρὰ δὲ Φοινίκων Κυθήριοι μαθόντες σέβουσιν· Ἀθηναίοις δὲ κατεστήσατο Αἰγεύς, αὑτῷ τε οὐκ εἶναι παῖδας νομίζων—οὐ γάρ πω τότε ἦσαν— καὶ ταῖς ἀδελφαῖς γενέσθαι τὴν συμφορὰν ἐκ μηνίματος τῆς Οὐρανίας. τὸ δὲ ἐφ’ ἡμῶν ἔτι ἄγαλμα λίθου Παρίου καὶ ἔργον Φειδίου· δῆμος δέ ἐστιν Ἀθηναίοις Ἀθμονέων, οἳ Πορφυρίωνα ἔτι πρότερον Ἀκταίου βασιλεύσαντα τῆς Οὐρανίας φασὶ τὸ παρὰ σφίσιν ἱερὸν ἱδρύσασθαι. λέγουσι δὲ ἀνὰ τοὺς δήμους καὶ ἄλλα οὐδὲν ὁμοίως καὶ οἱ τὴν πόλιν ἔχοντες.", "st": "1.14"}, {"sp": "N", "t": "ἰοῦσι δὲ πρὸς τὴν στοάν, ἣν Ποικίλην ὀνομάζουσιν ἀπὸ τῶν γραφῶν, ἔστιν Ἑρμῆς χαλκοῦς καλούμενος Ἀγοραῖος καὶ πύλη πλησίον· ἔπεστι δέ οἱ τρόπαιον Ἀθηναίων ἱππομαχίᾳ κρατησάντων Πλείσταρχον, ὃς τῆς ἵππου Κασσάνδρου καὶ τοῦ ξενικοῦ τὴν ἀρχὴν ἀδελφὸς ὢν ἐπετέτραπτο. αὕτη δὲ ἡ στοὰ πρῶτα μὲν Ἀθηναίους ἔχει τεταγμένους ἐν Οἰνόῃ τῆς Ἀργεία; ἐναντία Λακεδαιμονίων· γέγραπται δὲ οὐκ ἐς ἀκμὴν ἀγῶνος οὐδὲ τολμημάτων ἐς ἐπίδειξιν τὸ ἔργον ἤδη προῆκον, ἀλλὰ ἀρχομένη τε ἡ μάχη καὶ ἐς χεῖρας ἔτι συνιόντες.", "st": "1.15"}, {"sp": "N", "t": "ἐν δὲ τῷ μέσῳ τῶν τοίχων Ἀθηναῖοι καὶ Θησεὺς Ἀμαζόσι μάχονται. μόναις δὲ ἄρα ταῖς γυναιξὶν οὐκ ἀφῄρει τὰ πταίσματα τὸ ἐς τοὺς κινδύνους ἀφειδές, εἴ γε Θεμισκύρας τε ἁλούσης ὑπὸ Ἡρακλέους καὶ ὕστερον φθαρείσης σφίσι τῆς στρατιᾶς, ἣν ἐπ’ Ἀθήνας ἔστειλαν, ὅμως ἐς Τροίαν ἦλθον Ἀθηναίοις τε αὐτοῖς μαχούμεναι καὶ τοῖς πᾶσιν Ἕλλησιν. ἐπὶ δὲ ταῖς Ἀμαζόσιν Ἕλληνές εἰσιν ᾑρηκότες Ἴλιον καὶ οἱ βασιλεῖς ἠθροισμένοι διὰ τὸ Αἴαντος ἐς Κασσάνδραν τόλμημα· καὶ αὐτὸν ἡ γραφὴ τὸν Αἴαντα ἔχει καὶ γυναῖκας τῶν αἰχμαλώτων ἄλλας τε καὶ Κασσάνδραν.", "st": "1.15"}, {"sp": "N", "t": "τελευταῖον δὲ τῆς γραφῆς εἰσιν οἱ μαχεσάμενοι Μαραθῶνι· Βοιωτῶν δὲ οἱ Πλάταιαν ἔχοντες καὶ ὅσον ἦν Ἀττικὸν ἴασιν ἐς χεῖρας τοῖς βαρβάροις. καὶ ταύτῃ μέν ἐστιν ἴσα ⟨τὰ⟩ παρ’ ἀμφοτέρων ἐς τὸ ἔργον· τὸ δὲ ἔσω τῆς μάχης φεύγοντές εἰσιν οἱ βάρβαροι καὶ ἐς τὸ ἕλος ὠθοῦντες ἀλλήλους, ἔσχαται δὲ τῆς γραφῆς νῆές τε αἱ Φοίνισσαι καὶ τῶν βαρβάρων τοὺς ἐσπίπτοντας ἐς ταύτας φονεύοντες οἱ Ἕλληνες. ἐνταῦθα καὶ Μαραθὼν γεγραμμένος ἐστὶν ἥρως, ἀφ’ οὗ τὸ πεδίον ὠνόμασται, καὶ Θησεὺς ἀνιόντι ἐκ γῆς εἰκασμένος Ἀθηνᾶ τε καὶ Ἡρακλῆς· Μαραθωνίοις γάρ, ὡς αὐτοὶ λέγουσιν, Ἡρακλῆς ἐνομίσθη θεὸς πρώτοις. τῶν μαχομένων δὲ δῆλοι μάλιστά εἰσιν ἐν τῇ γραφῇ Καλλίμαχός τε, ὃς Ἀθηναίοις πολεμαρχεῖν ᾕρητο, καὶ Μιλτιάδης τῶν στρατηγούντων, ἥρως τε Ἔχετλος καλούμενος, οὗ καὶ ὕστερον ποιήσομαι μνήμην.", "st": "1.15"}, {"sp": "N", "t": "ἐνταῦθα ἀσπίδες κεῖνται χαλκαῖ, καὶ ταῖς μέν ἐστιν ἐπίγραμμα ἀπὸ ⟨Σ⟩κιωναίων καὶ τῶν ἐπικούρων εἶναι, τὰς δὲ ἐπαληλιμμένας πίσσῃ, μὴ σφᾶς ὅ τε χρόνος λυμήνηται καὶ ⟨ὁ⟩ ἰός, Λακεδαιμονίων εἶναι λέγεται τῶν ἁλόντων ἐν τῇ Σφακτηρίᾳ νήσῳ.", "st": "1.15"}, {"sp": "N", "t": "ἀνδριάντες δὲ χαλκοῖ κεῖνται πρὸ μὲν τῆς στοᾶς Σόλων ὁ τοὺς νόμους Ἀθηναίοις γράψας, ὀλίγον δὲ ἀπωτέρω Σέλευκος, ᾧ καὶ πρότερον ἐγένετο ἐς τὴν εὐδαιμονίαν τὴν μέλλουσαν σημεῖα οὐκ ἀφανῆ. Σελεύκῳ γάρ, ὡς ὡρμᾶτο ἐκ Μακεδονίας σὺν Ἀλεξάνδρῳ, θύοντι ἐν Πέλλῃ τῷ Διὶ τὰ ξύλα ⟨τὰ⟩ ἐπὶ τοῦ βωμοῦ κείμενα προύβη τε αὐτόματα πρὸς τὸ ἄγαλμα καὶ ἄνευ πυρὸς ἥφθη. τελευτήσαντος δὲ Ἀλεξάνδρου Σέλευκος Ἀντίγονον ἐς Βαβυλῶνα ἀφικόμενον δείσας καὶ παρὰ Πτολεμαῖον φυγὼν τὸν Λάγου κατῆλθεν αὖθις ἐς Βαβυλῶνα, κατελθὼν δὲ ἐκράτησε μὲν τῆς Ἀντιγόνου στρατιᾶς καὶ αὐτὸν ἀπέκτεινεν Ἀντίγονον, εἷλε δὲ ἐπιστρατεύσαντα ὕστερον Δημήτριον τὸν Ἀντιγόνου.", "st": "1.16"}, {"sp": "N", "t": "ὡς δέ οἱ ταῦτα προκεχωρήκει καὶ μετ’ ὀλίγον τὰ Λυσιμάχου κατείργαστο, τὴν μὲν ἐν τῇ Ἀσίᾳ πᾶσαν ἀρχὴν παρέδωκεν Ἀντιόχῳ τῷ παιδί, αὐτὸς δὲ ἐς Μακεδονίαν ἠπείγετο. στρατιὰ μὲν καὶ Ἑλλήνων καὶ βαρβάρων ἦν παρὰ Σελεύκῳ· Πτολεμαῖος δὲ ἀδελφὸς μὲν Λυσάνδρας καὶ παρὰ Λυσιμάχου παρ’ αὐτὸν πεφευγώς, ἄλλως δὲ τολμῆσαι πρόχειρος καὶ δι’ αὐτὸ Κεραυνὸς καλούμενος, οὗτος ὁ Πτολεμαῖος, ὡς προσιὼν ὁ Σελεύκου στρατὸς ἐγένετο κατὰ Λυσιμάχειαν, λαθὼν Σέλευκον κτείνει, διαρπάσαι δὲ ἐπιτρέψας τὰ χρήματα τοῖς βασιλεῦσιν ἐβασίλευσε Μακεδονίας, ἐς ὃ Γαλάταις πρῶτος ὧν ἴσμεν βασιλέων ἀντιτάξασθαι τολμήσας ἀναιρεῖται ὑπὸ τῶν βαρβάρων· τὴν δὲ ἀρχὴν Ἀντίγονος ἀνεσώσατο ὁ Δημητρίου.", "st": "1.16"}, {"sp": "N", "t": "Σέλευκον δὲ βασιλέων ἐν τοῖς μάλιστα πείθομαι καὶ ἄλλως γενέσθαι δίκαιον καὶ πρὸς τὸ θεῖον εὐσεβῆ. τοῦτο μὲν γὰρ Σέλευκός ἐστιν ὁ Μιλησίοις τὸν χαλκοῦν καταπέμψας Ἀπόλλωνα ἐς Βραγχίδας, ἀνακομισθέντα ἐς Ἐκβάτανα τὰ Μηδικὰ ὑπὸ Ξέρξου· τοῦτο δὲ Σελεύκειαν οἰκίσας ἐπὶ Τίγρητι ποταμῷ καὶ Βαβυλωνίους οὗτος ἐπαγόμενος ἐς αὐτὴν συνοίκους ὑπελ[ε]ίπετο μὲν τὸ τεῖχος Βαβυλῶνος, ὑπελ[ε]ίπετο δὲ. τοῦ Βὴλ τὸ ἱερὸν καὶ περὶ αὐτὸ τοὺς Χαλδαίους οἰκεῖν.", "st": "1.16"}, {"sp": "N", "t": "Ἀθηναίοις δὲ ἐν τῇ ἀγορᾷ καὶ ἄλλα ἐστὶν οὐκ ἐς ἅπαντας ἐπίσημα καὶ Ἐλέου βωμός, ᾧ μάλιστα θεῶν ἐς ἀνθρώπινον βίον καὶ μεταβολὰς πραγμάτων ὄντι ὠφελίμῳ μόνοι τιμὰς Ἑλλήνων νέμουσιν Ἀθηναῖοι. τούτοις δὲ οὐ τὰ ἐς φιλανθρωπίαν μόνον καθέστηκεν, ἀλλὰ καὶ θεοὺς εὐσεβοῦσιν ἄλλων πλέον, καὶ γὰρ Αἰδοῦς σφισι βωμός ἐστι καὶ Φήμης καὶ Ὁρμῆς· δῆλά τε ἐναργῶς, ὅσοις πλέον τι ἑτέρων εὐσεβείας μέτεστιν, ἴσον σφίσι παρὸν τύχης χρηστῆς.", "st": "1.17"}, {"sp": "N", "t": "ἐν δὲ τῷ γυμνασίῳ τῆς ἀγορᾶς ἀπέχοντι οὐ πολύ, Πτολεμαίου δὲ ἀπὸ τοῦ κατασκευασαμένου καλουμένῳ, λίθοι τέ εἰσιν Ἑρμαῖ θέας ἄξιοι καὶ εἰκὼν Πτολεμαίου χαλκῆ· καὶ ὅ τε Λίβυς Ἰόβας ἐνταῦθα κεῖται καὶ [ὁ] Χρύσιππος ὁ Σολεύς. πρὸς δὲ τῷ γυμνασίῳ Θησέως ἐστὶν ἱερόν· γραφαὶ δέ εἰσι πρὸς Ἀμαζόνας Ἀθηναῖοι μαχόμενοι. πεποίηται δέ σφισιν ὁ πόλεμος οὗτος καὶ τῇ Ἀθηνᾷ ἐπὶ τῇ ἀσπίδι καὶ τοῦ Ὀλυμπίου Διὸς ἐπὶ τῷ βάθρῳ. γέγραπται δὲ ἐν τῷ τοῦ Θησέως ἱερῷ καὶ ἡ Κενταύρων καὶ [ἡ] Λαπιθῶν μάχη· Θησεὺς μὲν οὖν ἀπεκτονώς ἐστιν ἤδη Κένταυρον, τοῖς δὲ ἄλλοις ἐξ ἴσου καθέστηκεν ἔτι ἡ μάχη.", "st": "1.17"}, {"sp": "N", "t": "τοῦ δὲ τρίτου τῶν τοίχων ἡ γραφὴ μὴ πυθομένοις ἃ λέγουσιν οὐ σαφής ἐστι, τὰ μέν που διὰ τὸν χρόνον, τὰ δὲ Μίκων οὐ τὸν πάντα ἔγραψε λόγον. Μίνως ἡνίκα Θησέα καὶ τὸν ἄλλον στόλον τῶν παίδων ἦγεν ἐς Κρήτην, ἐρασθεὶς Περιβοίας, ὥς οἱ Θησεὺς μάλιστα ἠναντιοῦτο, καὶ ἄλλα ὑπὸ ὀργῆς ἀπέρριψεν ἐς αὐτὸν καὶ παῖδα οὐκ ἔφη Ποσειδῶνος εἶναι, ἐπεὶ ⟨οὐ⟩ δύνασθαι τὴν σφραγῖδα, ἣν αὐτὸς φέρων ἔτυχεν, ἀφέντι ἐς θάλασσαν ἀνασῶσαί οἱ. Μίνως μὲν λέγεται ταῦτα εἰπὼν ἀφεῖναι τὴν σφραγῖδα· Θησέα δὲ σφραγῖδά τε ἐκείνην ἔχοντα καὶ στέφανον χρυσοῦν, Ἀμφιτρίτης δῶρον, ἀνελθεῖν λέγουσιν ἐκ τῆς θαλάσσης.", "st": "1.17"}, {"sp": "N", "t": "ἐς δὲ τὴν τελευτὴν τὴν Θησέως πολλὰ ἤδη καὶ οὐχ ὁμολογοῦντα εἴρηται· δεδέσθαι τε γὰρ αὐτὸν λέγουσιν ἐς τόδε ἕως ὑφ’ Ἡρακλέους ἀναχθείη, πιθανώτατα δὲ ὧν ἤκουσα· Θησεὺς ἐς Θεσπρωτοὺς ἐμβαλών, τοῦ βασιλέως τῶν Θεσπρωτῶν γυναῖκα ἁρπάσων, τὸ πολὺ τῆς στρατιᾶς οὕτως ἀπόλλυσι, καὶ αὐτός τε καὶ Πειρίθους— Πειρίθους γὰρ καὶ τὸν γάμον σπεύδων ἐστράτευεν— ἥλωσαν, καὶ σφᾶς ὁ Θεσπρωτὸς δήσας εἶχεν ἐν Κιχύρῳ.", "st": "1.17"}, {"sp": "N", "t": "γῆς δὲ τῆς Θεσπρωτίδος ἔστι μέν που καὶ ἄλλα θέας ἄξια, ἱερόν τε Διὸς ἐν Δωδώνῃ καὶ ἱερὰ τοῦ θεοῦ φηγός· πρὸς δὲ τῇ Κιχύρῳ λίμνη τέ ἐστιν Ἀχερουσία καλουμένη καὶ ποταμὸς Ἀχέρων, ῥεῖ δὲ καὶ Κωκυτὸς ὕδωρ ἀτερπέστατον. Ὅμηρός τέ μοι δοκεῖ ταῦτα ἑωρακὼς ἔς τε τὴν ἄλλην ποίησιν ἀποτολμῆσαι τῶν ἐν Ἅιδου καὶ δὴ καὶ τὰ ὀνόματα τοῖς ποταμοῖς ἀπὸ τῶν ἐν Θεσπρωτίδι θέσθαι. τότε δὲ ἐχομένου Θησέως στρατεύουσιν ἐς Ἄφιδναν οἱ Τυνδάρεω παῖδες καὶ τήν τε Ἄφιδναν αἱροῦσι καὶ Μενεσθέα ἐπὶ βασιλείᾳ κατήγαγον·", "st": "1.17"}, {"sp": "N", "t": "Μενεσθεὺς δὲ τῶν μὲν παίδων τῶν Θησέως παρ’ Ἐλεφήνορα ὑπεξελθόντων ἐς Εὔβοιαν εἶχεν οὐδένα λόγον, Θησέα δέ, εἴ ποτε παρὰ Θεσπρωτῶν ἀνακομισθήσεται, δυσανταγώνιστον ἡγούμενος διὰ θεραπείας τὰ τοῦ δήμου καθίστατο, ὡς Θησέα ἀνασωθέντα ὕστερον ἀπωσθῆναι. στέλλεται δὴ Θησεὺς παρὰ Δευκαλίωνα ἐς Κρήτην, ἐξενεχθέντα δὲ αὐτὸν ὑπὸ πνευμάτων ἐς Σκῦρον τὴν νῆσον λαμπρῶς περιεῖπον οἱ Σκύριοι κατὰ γένους δόξαν καὶ ἀξίωμα ὧν ἦν αὐτὸς εἰργασμένος· καί οἱ θάνατον Λυκομήδης διὰ ταῦτα ἐβούλευσεν. ὁ μὲν δὴ Θησέως σηκὸς Ἀθηναίοις ἐγένετο ὕστερον ἢ Μῆδοι Μαραθῶνι ἔσχον, Κίμωνος τοῦ Μιλτιάδου Σκυρίους ποιήσαντος ἀναστάτους—δίκην δὴ τοῦ Θησέως θανάτου—καὶ τὰ ὀστᾶ κομίσαντος ἐς Ἀθήνας·", "st": "1.17"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τῶν Διοσκούρων ἐστὶν ἀρχαῖον, αὐτοί τε ἑστῶτες καὶ οἱ παῖδες καθήμενοί σφισιν ἐφ’ ἵππων. ἐνταῦθα Πολύγνωτος μὲν ἔχοντα ἐς αὐτοὺς ἔγραψε γάμον τῶν θυγατέρων τῶν Λευκίππου, Μίκων δὲ τοὺς μετὰ Ἰάσονος ἐς Κόλχους πλεύσαντας· καί οἱ τῆς γραφῆς ἡ σπουδὴ μάλιστα ἐς Ἄκαστον καὶ τοὺς ἵππους ἔχει τοὺς Ἀκάστου.", "st": "1.18"}, {"sp": "N", "t": "ὑπὲρ δὲ τῶν Διοσκούρων τὸ ἱερὸν Ἀγλαύρου τέμενός ἐστιν. Ἀγλαύρῳ δὲ καὶ ταῖς ἀδελφαῖς Ἕρσῃ καὶ Πανδρόσῳ δοῦναί φασιν Ἀθηνᾶν Ἐριχθόνιον καταθεῖσαν ἐς κιβωτόν, ἀπειποῦσαν ἐς τὴν παρακαταθήκην μὴ πολυπραγμονεῖν· Πάνδροσον μὲν δὴ λέγουσι πείθεσθαι, τὰς δὲ δύο—ἀνοῖξαι γὰρ σφᾶς τὴν κιβωτόν—μαίνεσθαί τε, ὡς εἶδον τὸν Ἐριχθόνιον, καὶ κατὰ τῆς ἀκροπόλεως, ἔνθα ἦν μάλιστα ἀπότομον, αὑτὰς ῥῖψαι. κατὰ τοῦτο ἐπαναβάντες Μῆδοι κατεφόνευσαν Ἀθηναίων τοὺς πλέον τι ἐς τὸν χρησμὸν ἢ Θεμιστοκλῆς εἰδέναι νομίζοντας καὶ τὴν ἀκρόπολιν ξύλοις καὶ σταυροῖς ἀποτειχίσαντας.", "st": "1.18"}, {"sp": "N", "t": "πλησίον δὲ πρυτανεῖόν ἐστιν, ἐν ᾧ νόμοι τε οἱ Σόλωνός εἰσι γεγραμμένοι καὶ θεῶν Εἰρήνης ἀγάλματα κεῖται καὶ Ἑστίας, ἀνδριάντες δὲ ἄλλοι τε καὶ Αὐτόλυκος ὁ παγκρατιαστής· τὰς γὰρ Μιλτιάδου καὶ Θεμιστοκλέους εἰκόνας ἐς Ῥωμαῖόν τε ἄνδρα καὶ Θρᾷκα μετέγραψαν.", "st": "1.18"}, {"sp": "N", "t": "ἐντεῦθεν ἰοῦσιν ἐς τὰ κάτω τῆς πόλεως Σαράπιδός ἐστιν ἱερόν, ὃν Ἀθηναῖοι παρὰ Πτολεμαίου θεὸν ἐσηγάγοντο. Αἰγυπτίοις δὲ ἱερὰ Σαράπιδος ἐπιφανέστατον μέν ἐστιν Ἀλεξανδρεῦσιν, ἀρχαιότατον δὲ ἐν Μέμφει· ἐς τοῦτο ἐσελθεῖν οὔτε ξένοις ἔστιν οὔτε τοῖς ἱερεῦσι, πρὶν ἂν τὸν Ἆπιν θάπτωσι. τοῦ δὲ ἱεροῦ τοῦ Σαράπιδος οὐ πόρρω χωρίον ἐστίν, ἔνθα Πειρίθουν καὶ Θησέα συνθεμένους ἐς Λακεδαίμονα καὶ ὕστερον ἐς Θεσπρωτοὺς σταλῆναι λέγουσι.", "st": "1.18"}, {"sp": "N", "t": "πλησίον δὲ ᾠκοδόμητο ναὸς Εἰλειθυίας, ἣν ἐλθοῦσαν ἐξ Ὑπερβορέων ἐς Δῆλον γενέσθαι βοηθὸν ταῖς Λητοῦς ὠδῖσι, τοὺς δὲ ἄλλους παρ’ αὐτῶν φασι τῆς Εἰλειθυίας μαθεῖν τὸ ὄνομα· καὶ θύουσί τε Εἰλειθυίᾳ Δήλιοι καὶ ὕμνον ᾄδουσιν Ὠλῆνος. Κρῆτες δὲ χώρας τῆς Κνωσσίας ἐν Ἀμνισῷ γενέσθαι νομίζουσιν Εἰλείθυιαν καὶ παῖδα Ἥρας εἶναι· μόνοις δὲ Ἀθηναίοις τῆς Εἰλειθυίας κεκάλυπται τὰ ξόανα ἐς ἄκρους τοὺς πόδας. τὰ μὲν δὴ δύο εἶναι Κρητικὰ καὶ Φαίδρας ἀναθήματα ἔλεγον αἱ γυναῖκες, τὸ δὲ ἀρχαιότατον Ἐρυσίχθονα ἐκ Δήλου κομίσαι.", "st": "1.18"}, {"sp": "N", "t": "πρὶν δὲ ἐς τὸ ἱερὸν ἰέναι τοῦ Διὸς τοῦ Ὀλυμπίου —Ἀδριανὸς ὁ Ῥωμαίων βασιλεὺς τόν τε ναὸν ἀνέθηκε καὶ τὸ ἄγαλμα θέας ἄξιον, οὗ μεγέθει μέν, ὅτι μὴ Ῥοδίοις καὶ Ῥωμαίοις εἰσὶν οἱ κολοσσοί, τὰ λοιπὰ ἀγάλματα ὁμοίως ἀπολείπεται, πεποίηται δὲ ἔκ τε ἐλέφαντος καὶ χρυσοῦ καὶ ἔχει τέχνης εὖ πρὸς τὸ μέγεθος ὁρῶσιν—, ἐνταῦθα εἰκόνες Ἀδριανοῦ δύο μέν εἰσι Θασίου λίθου, δύο δὲ Αἰγυπτίου· χαλκαῖ δὲ ἑστᾶσι πρὸ τῶν κιόνων ἃς Ἀθηναῖοι καλοῦσιν ἀποίκους πόλεις. ὁ μὲν δὴ πᾶς περίβολος σταδίων μάλιστα τεσσάρων ἐστίν, ἀνδριάντων δὲ πλήρης· ἀπὸ γὰρ πόλεως ἑκάστης εἰκὼν Ἀδριανοῦ βασιλέως ἀνάκειται, καὶ σφᾶς ὑπερεβάλοντο Ἀθηναῖοι τὸν κολοσσὸν ἀναθέντες ὄπισθε τοῦ ναοῦ θέας ἄξιον.", "st": "1.18"}, {"sp": "N", "t": "ἔστι δὲ ἀρχαῖα ἐν τῷ περιβόλῳ Ζεὺς χαλκοῦς καὶ ναὸς Κρόνου καὶ Ῥέας καὶ τέμενος ⟨Γῆς⟩ [τὴν] ἐπίκλησιν Ὀλυμπίας. ἐνταῦθα ὅσον ἐς πῆχυν τὸ ἔδαφος διέστηκε, καὶ λέγουσι μετὰ τὴν ἐπομβρίαν τὴν ἐπὶ Δευκαλίωνος συμβᾶσαν ὑπορρυῆναι ταύτῃ τὸ ὕδωρ, ἐσβάλλουσί τε ἐς αὐτὸ ἀνὰ πᾶν ἔτος ἄλφιτα πυρῶν μέλιτι μίξαντες.", "st": "1.18"}, {"sp": "N", "t": "κεῖται δὲ ἐπὶ κίονος Ἰσοκράτους ἀνδριάς, ὃς ἐς μνήμην τρία ὑπελίπετο, ἐπιπονώτατον μὲν ὅτι οἱ βιώσαντι ἔτη δυοῖν δέοντα ἑκατὸν οὔποτε κατελύθη μαθητὰς ἔχειν, σωφρονέστατον δὲ ὅτι πολιτείας ἀπεχόμενος διέμεινε καὶ τὰ κοινὰ οὐ πολυπραγμονῶν, ἐλευθερώτατον δὲ ὅτι πρὸς τὴν ἀγγελίαν τῆς ἐν Χαιρωνείᾳ μάχης ἀλγήσας ἐτελεύτησεν ἐθελοντής. κεῖνται δὲ καὶ λίθου Φρυγίου Πέρσαι χαλκοῦν τρίποδα ἀνέχοντες, θέας ἄξιοι καὶ αὐτοὶ καὶ ὁ τρίπους. τοῦ δὲ Ὀλυμπίου Διὸς Δευκαλίωνα οἰκοδομῆσαι λέγουσι τὸ ἀρχαῖον ἱερόν, σημεῖον ἀποφαίνοντες ὡς Δευκαλίων Ἀθήνῃσιν ᾤκησε τάφον τοῦ ναοῦ τοῦ νῦν οὐ πολὺ ἀφεστηκότα.", "st": "1.18"}, {"sp": "N", "t": "Ἀδριανὸς δὲ κατεσκευάσατο μὲν καὶ ἄλλα Ἀθηναίοις, ναὸν Ἥρας καὶ Διὸς Πανελληνίου καὶ θεοῖς τοῖς πᾶσιν ἱερὸν κοινόν, τὰ δὲ ἐπιφανέστατα ἑκατόν εἰσι κίονες Φρυγίου λίθου· πεποίηνται δὲ καὶ ταῖς στοαῖς κατὰ τὰ αὐτὰ οἱ τοῖχοι. καὶ οἰκήματα ἐνταῦθά ἐστιν ὀρόφῳ τε ἐπιχρύσῳ καὶ ἀλαβάστρῳ λίθῳ, πρὸς δὲ ἀγάλμασι κεκοσμημένα καὶ γραφαῖς· κατάκειται δὲ ἐς αὐτὰ βιβλία. καὶ γυμνάσιόν ἐστιν ἐπώνυμον Ἀδριανοῦ· κίονες δὲ καὶ ἐνταῦθα ἑκατὸν λιθοτομίας τῆς Λιβύων.", "st": "1.18"}, {"sp": "N", "t": "μετὰ δὲ τὸν ναὸν τοῦ Διὸς τοῦ Ὀλυμπίου πλησίον ἄγαλμά ἐστιν Ἀπόλλωνος Πυθίου· ἔστι δὲ καὶ ἄλλο ἱερὸν Ἀπόλλωνος ἐπίκλησιν Δελφινίου. λέγουσι δὲ ὡς ἐξειργασμένου τοῦ ναοῦ πλὴν τῆς ὀροφῆς ἀγνὼς ἔτι τοῖς πᾶσιν ἀφίκοιτο Θησεὺς ἐς τὴν πόλιν· οἷα δὲ χιτῶνα ἔχοντος αὐτοῦ ποδήρη καὶ πεπλεγμένης ἐς εὐπρεπές οἱ τῆς κόμης, ὡς ἐγίνετο κατὰ τὸν τοῦ Δελφινίου ναόν, οἱ τὴν στέγην οἰκοδομοῦντες ἤροντο σὺν χλευασίᾳ, ὅ τι δὴ παρθένος ἐν ὥρᾳ γάμου πλανᾶται μόνη· Θησεὺς δὲ ἄλλο μὲν αὐτοῖς ἐδήλωσεν οὐδέν, ἀπολύσας δὲ ὡς λέγεται τῆς ἁμάξης τοὺς βοῦς, ἥ σφισι παρῆν, [τὸν ὄροφον] ἀνέρριψεν ἐς ὑψηλότερον ἢ τῷ ναῷ τὴν στέγην ἐποιοῦντο.", "st": "1.19"}, {"sp": "N", "t": "—ἐς δὲ τὸ χωρίον, ὃ Κήπους ὀνομάζουσι, καὶ τῆς Ἀφροδίτης τὸν ναὸν οὐδεὶς λεγόμενός σφισίν ἐστι λόγος· οὐ μὴν οὐδὲ ἐς τὴν Ἀφροδίτην, ἣ τοῦ ναοῦ πλησίον ἕστηκε. ταύτης γὰρ σχῆμα μὲν τετράγωνον κατὰ ταὐτὰ καὶ τοῖς Ἑρμαῖς, τὸ δὲ ἐπίγραμμα σημαίνει τὴν Οὐρανίαν Ἀφροδίτην τῶν καλουμένων Μοιρῶν εἶναι πρεσβυτάτην. τὸ δὲ ἄγαλμα τῆς Ἀφροδίτης ⟨τῆς⟩ ἐν [τοῖς] Κήποις ἔργον ἐστὶν Ἀλκαμένους καὶ τῶν Ἀθήνῃσιν ἐν ὀλίγοις θέας ἄξιον.", "st": "1.19"}, {"sp": "N", "t": "ἔστι δὲ Ἡρακλέους ἱερὸν καλούμενον Κυνόσαργες· καὶ τὰ μὲν ἐς τὴν κύνα εἰδέναι τὴν λευκὴν ἐπιλεξαμένοις ἔστι τὸν χρησμόν, βωμοὶ δέ εἰσιν Ἡρακλέους τε καὶ Ἥβης, ἣν Διὸς παῖδα οὖσαν συνοικεῖν Ἡρακλεῖ νομίζουσιν· Ἀλκμήνης τε βωμὸς καὶ Ἰολάου πεποίηται, ὃς τὰ πολλὰ Ἡρακλεῖ συνεπόνησε τῶν ἔργων. Λύκειον δὲ ἀπὸ μὲν Λύκου τοῦ Πανδίονος ἔχει τὸ ὄνομα, Ἀπόλλωνος δὲ ἱερὸν ἐξ ἀρχῆς τε εὐθὺς καὶ καθ’ ἡμᾶς ἐνομίζετο, Λύκ⟨ε⟩ιός τε ὁ θεὸς ἐνταῦθα ὠνομάσθη πρῶτον· λέγεται δὲ ὅτι καὶ Τερμίλαις, ἐς οὓς ἦλθεν ὁ Λύκος φεύγων Αἰγέα, καὶ τούτοις αἴτιός ἐστι Λυκίους ἀπ’ αὐτοῦ καλεῖσθαι.", "st": "1.19"}, {"sp": "N", "t": "ἔστι δὲ ὄπισθεν τοῦ Λυκ⟨ε⟩ίου Νίσου μνῆμα, ὃν ἀποθανόντα ὑπὸ Μίνω βασιλεύοντα Μεγάρων κομίσαντες Ἀθηναῖοι ταύτῃ θάπτουσιν. ἐς τοῦτον τὸν Νῖσον ἔχει λόγος τρίχας ἐν τῇ κεφαλῇ οἱ πορφυρᾶς εἶναι, χρῆναι δὲ αὐτὸν τελευτᾶν ἐπὶ ταύταις ἀποκαρείσαις· ὡς δὲ οἱ Κρῆτες ἦλθον ἐς τὴν γῆν, τὰς μὲν ἄλλας ἐξ ἐπιδρομῆς ᾕρουν τὰς ἐν τῇ Μεγαρίδι πόλεις, ἐς δὲ τὴν Νίσαιαν καταφεύγοντα τὸν Νῖσον ἐπολιόρκουν· ἐνταῦθα τοῦ Νίσου λέγεται θυγατέρα ἐρασθῆναι Μίνω καὶ ὡς ἀπέκειρε τὰς τρίχας τοῦ πατρός.", "st": "1.19"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω γενέσθαι λέγουσι· ποταμοὶ δὲ Ἀθηναίοις ῥέουσιν Ἰλισός τε καὶ Ἠριδανῷ τῷ Κελτικῷ κατὰ τὰ αὐτὰ ὄνομα ἔχων, ἐκδιδοὺς ἐς τὸν Ἰλισόν. ὁ δὲ Ἰλισός ἐστιν οὗτος, ἔνθα παίζουσαν Ὠρείθυιαν ὑπὸ ἀνέμου Βορέου φασὶν ἁρπασθῆναι· καὶ συνοικεῖν Ὠρειθυίᾳ Βορέαν καί σφισι διὰ τὸ κῆδος ἀμύναντα τῶν τριήρων τῶν βαρβαρικῶν ἀπολέσαι τὰς πολλάς. ἐθέλουσι δὲ Ἀθηναῖοι καὶ ἄλλων θεῶν ἱερὸν εἶναι τὸν Ἰλισόν, καὶ Μουσῶν βωμὸς ἐπ’ αὐτῷ ἐστιν Ἰλισιάδων· δείκνυται δὲ καὶ ἔνθα Πελοποννήσιοι Κόδρον τὸν Μελάνθου βασιλεύοντα Ἀθηναίων κτείνουσι.", "st": "1.19"}, {"sp": "N", "t": "διαβᾶσι δὲ τὸν Ἰλισὸν χωρίον Ἄγραι καλούμενον καὶ ναὸς Ἀγροτέρας ἐστὶν Ἀρτέμιδος· ἐνταῦθα Ἄρτεμιν πρῶτον θηρεῦσαι λέγουσιν ἐλθοῦσαν ἐκ Δήλου, καὶ τὸ ἄγαλμα διὰ τοῦτο ἔχει τόξον. τὸ δὲ ἀκούσασι μὲν οὐχ ὁμοίως ἐπαγωγόν, θαῦμα δ’ ἰδοῦσι, στάδιόν ἐστι λευκοῦ λίθου. μέγεθος δὲ αὐτοῦ τῇδε ἄν τις μάλιστα τεκμαίροιτο· ἄνωθεν ὄρος ὑπὲρ τὸν Ἰλισὸν ἀρχόμενον ἐκ μηνοειδοῦς καθήκει τοῦ ποταμοῦ πρὸς τὴν ὄχθην εὐθύ τε καὶ διπλοῦν. τοῦτο ἀνὴρ Ἀθηναῖος Ἡρώδης ᾠκοδόμησε, καί οἱ τὸ πολὺ τῆς λιθοτομίας τῆς Πεντελῆσιν ἐς τὴν οἰκοδομὴν ἀνηλώθη.", "st": "1.19"}, {"sp": "N", "t": "ἔστι δὲ ὁδὸς ἀπὸ τοῦ πρυταν⟨ε⟩ίου καλουμένη Τρίποδες· ἀφ’ οὗ καλοῦσι τὸ χωρίον, ναοὶ ὅσον ἐς τοῦτο μεγάλοι, καί σφισιν ἐφεστήκασι τρίποδες χαλκοῖ μέν, μνήμης δὲ ἄξια μάλιστα περιέχοντες εἰργασμένα. σάτυρος γάρ ἐστιν, ἐφ’ ᾧ Πραξιτέλην λέγεται φρονῆσαι μέγα· καί ποτε Φρύνης αἰτούσης, ὅ τι οἱ κάλλιστον εἴη τῶν ἔργων, ὁμολογεῖν μέν φασιν οἷα ἐραστὴν διδόναι [μὲν], κατειπεῖν δ’ οὐκ ἐθέλειν ὅ τι κάλλιστον αὐτῷ οἱ φαίνοιτο. ἐσδραμὼν οὖν οἰκέτης Φρύνης ἔφασκεν οἴχεσθαι Πραξιτέλει τὸ πολὺ τῶν ἔργων πυρὸς ἐσπεσόντος ἐς τὸ οἴκημα, οὐ μὲν οὖν πάντα γε ἀφανισθῆναι·", "st": "1.20"}, {"sp": "N", "t": "Πραξιτέλης δὲ αὐτίκα ἔθει διὰ θυρῶν ἔξω καί οἱ καμόντι οὐδὲν ἔφασκεν εἶναι πλέον, εἰ δὴ καὶ τὸν Σάτυρον ἡ φλὸξ καὶ τὸν Ἔρωτα ἐπέλαβε· Φρύνη δὲ μένειν θαρροῦντα ἐκέλευε· παθεῖν γὰρ ἀνιαρὸν οὐδέν, τέχνῃ δὲ ἁλόντα ὁμολογεῖν τὰ κάλλιστα ὧν ἐποίησε. Φρύνη μὲν οὕτω τὸν Ἔρωτα αἱρεῖται· Διονύσῳ δὲ ἐν τῷ ναῷ τῷ πλησίον Σάτυρός ἐστι παῖς καὶ δίδωσιν ἔκπωμα· Ἔρωτα δ’ ἑστηκότα ὁμοῦ καὶ Διόνυσον Θυμίλος ἐποίησεν.", "st": "1.20"}, {"sp": "N", "t": "τοῦ Διονύσου δέ ἐστι πρὸς τῷ θεάτρῳ τὸ ἀρχαιότατον ἱερόν· δύο δέ εἰσιν ἐντὸς τοῦ περιβόλου ναοὶ καὶ Διόνυσοι, ὅ τε Ἐλευθερεὺς καὶ ὃν Ἀλκαμένης ἐποίησεν ἐλέφαντος καὶ χρυσοῦ. γραφαὶ δὲ αὐτόθι Διόνυσός ἐστιν ἀνάγων Ἥφαιστον ἐς οὐρανόν· λέγεται δὲ καὶ τάδε ὑπὸ Ἑλλήνων, ὡς Ἥρα ῥίψαι γενόμενον Ἥφαιστον, ὁ δέ οἱ μνησικακῶν πέμψαι δῶρον χρυσοῦν θρόνον ἀφανεῖς δεσμοὺς ἔχοντα, καὶ τὴν μὲν ἐπεί τε ἐκαθέζετο δεδέσθαι, θεῶν δὲ τῶν μὲν ἄλλων οὐδενὶ τὸν Ἥφαιστον ἐθέλειν πείθεσθαι, Διόνυσος δὲ— μάλιστα γὰρ ἐς τοῦτον πιστὰ ἦν Ἡφαίστῳ—μεθύσας αὐτὸν ἐς οὐρανὸν ἤγαγε· ταῦτά τε δὴ γεγραμμένα εἰσὶ καὶ Πενθεὺς καὶ Λυκοῦργος ὧν ἐς Διόνυσον ὕβρισαν διδόντες δίκας, Ἀριάδνη δὲ καθεύδουσα καὶ Θησεὺς ἀναγόμενος καὶ Διόνυσος ἥκων ἐς τῆς Ἀριάδνης τὴν ἁρπαγήν.", "st": "1.20"}, {"sp": "N", "t": "ἔστι δὲ πλησίον τοῦ τε ἱεροῦ τοῦ Διονύσου καὶ τοῦ θεάτρου κατασκεύασμα, ποιηθῆναι δὲ τῆς σκηνῆς αὐτὸ ἐς μίμησιν τῆς Ξέρξου λέγεται· ἐποιήθη δὲ καὶ δεύτερον, τὸ γὰρ ἀρχαῖον στρατηγὸς Ῥωμαίων ἐνέπρησε Σύλλας Ἀθήνας ἑλών. αἰτία δὲ ἥδε τοῦ πολέμου. Μιθριδάτης ἐβασίλευε βαρβάρων τῶν περὶ τὸν Πόντον τὸν Εὔξεινον. πρόφασις μὲν δὴ δι’ ἥντινα Ῥωμαίοις ἐπολέμησε καὶ ὃν τρόπον ἐς τὴν Ἀσίαν διέβη καὶ ὅσας ἢ πολέμῳ βιασάμενος πόλεις ἔσχεν ἢ φίλας ἐποιήσατο, τάδε μὲν τοῖς ἐπίστασθαι τὰ Μιθριδάτου θέλουσι μελέτω· ἐγὼ δὲ ὅσον ἐς τὴν ἅλωσιν τὴν Ἀθηναίων ἔχει δηλώσω.", "st": "1.20"}, {"sp": "N", "t": "ἦν Ἀριστίων Ἀθηναῖος, ᾧ Μιθριδάτης πρεσβεύειν ἐς τὰς πόλεις τὰς Ἑλληνίδας ἐχρῆτο· οὗτος ἀνέπεισεν Ἀθηναίους Μιθριδάτην θέσθαι Ῥωμαίων ἐπίπροσθεν. ἀνέπεισε δὲ οὐ πάντας, ἀλλ’ ὅσον δῆμος ἦν καὶ δήμου τὸ ταραχῶδες· Ἀθηναῖοι δὲ ὧν τις λόγος, παρὰ τοὺς Ῥωμαίους ἐκπίπτουσιν ἐθελονταί. γενομένης δὲ μάχης πολλῷ περιῆσαν οἱ Ῥωμαῖοι, καὶ φεύγοντας Ἀριστίωνα μὲν καὶ Ἀθηναίους ἐς τὸ ἄστυ καταδιώκουσιν, Ἀρχέλαον δὲ καὶ τοὺς βαρβάρους ἐς τὸν Πειραιᾶ· Μιθριδάτου δὲ στρατηγὸς καὶ οὗτος ἦν, ὃν πρότερον τούτων Μάγνητες οἱ τὸν Σίπυλον οἰκοῦντες σφᾶς ἐπεκδραμόντα αὐτόν τε τιτρώσκουσι καὶ τῶν βαρβάρων φονεύουσι τοὺς πολλούς.", "st": "1.20"}, {"sp": "N", "t": "Ἀθηναίοις μὲν δὴ πολιορκία καθειστήκει, Ταξίλος δὲ Μιθριδάτου στρατηγὸς ἐτύγχανε μὲν περικαθήμενος Ἐλάτειαν τὴν ἐν τῇ Φωκίδι, ἀφικομένων δὲ ἀγγέλων ἀναστήσας τὸν στρατὸν ἐς τὴν Ἀττικὴν ἦγεν. ἃ πυνθανόμενος ὁ στρατηγὸς τῶν Ῥωμαίων Ἀθήνας μὲν τοῦ στρατοῦ μέρει πολιορκεῖν ἀφῆκεν, αὐτὸς δὲ Ταξίλῳ τὸ πολὺ τῆς δυνάμεως ἔχων ἐς Βοιωτοὺς ἀπαντᾷ. τρίτῃ δὲ ὕστερον ἡμέρᾳ τοῖς Ῥωμαίοις ἦλθον ἐπ’ ἀμφότερα τὰ στρατόπεδα ἄγγελοι, Σύλλᾳ μὲν ὡς Ἀθηναίοις εἴη ⟨τὸ⟩ τεῖχος ἑαλωκός, τοῖς δὲ Ἀθήνας πολιορκήσασι Ταξίλον κεκρατῆσθαι μάχῃ περὶ Χαιρώνειαν. Σύλλας δὲ ὡς ἐς τὴν Ἀττικὴν ἐπανῆλθε, τοὺς ἐναντιωθέντας Ἀθηναίων καθείρξας ἐς τὸν Κεραμεικὸν τὸν λαχόντα σφῶν ἐκ δεκάδος ἑκάστης ἐκέλευσεν ἄγεσθαι τὴν ἐπὶ θανάτῳ.", "st": "1.20"}, {"sp": "N", "t": "Σύλλου δὲ οὐκ ἀνιέντος ἐς Ἀθηναίους τοῦ θυμοῦ λαθόντες ἐκδιδράσκουσιν ἄνδρες ἐς Δελφοὺς· ἐρομένοις δέ σφισιν, εἰ καταλαμβάνοι τὸ χρεὼν ἤδη καὶ τὰς Ἀθήνας ἐρημωθῆναι, τούτοις ἔχρησεν ἡ Πυθία τὰ ἐς τὸν ἀσκὸν ἔχοντα. Σύλλᾳ δὲ ὕστερον τούτων ἐνέπεσεν ἡ νόσος, ᾗ καὶ τὸν Σύριον Φερεκύδην ἁλῶναι πυνθάνομαι. Σύλλᾳ δὲ ἔστι μὲν καὶ τὰ ἐς τοὺς πολλοὺς Ἀθηναίων ἀγριώτερα ἢ ὡς ἄνδρα εἰκὸς ἦν ἐργάσασθαι Ῥωμαῖον· ἀλλὰ γὰρ οὐ ταῦτα δὴ αἰτίαν γενέσθαι οἱ δοκῶ τῆς συμφορᾶς, Ἱκεσίου δὲ μήνιμα, ὅτι καταφυγόντα ἐς τὸ τῆς Ἀθηνᾶς ἱερὸν ἀπέκτεινεν ἀποσπάσας Ἀριστίωνα. Ἀθῆναι μὲν οὕτως ὑπὸ τοῦ πολέμου κακωθεῖσαι τοῦ Ῥωμαίων αὖθις Ἀδριανοῦ βασιλεύοντος ἤνθησαν·", "st": "1.20"}, {"sp": "N", "t": "εἰσὶ δὲ Ἀθηναίοις εἰκόνες ἐν τῷ θεάτρῳ καὶ τραγῳδίας καὶ κωμῳδίας ποιητῶν, αἱ πολλαὶ τῶν ἀφανεστέρων· ὅτι μὴ γὰρ Μένανδρος, οὐδεὶς ἦν ποιητὴς κωμῳδίας τῶν ἐς δόξαν ἡκόντων. τραγῳδίας δὲ κεῖνται τῶν φανερῶν Εὐριπίδης καὶ Σοφοκλῆς. λέγεται δὲ Σοφοκλέους τελευτήσαντος ἐσβαλεῖν ἐς τὴν Ἀττικὴν Λακεδαιμονίους, καὶ σφῶν τὸν ἡγούμενον ἰδεῖν ἐπιστάντα οἱ Διόνυσον κελεύειν τιμαῖς, ὅσαι καθεστήκασιν ἐπὶ τοῖς τεθνεῶσι, τὴν Σειρῆνα τὴν νέαν τιμᾶν· καί οἱ τὸ ὄναρ ⟨ἐς⟩ Σοφοκλέα καὶ τὴν Σοφοκλέους ποίησιν ἐφαίνετο ἔχειν, εἰώθασι δὲ καὶ νῦν ἔτι ποιημάτων καὶ λόγων τὸ ἐπαγωγὸν Σειρῆνι εἰκάζειν.", "st": "1.21"}, {"sp": "N", "t": "τὴν δὲ εἰκόνα τὴν Αἰσχύλου πολλῷ τε ὕστερον τῆς τελευτῆς δοκῶ ποιηθῆναι ⟨καὶ⟩ τῆς γραφῆς ἣ τὸ ἔργον ἔχει τὸ Μαραθῶνι. ἔφη δὲ Αἰσχύλος μειράκιον ὢν καθεύδειν ἐν ἀγρῷ φυλάσσων σταφυλάς, καί οἱ Διόνυσον ἐπιστάντα κελεῦσαι τραγῳδίαν ποιεῖν· ὡς δὲ ἦν ἡμέρα— πείθεσθαι γὰρ ἐθέλειν—ῥᾷστα ἤδη πειρώμενος ποιεῖν.", "st": "1.21"}, {"sp": "N", "t": "οὗτος μὲν ταῦτα ἔλεγεν· ἐπὶ δὲ τοῦ Νοτίου καλουμένου τείχους, ὃ τῆς ἀκροπόλεως ἐς τὸ θέατρόν ἐστι τετραμμένον, ἐπὶ τούτου Μεδούσης τῆς Γοργόνος ἐπίχρυσος ἀνάκειται κεφαλή, καὶ περὶ αὐτὴν αἰγὶς πεποίηται. ἐν δὲ τῇ κορυφῇ τοῦ θεάτρου σπήλαιόν ἐστιν ἐν ταῖς πέτραις ὑπὸ τὴν ἀκρόπολιν· τρίπους δὲ ἔπεστι καὶ τούτῳ· Ἀπόλλων δὲ ἐν αὐτῷ καὶ Ἄρτεμις τοὺς παῖδάς εἰσιν ἀναιροῦντες τοὺς Νιόβης. ταύτην τὴν Νιόβην καὶ αὐτὸς εἶδον ἀνελθὼν ἐς τὸν Σίπυλον τὸ ὄρος· ἡ δὲ πλησίον μὲν πέτρα καὶ κρημνός ἐστιν οὐδὲν παρόντι σχῆμα παρεχόμενος γυναικὸς οὔτε ἄλλως οὔτε πενθούσης· εἰ δέ γε πορρωτέρω γένοιο, δεδακρυμένην δόξεις ὁρᾶν καὶ κατηφῆ γυναῖκα.", "st": "1.21"}, {"sp": "N", "t": "ἰόντων δὲ Ἀθήνῃσιν ἐς τὴν ἀκρόπολιν ἀπὸ τοῦ θεάτρου τέθαπται Κάλως· τοῦτον τὸν Κάλων ἀδελφῆς παῖδα ὄντα καὶ τῆς τέχνης μαθητὴν φονεύσας Δαίδαλος ἐς Κρήτην ἔφυγε, χρόνῳ δὲ ὕστερον ἐς Σικελίαν ἐκδιδράσκει παρὰ Κώκαλον. τοῦ δὲ Ἀσκληπιοῦ τὸ ἱερὸν ἔς τε τὰ ἀγάλματά ἐστιν, ὁπόσα τοῦ θεοῦ πεποίηται καὶ τῶν παίδων, καὶ ἐς τὰς γραφὰς θέας ἄξιον· ἔστι δὲ ἐν αὐτῷ κρήνη, παρ’ ᾗ λέγουσι Ποσειδῶνος παῖδα Ἁλιρρόθιον θυγατέρα Ἄρεως Ἀλκίππην αἰσχύναντα ἀποθανεῖν ὑπὸ Ἄρεως, καὶ δίκην ἐπὶ τούτῳ τῷ φόνῳ γενέσθαι πρῶτον.", "st": "1.21"}, {"sp": "N", "t": "ἐνταῦθα ἄλλα τε καὶ Σαυροματικὸς ἀνάκειται θώραξ· ἐς τοῦτόν τις ἰδὼν οὐδὲν ἧσσον Ἑλλήνων τοὺς βαρβάρους φήσει σοφοὺς ἐς τὰς τέχνας εἶναι. Σαυρομάταις γὰρ οὔτε αὐτοῖς σίδηρός ἐστιν ὀρυσσόμενος οὔτε σφίσιν ἐσάγουσιν· ἄμικτοι γὰρ μάλιστα τῶν ταύτῃ βαρβάρων εἰσί. πρὸς οὖν τὴν ἀπορίαν ταύτην ἐξεύρηταί σφισιν· ἐπὶ μὲν τοῖς δόρασιν αἰχμὰς ὀστεΐνας ἀντὶ σιδήρου φοροῦσι, τόξα τε κράνινα καὶ ὀιστοὺς καὶ ὀστεΐνας ἀκίδας ἐπὶ τοῖς ὀιστοῖς· καὶ σειραῖς περιβαλόντες τῶν πολεμίων ὁπόσους καὶ τύχοιεν, τοὺς ἵππους ἀποστρέψαντες ἀνατρέπουσι τοὺς ἐνσχεθέντας ταῖς σειραῖς.", "st": "1.21"}, {"sp": "N", "t": "τοὺς δὲ θώρακας ποιοῦνται τὸν τρόπον τοῦτον. ἵππους πολλὰς ἕκαστος τρέφει, ὡς ἂν οὔτε ἐς ἰδιωτῶν κλήρους τῆς γῆς μεμερισμένης οὔτε τι φερούσης πλὴν ὕλης ἀγρίας ἅτε ὄντων νομάδων· ταύταις οὐκ ἐς πόλεμον χρῶνται μόνον, ἀλλὰ καὶ θεοῖς θύουσιν ἐπιχωρίοις καὶ ἄλλως σιτοῦνται. συλλεξάμενοι δὲ τὰς ὁπλὰς ἐκκαθήραντές τε καὶ διελόντες ποιοῦσιν ἀπ’ αὐτῶν ἐμφερῆ δρακόντων φολίσιν· ὅστις δὲ οὐκ εἶδέ πω δράκοντα, πίτυός γε εἶδε καρπὸν χλωρὸν ἔτι· ταῖς οὖν ἐπὶ τῷ καρπῷ τῆς πίτυος φαινομέναις ἐντομαῖς εἰκάζων τὸ ἔργον τὸ ἐκ τῆς ὁπλῆς οὐκ ἂν ἁμαρτάνοι. ταῦτα διατρήσαντες καὶ νεύροις ἵππων καὶ βοῶν συρράψαντες χρῶνται θώραξιν οὔτε εὐπρεπείᾳ τῶν Ἑλληνικῶν ἀποδέουσιν οὔτε ἀσθενεστέροις· καὶ γὰρ συστάδην τυπτόμενοι καὶ βληθέντες ἀνέχονται.", "st": "1.21"}, {"sp": "N", "t": "οἱ δὲ θώρακες οἱ λινοῖ μαχομένοις μὲν οὐχ ὁμοίως εἰσὶ χρήσιμοι, διιᾶσι γὰρ καὶ βιαζόμενοι τὸν σίδηρον· θηρεύοντας δὲ ὠφελοῦσιν, ἐναποκλῶνται γάρ σφισι καὶ λεόντων ὀδόντες καὶ παρδάλεων. θώρακας δὲ λινοῦς ἰδεῖν ἔν τε ἄλλοις ἱεροῖς ἔστιν ἀνακειμένους καὶ ἐν Γρυνείῳ, ἔνθα Ἀπόλλωνος κάλλιστον ἄλσος δένδρων καὶ ἡμέρων καὶ ὅσα τῶν ἀκάρπων ὀσμῆς παρέχεταί τινα ἢ θέας ἡδονήν.", "st": "1.21"}, {"sp": "N", "t": "μετὰ δὲ τὸ ἱερὸν τοῦ Ἀσκληπιοῦ ταύτῃ πρὸς τὴν ἀκρόπολιν ἰοῦσι Θέμιδος ναός ἐστι. κέχωσται δὲ πρὸ αὐτοῦ μνῆμα Ἱππολύτῳ· τοῦ δέ οἱ βίου τὴν τελευτὴν συμβῆναι λέγουσιν ἐκ καταρῶν. δῆλα δέ, καὶ ὅστις βαρβάρων γλῶσσαν ἔμαθεν Ἑλλήνων, ὅ τε ἔρως τῆς Φαίδρας καὶ τῆς τροφοῦ τὸ ἐς τὴν διακονίαν τόλμημα. ἔστι δὲ καὶ Τροιζηνίοις Ἱππολύτου τάφος· ἔχει δέ σφισιν ὧδε ὁ λόγος.", "st": "1.22"}, {"sp": "N", "t": "Θησεὺς ὡς ἔμελλεν ἄξεσθαι Φαίδραν, οὐκ ἐθέλων εἴ οἱ γένοιντο παῖδες οὔτε ἄρχεσθαι τὸν Ἱππόλυτον οὔτε βασιλεύειν ἀντ’ αὐτῶν, πέμπει παρὰ Πιτθέα τραφησόμενον αὐτὸν καὶ βασιλεύσοντα Τροιζῆνος. χρόνῳ δὲ ὕστερον Πάλλας καὶ οἱ παῖδες ἐπανέστησαν Θησεῖ· τούτους κτείνας ἐς Τροιζῆνα ἔρχεται καθαρσίων ἕνεκα, καὶ Φαίδρα πρώτη ἐνταῦθα εἶδεν Ἱππόλυτον καὶ τὰ ἐς τὸν θάνατον ἐρασθεῖσα ἐβούλευσε. μυρσίνη δέ ἐστι Τροιζηνίοις τὰ φύλλα διὰ πάσης ἔχουσα τετρυπημένα· φῦναι δὲ οὐκ ἐξ ἀρχῆς αὐτὴν λέγουσιν, ἀλλὰ τὸ ἔργον γεγενῆσθαι τῆς ἐς τὸν ἔρωτα ἄσης καὶ τῆς περόνης ἣν ἐπὶ ταῖς θριξὶν εἶχεν ἡ Φαίδρα.", "st": "1.22"}, {"sp": "N", "t": "Ἀφροδίτην δὲ τὴν Πάνδημον, ἐπεί τε Ἀθηναίους Θησεὺς ἐς μίαν ἤγαγεν ἀπὸ τῶν δήμων πόλιν, αὐτήν τε σέβεσθαι καὶ Πειθὼ κατέστησε· τὰ μὲν δὴ παλαιὰ ἀγάλματα οὐκ ἦν ἐπ’ ἐμοῦ, τὰ δὲ ἐπ’ ἐμοῦ τεχνιτῶν ἦν οὐ τῶν ἀφανεστάτων. ἔστι δὲ καὶ Γῆς Κουροτρόφου καὶ Δήμητρος ἱερὸν Χλόης· τὰ δὲ ἐς τὰς ἐπωνυμίας ἔστιν αὐτῶν διδαχθῆναι τοῖς ἱερεῦσιν ἐλθόντα ἐς λόγους.", "st": "1.22"}, {"sp": "N", "t": "ἐς δὲ τὴν ἀκρόπολίν ἐστιν ἔσοδος μία· ἑτέραν δὲ οὐ παρέχεται, πᾶσα ἀπότομος οὖσα καὶ τεῖχος ἔχουσα ἐχυρόν. τὰ δὲ προπύλαια λίθου λευκοῦ τὴν ὀροφὴν ἔχει καὶ κόσμῳ καὶ μεγέθει τῶν λίθων μέχρι γε καὶ ἐμοῦ προεῖχε. τὰς μὲν οὖν εἰκόνας τῶν ἱππέων οὐκ ἔχω σαφῶς εἰπεῖν, εἴτε οἱ παῖδές εἰσιν οἱ Ξενοφῶντος εἴτε ἄλλως ⟨ἐς⟩ εὐπρέπειαν πεποιημέναι· τῶν δὲ προπυλαίων ἐν δεξιᾷ Νίκης ἐστὶν Ἀπτέρου ναός. ἐντεῦθεν ἡ θάλασσά ἐστι σύνοπτος, καὶ ταύτῃ ῥίψας Αἰγεὺς ἑαυτὸν ὡς λέγουσιν ἐτελεύτησεν.", "st": "1.22"}, {"sp": "N", "t": "ἀνήγετο μὲν γὰρ ἡ ναῦς μέλασιν ἱστίοις ἡ τοὺς παῖδας φέρουσα ἐς Κρήτην, Θησεὺς δὲ—ἔπλει γὰρ τόλμης τι ἔχων ἐς τὸν Μίνω καλούμενον ταῦρον—πρὸς τὸν πατέρα προεῖπε χρήσεσθαι τοῖς ἱστίοις λευκοῖς, ἢν ὀπίσω πλέῃ τοῦ ταύρου κρατήσας· τούτων λήθην ἔσχεν Ἀριάδνην ἀφῃρημένος· ἐνταῦθα Αἰγεὺς ὡς εἶδεν ἱστίοις μέλασι τὴν ναῦν κομιζομένην, οἷα τὸν παῖδα τεθνάναι δοκῶν, ἀφεὶς αὑτὸν διαφθείρεται· καί οἱ παρὰ Ἀθηναίοις ἐστὶ καλούμενον ἡρῷον Αἰγέως.", "st": "1.22"}, {"sp": "N", "t": "—ἔστι δὲ ἐν ἀριστερᾷ τῶν προπυλαίων οἴκημα ἔχον γραφάς· ὁπόσαις δὲ μὴ καθέστηκεν ὁ χρόνος αἴτιος ἀφανέσιν εἶναι, Διομήδης ἦν, ὁ μὲν ἐν Λήμνῳ τὸ Φιλοκτήτου τόξον, ὁ δὲ τὴν Ἀθηνᾶν ἀφαιρούμενος ἐξ Ἰλίου. ἐνταῦθα ἐν ταῖς γραφαῖς Ὀρέστης ἐστὶν Αἴγισθον φονεύων καὶ Πυλάδης τοὺς παῖδας τοὺς Ναυπλίου βοηθοὺς ἐλθόντας Αἰγίσθῳ· τοῦ δὲ Ἀχιλλέως τάφου πλησίον μέλλουσά ἐστι σφάζεσθαι Πολυξένη. Ὁμήρῳ δὲ εὖ μὲν παρείθη τόδε ⟨τὸ⟩ ὠμὸν οὕτως ἔργον· εὖ δέ μοι φαίνεται ποιῆσαι Σκῦρον ὑπὸ Ἀχιλλέως ἁλοῦσαν, οὐδὲν ὁμοίως καὶ ὅσοι λέγουσιν ὁμοῦ ταῖς παρθένοις Ἀχιλλέα ἔχειν ἐν Σκύρῳ δίαιταν, ἃ δὴ καὶ Πολύγνωτος ἔγραψεν. ἔγραψε δὲ καὶ πρὸς τῷ ποταμῷ ταῖς ὁμοῦ Ναυσικᾷ πλυνούσαις ἐφιστάμενον Ὀδυσσέα κατὰ τὰ αὐτὰ καθὰ δὴ καὶ Ὅμηρος ἐποίησε. γραφαὶ δέ εἰσι καὶ ἄλλαι καὶ Ἀλκιβιάδης,", "st": "1.22"}, {"sp": "N", "t": "ἵππων δέ οἱ νίκης τῆς ἐν Νεμέᾳ ἐστὶ σημεῖα ἐν τῇ γραφῇ· καὶ Περσεύς ἐστιν ἐς Σέριφον κομιζόμενος, Πολυδέκτῃ φέρων τὴν κεφαλὴν τὴν Μεδούσης. καὶ τὰ μὲν ἐς Μέδουσαν οὐκ εἰμὶ πρόθυμος ἐν τοῖς Ἀττικοῖς σημῆναι· ἔτι δὲ τῶν γραφῶν παρέντι τὸν παῖδα τὸν τὰς ὑδρίας φέροντα καὶ τὸν παλαιστὴν ὃν Τιμαίνετος ἔγραψεν, ἐστὶ Μουσαῖος. ἐγὼ δὲ ἔπη μὲν ἐπελεξάμην, ἐν οἷς ἐστι πέτεσθαι Μουσαῖον ὑπὸ Βορέου δῶρον, δοκεῖν δέ μοι πεποίηκεν αὐτὰ Ὀνομάκριτος καὶ ἔστιν οὐδὲν Μουσαίου βεβαίως ὅτι μὴ μόνον ἐς Δήμητρα ὕμνος Λυκομίδαις.", "st": "1.22"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἔσοδον αὐτὴν ἤδη τὴν ἐς ἀκρόπολιν Ἑρμῆν ὃν Προπύλαιον ὀνομάζουσι καὶ Χάριτας Σωκράτην ποιῆσαι τὸν Σωφρονίσκου λέγουσιν, ᾧ σοφῷ γενέσθαι μάλιστα ἀνθρώπων ἐστὶν ἡ Πυθία μάρτυς, ὃ μηδὲ Ἀνάχαρσιν ἐθέλοντα ὅμως καὶ δι’ αὐτὸ ἐς Δελφοὺς ἀφικόμενον προσεῖπεν.", "st": "1.22"}, {"sp": "N", "t": "Ἕλληνες δὲ ἄλλα τε λέγουσι καὶ ἄνδρας ἑπτὰ γενέσθαι σοφούς. τούτων καὶ τὸν Λέσβιον τύραννον καὶ Περίανδρον εἶναί φασι τὸν Κυψέλου· καίτοι Περιάνδρου Πεισίστρατος καὶ ὁ παῖς Ἱππίας φιλάνθρωποι μᾶλλον καὶ σοφώτεροι τά τε πολεμικὰ ἦσαν καὶ ὅσα ἧκεν ἐς κόσμον τῶν πολιτῶν, ἐς ὃ διὰ τὸν Ἱππάρχου θάνατον Ἱππίας ἄλλα τε ἐχρήσατο θυμῷ καὶ ἐς γυναῖκα ὄνομα Λέαιναν.", "st": "1.23"}, {"sp": "N", "t": "ταύτην γάρ, ἐπεί τε ἀπέθανεν Ἵππαρχος, —λέγω δὲ οὐκ ἐς συγγραφὴν πρότερον ἥκοντα, πιστὰ δὲ ἄλλως Ἀθηναίων τοῖς πολλοῖς—Ἱππίας εἶχεν ἐν αἰκίᾳ ἐς ὃ διέφθειρεν, οἷα ἑταίραν Ἀριστογείτονος ἐπιστάμενος οὖσαν καὶ τὸ βούλευμα οὐδαμῶς ἀγνοῆσαι δοξάζων· ἀντὶ δὲ τούτων, ἐπεὶ τυραννίδος ἐπαύθησαν οἱ Πεισιστρατίδαι, χαλκῆ λέαινα Ἀθηναίοις ἐστὶν ἐς μνήμην τῆς γυναικός, παρὰ δὲ αὐτὴν ἄγαλμα Ἀφροδίτης, ὃ Καλλίου τέ φασιν ἀνάθημα εἶναι καὶ ἔργον Καλάμιδος.", "st": "1.23"}, {"sp": "N", "t": "πλησίον δέ ἐστι Διιτρέφους χαλκοῦς ἀνδριὰς ὀιστοῖς βεβλημένος. οὗτος ὁ Διιτρέφης ἄλλα τε ἔπραξεν ὁπόσα λέγουσιν Ἀθηναῖοι καὶ Θρᾷκας μισθωτοὺς ἀφικομένους ὕστερον ἢ Δημοσθένης ἐς Συρακούσας ἐξέπλευσε, τούτους ὡς ὑστέρησαν ὁ Διιτρέφης ἀπῆγεν ὀπίσω. καὶ δὴ κατὰ τὸν Χαλκιδικὸν ἔσχεν Εὔριπον, ἔνθα Βοιωτῶν ἐν μεσογαίᾳ πόλις Μυκαλησσὸς ἦν· ταύτην ἐπαναβὰς ἐκ θαλάσσης ὁ Λιιτρέφης εἷλε. Μυκαλησσίων δὲ οὐ μόνον τὸ μάχιμον οἱ Θρᾷκες ἀλλὰ καὶ γυναῖκας ἐφόνευσαν καὶ παῖδας. μαρτυρεῖ δέ μοι· Βοιωτῶν γὰρ ὅσους ἀνέστησαν Θηβαῖοι, ᾠκοῦντο αἱ πόλεις ἐπ’ ἐμοῦ, διαφυγόντων ὑπὸ τὴν ἅλωσιν τῶν ἀνθρώπων· εἰ δὲ καὶ Μυκαλησσίοις οἱ βάρβαροι μὴ πᾶσιν ἀποκτείναντες ἐπεξῆλθον, ὕστερον ἂν τὴν πόλιν ἀπέλαβον οἱ λειφθέντες.", "st": "1.23"}, {"sp": "N", "t": "τοσοῦτον μὲν παρέστη μοι θαῦμα ἐς τὴν εἰκόνα τοῦ Διιτρέφους, ὅτι ὀιστοῖς ἐβέβλητο, Ἕλλησιν ὅτι μὴ Κρησὶν οὐκ ἐπιχώριον ὂν τοξεύειν· Λοκροὺς γὰρ τοὺς Ὀπουντίους ὁπλιτεύοντας ἤδη κατὰ τὰ Μηδικὰ ἴσμεν, οὓς Ὅμηρος ἐποίησεν ὡς φερόμενοι τόξα καὶ σφενδόνας ἐς Ἴλιον ἔλθοιεν· οὐ μὴν οὐδὲ Μαλιεῦσι παρέμεινε μελέτη τῶν τόξων, δοκῶ δὲ οὔτε πρότερον ἐπίστασθαι σφᾶς πρὶν ἢ Φιλοκτήτην, παύσασθαί τε οὐ διὰ μακροῦ· τοῦ δὲ Διιτρέφους πλησίον—τὰς γὰρ εἰκόνας τὰς ἀφανεστέρας γράφειν οὐκ ἐθέλω—θεῶν ἀγάλματά ἐστιν Ὑγείας τε, ἣν Ἀσκληπιοῦ παῖδα εἶναι λέγουσι, καὶ Ἀθηνᾶς ἐπίκλησιν καὶ ταύτης Ὑγείας.", "st": "1.23"}, {"sp": "N", "t": "ἔστι δὲ λίθος οὐ μέγας, ἀλλ’ ὅσον καθίζεσθαι μικρὸν ἄνδρα· ἐπὶ τούτῳ λέγουσιν, ἡνίκα Διόνυσος ἦλθεν ἐς τὴν γῆν, ἀναπαύσασθαι τὸν Σιληνόν. τοὺς γὰρ ἡλικίᾳ τῶν Σατύρων προήκοντας ὀνομάζουσι Σιληνούς· περὶ δὲ Σατύρων, οἵτινές εἰσιν, ἑτέρου πλέον ἐθέλων ἐπίστασθαι πολλοῖς αὐτῶν τούτων ἕνεκα ἐς λόγους ἦλθον. ἔφη δὲ Εὔφημος Κὰρ ἀνὴρ πλέων ἐς Ἰταλίαν ἁμαρτεῖν ὑπὸ ἀνέμων τοῦ πλοῦ καὶ ἐς τὴν ἔξω θάλασσαν, ἐς ἣν οὐκέτι πλέουσιν, ἐξενεχθῆναι. νήσους δὲ εἶναι μὲν ἔλεγεν ἐρήμους πολλάς, ἐν δὲ ἄλλαις οἰκεῖν ἄνδρας ἀγρίους·", "st": "1.23"}, {"sp": "N", "t": "ταύταις δὲ οὐκ ἐθέλειν νήσοις … προσίσχειν τοὺς ναύτας οἷα πρότερόν τε προσσχόντας καὶ τῶν ἐνοικούντων οὐκ ἀπείρως ἔχοντας, βιασθῆναι δ’ οὖν καὶ τότε. ταύτας καλεῖσθαι μὲν ὑπὸ τῶν ναυτῶν Σατυρίδας, εἶναι δὲ τοὺς ἐνοικοῦντας [καὶ] καπυροὺς καὶ ἵππων οὐ πολὺ μείους ἔχειν ἐπὶ τοῖς ἰσχίοις οὐράς. τούτους, ὡς ᾔσθοντο, καταδραμόντας ἐπὶ τὴν ναῦν φωνὴν μὲν οὐδεμίαν ἱέναι, ταῖς δὲ γυναιξὶν ἐπιχειρεῖν ταῖς ἐν τῇ νηί· τέλος δὲ δείσαντας τοὺς ναύτας βάρβαρον γυναῖκα ἐκβαλεῖν ἐς τὴν νῆσον· ἐς ταύτην οὖν ὑβρίζειν τοὺς Σατύρους οὐ μόνον ᾗ καθέστηκεν, ἀλλὰ καὶ τὸ πᾶν ὁμοίως σῶμα.", "st": "1.23"}, {"sp": "N", "t": "καὶ ἄλλα ἐν τῇ Ἀθηναίων ἀκροπόλει θεασάμενος οἶδα, Λυκίου τοῦ Μύρωνος χαλκοῦν παῖδα, ὃς τὸ περιρραντήριον ἔχει, καὶ Μύρωνος Περσέα τὸ ἐς Μέδουσαν ἔργον εἰργασμένον. καὶ Ἀρτέμιδος ἱερόν ἐστι Βραυρωνίας, Πραξιτέλους μὲν τέχνη τὸ ἄγαλμα, τῇ θεῷ δέ ἐστιν ἀπὸ Βραυρῶνος δήμου τὸ ὄνομα καὶ τὸ ἀρχαῖον ξόανόν ἐστιν ἐν Βραυρῶνι, Ἄρτεμις ὡς λέγουσιν ἡ Ταυρική.", "st": "1.23"}, {"sp": "N", "t": "ἵππος δὲ ὁ καλούμενος Δούριος ἀνάκειται χαλκοῦς. καὶ ὅτι μὲν τὸ ποίημα τὸ Ἐπειοῦ μηχάνημα ἦν ἐς διάλυσιν τοῦ τείχους, οἶδεν ὅστις μὴ πᾶσαν ἐπιφέρει τοῖς Φρυξὶν εὐήθειαν· λέγεται δὲ ἔς τε ἐκεῖνον τὸν ἵππον ὡς τῶν Ἑλλήνων ἔνδον ἔχοι τοὺς ἀρίστους, καὶ δὴ καὶ τοῦ χαλκοῦ τὸ σχῆμά ἐστι κατὰ ταῦτα· καὶ Μενεσθεὺς καὶ Τεῦκρος ὑπερκύπτουσιν ἐξ αὐτοῦ, προσέτι δὲ καὶ οἱ παῖδες οἱ Θησέως.", "st": "1.23"}, {"sp": "N", "t": "ἀνδριάντων δὲ ὅσοι μετὰ τὸν ἵππον ἑστήκασιν Ἐπιχαρίνου μὲν ὁπλιτοδρομεῖν ἀσκήσαντος τὴν εἰκόνα ἐποίησε Κριτίας, Οἰνοβίῳ δὲ ἔργον ἐστὶν ἐς Θουκυδίδην τὸν Ὀλόρου χρηστόν· ψήφισμα γὰρ ἐνίκησεν Οἰνόβιος κατελθεῖν ἐς Ἀθήνας Θουκυδίδην, καί οἱ δολοφονηθέντι ὡς κατῄει μνῆμά ἐστιν οὐ πόρρω πυλῶν Μελιτίδων.", "st": "1.23"}, {"sp": "N", "t": "τὰ δὲ ἐς Ἑρμόλυκον τὸν παγκρατιαστὴν καὶ Φορμίωνα τὸν Ἀσωπίχου γραψάντων ἑτέρων παρίημι· ἐς δὲ Φορμίωνα τοσόνδε ἔχω πλέον γράψαι. Φορμίωνι γὰρ τοῖς ἐπιεικέσιν Ἀθηναίων ὄντι ὁμοίῳ καὶ ἐς προγόνων δόξαν οὐκ ἀφανεῖ συνέβαινεν ὀφείλειν χρέα· ἀναχωρήσας οὖν ἐς τὸν Παιανιέα δῆμον ἐνταῦθα εἶχε δίαιταν, ἐς ὃ ναύαρχον αὐτὸν Ἀθηναίων αἱρουμένων ἐκπλεύσεσθαι οὐκ ἔφασκεν· ὀφείλειν τε γὰρ καί οἱ, πρὶν ἂν ἐκτίσῃ, πρὸς τοὺς στρατιώτας οὐκ εἶναι παρέχεσθαι φρόνημα. οὕτως Ἀθηναῖοι—πάντως γὰρ ἐβούλοντο ἄρχειν Φορμίωνα—τὰ χρέα ὁπόσοις ὤφειλε διαλύουσιν.", "st": "1.23"}, {"sp": "N", "t": "ἐνταῦθα Ἀθηνᾶ πεποίηται τὸν Σιληνὸν Μαρσύαν παίουσα, ὅτι δὴ τοὺς αὐλοὺς ἀνέλοιτο, ἐρρῖφθαι σφᾶς τῆς θεοῦ βουλομένης. —τούτων πέραν, ὧν εἴρηκα, ἐστὶν ἡ λεγομένη Θησέως μάχη πρὸς τὸν ταῦρον τὸν Μίνω καλούμενον, εἴτε ἀνὴρ εἴτε θηρίον ἦν ὁποῖον κεκράτηκεν ὁ λόγος· τέρατα γὰρ πολλῷ καὶ τοῦδε θαυμασιώτερα καὶ καθ’ ἡμᾶς ἔτικτον γυναῖκες.", "st": "1.24"}, {"sp": "N", "t": "κεῖται δὲ καὶ Φρίξος ὁ Ἀθάμαντος ἐξενηνεγμένος ἐς Κόλχους ὑπὸ τοῦ κριοῦ· θύσας δὲ αὐτὸν ὅτῳ δὴ θεῷ, ὡς δὲ εἰκάσαι τῷ Λαφυστίῳ καλουμένῳ παρὰ Ὀρχομενίοις, τοὺς μηροὺς κατὰ νόμον ἐκτεμὼν τὸν Ἑλλήνων ἐς αὐτοὺς καιομένους ὁρᾷ. κεῖνται δὲ ἑξῆς ἄλλαι τε εἰκόνες καὶ Ἡρακλέους· ἄγχει δέ, ὡς λόγος ἔχει, τοὺς δράκοντας. Ἀθηνᾶ τέ ἐστιν ἀνιοῦσα ἐκ τῆς κεφαλῆς τοῦ Διός. ἔστι δὲ καὶ ταῦρος ἀνάθημα τῆς βουλῆς τῆς ἐν Ἀρείῳ πάγῳ, ἐφ’ ὅτῳ δὴ ἀνέθηκεν ἡ βουλή·", "st": "1.24"}, {"sp": "N", "t": "πολλὰ δ’ ἄν τις ἐθέλων εἰκάζοι. λέλεκται δέ μοι καὶ πρότερον ὡς Ἀθηναίοις περισσότερόν τι ἢ τοῖς ἄλλοις ἐς τὰ θεῖά ἐστι σπουδῆς· πρῶτοι μὲν γὰρ Ἀθηνᾶν ἐπωνόμασαν Ἐργάνην, πρῶτοι δ’ ἀκώλους Ἑρμᾶς ⟨ἀνέθεσαν⟩, ὁμοῦ δέ σφισιν ἐν τῷ ναῷ †σπουδαίων δαίμων ἐστίν. ὅστις δὲ τὰ σὺν τέχνῃ πεποιημένα ἐπίπροσθε τίθεται τῶν ἐς ἀρχαιότητα ἡκόντων, καὶ τάδε ἔστιν οἱ θεάσασθαι. κράνος ἐστὶν ἐπικείμενος ἀνὴρ Κλεοίτου, καί οἱ τοὺς ὄνυχας ἀργυροῦς ἐνεποίησεν ὁ Κλεοίτας· ἔστι δὲ καὶ Γῆς ἄγαλμα ἱκετευούσης ὗσαί οἱ τὸν Δία, εἴτε αὐτοῖς ὄμβρου δεῆσαν Ἀθηναίοις εἴτε καὶ τοῖς πᾶσιν Ἕλλησι συμβὰς αὐχμός. ἐνταῦθα καὶ Τιμόθεος ὁ Κόνωνος καὶ αὐτὸς κεῖται Κόνων· Πρόκνην δὲ τὰ ἐς τὸν παῖδα βεβουλευμένην αὐτήν τε καὶ τὸν Ἴτυν ἀνέθηκεν Ἀλκαμένης. πεποίηται δὲ καὶ τὸ φυτὸν τῆς ἐλαίας Ἀθηνᾶ καὶ κῦμα ἀναφαίνων Ποσειδῶν·", "st": "1.24"}, {"sp": "N", "t": "καὶ Διός ἐστιν ἄγαλμα τό τε Λεωχάρους καὶ ὁ ὀνομαζόμενος Πολιεύς, ᾧ τὰ καθεστηκότα ἐς τὴν θυσίαν γράφων τὴν ἐπ’ αὐτοῖς λεγομένην αἰτίαν οὐ γράφω. τοῦ Διὸς τοῦ Πολιέως κριθὰς καταθέντες ἐπὶ τὸν βωμὸν μεμιγμένας πυροῖς οὐδεμίαν ἔχουσι φυλακήν· ὁ βοῦς δέ, ὃν ἐς τὴν θυσίαν ἑτοιμάσαντες φυλάσσουσιν, ἅπτεται τῶν σπερμάτων φοιτῶν ἐπὶ τὸν βωμόν. καλοῦσι δέ τινα τῶν ἱερέων βουφόνον, ⟨ὃς κτείνας τὸν βοῦν⟩ καὶ ταύτῃ τὸν πέλεκυν ῥίψας—οὕτω γάρ ἐστίν οἱ νόμος— οἴχεται φεύγων· οἱ δὲ ἅτε τὸν ἄνδρα ὃς ἔδρασε τὸ ἔργον οὐκ εἰδότες, ἐς δίκην ὑπάγουσι τὸν πέλεκυν. ταῦτα μὲν τρόπον τὸν εἰρημένον δρῶσιν· ἐς δὲ τὸν ναὸν ὃν Παρθενῶνα ὀνομάζουσιν, ἐς τοῦτον ἐσιοῦσιν", "st": "1.24"}, {"sp": "N", "t": "ὁπόσα ἐν τοῖς καλουμένοις ἀετοῖς κεῖται, πάντα ἐς τὴν Ἀθηνᾶς ἔχει γένεσιν, τὰ δὲ ὄπισθεν ἡ Ποσειδῶνος πρὸς Ἀθηνᾶν ἐστιν ἔρις ὑπὲρ τῆς γῆς· αὐτὸ δὲ ἔκ τε ἐλέφαντος τὸ ἄγαλμα καὶ χρυσοῦ πεποίηται. μέσῳ μὲν οὖν ἐπίκειταί οἱ τῷ κράνει Σφιγγὸς εἰκών—ἃ δὲ ἐς τὴν Σφίγγα λέγεται, γράψω προελθόντος ἐς τὰ Βοιώτιά μοι τοῦ λόγου—, καθ’ ἑκάτερον δὲ τοῦ κράνους γρῦπές εἰσιν ἐπειργασμένοι.", "st": "1.24"}, {"sp": "N", "t": "τούτους τοὺς γρῦπας ἐν τοῖς ἔπεσιν Ἀριστέας ὁ Προκοννήσιος μάχεσθαι περὶ τοῦ χρυσοῦ φησιν Ἀριμασποῖς ⟨τοῖς⟩ ὑπὲρ Ἰσσηδόνων· τὸν δὲ χρυσόν, ὃν φυλάσσουσιν οἱ γρῦπες, ἀνιέναι τὴν γῆν· εἶναι δὲ Ἀριμασποὺς μὲν ἄνδρας μονοφθάλμους πάντας ἐκ γενετῆς, γρῦπας δὲ θηρία λέουσιν εἰκασμένα, πτερὰ δὲ ἔχειν καὶ στόμα ἀετοῦ. καὶ γρυπῶν μὲν πέρι τοσαῦτα εἰρήσθω·", "st": "1.24"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα τῆς Ἀθηνᾶς ὀρθόν ἐστιν ἐν χιτῶνι ποδήρει καί οἱ κατὰ τὸ στέρνον ἡ κεφαλὴ Μεδούσης ἐλέφαντός ἐστιν ἐμπεποιημένη· καὶ Νίκην τε ὅσον τεσσάρων πηχῶν, ἐν δὲ τῇ χειρί δόρυ ἔχει, καί οἱ πρὸς τοῖς ποσὶν ἀσπίς τε κεῖται καὶ πλησίον τοῦ δόρατος δράκων ἐστίν· εἴη δ’ ἂν Ἐριχθόνιος οὗτος ὁ δράκων. ἔστι δὲ τῷ βάθρῳ τοῦ ἀγάλματος ἐπειργασμένη Πανδώρας γένεσις. πεποίηται δὲ Ἡσιόδῳ τε καὶ ἄλλοις ὡς ἡ Πανδώρα γένοιτο αὕτη γυνὴ πρώτη· πρὶν δὲ ἢ γενέσθαι Πανδώραν οὐκ ἦν πω γυναικῶν γένος. ἐνταῦθα εἰκόνα ἰδὼν οἶδα Ἀδριανοῦ βασιλέως μόνου, καὶ κατὰ τὴν ἔσοδον Ἰφικράτους ἀποδειξαμένου πολλά τε καὶ θαυμαστὰ ἔργα.", "st": "1.24"}, {"sp": "N", "t": "τοῦ ναοῦ δέ ἐστι πέραν Ἀπόλλων χαλκοῦς, καὶ τὸ ἄγαλμα λέγουσι Φειδίαν ποιῆσαι· Παρνόπιον δὲ καλοῦσιν, ὅτι σφίσι παρνόπων βλαπτόντων τὴν γῆν ἀποτρέψειν ὁ θεὸς εἶπεν ἐκ τῆς χώρας. καὶ ὅτι μὲν ἀπέτρεψεν ἴσασι, τρόπῳ δὲ οὐ λέγουσι ποίῳ. τρὶς δὲ αὐτὸς ἤδη πάρνοπας ἐκ Σιπύλου τοῦ ὄρους οὐ κατὰ ταὐτὰ οἶδα φθαρέντας, ἀλλὰ τοὺς μὲν ἐξέωσε βίαιος ἐμπεσὼν ἄνεμος, τοὺς δὲ ὕσαντος τοῦ θεοῦ καῦμα ἰσχυρὸν καθεῖλεν ἐπιλαβόν, οἱ δὲ αἰφνιδίῳ ῥίγει καταληφθέντες ἀπώλοντο.", "st": "1.24"}, {"sp": "N", "t": "τοιαῦτα μὲν αὐτοῖς συμβαίνοντα εἶδον· ἔστι δὲ ἐν τῇ Ἀθηναίων ἀκροπόλει καὶ Περικλῆς ὁ Ξανθίππου καὶ αὐτὸς Ξάνθιππος, ὃς ἐναυμάχησεν ἐπὶ Μυκάλῃ Μήδοις. ἀλλ’ ὁ μὲν Περικλέους ἀνδριὰς ἑτέρωθι ἀνάκειται, τοῦ δὲ Ξανθίππου πλησίον ἕστηκεν Ἀνακρέων ὁ Τήιος, πρῶτος μετὰ Σαπφὼ τὴν Λεσβίαν τὰ πολλὰ ὧν ἔγραψεν ἐρωτικὰ ποιήσας· καί οἱ τὸ σχῆμά ἐστιν οἷον ᾄδοντος ἂν ἐν μέθῃ γένοιτο ἀνθρώπου. γυναῖκας δὲ πλησίον Δεινομένης Ἰὼ τὴν Ἰνάχου καὶ Καλλιστὼ τὴν Λυκάονος πεποίηκεν, αἷς ἀμφοτέραις ἐστὶν ἐς ἅπαν ὅμοια διηγήματα ἔρως Διὸς καὶ Ἥρας ὀργὴ καὶ ἀλλαγὴ τῇ μὲν ἐς βοῦν, Καλλιστοῖ δὲ ἐς ἄρκτον.", "st": "1.25"}, {"sp": "N", "t": "πρὸς δὲ τῷ τείχει τῷ Νοτίῳ γιγάντων, οἳ περὶ Θρᾴκην ποτὲ καὶ τὸν ἰσθμὸν τῆς Παλλήνης ᾤκησαν, τούτων τὸν λεγόμενον πόλεμον καὶ μάχην πρὸς Ἀμαζόνας Ἀθηναίων καὶ τὸ Μαραθῶνι πρὸς Μήδους ἔργον καὶ Γαλατῶν τὴν ἐν Μυσίᾳ φθορὰν ἀνέθηκεν Ἄτταλος, ὅσον τε δύο πηχῶν ἕκαστον. ἕστηκε δὲ καὶ Ὀλυμπιόδωρος, μεγέθει τε ὧν ἔπραξε λαβὼν δόξαν καὶ οὐχ ἥκιστα τῷ καιρῷ, φρόνημα ἐν ἀνθρώποις παρασχόμενος συνεχῶς ἐπταικόσι καὶ δι’ αὐτὸ οὐδὲ ἓν χρηστὸν οὐδὲ ἐς τὰ μέλλοντα ἐλπίζουσι.", "st": "1.25"}, {"sp": "N", "t": "τὸ γὰρ ἀτύχημα τὸ ἐν Χαιρωνείᾳ ἅπασι τοῖς Ἕλλησιν ἦρξε κακοῦ καὶ οὐχ ἥκιστα δούλους ἐποίησε τοὺς ὑπεριδόντας καὶ ὅσοι μετὰ Μακεδόνων ἐτάχθησαν. τὰς μὲν δὴ πολλὰς Φίλιππος τῶν πόλεων εἷλεν, Ἀθηναίοις δὲ λόγῳ συνθέμενος ἔργῳ σφᾶς μάλιστα ἐκάκωσε, νήσους τε ἀφελόμενος καὶ τῆς ἐς τὰ ναυτικὰ παύσας ἀρχῆς. καὶ χρόνον μέν τινα ἡσύχασαν Ἀθηναῖοι Φιλίππου βασιλεύοντος καὶ ὕστερον Ἀλεξάνδρου· τελευτήσαντος δὲ Ἀλεξάνδρου Μακεδόνες μὲν βασιλεύειν εἵλοντο Ἀριδαῖον, Ἀντιπάτρῳ δὲ ἐπετέτραπτο ἡ πᾶσα ἀρχή, καὶ Ἀθηναίοις οὐκέτι ἀνεκτὰ ἐφαίνετο εἰ τὸν πάντα χρόνον ἔσται ἐπὶ Μακεδόσι τὸ Ἑλληνικόν, ἀλλ’ αὐτοί τε πολεμεῖν ὥρμηντο καὶ ἄλλους ἐς τὸ ἔργον ἤγειρον.", "st": "1.25"}, {"sp": "N", "t": "ἐγένοντο δὲ αἱ μετασχοῦσαι πόλεις Πελοποννησίων μὲν Ἄργος Ἐπίδαυρος Σικυὼν Τροιζὴν Ἠλεῖοι Φλιάσιοι Μεσσήνη, οἱ δὲ ἔξω τοῦ Κορινθίων ἰσθμοῦ Λοκροὶ Φωκεῖς Θεσσαλοὶ Κάρυστος Ἀκαρνᾶνες ἐς τὸ Αἰτωλικὸν συντελοῦντες· Βοιωτοὶ δὲ Θηβαίων ἠρημωμένην τὴν γῆν τὴν Θηβαΐδα νεμόμενοι δέει μὴ Θήβας αὖθις Ἀθηναῖοί σφισιν ἐποικίζωσιν οὔτε ἐς τὴν συμμαχίαν ἐτάσσοντο καὶ ἐς ὅσον ἧκον δυνάμεως τὰ Μακεδόνων ηὖξον.", "st": "1.25"}, {"sp": "N", "t": "τοὺς δὲ ἐς τὸ συμμαχικὸν ταχθέντας κατὰ πόλεις τε ἑκάστους ἦγον στρατηγοὶ καὶ τοῦ παντὸς ἄρχειν ᾕρητο Ἀθηναῖος Λεωσθένης πόλεώς τε ἀξιώματι καὶ αὐτὸς εἶναι δοκῶν πολέμων ἔμπειρος. ὑπῆρχε δέ οἱ καὶ πρὸς πάντας εὐεργεσία τοὺς Ἕλληνας· ὁπόσοι γὰρ μισθοῦ παρὰ Δαρείῳ καὶ σατράπαις ἐστρατεύοντο Ἕλληνες, ἀνοικίσαι σφᾶς ἐς τὴν Περσίδα θελήσαντος Ἀλεξάνδρου Λεωσθένης ἔφθη κομίσας ναυσὶν ἐς τὴν Εὐρώπην. καὶ δὴ καὶ τότε ὧν ἐς αὐτὸν ἤλπισαν [τὰ] ἔργα λαμπρότερα ἐπιδειξάμενος παρέσχεν ἀποθανὼν ἀθυμῆσαι πᾶσι καὶ δι’ αὐτὸ οὐχ ἥκιστα σφαλῆναι· φρουρά τε Μακεδόνων ἐσῆλθεν Ἀθηναίοις, οἳ Μουνυχίαν, ὕστερον δὲ καὶ Πειραιᾶ καὶ τείχη μακρὰ ἔσχον.", "st": "1.25"}, {"sp": "N", "t": "Ἀντιπάτρου δὲ ἀποθανόντος Ὀλυμπιὰς διαβᾶσα ἐξ Ἠπείρου χρόνον μέν τινα ἦρξεν ἀποκτείνασα Ἀριδαῖον, οὐ πολλῷ δὲ ὕστερον ἐκπολιορκηθεῖσα ὑπὸ Κασσάνδρου παρεδόθη τῷ πλήθει. Κάσσανδρος δὲ βασιλεύσας—τὰ δὲ ἐς Ἀθηναίους ἐπέξεισί μοι μόνα ὁ λόγος—Πάνακτον τεῖχος ἐν τῇ Ἀττικῇ καὶ Σαλαμῖνα εἷλε τύραννόν τε Ἀθηναίοις ἔπραξε γενέσθαι Δημήτριον τὸν Φανοστράτου, [τὰ πρὸς] δόξαν εἰληφότα ἐπὶ σοφίᾳ. τοῦτον μὲν δὴ τυραννίδος ἔπαυσε Δημήτριος ὁ Ἀντιγόνου, νέος τε ὢν καὶ φιλοτίμως πρὸς τὸ Ἑλληνικὸν διακείμενος·", "st": "1.25"}, {"sp": "N", "t": "Κάσσανδρος δὲ—δεινὸν γάρ τι ὑπῆν οἱ μῖσος ἐς τοὺς Ἀθηναίους—, ὁ δὲ αὖθις Λαχάρην προεστηκότα ἐς ἐκεῖνο τοῦ δήμου, τοῦτον τὸν ἄνδρα οἰκειωσάμενος τυραννίδα ἔπεισε βουλεῦσαι, τυράννων ὧν ἴσμεν τά τε ἐς ἀνθρώπους μάλιστα ἀνήμερον καὶ ἐς τὸ θεῖον ἀφειδέστατον. Δημητρίῳ δὲ τῷ Ἀντιγόνου διαφορὰ μὲν ἦν ἐς τὸν δῆμον ἤδη τῶν Ἀθηναίων, καθεῖλε δὲ ὅμως καὶ τὴν Λαχάρους τυραννίδα· ἁλισκομένου δὲ τοῦ τείχους ἐκδιδράσκει Λαχάρης ἐς Βοιωτούς, ἅτε δὲ ἀσπίδας ἐξ ἀκροπόλεως καθελὼν χρυσᾶς καὶ αὐτὸ τῆς Ἀθηνᾶς τὸ ἄγαλμα τὸν περιαιρετὸν ἀποδύσας κόσμον ὑπωπτεύετο εὐπορεῖν μεγάλως χρημάτων.", "st": "1.25"}, {"sp": "N", "t": "Λαχάρην μὲν οὖν τούτων ἕνεκα κτείνουσιν ἄνδρες Κορωναῖοι· Δημήτριος δὲ ὁ Ἀντιγόνου τυράννων ἐλευθερώσας Ἀθηναίους τό τε παραυτίκα μετὰ τὴν Λαχάρους φυγὴν οὐκ ἀπέδωκέ σφισι τὸν Πειραιᾶ καὶ ὕστερον πολέμῳ κρατήσας ἐσήγαγεν ἐς αὐτὸ φρουρὰν τὸ ἄστυ, τὸ Μουσεῖον καλούμενον τειχίσας. ἔστι δὲ ἐντὸς τοῦ περιβόλου τοῦ ἀρχαίου τὸ Μουσεῖον ἀπαντικρὺ τῆς ἀκροπόλεως λόφος, ἔνθα Μουσαῖον ᾄδειν καὶ ἀποθανόντα γήρᾳ ταφῆναι λέγουσιν· ὕστερον δὲ καὶ μνῆμα αὐτόθι ἀνδρὶ ᾠκοδομήθη Σύρῳ. τότε δὲ Δημήτριος τειχίσας εἶχε·", "st": "1.25"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον ἄνδρας ἐσῆλθεν οὐ πολλοὺς [καὶ] μνήμη τε προγόνων καὶ ἐς οἵαν μεταβολὴν τὸ ἀξίωμα ἥκοι τῶν Ἀθηναίων, αὐτίκα τε ὡς εἶχον αἱροῦνται στρατηγὸν Ὀλυμπιόδωρον. ὁ δὲ σφᾶς ἐπὶ τοὺς Μακεδόνας ἦγε καὶ γέροντας καὶ μειράκια ὁμοίως, προθυμίᾳ πλέον ἢ ῥώμῃ κατορθοῦσθαι τὰ ἐς πόλεμον ἐλπίζων· ἐπεξελθόντας δὲ τοὺς Μακεδόνας μάχῃ τε ἐκράτησε καὶ φυγόντων ἐς τὸ Μουσεῖον τὸ χωρίον εἷλεν.", "st": "1.26"}, {"sp": "N", "t": "Ἀθῆναι μὲν οὕτως ἀπὸ Μακεδόνων ἠλευθερώθησαν, Ἀθηναίων δὲ πάντων ἀγωνισαμένων ἀξίως λόγου Λεώκριτος μάλιστα ὁ Πρωτάρχου λέγεται τόλμῃ χρήσασθαι πρὸς τὸ ἔργον· πρῶτος μὲν γὰρ ἐπὶ τὸ τεῖχος ἀνέβη, πρῶτος δὲ ἐς τὸ Μουσεῖον ἐσήλατο, καί οἱ πεσόντι ἐν τῇ μάχῃ τιμαὶ παρ’ Ἀθηναίων καὶ ἄλλαι γεγόνασι καὶ τὴν ἀσπίδα ἀνέθεσαν τῷ Διὶ τῷ Ἐλευθερίῳ, τὸ ὄνομα τοῦ Λεωκρίτου καὶ τὸ κατόρθωμα ἐπιγράψαντες.", "st": "1.26"}, {"sp": "N", "t": "Ὀλυμπιοδώρῳ δὲ τόδε μέν ἐστιν ἔργον μέγιστον χωρὶς τούτων ὧν ἔπραξε Πειραιᾶ καὶ Μουνυχίαν ἀνασωσάμενος· ποιουμένων δὲ Μακεδόνων καταδρομὴν ἐς Ἐλευσῖνα Ἐλευσινίους συντάξας ἐνίκα τοὺς Μακεδόνας. πρότερον δὲ ἔτι τούτων ἐσβαλόντος ἐς τὴν Ἀττικὴν Κασσάνδρου πλεύσας Ὀλυμπιόδωρος ἐς Αἰτωλίαν βοηθεῖν Αἰτωλοὺς ἔπεισε, καὶ τὸ συμμαχικὸν τοῦτο ἐγένετο Ἀθηναίοις αἴτιον μάλιστα διαφυγεῖν τὸν Κασσάνδρου πόλεμον. Ὀλυμπιοδώρῳ δὲ τοῦτο μὲν ἐν Ἀθήναις εἰσὶν ἔν τε ἀκροπόλει καὶ ἐν πρυτανείῳ τιμαί, τοῦτο δὲ ἐν Ἐλευσῖνι γραφή· καὶ Φωκέων οἱ Ἐλάτειαν ἔχοντες χαλκοῦν Ὀλυμπιόδωρον ἐν Δελφοῖς ἀνέθεσαν, ὅτι καὶ τούτοις ἤμυνεν ἀποστᾶσι Κασσάνδρου.", "st": "1.26"}, {"sp": "N", "t": "τῆς δὲ εἰκόνος πλησίον τῆς Ὀλυμπιοδώρου χαλκοῦν Ἀρτέμιδος ἄγαλμα ἕστηκεν ἐπίκλησιν Λευκοφρύνης, ἀνέθεσαν δὲ οἱ παῖδες οἱ Θεμιστοκλέους· Μάγνητες γάρ, ὧν ἦρχε Θεμιστοκλῆς λαβὼν παρὰ βασιλέως, Λευκοφρύνην Ἄρτεμιν ἄγουσιν ἐν τιμῇ. δεῖ δέ με ἀφικέσθαι τοῦ λόγου πρόσω, πάντα ὁμοίως ἐπεξιόντα τὰ Ἑλληνικά. Ἔνδοιος ἦν γένος μὲν Ἀθηναῖος, Δαιδάλου δὲ μαθητής, ὃς καὶ φεύγοντι Δαιδάλῳ διὰ τὸν Κάλω θάνατον ἐπηκολούθησεν ἐς Κρήτην· τούτου καθήμενόν ἐστιν Ἀθηνᾶς ἄγαλμα, ἐπίγραμμα ἔχον ὡς Καλλίας μὲν ἀναθείη, ποιήσειε δὲ Ἔνδοιος.", "st": "1.26"}, {"sp": "N", "t": "—ἔστι δὲ καὶ οἴκημα Ἐρέχθειον καλούμενον· πρὸ δὲ τῆς ἐσόδου Διός ἐστι βωμὸς Ὑπάτου, ἔνθα ἔμψυχον θύουσιν οὐδέν, πέμματα δὲ θέντες οὐδὲν ἔτι οἴνῳ χρήσασθαι νομίζουσιν. ἐσελθοῦσι δέ εἰσι βωμοί, Ποσειδῶνος, ἐφ’ οὗ καὶ Ἐρεχθεῖ θύουσιν ἔκ του μαντεύματος, καὶ ἥρωος Βούτου, τρίτος δὲ Ἡφαίστου· γραφαὶ δὲ ἐπὶ τῶν τοίχων τοῦ γένους εἰσὶ τοῦ Βαυταδῶν καὶ—διπλοῦν γάρ ἐστι τὸ οἴκημα—[καὶ] ὕδωρ ἐστὶν ἔνδον θαλάσσιον ἐν φρέατι. τοῦτο μὲν θαῦμα οὐ μέγα· καὶ γὰρ ὅσοι μεσόγαιαν οἰκοῦσιν, ἄλλοις τε ἔστι καὶ Καρσὶν Ἀφροδισιεῦσιν· ἀλλὰ τόδε ⟨τὸ⟩ φρέαρ ἐς συγγραφὴν παρέχεται κυμάτων ἦχον ἐπὶ νότῳ πνεύσαντι. καὶ τριαίνης ἐστὶν ἐν τῇ πέτρᾳ σχῆμα· ταῦτα δὲ λέγεται Ποσειδῶνι μαρτύρια ἐς τὴν ἀμφισβήτησιν τῆς χώρας φανῆναι.", "st": "1.26"}, {"sp": "N", "t": "ἱερὰ μὲν τῆς Ἀθηνᾶς ἐστιν ἥ τε ἄλλη πόλις καὶ ἡ πᾶσα ὁμοίως γῆ—καὶ γὰρ ὅσοις θεοὺς καθέστηκεν ἄλλους ἐν τοῖς δήμοις σέβειν, οὐδέν τι ἧσσον τὴν Ἀθηνᾶν ἄγουσιν ἐν τιμῇ—, τὸ δὲ ἁγιώτατον ἐν κοινῷ πολλοῖς πρότερον νομισθὲν ἔτεσιν ⟨ἢ⟩ συνῆλθον ἀπὸ τῶν δήμων ἐστὶν Ἀθηνᾶς ἄγαλμα ἐν τῇ νῦν ἀκροπόλει, τότε δὲ ὀνομαζομένῃ πόλει· φήμη δὲ ἐς αὐτὸ ἔχει πεσεῖν ἐκ τοῦ οὐρανοῦ. καὶ τοῦτο μὲν οὐκ ἐπέξειμι εἴτε οὕτως εἴτε ἄλλως ἔχει, λύχνον δὲ τῇ θεῷ χρυσοῦν Καλλίμαχος ἐποίησεν·", "st": "1.26"}, {"sp": "N", "t": "ἐμπλήσαντες δὲ ἐλαίου τὸν λύχνον τὴν αὐτὴν τοῦ μέλλοντος ἔτους ἀναμένουσιν ἡμέραν, ἔλαιον δὲ ἐκεῖνο τὸν μεταξὺ ἐπαρκεῖ χρόνον τῷ λύχνῳ κατὰ τὰ αὐτὰ ἐν ἡμέρᾳ καὶ νυκτὶ φαίνοντι. καί οἱ λίνου Καρπασίου θρυαλλὶς ἔνεστιν, ὃ δὴ πυρὶ λίνων μόνον οὐκ ἔστιν ἁλώσιμον· φοῖνιξ δὲ ὑπὲρ τοῦ λύχνου χαλκοῦς ἀνήκων ἐς τὸν ὄροφον ἀνασπᾷ τὴν ἀτμίδα. ὁ δὲ Καλλίμαχος ⟨ὁ⟩ τὸν λύχνον ποιήσας, ἀποδέων τῶν πρώτων ἐς αὐτὴν τὴν τέχνην, οὕτω σοφίᾳ πάντων ἐστὶν ἄριστος ὥστε καὶ λίθους πρῶτος ἐτρύπησε καὶ ὄνομα ἔθετο κατατηξίτεχνον, ἢ θεμένων ἄλλων κατέστησεν ἐφ’ αὑτῷ.", "st": "1.26"}, {"sp": "N", "t": "κεῖται δὲ ἐν τῷ ναῷ τῆς Πολιάδος Ἑρμῆς ξύλου, Κέκροπος εἶναι λεγόμενον ἀνάθημα, ὑπὸ κλάδων μυρσίνης οὐ σύνοπτον. ἀναθήματα δὲ ὁπόσα ἄξια λόγου, τῶν μὲν ἀρχαίων δίφρος ὀκλαδίας ἐστὶ Δαιδάλου ποίημα, λάφυρα δὲ ἀπὸ Μήδων Μασιστίου θώραξ, ὃς εἶχεν ἐν Πλαταιαῖς τὴν ἡγεμονίαν τῆς ἵππου, καὶ ἀκινάκης Μαρδονίου λεγόμενος εἶναι. Μασίστιον μὲν δὴ τελευτήσαντα ὑπὸ τῶν Ἀθηναίων οἶδα ἱππέων· Μαρδονίου δὲ μαχεσαμένου Λακεδαιμονίοις ἐναντία καὶ ὑπὸ ἀνδρὸς Σπαρτιάτου πεσόντος οὐδ’ ἂν ὑπεδέξαντο ἀρχὴν οὐδὲ ἴσως Ἀθηναίοις παρῆκαν φέρεσθαι Λακεδαιμόνιοι τὸν ἀκινάκην.", "st": "1.27"}, {"sp": "N", "t": "περὶ δὲ τῆς ἐλαίας οὐδὲν ἔχουσιν ἄλλο εἰπεῖν ἢ τῇ θεῷ μαρτύριον γενέσθαι τοῦτο ἐς τὸν ἀγῶνα τὸν ἐπὶ τῇ χώρᾳ· λέγουσι δὲ καὶ τάδε, κατακαυθῆναι μὲν τὴν ἐλαίαν, ἡνίκα ὁ Μῆδος τὴν πόλιν ἐνέπρησεν Ἀθηναίοις, κατακαυθεῖσαν δὲ αὐθημερὸν ὅσον τε ἐπὶ δύο βλαστῆσαι πήχεις. τῷ ναῷ δὲ τῆς Ἀθηνᾶς Πανδρόσου ναὸς συνεχής ἐστι· καὶ ἔστι Πάνδροσος ἐς τὴν παρακαταθήκην ἀναίτιος τῶν ἀδελφῶν μόνη.", "st": "1.27"}, {"sp": "N", "t": "ἃ δέ μοι θαυμάσαι μάλιστα παρέσχεν, ἔστι μὲν οὐκ ἐς ἅπαντα⟨ς⟩ γνώριμα, γράψω δὲ οἷα συμβαίνει. παρθένοι δύο τοῦ ναοῦ τῆς Πολιάδος οἰκοῦσιν οὐ πόρρω, καλοῦσι δὲ Ἀθηναῖοι σφᾶς ἀρρηφόρους· αὗται χρόνον μέν τινα δίαιταν ἔχουσι παρὰ τῇ θεῷ, παραγενομένης δὲ τῆς ἑορτῆς δρῶσιν ἐν νυκτὶ τοιάδε. ἀναθεῖσαί σφισιν ἐπὶ τὰς κεφαλὰς ἃ ἡ τῆς Ἀθηνᾶς ἱέρεια δίδωσι φέρειν, οὔτε ἡ διδοῦσα ὁποῖόν τι δίδωσιν εἰδυῖα οὔτε ταῖς φερούσαις ἐπισταμέναις—ἔστι δὲ περίβολος ἐν τῇ πόλει τῆς καλουμένης ἐν Κήποις Ἀφροδίτης οὐ πόρρω καὶ δι’ αὐτοῦ κάθοδος ὑπόγαιος αὐτομάτη—, ταύτῃ κατίασιν αἱ παρθένοι. κάτω μὲν δὴ τὰ φερόμενα λείπουσιν, λαβοῦσαι δὲ ἄλλο τι κομίζουσιν ἐγκεκαλυμμένον· καὶ τὰς μὲν ἀφιᾶσιν ἤδη τὸ ἐντεῦθεν, ἑτέρας δὲ ἐς τὴν ἀκρόπολιν παρθένους ἄγουσιν ἀντ’ αὐτῶν.", "st": "1.27"}, {"sp": "N", "t": "πρὸς δὲ τῷ ναῷ τῆς Ἀθηνᾶς ἔστι μὲν †εὐήρις πρεσβῦτις ὅσον τε πήχεος μάλιστα, φαμένη διάκονος εἶναι Λυσιμάχης, ἔστι δὲ ἀγάλματα μεγάλα χαλκοῦ διεστῶτες ⟨ἄνδρες⟩ ἐς μάχην· καὶ τὸν μὲν Ἐρεχθέα καλοῦσι, τὸν δὲ Εὔμολπον· καίτοι λέληθέ γε οὐδὲ Ἀθηναίων ὅσοι τὰ ἀρχαῖα ἴσασιν, Ἰμμάραδον εἶναι παῖδα Εὐμόλπου τοῦτον τὸν ἀποθανόντα ὑπὸ Ἐρεχθέως.", "st": "1.27"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ βάθρου καὶ ἀνδριάντες εἰσὶ Θεαίνετος ὃς ἐμαντεύετο Τολμίδῃ καὶ αὐτὸς Τολμίδης, ὃς Ἀθηναίων ναυσὶν ἡγούμενος ἄλλους τε ἐκάκωσε καὶ Πελοποννησίων τὴν χώραν ὅσοι νέμονται τὴν παραλίαν, καὶ Λακεδαιμονίων ἐπὶ Γυθίῳ τὰ νεώρια ἐνέπρησε καὶ τῶν περιοίκων Βοιὰς εἷλε καὶ τὴν Κυθηρίων νῆσον· ἐς δὲ τὴν Σικυωνίαν ποιησάμενος ἀπόβασιν, ὥς οἱ δῃοῦντι τὴν γῆν ἐς μάχην κατέστησαν, τρεψάμενος σφᾶς κατεδίωξε πρὸς τὴν πόλιν. ὕστερον δὲ ὡς ἐπανῆλθεν ἐς Ἀθήνας, ἐσήγαγε μὲν ἐς Εὔβοιαν καὶ Νάξον Ἀθηναίων κληρούχους, ἐσέβαλε δὲ ἐς Βοιωτοὺς στρατῷ· πορθήσας δὲ τῆς γῆς τὴν πολλὴν καὶ παραστησάμενος πολιορκίᾳ Χαιρώνειαν, ὡς ἐς τὴν Ἀλιαρτίαν προῆλθεν, αὐτός τε μαχόμενος ἀπέθανε καὶ τὸ πᾶν ἤδη στράτευμα ἡττᾶτο. τὰ μὲν ἐς Τολμίδην τοιαῦτα ἐπυνθανόμην ὄντα, ἔστι δὲ Ἀθηνᾶς ἀγάλματα", "st": "1.27"}, {"sp": "N", "t": "ἀρχαῖα· καί σφισιν ἀπετάκη μὲν οὐδέν, μελάντερα δὲ καὶ πληγὴν ἐνεγκεῖν ἐστιν ἀσθενέστερα· ἐπέλαβε γὰρ καὶ ταῦτα ἡ φλόξ, ὅτε ἐσβεβηκότων ἐς τὰς ναῦς Ἀθηναίων βασιλεὺς εἷλεν ἔρημον τῶν ἐν ἡλικίᾳ τὴν πόλιν. ἔστι δὲ συός τε θήρα, περὶ οὗ σαφὲς οὐδὲν οἶδα εἰ τοῦ Καλυδωνίου, καὶ Κύκνος Ἡρακλεῖ μαχόμενος· τοῦτον τὸν Κύκνον φασὶν ἄλλους τε φονεῦσαι καὶ Λύκον Θρᾷκα προτεθέντων σφίσι μονομαχίας ἄθλων, περὶ δὲ τὸν ποταμὸν τὸν Πηνειὸν ἀπέθανεν ὑφ’ Ἡρακλέους.", "st": "1.27"}, {"sp": "N", "t": "τῶν δὲ ἐν Τροιζῆνι λόγων, οὓς ἐς Θησέα λέγουσιν, ἐστὶν ὡς Ἡρακλῆς ἐς Τροιζῆνα ἐλθὼν παρὰ Πιτθέα καταθεῖτο ἐπὶ τῷ δείπνῳ τοῦ λέοντος τὸ δέρμα, ἐσέλθοιεν δὲ παρ’ αὐτὸν ἄλλοι τε Τροιζηνίων παῖδες καὶ Θησεὺς ἕβδομον μάλιστα γεγονὼς ἔτος· τοὺς μὲν δὴ λοιποὺς παῖδας, ὡς τὸ δέρμα εἶδον, φεύγοντάς φασιν οἴχεσθαι, Θησέα δὲ ὑπεξελθόντα οὐκ ἄγαν σὺν φόβῳ παρὰ τῶν διακόνων ἁρπάσαι πέλεκυν καὶ αὐτίκα ἐπιέναι σπουδῇ, λέοντα εἶναι τὸ δέρμα ἡγούμενον.", "st": "1.27"}, {"sp": "N", "t": "ὅδε μὲν τῶν λόγων πρῶτος ἐς αὐτόν ἐστι Τροιζηνίοις· ὁ δὲ ἐπὶ τούτῳ, κρηπῖδας Αἰγέα ὑπὸ πέτρᾳ καὶ ξίφος θεῖναι γνωρίσματα εἶναι τῷ παιδὶ καὶ τὸν μὲν ἐς Ἀθήνας ἀποπλεῖν, Θησέα δέ, ὡς ἕκτον καὶ δέκατον ἔτος ἐγεγόνει, τὴν πέτραν ἀνώσαντα οἴχεσθαι [καὶ] τὴν παρακαταθήκην τὴν Αἰγέως φέροντα. τούτου δὲ εἰκὼν ἐν ἀκροπόλει πεποίηται τοῦ λόγου, χαλκοῦ πάντα ὁμοίως πλὴν τῆς πέτρας·", "st": "1.27"}, {"sp": "N", "t": "ἀνέθεσαν δὲ καὶ ἄλλο Θησέως ἔργον, καὶ ὁ λόγος οὕτως ἐς αὐτὸ ἔχει. Κρησὶ τήν τε ἄλλην γῆν καὶ τὴν ἐπὶ ποταμῷ Τεθρίνι ταῦρος ἐλυμαίνετο. πάλαι δὲ ἄρα τὰ θηρία φοβερώτερα ἦν τοῖς ἀνθρώποις ὡς ὅ τ’ ἐν Νεμέᾳ λέων καὶ ὁ Παρνάσ⟨σ⟩ιος καὶ δράκοντες τῆς Ἑλλάδος πολλαχοῦ καὶ ὗς περί τε Καλυδῶνα καὶ Ἐρύμανθον καὶ τῆς Κορινθίας ἐν Κρομ[μ]υῶνι, ὥστε καὶ ἐλέγετο τὰ μὲν ἀνιέναι τὴν γῆν, τὰ δὲ ὡς ἱερὰ εἴη θεῶν, τὰ δὲ καὶ ἐς τιμωρίαν ἀνθρώπων ἀφεῖσθαι. καὶ τοῦτον οἱ Κρῆτες τὸν ταῦρον ἐς τὴν γῆν πέμψαι σφίσι Ποσειδῶνά φασιν, ὅτι θαλάσσης ἄρχων Μίνως τῆς Ἑλληνικῆς οὐδενὸς Ποσειδῶνα ἦγεν ἄλλου θεοῦ μᾶλλον ἐν τιμῇ.", "st": "1.27"}, {"sp": "N", "t": "κομισθῆναι μὲν δὴ τὸν ταῦρον τοῦτόν φασιν ἐς Πελοπόννησον ἐκ Κρήτης καὶ Ἡρακλεῖ τῶν δώδεκα καλουμένων ἕνα καὶ τοῦτον γενέσθαι τὸν ἆθλον· ὡς δὲ ἐς τὸ πεδίον ἀφείθη τὸ Ἀργείων, φεύγει διὰ τοῦ Κορινθίου ἰσθμοῦ, φεύγει δὲ ἐς γῆν τὴν Ἀττικὴν καὶ τῆς Ἀττικῆς ἐς δῆμον τὸν Μαραθωνίων, καὶ ἄλλους τε ὁπόσοις ἐπέτυχε καὶ Μίνω παῖδα Ἀνδρόγεων ἀπέκτεινε. Μίνως δὲ ναυσὶν ἐπ’ Ἀθήνας πλεύσας—οὐ γὰρ ἐπείθετο ἀναιτίους εἶναι σφᾶς τῆς Ἀνδρόγεω τελευτῆς—ἐς τοσοῦτον ἐκάκωσεν, ἐς ὃ συνεχωρήθη οἱ παρθένους ἐς Κρήτην ἑπτὰ καὶ παῖδας ἴσους ἄγειν τῷ λεγομένῳ Μίνω ταύρῳ τὸν ἐν Κνωσσῷ Λαβύρινθον οἰκῆσαι· τὸν δὲ ἐν τῷ Μαραθῶνι ταῦρον ὕστερον Θησεὺς ἐς τὴν ἀκρόπολιν ἐλάσαι καὶ θῦσαι λέγεται τῇ θεῷ, καὶ τὸ ἀνάθημά ἐστι τοῦ δήμου τοῦ Μαραθωνίων.", "st": "1.27"}, {"sp": "N", "t": "Κύλωνα δὲ οὐδὲν ἔχω σαφὲς εἰπεῖν ἐφ’ ὅτῳ χαλκοῦν ἀνέθεσαν τυραννίδα ὅμως βουλεύσαντα· τεκμαίρομαι δὲ τῶνδε ἕνεκα, ὅτι εἶδος κάλλιστος καὶ τὰ ἐς δόξαν ἐγένετο οὐκ ἀφανὴς ἀνελόμενος διαύλου νίκην Ὀλυμπικὴν καί οἱ θυγατέρα ὑπῆρξε γῆμαι Θεαγένους, ὃς Μεγάρων ἐτυράννησε.", "st": "1.28"}, {"sp": "N", "t": "χωρὶς δὲ ἢ ὅσα κατέλεξα δύο μὲν Ἀθηναίοις εἰσὶ δεκάται πολεμήσασιν, ἄγαλμα Ἀθηνᾶς χαλκοῦν ἀπὸ Μήδων τῶν ἐς Μαραθῶνα ἀποβάντων τέχνη Φειδίου—καί οἱ τὴν ἐπὶ τῆς ἀσπίδος ⟨μάχην⟩ Λαπιθῶν πρὸς Κενταύρους καὶ ὅσα ἄλλα ἐστὶν ἐπειργασμένα λέγουσι τορεῦσαι Μῦν, τῷ δὲ Μυῒ ταῦτά τε καὶ τὰ λοιπὰ τῶν ἔργων Παρράσιον καταγράψαι τὸν Εὐήνορος· ταύτης τῆς Ἀθηνᾶς ἡ τοῦ δόρατος αἰχμὴ καὶ ὁ λόφος τοῦ κράνους ἀπὸ Σουνίου προσπλέουσίν ἐστιν ἤδη σύνοπτα—, καὶ ἅρμα κεῖται χαλκοῦν ἀπὸ Βοιωτῶν δεκάτη καὶ Χαλκιδέων τῶν ἐν Εὐβοίᾳ. δύο δὲ ἄλλα ἐστὶν ἀναθήματα, Περικλῆς ὁ Ξανθίππου καὶ τῶν ἔργων τῶν Φειδίου θέας μάλιστα ἄξιον Ἀθηνᾶς ἄγαλμα ἀπὸ τῶν ἀναθέντων καλουμένης Λημνίας.", "st": "1.28"}, {"sp": "N", "t": "τῇ δὲ ἀκροπόλει, πλὴν ὅσον Κίμων ᾠκοδόμησεν αὐτῆς ὁ Μιλτιάδου, περιβαλεῖν τὸ λοιπὸν λέγεται τοῦ τείχους Πελασγοὺς οἰκήσαντάς ποτε ὑπὸ τὴν ἀκρόπολιν· φασὶ γὰρ Ἀγρόλαν καὶ Ὑπέρβιον ⟨τοὺς οἰκοδομήσαντας εἶναι⟩. πυνθανόμενος δὲ οἵτινες ἦσαν οὐδὲν ἄλλο ἐδυνάμην μαθεῖν ἢ Σικελοὺς τὸ ἐξ ἀρχῆς ὄντας ⟨ἐς⟩ Ἀκαρνανίαν μετοικῆσαι.", "st": "1.28"}, {"sp": "N", "t": "καταβᾶσι δὲ οὐκ ἐς τὴν κάτω πόλιν ἀλλ’ ὅσον ὑπὸ τὰ προπύλαια πηγή τε ὕδατός ἐστι καὶ πλησίον Ἀπόλλωνος ἱερὸν ἐν σπηλαίῳ· Κρεούσῃ δὲ θυγατρὶ Ἐρεχθέως Ἀπόλλωνα ἐνταῦθα συγγενέσθαι νομίζουσι. … ὡς πεμφθείη Φιλιππίδης ἐς Λακεδαίμονα ἄγγελος ἀποβεβηκότων Μήδων ἐς τὴν γῆν, ἐπανήκων δὲ Λακεδαιμονίους ὑπερβαλέσθαι φαίη τὴν ἔξοδον, εἶναι γὰρ δὴ νόμον αὐτοῖς μὴ πρότερον μαχουμένους ἐξιέναι πρὶν ἢ πλήρη τὸν κύκλον τῆς σελήνης γενέσθαι· τὸν δὲ Πᾶνα ὁ Φιλιππίδης ἔλεγε περὶ τὸ ὄρος ἐντυχόντα οἱ τὸ Παρθένιον φάναι τε ὡς εὔνους Ἀθηναίοις εἴη καὶ ὅτι ἐς Μαραθῶνα ἥξει συμμαχήσων. οὗτος μὲν οὖν ὁ θεὸς ἐπὶ ταύτῃ τῇ ἀγγελίᾳ τετίμηται·", "st": "1.28"}, {"sp": "N", "t": "[καθὸ καὶ ὁ Ἄρειος πάγος.] ἔστι δὲ Ἄρειος πάγος καλούμενος, ὅτι πρῶτος Ἄρης ἐνταῦθα ἐκρίθη, καί μοι καὶ ταῦτα δεδήλωκεν ὁ λόγος ὡς Ἁλιρρόθιον ἀνέλοι καὶ ἐφ’ ὅτῳ κτείνειε. κριθῆναι δὲ καὶ ὕστερον Ὀρέστην λέγουσιν ἐπὶ τῷ φόνῳ τῆς μητρός· καὶ βωμός ἐστιν Ἀθηνᾶς Ἀρείας, ὃν ἀνέθηκεν ἀποφυγὼν τὴν δίκην. τοὺς δὲ ἀργοὺς λίθους, ἐφ’ ὧν ἑστᾶσιν ὅσοι δίκας ὑπέχουσι καὶ οἱ διώκοντες, τὸν μὲν Ὕβρεως τὸν δὲ Ἀναιδείας αὐτῶν ὀνομάζουσι.", "st": "1.28"}, {"sp": "N", "t": "πλησίον δὲ ἱερὸν θεῶν ἐστιν ἃς καλοῦσιν Ἀθηναῖοι Σεμνάς, Ἡσίοδος δὲ Ἐρινῦς ἐν Θεογονίᾳ. πρῶτος δέ σφισιν Αἰσχύλος δράκοντας ἐποίησεν ὁμοῦ ταῖς ἐν τῇ κεφαλῇ θριξὶν εἶναι· τοῖς δὲ ἀγάλμασιν οὔτε τούτοις ἔπεστιν οὐδὲν φοβερὸν οὔτε ὅσα ἄλλα κεῖται θεῶν τῶν ὑπογαίων. κεῖται δὲ καὶ Πλούτων καὶ Ἑρμῆς καὶ Γῆς ἄγαλμα· ἐνταῦθα θύουσι μὲν ὅσοις ἐν Ἀρείῳ πάγῳ τὴν αἰτίαν ἐξεγένετο ἀπολύσασθαι, θύουσι δὲ καὶ ἄλλως ξένοι τε ὁμοίως καὶ ἀστοί.", "st": "1.28"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἐντὸς τοῦ περιβόλου μνῆμα Οἰδίποδος, πολυπραγμονῶν δὲ εὕρισκον τὰ ὀστᾶ ἐκ Θηβῶν κομισθέντα· τὰ γὰρ ἐς τὸν θάνατον Σοφοκλεῖ πεποιημένα τὸν Οἰδίποδος Ὅμηρος οὐκ εἴα μοι δόξαι πιστά, ὃς ἔφη Μηκιστέα τελευτήσαντος Οἰδίποδος ἐπιτάφιον ἐλθόντα ἐς Θήβας ἀγωνίσασθαι.", "st": "1.28"}, {"sp": "N", "t": "ἔστι δὲ Ἀθηναίοις καὶ ἄλλα δικαστήρια οὐκ ἐς τοσοῦτο δόξης ἥκοντα. τὸ μὲν οὖν καλούμενον παράβυστον καὶ τρίγωνον, τὸ μὲν ἐν ἀφανεῖ τῆς πόλεως ὂν καὶ ἐπ’ ἐλαχίστοις συνιόντων ἐς αὐτό, τὸ δὲ ἀπὸ τοῦ σχήματος ἔχει τὰ ὀνόματα· βατραχιοῦν δὲ καὶ φοινικιοῦν ἀπὸ χρωμάτων [τὸ δὲ] καὶ ἐς τόδε διαμεμένηκεν ὀνομάζεσθαι. τὸ δὲ μέγιστον καὶ ἐς ὃ πλεῖστοι συνίασιν, ἡλιαίαν καλοῦσιν. ὁπόσα δὲ ἐπὶ τοῖς φονεῦσιν, ἔστιν ἄλλα· καὶ ἐπὶ Παλλαδίῳ καλοῦσι καὶ τοῖς ἀποκτείνασιν ἀκουσίως κρίσις καθέστηκε. καὶ ὅτι μὲν Δημοφῶν πρῶτος ἐνταῦθα ὑπέσχε δίκας, ἀμφισβητοῦσιν οὐδένες·", "st": "1.28"}, {"sp": "N", "t": "ἐφ’ ὅτῳ δέ, διάφορα ἐς τοῦτο εἴρηται. Διομήδην φασὶν ἁλούσης Ἰλίου ταῖς ναυσὶν ὀπίσω κομίζεσθαι, καὶ ἤδη τε νύκτα ἐπέχειν ὡς κατὰ Φάληρον πλέοντες γίνονται καὶ τοὺς Ἀργείους ὡς ἐς πολεμίαν ἀποβῆναι τὴν γῆν, ἄλλην που δόξαντας ἐν τῇ νυκτὶ καὶ οὐ τὴν Ἀττικὴν εἶναι. ἐνταῦθα Δημοφῶντα λέγουσιν ἐκβοηθήσαντα, οὐκ ἐπιστάμενον οὐδὲ τοῦτον τοὺς ἀπὸ τῶν νεῶν ὡς εἰσὶν Ἀργεῖοι, καὶ ἄνδρας αὐτῶν ἀποκτεῖναι καὶ τὸ Παλλάδιον ἁρπάσαντα οἴχεσθαι, Ἀθηναῖόν τε ἄνδρα οὐ προϊδόμενον ὑπὸ τοῦ ἵππου τοῦ Δημοφῶντος ἀνατραπῆναι καὶ συμπατηθέντα ἀποθανεῖν· ἐπὶ τούτῳ Δημοφῶντα ὑποσχεῖν δίκας οἱ μὲν τοῦ συμπατηθέντος τοῖς προσήκουσιν, οἱ δὲ Ἀργείων φασὶ τῷ κοινῷ.", "st": "1.28"}, {"sp": "N", "t": "ἐπὶ Δελφινίῳ δὲ κρίσις καθέστηκεν ἐργάσασθαι φόνον σὺν τῷ δικαίῳ φαμένοις, ὁποῖόν τι καὶ Θησεὺς παρεχόμενος ἀπέφυγεν, ὅτε Πάλλαντα ἐπαναστάντα καὶ τοὺς παῖδας ἔκτεινε· πρότερον δὲ πρὶν ἢ Θησεὺς ἀφείθη, καθειστήκει πᾶσι φεύγειν κτείναντα ἢ κατὰ ταὐτὰ θνήσκειν μένοντα. τὸ δὲ ἐν πρυτανείῳ καλούμενον, ἔνθα τῷ σιδήρῳ καὶ πᾶσιν ὁμοίως τοῖς ἀψύχοις δικάζουσιν, ἐπὶ τῷδε ἄρξασθαι νομίζω. Ἀθηναίων βασιλεύοντος Ἐρεχθέως, τότε πρῶτον βοῦν ἔκτεινεν ὁ βουφόνος ἐπὶ τοῦ βωμοῦ τοῦ Πολιέως Διός· καὶ ὁ μὲν ἀπολιπὼν ταύτῃ τὸν πέλεκυν ἀπῆλθεν ἐκ τῆς χώρας φεύγων, ὁ δὲ πέλεκυς παραυτίκα ἀφείθη κριθεὶς καὶ ἐς τόδε ἀνὰ πᾶν ἔτος κρίνεται.", "st": "1.28"}, {"sp": "N", "t": "λέγεται μὲν δὴ καὶ ἄλλα τῶν ἀψύχων αὐτόματα ἐπιθεῖναι σὺν τῷ δικαίῳ τιμωρίαν ἀνθρώποις· ἔργον δὲ κάλλιστον καὶ δόξῃ φανερώτατον ὁ Καμβύσου παρέσχετο ἀκινάκης. ἔστι δὲ τοῦ Πειραιῶς πρὸς θαλάσσῃ Φρεαττύς· ἐνταῦθα οἱ πεφευγότες, ἢν ἀπελθόντας ἕτερον ἐπιλάβῃ σφᾶς ἔγκλημα, πρὸς ἀκροωμένους ἐκ τῆς γῆς ἀπὸ νεὼς ἀπολογοῦνται· Τεῦκρον πρῶτον λόγος ἔχει Τελαμῶνι οὕτως ἀπολογήσασθαι μηδὲν ἐς τὸν Αἴαντος θάνατον εἰργάσθαι. τάδε μὲν οὖν εἰρήσθω μοι τῶνδε ἕνεκα, γνῶναι ὁπόσοις μέτεστι σπουδῆς ⟨τὰ⟩ ἐς τὰ δικαστήρια·", "st": "1.28"}, {"sp": "N", "t": "τοῦ δὲ Ἀρείου πάγου πλησίον δείκνυται ναῦς ποιηθεῖσα ἐς τὴν τῶν Παναθηναίων πομπήν. καὶ ταύτην μὲν ἤδη πού τις ὑπερεβάλετο· τὸ δὲ ἐν Δήλῳ πλοῖον οὐδένα πω νικήσαντα οἶδα, καθῆκον ἐς ἐννέα ἐρέτας ἀπὸ τῶν καταστρωμάτων.", "st": "1.29"}, {"sp": "N", "t": "Ἀθηναίοις δὲ καὶ ἔξω πόλεως ἐν τοῖς δήμοις καὶ κατὰ τὰς ὁδοὺς θεῶν ἐστιν ἱερὰ καὶ ἡρώων καὶ ἀνδρῶν τάφοι· ἐγγυτάτω δὲ Ἀκαδημία, χωρίον ποτὲ ἀνδρὸς ἰδιώτου, γυμνάσιον δὲ ἐπ’ ἐμοῦ. κατιοῦσι δ’ ἐς αὐτὴν περίβολός ἐστιν Ἀρτέμιδος καὶ ξόανα Ἀρίστης καὶ Καλλίστης· ὡς μὲν ἐγὼ δοκῶ καὶ ὁμολογεῖ τὰ ἔπη τὰ Πάμφω, τῆς Ἀρτέμιδός εἰσιν ἐπικλήσεις αὗται, λεγόμενον δὲ καὶ ἄλλον ἐς αὐτὰς λόγον εἰδὼς ὑπερβήσομαι. καὶ ναὸς οὐ μέγας ἐστίν, ἐς ὃν τοῦ Διονύσου τοῦ Ἐλευθερέως τὸ ἄγαλμα ἀνὰ πᾶν ἔτος κομίζουσιν ἐν τεταγμέναις ἡμέραις.", "st": "1.29"}, {"sp": "N", "t": "ἱερὰ μέν σφισι ταύτῃ τοσαῦτά ἐστι, τάφοι δὲ Θρασυβούλου μὲν πρῶτον τοῦ Λύκου, ἀνδρὸς τῶν τε ὕστερον καὶ ὅσοι πρὸ αὐτοῦ γεγόνασιν Ἀθηναίοις λόγιμοι τὰ πάντα ἀρίστου—παρέντι δέ μοι τὰ πλείω τοσάδε ἐς πίστιν ἀρκέσει τοῦ λόγου· τυραννίδα γὰρ ἔπαυσε τῶν τριάκοντα καλουμένων σὺν ἀνδράσιν ἑξήκοντα τὸ κατ’ ἀρχὰς ὁρμηθεὶς ἐκ Θηβῶν, καὶ Ἀθηναίους στασιάζοντας διαλλαγῆναι καὶ συνθεμένους ἔπεισε μεῖναι—, πρῶτος μέν ἐστιν οὗτος τάφος, ἐπὶ δὲ αὐτῷ Περικλέους τε καὶ Χαβρίου καὶ Φορμίωνος.", "st": "1.29"}, {"sp": "N", "t": "ἔστι δὲ καὶ πᾶσι μνῆμα Ἀθηναίοις ὁπόσοις ἀποθανεῖν συνέπεσεν ἔν τε ναυμαχίαις καὶ ἐν μάχαις πεζαῖς πλὴν ὅσοι Μαραθῶνι αὐτῶν ἠγωνίσαντο· τούτοις γὰρ κατὰ χώραν εἰσὶν οἱ τάφοι δι’ ἀνδραγαθίαν, οἱ δὲ ἄλλοι κατὰ τὴν ὁδὸν κεῖνται τὴν ἐς Ἀκαδημίαν, καὶ σφῶν ἑστᾶσιν ἐπὶ τοῖς τάφοις στῆλαι τὰ ὀνόματα καὶ τὸν δῆμον ἑκάστου λέγουσαι. πρῶτοι δὲ ἐτάφησαν οὓς ἐν Θρᾴκῃ ποτὲ ἐπικρατοῦντας μέχρι Δραβησκοῦ τῆς χώρας Ἠδωνοὶ φονεύουσιν ἀνέλπιστοι ἐπιθέμενοι·", "st": "1.29"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὡς κεραυνοὶ πέσοιεν ἐς αὐτούς. στρατηγοὶ δὲ ἄλλοι τε ἦσαν καὶ Λέαγρος, ᾧ μάλιστα ἐπετέτραπτο ἡ δύναμις, καὶ Δεκελεὺς Σωφάνης, ὃς τὸν Ἀργεῖόν ποτε πένταθλον Νεμείων ἀνῃρημένον νίκην ἀπέκτεινεν Εὐρυβάτην βοηθοῦντα Αἰγινήταις. στρατὸν δὲ ἔξω τῆς Ἑλλάδος Ἀθηναῖοι τρίτον τοῦτον ἔστειλαν· Πριάμῳ μὲν γὰρ καὶ Τρωσὶ πάντες Ἕλληνες ἀπὸ κοινοῦ λόγου κατέστησαν ἐς πόλεμον, Ἀθηναῖοι δὲ ἰδίᾳ μετ’ Ἰολάου τε ἐς Σαρδὼ καὶ δευτέραν ἐς τὴν νῦν Ἰωνίαν ἐστράτευσαν καὶ τρίτον δὴ τότε ἐς τὴν Θρᾴκην.", "st": "1.29"}, {"sp": "N", "t": "ἔστι δὲ ἔμπροσθεν τοῦ μνήματος στήλη μαχομένους ἔχουσα ἱππεῖς· Μελάνωπός σφισίν ἐστι καὶ Μακάρτατος ὀνόματα, οὓς κατέλαβεν ἀποθανεῖν ἐναντία Λακεδαιμονίων καὶ Βοιωτῶν τεταγμένους, ἔνθα τῆς Ἐλεωνίας εἰσὶ χώρας πρὸς Ταναγραίους ὅροι. καὶ Θεσσαλῶν τάφος ἐστὶν ἱππέων κατὰ παλαιὰν φιλίαν ἐλθόντων, ὅτε σὺν Ἀρχιδάμῳ Πελοποννήσιοι πρῶτον ἐσέβαλον ἐς τὴν Ἀττικὴν στρατιᾷ, καὶ πλησίον τοξόταις Κρησίν· αὖθις δέ ἐστιν Ἀθηναίων μνήματα Κλεισθένους, ᾧ τὰ ἐς τὰς φυλὰς αἳ νῦν καθεστᾶσιν εὑρέθη, καὶ ἱππεῦσιν ἀποθανοῦσιν ἡνίκα συνεπελάβοντο οἱ Θεσσαλοὶ τοῦ κινδύνου.", "st": "1.29"}, {"sp": "N", "t": "ἐνταῦθα καὶ Κλεωναῖοι κεῖνται, μετὰ Ἀργείων ἐς τὴν Ἀττικὴν ἐλθόντες· ἐφ’ ὅτῳ δέ, γράψω τοῦ λόγου μοι κατελθόντος ἐς τοὺς Ἀργείους. καὶ Ἀθηναίων δ’ ἔστι τάφος, οἳ πρὶν ἢ στρατεῦσαι τὸν Μῆδον ἐπολέμησαν πρὸς Αἰγινήτας. ἦν δὲ ἄρα καὶ δήμου δίκαιον βούλευμα, εἰ δὴ καὶ Ἀθηναῖοι μετέδοσαν δούλοις δημοσίᾳ ταφῆναι καὶ τὰ ὀνόματα ἐγγραφῆναι στήλῃ· δηλοῖ δὲ ἀγαθοὺς σφᾶς ἐν τῷ πολέμῳ γενέσθαι περὶ τοὺς δεσπότας. ἔστι δὲ καὶ ἀνδρῶν ὀνόματα ἄλλων, διάφορα δέ σφισι τὰ χωρία τῶν ἀγώνων· καὶ γὰρ τῶν ἐπ’ Ὄλυνθον ἐλθόντων οἱ δοκιμώτατοι καὶ Μελήσανδρος ἐς τὴν ἄνω Καρίαν ναυσὶν ἀναπλεύσας διὰ τοῦ Μαιάνδρου, ἐτάφησαν δὲ καὶ οἱ τελευτήσαντες", "st": "1.29"}, {"sp": "N", "t": "πολεμοῦντος Κασσάνδρου καὶ οἱ συμμαχήσαντές ποτε Ἀργείων. πραχθῆναι δὲ οὕτω σφίσι τὴν πρὸς Ἀργείους λέγουσι συμμαχίαν· Λακεδαιμονίοις τὴν πόλιν τοῦ θεοῦ σείσαντος οἱ εἵλωτες ἐς Ἰθώμην ἀπέστησαν, ἀφεστηκότων δὲ οἱ Λακεδαιμόνιοι βοηθοὺς καὶ ἄλλους καὶ παρὰ Ἀθηναίων μετεπέμποντο· οἱ δέ σφισιν ἐπιλέκτους ἄνδρας ἀποστέλλουσι καὶ στρατηγὸν Κίμωνα τὸν Μιλτιάδου. τούτους ἀποπέμπουσιν οἱ Λακεδαιμόνιοι πρὸς ὑποψίαν·", "st": "1.29"}, {"sp": "N", "t": "Ἀθηναίοις δὲ οὐκ ἀνεκτὰ ἐφαίνετο περιυβρίσθαι, καὶ ὡς ἐκομίζοντο ὀπίσω συμμαχίαν ἐποιήσαντο Ἀργείοις Λακεδαιμονίων ἐχθροῖς τὸν ἅπαντα οὖσι χρόνον. ὕστερον δὲ μελλούσης Ἀθηναίων ἐν Τανάγρᾳ γίνεσθαι πρὸς Βοιωτοὺς καὶ Λακεδαιμονίους μάχης, ἀφίκοντο Ἀθηναίοις Ἀργεῖοι βοηθοῦντες· καὶ παραυτίκα μὲν ἔχοντας πλέον τοὺς Ἀργείους νὺξ ἐπελθοῦσα ἀφείλετο τὸ σαφὲς τῆς νίκης, ἐς δὲ τὴν ὑστεραίαν ὑπῆρξε κρατῆσαι Λακεδαιμονίοις Θεσσαλῶν προδόντων Ἀθηναίους.", "st": "1.29"}, {"sp": "N", "t": "καταλέξαι δέ μοι καὶ τούσδε ἐπῆλθεν, Ἀπολλόδωρον ξένων ἡγεμόνα, ὃς Ἀθηναῖος μὲν ἦν, ἐκπεμφθεὶς δὲ ὑπὸ Ἀρσίτου σατράπου τῆς ἐφ’ Ἑλλησπόντῳ Φρυγίας διεφύλαξε Περινθίοις τὴν πόλιν ἐσβεβληκότος ἐς τὴν Περινθίαν Φιλίππου στρατῷ· οὗτός τε οὖν ἐνταῦθα τέθαπται καὶ Εὔβουλος ὁ Σπινθάρου καὶ ἄνδρες οἷς ἀγαθοῖς οὖσιν οὐκ ἐπηκολούθησε τύχη χρηστή, τοῖς μὲν ἐπιθεμένοις τυραννοῦντι Λαχάρει, οἱ δὲ τοῦ Πειραιῶς κατάληψιν ἐβούλευσαν Μακεδόνων φρουρούντων, πρὶν δὲ εἰργάσθαι τὸ ἔργον ὑπὸ τῶν συνειδότων μηνυθέντες ἀπώλοντο.", "st": "1.29"}, {"sp": "N", "t": "κεῖνται δὲ καὶ οἱ περὶ Κόρινθον πεσόντες· ἐδήλωσε δὲ οὐχ ἥκιστα ὁ θεὸς ἐνταῦθα καὶ αὖθις ἐν Λεύκτροις τοὺς ὑπὸ Ἑλλήνων καλουμένους ἀνδρείους τὸ μηδὲν ἄνευ Τύχης εἶναι, εἰ δὴ Λακεδαιμόνιοι, Κορινθίων τότε καὶ Ἀθηναίων, ἔτι δὲ καὶ Ἀργείων καὶ Βοιωτῶν κρατήσαντες, ὕστερον ὑπὸ Βοιωτῶν μόνων ἐν Λεύκτροις ἐς τοσοῦτον ἐκακώθησαν. μετὰ δὲ τοὺς ἀποθανόντας ἐν Κορίνθῳ στήλην ἐπὶ τοῖσδε ἑστάναι τὴν αὐτὴν σημαίνει τὰ ἐλεγεῖα, τοῖς μὲν ἐν Εὐβοίᾳ καὶ Χίῳ τελευτήσασι, τοὺς δὲ ἐπὶ τοῖς ἐσχάτοις τῆς Ἀσιανῆς ἠπείρου διαφθαρῆναι δηλοῖ, τοὺς δὲ ἐν Σικελίᾳ.", "st": "1.29"}, {"sp": "N", "t": "γεγραμμένοι δέ εἰσιν οἵ τε στρατηγοὶ πλὴν Νικίου, καὶ τῶν στρατιωτῶν ὁμοῦ τοῖς ἀστοῖς Πλαταιεῖς· Νικίας δὲ ἐπὶ τῷδε παρείθη, γράφω δὲ οὐδὲν διάφορα ἢ Φίλιστος, ὃς ἔφη Δημοσθένην μὲν σπονδὰς ποιήσασθαι τοῖς ἄλλοις πλὴν αὑτοῦ καὶ ὡς ἡλίσκετο αὑτὸν ἐπιχειρεῖν ἀποκτεῖναι, Νικίᾳ δὲ τὴν παράδοσιν ἐθελοντῇ γενέσθαι· τούτων ἕνεκα οὐκ ἐνεγράφη Νικίας τῇ στήλῃ, καταγνωσθεὶς αἰχμάλωτος ἐθελοντὴς εἶναι καὶ οὐκ ἀνὴρ πολέμῳ πρέπων.", "st": "1.29"}, {"sp": "N", "t": "εἰσὶ δὲ ἐπ’ ἄλλῃ στήλῃ καὶ οἱ μαχεσάμενοι περὶ Θρᾴκην καὶ ἐν Μεγάροις καὶ ἡνίκα Ἀρκάδας τοὺς ἐν Μαντινείᾳ καὶ Ἠλείους ἔπεισεν Ἀλκιβιάδης Λακεδαιμονίων ἀποστῆναι καὶ οἱ πρὶν ἐς Σικελίαν ἀφικέσθαι Δημοσθένην Συρακουσίων κρατήσαντες. ἐτάφησαν δὲ καὶ οἱ περὶ τὸν Ἑλλήσποντον ναυμαχήσαντες καὶ ὅσοι Μακεδόνων ἐναντία ἠγωνίσαντο ἐν Χαιρωνείᾳ καὶ οἱ μετὰ Κλέωνος ἐς Ἀμφίπολιν στρατεύσαντες, οἵ τε ἐν Δηλίῳ τῷ Ταναγραίων τελευτήσαντες καὶ ὅσους ἐς Θεσσαλίαν Λεωσθένης ἤγαγε καὶ οἱ πλεύσαντες ἐς Κύπρον ὁμοῦ Κίμωνι, τῶν τε σὺν Ὀλυμπιοδώρῳ τὴν φρουρὰν ἐκβαλόντων τριῶν καὶ δέκα ἄνδρες οὐ πλείους.", "st": "1.29"}, {"sp": "N", "t": "φασὶ δὲ Ἀθηναῖοι καὶ Ῥωμαίοις ὅμορόν τινα πολεμοῦσι πόλεμον στρατιὰν οὐ πολλὴν πέμψαι, καὶ ὕστερον ναυμαχίας Ῥωμαίων πρὸς Καρχηδονίους γινομένης τριήρεις πέντε Ἀττικαὶ παρεγένοντο· ἔστιν οὖν καὶ τούτοις ἐνταῦθα τοῖς ἀνδράσιν ὁ τάφος. Τολμίδου δὲ καὶ τῶν σὺν αὐτῷ δεδήλωται μὲν ἤδη μοι τὰ ἔργα καὶ ὅν τρόπον ἐτελεύτησαν· ἴστω δὲ ὅτῳ φίλον κειμένους σφᾶς κατὰ τὴν ὁδὸν ταύτην. κεῖνται δὲ καὶ οἱ σὺν Κίμωνι τὸ μέγα ἔργον [ἐπὶ τῇ] πεζῇ καὶ ναυσὶν αὐθημερὸν κρατήσαντες·", "st": "1.29"}, {"sp": "N", "t": "τέθαπται δὲ καὶ Κόνων καὶ Τιμόθεος, δεύτεροι μετὰ Μιλτιάδην καὶ Κίμωνα οὗτοι πατὴρ καὶ παῖς ἔργα ἀποδειξάμενοι λαμπρά. κεῖται δὲ καὶ Ζήνων ἐνταῦθα ὁ Μνασέου καὶ Χρύσιππος ὁ Σολεύς, Νικίας τε ὁ Νικομήδου⟨ς⟩ ζῷα ἄριστος γράψαι τῶν ἐφ’ αὑτοῦ, καὶ Ἁρμόδιος καὶ Ἀριστογείτων οἱ τὸν Πεισιστράτου παῖδα Ἵππαρχον ἀποκτείναντες, ῥήτορές τε Ἐφιάλτης, ὃς τὰ νόμιμα τὰ ἐν Ἀρείῳ πάγῳ μάλιστα ἐλυμήνατο, καὶ Λυκοῦργος ὁ Λυκόφρονος.", "st": "1.29"}, {"sp": "N", "t": "Λυκούργῳ δὲ ἐπορίσθη μὲν τάλαντα ἐς τὸ δημόσιον πεντακοσίοις πλείονα καὶ ἑξακισχιλίοις ἢ ὅσα Περικλῆς ὁ Ξανθίππου συνήγαγε, κατεσκεύασε δὲ πομπεῖα τῇ θεῷ καὶ Νίκας χρυσᾶς καὶ παρθένοις κόσμον ἑκατόν, ἐς δὲ πόλεμον ὅπλα καὶ βέλη καὶ τετρακοσίας ναυμαχοῦσιν εἶναι τριήρεις· οἰκοδομήματα δὲ ἐπετέλεσε μὲν τὸ θέατρον ἑτέρων ὑπαρξαμένων, τὰ δὲ ἐπὶ τῆς αὐτοῦ πολιτείας ἃ ᾠκοδόμησεν ἐν Πειραιεῖ νεώς εἰσιν οἶκοι καὶ τὸ πρὸς τῷ Λυκείῳ καλουμένῳ γυμνάσιον. ὅσα μὲν οὖν ἀργύρου πεποιημένα ἦν καὶ χρυσοῦ, Λαχάρης καὶ ταῦτα ἐσύλησε τυραννήσας· τὰ δὲ οἰκοδομήματα καὶ ἐς ἡμᾶς ἔτι ἦν.", "st": "1.29"}, {"sp": "N", "t": "πρὸ δὲ τῆς ἐσόδου τῆς ἐς Ἀκαδημίαν ἐστὶ βωμὸς Ἔρωτος ἔχων ἐπίγραμμα ὡς Χάρμος Ἀθηναίων πρῶτος Ἔρωτι ἀναθείη. τὸν δὲ ἐν πόλει βωμὸν καλούμενον Ἀντέρωτος ἀνάθημα εἶναι λέγουσι μετοίκων, ὅτι Μέλης Ἀθηναῖος μέτοικον ἄνδρα Τιμαγόραν ἐρασθέντα ἀτιμάζων ἀφεῖναι κατὰ τῆς πέτρας αὑτὸν ἐκέλευσεν ἐς τὸ ὑψηλότατον αὐτῆς ἀνελθόντα· Τιμαγόρας δὲ ἄρα καὶ ψυχῆς εἶχεν ἀφειδῶς καὶ πάντα ὁμοίως κελεύοντι ἤθελε χαρίζεσθαι τῷ μειρακίῳ καὶ δὴ καὶ φέρων ἑαυτὸν ἀφῆκε· Μέλητα δέ, ὡς ἀποθανόντα εἶδε Τιμαγόραν, ἐς τοσοῦτο μετανοίας ἐλθεῖν ὡς πεσεῖν τε ἀπὸ τῆς πέτρας τῆς αὐτῆς καὶ οὕτως ἀφεὶς αὑτὸν ἐτελεύτησε. καὶ τὸ ἐντεῦθεν δαίμονα Ἀντέρωτα τὸν ἀλάστορα τὸν Τιμαγόρου κατέστη τοῖς μετοίκοις νομίζειν.", "st": "1.30"}, {"sp": "N", "t": "ἐν Ἀκαδημίᾳ δέ ἐστι Προμηθέως βωμός, καὶ θέουσιν ἀπ’ αὐτοῦ πρὸς τὴν πόλιν ἔχοντες καιομένας λαμπάδας· τὸ δὲ ἀγώνισμα ὁμοῦ τῷ δρόμῳ φυλάξαι τὴν δᾷδα ἔτι καιομένην ἐστίν, ἀποσβεσθείσης δὲ οὐδὲν ἔτι τῆς νίκης τῷ πρώτῳ, δευτέρῳ δὲ ἀντ’ αὐτοῦ μέτεστιν· εἰ δὲ μηδὲ τούτῳ καίοιτο, ὁ τρίτος ἐστὶν ὁ κρατῶν· εἰ δὲ καὶ πᾶσιν ἀποσβεσθείη, οὐδείς ἐστιν ὅτῳ καταλείπεται ἡ νίκη. ἔστι δὲ Μουσῶν τε βωμὸς καὶ ἕτερος Ἑρμοῦ καὶ ἔνδον Ἀθηνᾶς, τὸν δὲ Ἡρακλέους ἐποίησαν· καὶ φυτόν ἐστιν ἐλαίας, δεύτερον τοῦτο λεγόμενον φανῆναι.", "st": "1.30"}, {"sp": "N", "t": "Ἀκαδημίας δὲ οὐ πόρρω Πλάτωνος μνῆμά ἐστιν, ᾧ προεσήμαινεν ὁ θεὸς ἄριστον τὰ ἐς φιλοσοφίαν ἔσεσθαι· προεσήμαινε δὲ οὕτω. Σωκράτης τῇ προτέρᾳ νυκτὶ ἢ Πλάτων ἔμελλεν ἔσεσθαί οἱ μαθητὴς ἐσπτῆναί οἱ κύκνον ἐς τὸν κόλπον εἶδεν ὄνειρον· ἔστι δὲ κύκνῳ τῷ ὄρνιθι μουσικῆς δόξα, ὅτι Λιγύων τῶν Ἠριδανοῦ πέραν ὑπὲρ γῆς τῆς Κελτικῆς Κύκνον ἄνδρα μουσικὸν γενέσθαι βασιλέα φασί, τελευτήσαντα δὲ Ἀπόλλωνος γνώμῃ μεταβαλεῖν λέγουσιν αὐτὸν ἐς τὸν ὄρνιθα. ἐγὼ δὲ βασιλεῦσαι μὲν πείθομαι Λίγυσιν ἄνδρα μουσικόν, γενέσθαι δέ μοι ἄπιστον ὄρνιθα ἀπ’ ἀνδρός.", "st": "1.30"}, {"sp": "N", "t": "κατὰ τοῦτο τῆς χώρας φαίνεται πύργος Τίμωνος, ὃς μόνος εἶδε μηδένα τρόπον εὐδαίμονα εἶναι γενέσθαι πλὴν τοὺς ἄλλους φεύγοντα ἀνθρώπους. δείκνυται δὲ καὶ χῶρος καλούμενος κολωνὸς ἵππιος, ἔνθα τῆς Ἀττικῆς πρῶτον ἐλθεῖν λέγουσιν Οἰδίποδα—διάφορα μὲν καὶ ταῦτα τῇ Ὁμήρου ποιήσει, λέγουσι δ’ οὖν—, καὶ βωμὸς Ποσειδῶνος Ἱππίου καὶ Ἀθηνᾶς Ἱππίας, ἡρῷον δὲ Πειρίθου καὶ Θησέως Οἰδίποδός τε καὶ Ἀδράστου. τὸ δὲ ἄλσος τοῦ Ποσειδῶνος καὶ τὸν ναὸν ἐνέπρησεν Ἀντίγονος ἐσβαλών, καὶ ἄλλοτε στρατιᾷ κακώσας Ἀθηναίοις τὴν γῆν.", "st": "1.30"}, {"sp": "N", "t": "δῆμοι δὲ οἱ μικροὶ τῆς Ἀττικῆς, ὡς ἔτυχεν ἕκαστος οἰκισθείς, τάδε ἐς μνήμην παρείχοντο· Ἀλιμουσίοις ⟨μὲν⟩ Θεσμοφόρου Δήμητρος καὶ Κόρης ἐστὶν ἱερόν, ἐν Ζωστῆρι ⟨δὲ⟩ ἐπὶ θαλάσσης καὶ βωμὸς Ἀθηνᾶς καὶ Ἀπόλλωνος καὶ Ἀρτέμιδος καὶ Λητοῦς. τεκεῖν μὲν οὖν Λητὼ τοὺς παῖδας ἐνταῦθα οὔ φασι, λύσασθαι δὲ τὸν ζωστῆρα ὡς τεξομένην, καὶ τῷ χωρίῳ διὰ τοῦτο γενέσθαι τὸ ὄνομα. Προσπαλτίοις δέ ἐστι καὶ τούτοις Κόρης καὶ Δήμητρος ἱερόν, Ἀναγυρασίοις δὲ Μητρὸς θεῶν ἱερόν· Κεφαλῆσι δὲ οἱ Διόσκουροι νομίζονται μάλιστα, Μεγάλους γὰρ σφᾶς οἱ ταύτῃ θεοὺς ὀνομάζουσιν.", "st": "1.31"}, {"sp": "N", "t": "ἐν δὲ Πρασιεῦσιν Ἀπόλλωνός ἐστι ναός· ἐνταῦθα τὰς Ὑπερβορέων ἀπαρχὰς ἰέναι λέγεται, παραδιδόναι δὲ αὐτὰς Ὑπερβορέους μὲν Ἀριμασποῖς, Ἀριμασποὺς δ’ Ἰσσηδόσι, παρὰ δὲ τούτων Σκύθας ἐς Σινώπην κομίζειν, ἐντεῦθεν δὲ φέρεσθαι διὰ Ἑλλήνων ἐς Πρασιάς, Ἀθηναίους δὲ εἶναι τοὺς ἐς Δῆλον ἄγοντας· τὰς δὲ ἀπαρχὰς κεκρύφθαι μὲν ἐν καλάμῃ πυρῶν, γινώσκεσθαι δὲ ὑπ’ οὐδένων. ἔστι δὲ μνῆμα ἐπὶ Πρασιαῖς Ἐρυσίχθονος, ὡς ἐκομίζετο ὀπίσω μετὰ τὴν θεωρίαν ἐκ Δήλου, γενομένης οἱ κατὰ τὸν πλοῦν τῆς τελευτῆς.", "st": "1.31"}, {"sp": "N", "t": "Κραναὸν δὲ τὸν βασιλεύσαντα Ἀθηναίων ὅτι μὲν ἐξέβαλεν Ἀμφικτύων κηδεστὴν ὄντα, ἔτι πρότερον εἴρηταί μοι· φυγόντα δὲ αὐτὸν σὺν τοῖς στασιώταις ἐς τὸν δῆμον τὸν Λαμπτρέα ἀποθανεῖν τε αὐτοῦ καὶ ταφῆναί φασι, καὶ ἔστι καὶ ἐς ἐμὲ [καὶ] ἐν τοῖς Λαμπτρεῦσι Κραναοῦ μνῆμα. Ἴωνος δὲ τοῦ Ξούθου —καὶ γὰρ οὗτος ᾤκησε παρὰ Ἀθηναίοις καὶ Ἀθηναίων ἐπὶ τοῦ πολέμου τοῦ πρὸς Ἐλευσινίους ἐπολεμάρχησε —τάφος ἐν Ποταμοῖς ἐστι τῆς χώρας.", "st": "1.31"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω λέγεται, Φλυεῦσι δέ εἰσι καὶ Μυρρινουσίοις τοῖς μὲν Ἀπόλλωνος Διονυσοδότου καὶ Ἀρτέμιδος Σελασφόρου βωμοὶ Διονύσου τε Ἀνθίου καὶ νυμφῶν Ἰσμηνίδων καὶ Γῆς, ἣν Μεγάλην θεὸν ὀνομάζουσι· ναὸς δὲ ἕτερος ἔχει βωμοὺς Δήμητρος Ἀνησιδώρας ⟨καὶ⟩ Διὸς Κτησίου καὶ Τιθρωνῆς Ἀθηνᾶς καὶ Κόρης Πρωτογόνης καὶ Σεμνῶν ὀνομαζομένων θεῶν· τὸ δὲ ἐν Μυρρινοῦντι ξόανόν ἐστι Κολαινίδος. Ἀθμονεῖς δὲ τιμῶσιν Ἀμαρυσίαν Ἄρτεμιν·", "st": "1.31"}, {"sp": "N", "t": "πυνθανόμενος δὲ σαφὲς οὐδὲν ἐς αὐτὰς ἐπισταμένους τοὺς ἐξηγητὰς εὗρον, αὐτὸς δὲ συμβάλλομαι τῇδε. ἔστιν Ἀμάρυνθος ἐν Εὐβοίᾳ· καὶ γὰρ οἱ ταύτῃ τιμῶσιν Ἀμαρυσίαν, ἑορτὴν δὲ καὶ Ἀθηναῖοι τῆς Ἀμαρυσίας ἄγουσιν οὐδέν τι Εὐβοέων ἀφανέστερον· ταύτῃ μὲν γενέσθαι τὸ ὄνομα ἐπὶ τούτῳ παρὰ Ἀθμονεῦσιν ἡγοῦμαι, τὴν δὲ ἐν Μυρρινοῦντι Κολαινίδα ἀπὸ Κολαίνου καλεῖσθαι. γέγραπται δ’ ἤδη μοι τῶν ἐν τοῖς δήμοις φάναι πολλοὺς ὡς καὶ πρὸ τῆς ἀρχῆς ἐβασιλεύοντο τῆς Κέκροπος· ἔστι δὲ ὁ Κόλαινος ἀνδρὸς ὄνομα πρότερον ἢ Κέκροψ ἐβασίλευσεν —ὡς οἱ Μυρρινούσιοι λέγουσιν—ἄρξαντος.", "st": "1.31"}, {"sp": "N", "t": "ἔστι δὲ Ἀχαρναὶ δῆμος· οὗτοι θεῶν Ἀπόλλωνα τιμῶσιν Ἀγυιέα καὶ Ἡρακλέα. καὶ Ἀθηνᾶς βωμός ἐστιν Ὑγείας· τὴν δ’ Ἱππίαν Ἀθηνᾶν ὀνομάζουσι καὶ Διόνυσον Μελπόμενον καὶ Κισσὸν τὸν αὐτὸν θεόν, τὸν κισσὸν τὸ φυτὸν ἐνταῦθα πρῶτον φανῆναι λέγοντες.", "st": "1.31"}, {"sp": "N", "t": "ὄρη δὲ Ἀθηναίοις ἐστὶ Πεντελικὸν ἔνθα λιθοτομίαι, καὶ Πάρνης παρεχομένη θήραν συῶν ἀγρίων καὶ ἄρκτων, καὶ Ὑμηττὸς ὃς φύει νομὰς μελίσσαις ἐπιτηδειοτάτας πλὴν τῆς Ἀλαζώνων. Ἀλαζῶσι γὰρ συνήθεις ὁμοῦ τοῖς ἄλλοις ἐς νομὰς ἰοῦσιν εἰσὶν ἄφετοι καὶ μέλισσαι, οὐδὲ σφᾶς ἐς σίμβλους καθείρξαντες ἔχουσιν· αἱ δὲ ἐργάζονταί τε ὡς ἔτυχον τῆς χώρας καὶ συμφυὲς τὸ ἔργον αὐταῖς ἐστιν, ἰδίᾳ δὲ οὔτε κηρὸν οὔτε μέλι ἀπ’ αὐτοῦ ποιήσεις. τοῦτο μὲν τοιοῦτόν ἐστιν, Ἀθηναίοις δὲ τὰ ὄρη καὶ θεῶν ἀγάλματα ἔχει·", "st": "1.32"}, {"sp": "N", "t": "Πεντελῆσι μὲν Ἀθηνᾶς, ἐν Ὑμηττῷ δὲ ἄγαλμά ἐστιν Ὑμηττίου Διός, βωμοὶ δὲ καὶ Ὀμβρίου Διὸς καὶ Ἀπόλλωνός εἰσι Προοψίου. καὶ ἐν Πάρνηθι Παρνήθιος Ζεὺς χαλκοῦς ἐστι καὶ βωμὸς Σημαλέου Διός· ἔστι δὲ ἐν τῇ Πάρνηθι καὶ ἄλλος βωμός, θύουσι δὲ ἐπ’ αὐτοῦ τοτὲ μὲν Ὄμβριον τοτὲ δὲ Ἀπήμιον καλοῦντες Δία. καὶ Ἀγχεσμὸς ὄρος ἐστὶν οὐ μέγα καὶ Διὸς ἄγαλμα Ἀγχεσμίου.", "st": "1.32"}, {"sp": "N", "t": "πρὶν δὲ ἢ τῶν νήσων ἐς ἀφήγησιν τραπέσθαι, τὰ ἐς τοὺς δήμους ἔχοντα αὖθις ἐπέξειμι. δῆμός ἐστι Μαραθὼν ἴσον τῆς πόλεως τῶν Ἀθηναίων ἀπέχων καὶ Καρύστου τῆς ἐν Εὐβοίᾳ· ταύτῃ τῆς Ἀττικῆς ἔσχον οἱ βάρβαροι καὶ μάχῃ τε ἐκρατήθησαν καί τινας ὡς ἀνήγοντο ἀπώλεσαν τῶν νεῶν. τάφος δὲ ἐν τῷ πεδίῳ Ἀθηναίων ἐστίν, ἐπὶ δὲ αὐτῷ στῆλαι τὰ ὀνόματα τῶν ἀποθανόντων κατὰ φυλὰς ἑκάστων ἔχουσαι, καὶ ἕτερος Πλαταιεῦσι Βοιωτῶν καὶ δούλοις· ἐμαχέσαντο γὰρ καὶ δοῦλοι τότε πρῶτον.", "st": "1.32"}, {"sp": "N", "t": "καὶ ἀνδρός ἐστιν ἰδίᾳ μνῆμα Μιλτιάδου τοῦ Κίμωνος, συμβάσης ὕστερόν οἱ τῆς τελευτῆς Πάρου τε ἁμαρτόντι καὶ δι’ αὐτὸ ἐς κρίσιν Ἀθηναίοις καταστάντι. ἐνταῦθα ἀνὰ πᾶσαν νύκτα καὶ ἵππων χρεμετιζόντων καὶ ἀνδρῶν μαχομένων ἔστιν αἰσθέσθαι· καταστῆναι δὲ ἐς ἐναργῆ θέαν ἐπίτηδες μὲν οὐκ ἔστιν ὅτῳ συνήνεγκεν, ἀνηκόῳ δὲ ὄντι καὶ ἄλλως συμβὰν οὐκ ἔστιν ἐκ τῶν δαιμόνων ὀργή. σέβονται δὲ οἱ Μαραθώνιοι τούτους τε οἳ παρὰ τὴν μάχην ἀπέθανον ἥρωας ὀνομάζοντες καὶ Μαραθῶνα ἀφ’ οὗ τῷ δήμῳ τὸ ὄνομά ἐστι καὶ Ἡρακλέα, φάμενοι πρώτοις Ἑλλήνων σφίσιν Ἡρακλέα θεὸν νομισθῆναι.", "st": "1.32"}, {"sp": "N", "t": "συνέβη δὲ ὡς λέγουσιν ἄνδρα ἐν τῇ μάχῃ παρεῖναι τὸ εἶδος καὶ τὴν σκευὴν ἄγροικον· οὗτος τῶν βαρβάρων πολλοὺς καταφονεύσας ἀρότρῳ μετὰ τὸ ἔργον ἦν ἀφανής· ἐρομένοις δὲ Ἀθηναίοις ἄλλο μὲν ὁ θεὸς ἐς αὐτὸν ἔχρησεν οὐδέν, τιμᾶν δὲ Ἐχετλαῖον ἐκέλευσεν ἥρωα. πεποίηται δὲ καὶ τρόπαιον λίθου λευκοῦ. τοὺς δὲ Μήδους Ἀθηναῖοι μὲν θάψαι λέγουσιν ὡς πάντως ὅσιον ἀνθρώπου νεκρὸν γῇ κρύψαι, τάφον δὲ οὐδένα εὑρεῖν ἐδυνάμην· οὔτε γὰρ χῶμα οὔτε ἄλλο σημεῖον ἦν ἰδεῖν, ἐς ὄρυγμα δὲ φέροντες σφᾶς ὡς τύχοιεν ἐσέβαλον.", "st": "1.32"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῷ Μαραθῶνι πηγὴ καλουμένη Μακαρία, καὶ τοιάδε ἐς αὐτὴν λέγουσιν. Ἡρακλῆς ὡς ἐκ Τίρυνθος ἔφευγεν Εὐρυσθέα, παρὰ Κήυκα φίλον ὄντα μετοικίζεται βασιλεύοντα Τραχῖνος. ἐπεὶ δὲ ἀπελθόντος ἐξ ἀνθρώπων Ἡρακλέους ἐξῄτει τοὺς παῖδας Εὐρυσθεύς, ἐς Ἀθήνας πέμπει σφᾶς ὁ Τραχίνιος ἀσθένειάν τε λέγων τὴν αὑτοῦ καὶ Θησέα οὐκ ἀδύνατον εἶναι τιμωρεῖν· ἀφικόμενοι δὲ οἱ παῖδες ἱκέται πρῶτον τότε Πελοποννησίοις ποιοῦσι πόλεμον πρὸς Ἀθηναίους, Θησέως σφᾶς οὐκ ἐκδόντος αἰτοῦντι Εὐρυσθεῖ. λέγουσι δὲ Ἀθηναίοις γενέσθαι χρησμὸν τῶν παίδων ἀποθανεῖν χρῆναι τῶν Ἡρακλέους τινὰ ἐθελοντήν, ἐπεὶ ἄλλως γε οὐκ εἶναι νίκην σφίσιν· ἐνταῦθα Μακαρία Δηιανείρας καὶ Ἡρακλέους θυγάτηρ ἀποσφάξασα ἑαυτὴν ἔδωκεν Ἀθηναίοις τε κρατῆσαι τῷ πολέμῳ καὶ τῇ πηγῇ τὸ ὄνομα ἀφ’ αὑτῆς.", "st": "1.32"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῷ Μαραθῶνι λίμνη τὰ πολλὰ ἑλώδης· ἐς ταύτην ἀπειρίᾳ τῶν ὁδῶν φεύγοντες ἐσπίπτουσιν οἱ βάρβαροι, καί σφισι τὸν φόνον τὸν πολὺν ἐπὶ τούτῳ συμβῆναι λέγουσιν· ὑπὲρ δὲ τὴν λίμνην φάτναι εἰσὶ λίθου τῶν ἵππων τῶν Ἀρταφέρνους καὶ σημεῖα ἐν πέτραις σκηνῆς. ῥεῖ δὲ καὶ ποταμὸς ἐκ τῆς λίμνης, τὰ μὲν πρὸς αὐτῇ τῇ λίμνῃ βοσκήμασιν ὕδωρ ἐπιτήδειον παρεχόμενος, κατὰ δὲ τὴν ἐκβολὴν τὴν ἐς τὸ πέλαγος ἁλμυρὸς ἤδη γίνεται καὶ ἰχθύων τῶν θαλασσίων πλήρης. ὀλίγον δὲ ἀπωτέρω τοῦ πεδίου Πανός ἐστιν ὄρος καὶ σπήλαιον θέας ἄξιον· ἔσοδος μὲν ἐς αὐτὸ στενή, παρελθοῦσι δέ εἰσιν οἶκοι καὶ λουτρὰ καὶ καλούμενον Πανὸς αἰπόλιον, πέτραι τὰ πολλὰ αἰξὶν εἰκασμέναι.", "st": "1.32"}, {"sp": "N", "t": "Μαραθῶνος δὲ ἀπέχει τῇ μὲν Βραυρών, ἔνθα Ἰφιγένειαν τὴν Ἀγαμέμνονος ἐκ Ταύρων φεύγουσαν τὸ ἄγαλμα ἀγομένην τὸ Ἀρτέμιδος ἀποβῆναι λέγουσι, καταλιποῦσαν δὲ τὸ ἄγαλμα ταύτῃ καὶ ἐς Ἀθήνας καὶ ὕστερον ἐς Ἄργος ἀφικέσθαι· ξόανον μὲν δὴ καὶ αὐτόθι ἐστὶν Ἀρτέμιδος ἀρχαῖον, τὸ δὲ ἐκ τῶν βαρβάρων οἵτινες κατὰ γνώμην ἔχουσι τὴν ἐμήν, ἐν ἑτέρῳ λόγῳ δηλώσω·", "st": "1.33"}, {"sp": "N", "t": "Μαραθῶνος δὲ σταδίους μάλιστα ἑξήκοντα ἀπέχει Ῥαμνοῦς τὴν παρὰ θάλασσαν ἰοῦσιν ἐς Ὠρωπόν. καὶ αἱ μὲν οἰκήσεις ἐπὶ θαλάσσῃ τοῖς ἀνθρώποις εἰσί, μικρὸν δὲ ἀπὸ θαλάσσης ἄνω Νεμέσεώς ἐστιν ἱερόν, ἣ θεῶν μάλιστα ἀνθρώποις ὑβρισταῖς ἐστιν ἀπαραίτητος. δοκεῖ δὲ καὶ τοῖς ἀποβᾶσιν ἐς Μαραθῶνα τῶν βαρβάρων ἀπαντῆσαι μήνιμα ἐκ τῆς θεοῦ ταύτης· καταφρονήσαντες γὰρ ⟨μηδέν⟩ σφισιν ἐμποδὼν εἶναι τὰς Ἀθήνας ἑλεῖν, λίθον Πάριον [ὃν] ὡς ἐπ’ ἐξειργασμένοις ἦγον ἐς τροπαίου ποίησιν.", "st": "1.33"}, {"sp": "N", "t": "τοῦτον Φειδίας τὸν λίθον εἰργάσατο ἄγαλμα μὲν εἶναι Νεμέσεως, τῇ κεφαλῇ δὲ ἔπεστι τῆς θεοῦ στέφανος ἐλάφους ἔχων καὶ Νίκης ἀγάλματα οὐ μεγάλα· ταῖς δὲ χερσὶν ἔχει τῇ μὲν κλάδον μηλέας, τῆ δεξιᾷ δὲ φιάλην, Αἰθίοπες δὲ ἐπὶ τῇ φιάλῃ πεποίηνται. συμβαλέσθαι δὲ τὸ ἐς τοὺς Αἰθίοπας οὔτε αὐτὸς εἶχον οὔτε ἀπεδεχόμην τῶν συνιέναι πειθομένων, οἳ πεποιῆσθαι σφᾶς ἐπὶ τῇ φιάλῃ φασὶ διὰ ποταμὸν Ὠκεανόν· οἰκεῖν γὰρ Αἰθίοπας ἐπ’ αὐτῷ, Νεμέσει δὲ εἶναι πατέρα Ὠκεανόν.", "st": "1.33"}, {"sp": "N", "t": "Ὠκεανῷ γὰρ οὐ ποταμῷ, θαλάσσῃ δὲ ἐσχάτῃ τῆς ὑπὸ ἀνθρώπων πλεομένης προσοικοῦσιν Ἴβηρες καὶ Κελτοί, καὶ νῆσον Ὠκεανὸς ἔχει τὴν Βρεττανῶν· Αἰθιόπων δὲ τῶν ὑπὲρ Συήνης ἐπὶ θάλασσαν ἔσχατοι τὴν Ἐρυθρὰν κατοικοῦσιν Ἰχθυοφάγοι, καὶ ὁ κόλπος ὃν περιοικοῦσιν Ἰχθυοφάγων ὀνομάζεται. οἱ δὲ δικαιότατοι Μερόην πόλιν καὶ πεδίον Αἰθιοπικὸν καλούμενον οἰκοῦσιν· οὗτοι καὶ τὴν ἡλίου τράπεζάν εἰσιν οἱ δεικνύντες, οὐδέ σφισιν ἔστιν οὔτε θάλασσα οὔτε ποταμὸς ἄλλος γε ἢ Νεῖλος.", "st": "1.33"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ ἄλλοι πρόσοικοι Μαύροις Αἰθίοπες ἄχρι Νασαμώνων παρήκοντες. Νασαμῶνες γάρ, οὓς Ἄτλαντας Ἡρόδοτος, οἱ δὲ μέτρα φάμενοι γῆς εἰδέναι Λιξίτας καλοῦσι, Λιβύων οἱ ἔσχατοι πρὸς Ἄτλαντι οἰκοῦσι σπείροντες μὲν οὐδέν, ἀπὸ δὲ ἀμπέλων ζῶντες ἀγρίων. ποταμὸς δὲ οὐδὲ τούτοις τοῖς Αἰθίοψιν οὐδὲ τοῖς Νασαμῶσίν ἐστιν οὐδείς· τὸ γὰρ πρὸς τῷ Ἄτλαντι ὕδωρ, τρισί παρεχόμενον ἀρχὰς ῥεύμασιν, οὐδὲν τῶν ῥευμάτων ποιεῖ ποταμόν, ἀλλὰ πᾶν ὁμοίως αὐτίκα ἔχει συλλαβοῦσα ἡ ψάμμος. οὕτως Αἰθίοπες ποταμῷ γε οὐδενὶ προσοικοῦσιν [ἢ] Ὠκεανῷ.", "st": "1.33"}, {"sp": "N", "t": "τὸ δὲ ὕδωρ τὸ ἐκ τοῦ Ἄτλαντος θολερόν τέ ἐστι καὶ πρὸς τῇ πηγῇ κροκόδειλοι ⟨δι⟩πήχεων ἦσαν οὐκ ἐλάσσους, προσιόντων δὲ τῶν ἀνθρώπων κατεδύοντο ἐς τὴν πηγήν. παρίστατο δὲ οὐκ ὀλίγοις τὸ ὕδωρ τοῦτο ἀναφαινόμενον αὖθις ἐκ τῆς ψάμμου ποιεῖν τὸν Νεῖλον Αἰγυπτίοις. ὁ δὲ Ἄτλας ⟨ὄρος⟩ ὑψηλὸν μέν ἐστιν οὕτως ὥστε καὶ λέγεται ταῖς κορυφαῖς ψαύειν τοῦ οὐρανοῦ, ἄβατον δὲ ὑπὸ ὕδατος καὶ δένδρων ἃ διὰ παντὸς πέφυκε· τὰ μὲν δὴ πρὸς τοὺς Νασαμῶνας αὐτοῦ γινώσκεται, τὰ δὲ ἐς τὸ πέλαγος οὐδένα πω παραπλεύσαντα ἴσμεν.", "st": "1.33"}, {"sp": "N", "t": "τάδε μὲν ἐς τοσοῦτον εἰρήσθω· πτερὰ δ’ ἔχον οὔτε τοῦτο τὸ ἄγαλμα Νεμέσεως οὔτε ἄλλο πεποίηται τῶν ἀρχαίων, ἐπεὶ μηδὲ Σμυρναίοις τὰ ἁγιώτατα ξόανα ἔχει πτερά· οἱ δὲ ὕστερον—ἐπιφαίνεσθαι γὰρ τὴν θεὸν μάλιστα ἐπὶ τῷ ἐρᾶν ἐθέλουσιν—ἐπὶ τούτῳ Νεμέσει πτερὰ ὥσπερ Ἔρωτι ποιοῦσι. νῦν δὲ ἤδη δίειμι ὁπόσα ἐπὶ τῷ βάθρῳ τοῦ ἀγάλματός ἐστιν εἰργασμένα, τοσόνδε ἐς τὸ σαφὲς προδηλώσας. Ἑλένῃ Νέμεσιν μητέρα εἶναι λέγουσιν Ἕλληνες, Λήδαν δὲ μαστὸν ἐπισχεῖν αὐτῇ καὶ θρέψαι· πατέρα δὲ καὶ οὗτοι καὶ πάντες κατὰ ταὐτὰ Ἑλένης Δία καὶ οὐ Τυνδάρεων εἶναι νομίζουσι.", "st": "1.33"}, {"sp": "N", "t": "ταῦτα ἀκηκοὼς Φειδίας πεποίηκεν Ἑλένην ὑπὸ Λήδας ἀγομένην παρὰ τὴν Νέμεσιν, πεποίηκε δὲ Τυνδάρεών τε καὶ τοὺς παῖδας καὶ ἄνδρα σὺν ἵππῳ παρεστηκότα Ἱππέα ὄνομα· ἔστι δὲ Ἀγαμέμνων καὶ Μενέλαος καὶ Πύρρος ὁ Ἀχιλλέως, πρῶτος οὗτος Ἑρμιόνην τὴν Ἑλένης γυναῖκα λαβών· Ὀρέστης δὲ διὰ τὸ ἐς τὴν μητέρα τόλμημα παρείθη, παραμεινάσης τε ἐς ἅπαν Ἑρμιόνης αὐτῷ καὶ τεκούσης παῖδα. ἑξῆς δὲ ἐπὶ τῷ βάθρῳ καὶ Ἔποχος καλούμενος καὶ νεανίας ἐστὶν ἕτερος· ἐς τούτους ἄλλο μὲν ἤκουσα οὐδέν, ἀδελφοὺς δὲ εἶναι σφᾶς Οἰνόης, ἀφ’ ἧς ἐστι τὸ ὄνομα τῷ δήμῳ.", "st": "1.33"}, {"sp": "N", "t": "τὴν δὲ γῆν τὴν Ὠρωπίαν μεταξὺ τῆς Ἀττικῆς καὶ Ταναγρικῆς, Βοιωτίαν τὸ ἐξ ἀρχῆς οὖσαν, ἔχουσιν ἐφ’ ἡμῶν Ἀθηναῖοι, πολεμήσαντες μὲν τὸν πάντα ὑπὲρ αὐτῆς χρόνον, κτησάμενοι δὲ οὐ πρότερον βεβαίως πρὶν ἢ Φίλιππος Θήβας ἑλὼν ἔδωκέ σφισιν. ἡ μὲν οὖν πόλις ἐστὶν ἐπὶ θαλάσσης μέγα οὐδὲν ἐς συγγραφὴν παρεχομένη· ἀπέχει δὲ δώδεκα τῆς πόλεως σταδίους μάλιστα ἱερὸν τοῦ Ἀμφιαράου.", "st": "1.34"}, {"sp": "N", "t": "λέγεται δὲ Ἀμφιαράῳ φεύγοντι ἐκ Θηβῶν διαστῆναι τὴν γῆν καὶ ὡς αὐτὸν ὁμοῦ καὶ τὸ ἅρμα ὑπεδέξατο· πλὴν οὐ ταύτῃ συμβῆναί φασιν, ἀλλά ἐστιν ἐκ Θηβῶν ἰοῦσιν ἐς Χαλκίδα Ἅρμα καλούμενον. θεὸν δὲ Ἀμφιάραον πρώτοις Ὠρωπίοις κατέστη νομίζειν, ὕστερον δὲ καὶ οἱ πάντες Ἕλληνες ἥγηνται. καταλέξαι δὲ καὶ ἄλλους ἔχω γενομένους τότε ἀνθρώπους, οἳ θεῶν ⟨παρ’⟩ Ἕλλησι τιμὰς ἔχουσι, τοῖς δὲ καὶ ἀνάκεινται πόλεις, Ἐλεοῦς ἐν Χερρονήσῳ Πρωτεσιλάῳ, Λεβάδεια Βοιωτῶν Τροφωνίῳ· καὶ Ὠρωπίοις ναός τέ ἐστιν Ἀμφιαράου καὶ ἄγαλμα λευκοῦ λίθου.", "st": "1.34"}, {"sp": "N", "t": "παρέχεται δὲ ὁ βωμὸς μέρη· τὸ μὲν Ἡρακλέους καὶ Διὸς καὶ Ἀπόλλωνός ἐστι Παιῶνος, τὸ δὲ ἥρωσι καὶ ἡρώων ἀνεῖται γυναιξί, τρίτον δὲ Ἑστίας καὶ Ἑρμοῦ καὶ Ἀμφιαράου καὶ τῶν παίδων Ἀμφιλόχου· Ἀλκμαίων δὲ διὰ τὸ ἐς Ἐριφύλην ἔργον οὔτε ἐν Ἀμφιαράου τινά, οὐ μὴν οὐδὲ παρὰ τῷ Ἀμφιλόχῳ τιμὴν ἔχει. τετάρτη δέ ἐστι τοῦ βωμοῦ μοῖρα Ἀφροδίτης καὶ Πανακείας, ἔτι δὲ Ἰασοῦς καὶ Ὑγείας καὶ Ἀθηνᾶς Παιωνίας· πέμπτη δὲ πεποίηται νύμφαις καὶ Πανὶ καὶ ποταμοῖς Ἀχελῴῳ καὶ Κηφισῷ. τῷ δὲ Ἀμφιλόχῳ καὶ παρ’ Ἀθηναίοις ἐστὶν ἐν τῇ πόλει βωμὸς καὶ Κιλικίας ἐν Μαλλῷ μαντεῖον ἀψευδέστατον τῶν ἐπ’ ἐμοῦ.", "st": "1.34"}, {"sp": "N", "t": "ἔστι δὲ Ὠρωπίοις πηγὴ πλησίον τοῦ ναοῦ, ἣν Ἀμφιαράου καλοῦσιν, οὔτε θύοντες οὐδὲν ἐς αὐτὴν οὔτ’ ἐπὶ καθαρσίοις ἢ χέρνιβι χρῆσθαι νομίζοντες· νόσου δὲ ἀκεσθείσης ἀνδρὶ μαντεύματος γενομένου καθέστηκεν ἄργυρον ἀφεῖναι καὶ χρυσὸν ἐπίσημον ἐς τὴν πηγήν, ταύτῃ γὰρ ἀνελθεῖν τὸν Ἀμφιάραον λέγουσιν ἤδη θεόν. Ἰοφῶν δὲ Κνώσσιος τῶν ἐξηγητῶν χρησμοὺς ἐν ἑξαμέτρῳ παρείχετο, Ἀμφιάραον χρῆσαι φάμενος τοῖς ἐς Θήβας σταλεῖσιν Ἀργείων. ταῦτα τὰ ἔπη τὸ ἐς τοὺς πολλοὺς ἐπαγωγὸν ἀκρατῶς εἶχε· χωρὶς δὲ πλὴν ὅσους ἐξ Ἀπόλλωνος μανῆναι λέγουσι τὸ ἀρχαῖον, μάντεών γ’ οὐδεὶς χρησμολόγος ἦν, ἀγαθοὶ δὲ ὀνείρατα ἐξηγήσασθαι καὶ διαγνῶναι πτήσεις ὀρνίθων καὶ σπλάγχνα ἱερείων.", "st": "1.34"}, {"sp": "N", "t": "δοκῶ δὲ Ἀμφιάραον ὀνειράτων διακρίσει μάλιστα προ⟨σ⟩κεῖσθαι· δῆλος δέ, ἡνίκα ἐνομίσθη θεός, δι’ ὀνειράτων μαντικὴν καταστησάμενος. καὶ πρῶτον μὲν καθήρασθαι νομίζουσιν ὅστις ἦλθεν Ἀμφιαράῳ χρησόμενος· ἔστι δὲ καθάρσιον τῷ θεῷ θύειν, θύουσι δὲ καὶ αὐτῷ καὶ πᾶσιν ὅσοις ἐστὶν ἐπὶ τῷ ⟨βωμῷ⟩ τὰ ὀνόματα· προεξειργασμένων δὲ τούτων κριὸν θύσαντες καὶ τὸ δέρμα ὑποστρωσάμενοι καθεύδουσιν ἀναμένοντες δήλωσιν ὀνείρατος.", "st": "1.34"}, {"sp": "N", "t": "νῆσοι δὲ Ἀθηναίοις οὐ πόρρω τῆς χώρας εἰσίν, ἡ μὲν Πατρόκλου καλουμένη—τὰ δὲ ἐς αὐτὴν ἤδη μοι δεδήλωται—, ἄλλη δὲ ὑπὲρ Σουνίου τὴν Ἀττικὴν ἐν ἀριστερᾷ ⟨παρα⟩πλέουσιν· ἐς ταύτην ἀποβῆναι λέγουσιν Ἑλένην μετὰ τὴν ἅλωσιν τὴν Ἰλίου, καὶ διὰ τοῦτο ὄνομά ἐστιν Ἑλένη τῇ νήσῳ.", "st": "1.35"}, {"sp": "N", "t": "Σαλαμὶς δὲ κατὰ Ἐλευσῖνα κειμένη παρήκει καὶ ἐς τὴν Μεγαρικήν. πρῶτον δὲ [ἐν] τῇ νήσῳ ⟨τὸ ὄνομα⟩ θέσθαι τοῦτο[ν] ⟨Κυχρέα⟩ ἀπὸ τῆς μητρὸς Σαλαμῖνος τῆς Ἀσωποῦ, καὶ ὕστερον Αἰγινήτας τοὺς σὺν Τελαμῶνι ἐποικῆσαι· Φίλαιον δὲ τὸν Εὐρυσάκους τοῦ Αἴαντος παραδοῦναι λέγουσιν Ἀθηναίοις τὴν νῆσον, γενόμενον ὑπ’ αὐτῶν Ἀθηναῖον. Σαλαμινίους δὲ Ἀθηναῖοι τούτων ὕστερον πολλοῖς ἔτεσιν ἀναστάτους ἐποίησαν, καταγνόντες ἐθελοκακῆσαι σφᾶς ἐν τῷ πολέμῳ τῷ πρὸς Κάσσανδρον καὶ τὴν πόλιν γνώμῃ τὸ πλέον Μακεδόσιν ἐνδοῦναι· καὶ Αἰσχητάδου τε κατέγνωσαν θάνατον, ὃς τότε ᾕρητο ἐς τὴν Σαλαμῖνα στρατηγός, καὶ ἐς τὸν πάντα ἐπώμοσαν χρόνον Σαλαμινίοις ἀπομνημονεύ⟨σ⟩ειν προδοσίαν.", "st": "1.35"}, {"sp": "N", "t": "ἔστι δὲ ἀγορᾶς τε ἔτι ἐρείπια καὶ ναὸς Αἴαντος, ἄγαλμα δὲ ἐξ ἐβένου ξύλου· διαμένουσι δὲ καὶ ἐς τόδε τῷ Αἴαντι παρὰ Ἀθηναίοις τιμαὶ αὐτῷ τε καὶ Εὐρυσάκει, καὶ γὰρ Εὐρυσάκους βωμός ἐστιν ἐν Ἀθήναις. δείκνυται δὲ λίθος ἐν Σαλαμῖνι οὐ πόρρω τοῦ λιμένος· ἐπὶ τούτου καθήμενον Τελαμῶνα ὁρᾶν λέγουσιν ἐς τὴν ναῦν ἀποπλεόντων οἱ τῶν παίδων ἐς Αὐλίδα ἐπὶ τὸν κοινὸν τῶν Ἑλλήνων στόλον.", "st": "1.35"}, {"sp": "N", "t": "λέγουσι δὲ οἱ περὶ τὴν Σαλαμῖνα οἰκοῦντες ἀποθανόντος Αἴαντος τὸ ἄνθος σφίσιν ἐν τῇ γῇ τότε φανῆναι πρῶτον· λευκόν ἐστιν, ὑπέρυθρον, κρίνου καὶ αὐτὸ ἔλασσον καὶ τὰ φύλλα· γράμματα δὲ ἔπεστιν οἷα τοῖς ὑακίνθοις καὶ τούτῳ. λόγον δὲ τῶν μὲν Αἰολέων τῶν ὕστερον οἰκησάντων Ἴλιον ἐς τὴν κρίσιν τὴν ἐπὶ τοῖς ὅπλοις ἤκουσα, οἳ τῆς ναυαγίας Ὀδυσσεῖ συμβάσης ἐξενεχθῆναι κατὰ τὸν τάφον τὸν Αἴαντος τὰ ὅπλα λέγουσι· τὸ δὲ ἐς τὸ μέγεθος αὐτοῦ Μυσὸς ἔλεγεν ἀνήρ.", "st": "1.35"}, {"sp": "N", "t": "τοῦ γὰρ τάφου τὰ πρὸς τὸν αἰγιαλὸν ἔφασκεν ἐπικλύσαι τὴν θάλασσαν καὶ τὴν ἔσοδον ἐς τὸ μνῆμα οὐ χαλεπὴν ποιῆσαι, καί με τοῦ νεκροῦ τὸ μέγεθος τεκμαίρεσθαι τῇδε ἐκέλευε· πεντάθλου γὰρ παιδὸς εἶναί οἱ κατὰ δίσκον μάλιστα τὰ ἐπὶ τοῖς γόνασιν ὀστᾶ, καλουμένας δὲ ὑπὸ τῶν ἰατρῶν μύλας. ἐγὼ δέ, ὁπόσοι μὲν οἰκοῦσιν ἔσχατοι Κελτῶν ἔχοντες ὅμορον τῇ διὰ κρυμὸν ἐρήμῳ, οὓς Καβαρεῖς ὀνομάζουσι, τούτων μὲν οὐκ ἐθαύμασα τὸ μῆκος, οἳ νεκρῶν οὐδέν τι διαφόρως ἔχουσιν Αἰγυπτίων· ὁπόσα δὲ ἄξια ἐφαίνετο εἶναί μοι θέας, διηγήσομαι.", "st": "1.35"}, {"sp": "N", "t": "Μάγνησι τοῖς ἐπὶ Ληθαίῳ Πρωτοφάνης τῶν ἀστῶν ἀνείλετο ἐν Ὀλυμπίᾳ νίκας ἡμέρᾳ μιᾷ παγκρατίου καὶ πάλης· τούτου λῃσταὶ κερδανεῖν πού τι δοκοῦντες ἐσῆλθον ἐς τὸν τάφον, ἐπὶ δὲ τοῖς λῃσταῖς ἐσῄεσαν ἤδη θεασόμενοι τὸν νεκρὸν τὰς πλευρὰς οὐκ ἔχοντα διεστώσας, ἀλλά οἱ συμφυὲς ἦν ὅσον ἀπ’ ὤμων ἐς τὰς ἐλαχίστας πλευράς, καλουμένας δὲ ὑπὸ τῶν ἰατρῶν νόθας. ἔστι δὲ Μιλησίοις πρὸ τῆς πόλεως Λάδη νῆσος, ἀπερρώγασι δὲ ἀπ’ αὐτῆς νησῖδες· Ἀστερίου τὴν ἑτέραν ὀνομάζουσι καὶ τὸν Ἀστέριον ἐν αὐτῇ ταφῆναι λέγουσιν, εἶναι δὲ Ἀστέριον μὲν Ἄνακτος, Ἄνακτα δὲ Γῆς παῖδα· ἔχει δ’ οὖν ὁ νεκρὸς οὐδέν τι μεῖον πηχῶν δέκα.", "st": "1.35"}, {"sp": "N", "t": "τὸ δ’ ἐμοὶ θαῦμα παρασχόν, Λυδίας τῆς ἄνω πόλις ἐστὶν οὐ μεγάλη Τημένου θύραι· ἐνταῦθα παραραγέντος λόφου διὰ χειμῶνα ὀστᾶ ἐφάνη τὸ σχῆμα παρέχοντα ἐς πίστιν ὡς ἔστιν ἀνθρώπου, ἐπεὶ διὰ μέγεθος οὐκ ἔστιν ὅπως ἂν ἔδοξεν. αὐτίκα δὲ λόγος ἦλθεν ἐς τοὺς πολλοὺς Γηρυόνου τοῦ Χρυσάορος εἶναι μὲν τὸν νεκρόν, εἶναι δὲ καὶ τὸν θρόνον· καὶ γὰρ θρόνος ἀνδρός ἐστιν ἐνειργασμένος ὄρους λιθώδει προβολῇ· καὶ χείμαρρόν τε ποταμὸν Ὠκεανὸν ἐκάλουν καὶ βοῶν ἤδη κέρασιν ἔφασάν τινας ἐντυχεῖν ἀροῦντας, διότι ἔχει λόγος βοῦς ἀρίστας θρέψαι τὸν Γηρυόνην.", "st": "1.35"}, {"sp": "N", "t": "ἐπεὶ δέ σφισιν ἐναντιούμενος ἀπέφαινον ἐν Γαδείροις εἶναι Γηρυόνην, οὗ μνῆμα μὲν οὔ, δένδρον δὲ παρεχόμενον διαφόρους μορφάς, ἐνταῦθα οἱ τῶν Λυδῶν ἐξηγηταὶ τὸν ὄντα ἐδείκνυον λόγον, ὡς εἴη μὲν ὁ νεκρὸς Ὕλλου, παῖς δὲ Ὕλλος εἴη Γῆς, ἀπὸ τούτου δὲ ὁ ποταμὸς ὠνομάσθη· Ἡρακλέα δὲ διὰ τὴν παρ’ Ὀμφάλῃ ποτὲ ἔφασαν δίαιταν Ὕλλον ἀπὸ τοῦ ποταμοῦ καλέσαι τὸν παῖδα.", "st": "1.35"}, {"sp": "N", "t": "ἐν Σαλαμῖνι δὲ—ἐπάνειμι γὰρ ἐς τὸν προκείμενον λόγον—τοῦτο μὲν Ἀρτέμιδός ἐστιν ἱερόν, τοῦτο δὲ τρόπαιον ἕστηκεν ἀπὸ τῆς νίκης ἣν Θεμιστοκλῆς ὁ Νεοκλέους αἴτιος ἐγένετο γενέσθαι τοῖς Ἕλλησι· καὶ Κυχρέως ἐστὶν ἱερόν. ναυμαχούντων δὲ Ἀθηναίων πρὸς Μήδους δράκοντα ἐν ταῖς ναυσὶ λέγεται φανῆναι· τοῦτον ὁ θεὸς ἔχρησεν Ἀθηναίοις Κυχρέα εἶναι τὸν ἥρωα.", "st": "1.36"}, {"sp": "N", "t": "νῆσος δὲ πρὸ Σαλαμῖνός ἐστι καλουμένη Ψυττάλεια· ἐς ταύτην τῶν βαρβάρων ὅσον τετρακοσίους ἀποβῆναι λέγουσιν, ἡττωμένου δὲ τοῦ Ξέρξου ναυτικοῦ καὶ τούτους ἀπολέσθαι φασὶν ἐπιδιαβάντων ἐς τὴν Ψυττάλειαν τῶν Ἑλλήνων. ἄγαλμα δὲ ἐν τῇ νήσῳ σὺν τέχνῃ μέν ἐστιν οὐδέν, Πανὸς δὲ ὡς ἕκαστον ἔτυχε ξόανα πεποιημένα.", "st": "1.36"}, {"sp": "N", "t": "ἰοῦσι δὲ ἐπ’ Ἐλευσῖνα ἐξ Ἀθηνῶν ἣν Ἀθηναῖοι καλοῦσιν ὁδὸν ἱεράν, Ἀνθεμοκρίτου πεποίηται μνῆμα. ἐς τοῦτον Μεγαρεῦσίν ἐστιν ἀνοσιώτατον ἔργον, οἳ κήρυκα ἐλθόντα, ὡς μὴ τοῦ λοιποῦ τὴν χώραν ἐπεργάζοιντο, κτείνουσιν Ἀνθεμόκριτον· καί σφισι ταῦτα δράσασι παραμένει καὶ ἐς τόδε μήνιμα ἐκ τοῖν θεοῖν, οἷς οὐδὲ Ἀδριανὸς ὁ βασιλεὺς ὥστε καὶ ἐπαυξηθῆναι μόνοις ἐπήρκεσεν Ἑλλήνων.", "st": "1.36"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Ἀνθεμοκρίτου τὴν στήλην Μολοττοῦ τε τάφος ἐστὶν ἀξιωθέντος Ἀθηναίων καὶ τούτου στρατηγεῖν, ὅτε Πλουτάρχῳ βοηθοῦντες διέβησαν ἐς Εὔβοιαν, καὶ χωρίον Σκῖρον ἐπὶ τοιῷδε καλούμενον. Ἐλευσινίοις πολεμοῦσι πρὸς Ἐρεχθέα ἀνὴρ μάντις ἦλθεν ἐκ Δωδώνης ὄνομα Σκῖρος, ὃς καὶ τῆς Σκιράδος ἱδρύσατο Ἀθηνᾶς ἐπὶ Φαληρῷ τὸ ἀρχαῖον ἱερόν· πεσόντα δὲ αὐτὸν ἐν τῇ μάχῃ θάπτουσιν Ἐλευσίνιοι πλησίον ποταμοῦ χειμάρρου, καὶ τῷ τε χωρίῳ τὸ ὄνομα ἀπὸ τοῦ ἥρωός ἐστι καὶ τῷ ποταμῷ.", "st": "1.36"}, {"sp": "N", "t": "πλησίον δὲ πεποίηται Κηφισοδώρου μνῆμα δήμου προστάντος καὶ Φιλίππῳ τῷ Δημητρίου Μακεδόνων βασιλεύοντι ἐς τὰ μάλιστα ἐναντιωθέντος· συμμάχους δὲ ἐπήγετο Κηφισόδωρος Ἀθηναίοις γενέσθαι βασιλεῖς μὲν Ἄτταλον τὸν Μυσὸν καὶ Πτολεμαῖον τὸν Αἰγύπτιον, ἔθνη δὲ αὐτόνομα Αἰτωλοὺς καὶ νησιωτῶν Ῥοδίους καὶ Κρῆτας.", "st": "1.36"}, {"sp": "N", "t": "ὡς δὲ καὶ ἐξ Αἰγύπτου καὶ Μυσίας καὶ παρὰ τῶν Κρητῶν τὰ πολλὰ ὑστέριζον αἱ βοήθειαι, Ῥόδιοι δὲ μόναις ναυσὶν ἰσχύοντες πρὸς ὁπλίτας τοὺς Μακεδόνας οὐ μεγάλα ὠφέλουν, ἐνταῦθα Κηφισόδωρος ἐς Ἰταλίαν σὺν ἄλλοις Ἀθηναίων πλεύσας ἱκέτευεν ἀμῦναι Ῥωμαίους· οἱ δέ σφισι δύναμιν καὶ στρατηγὸν πέμπουσιν, οἳ τὰ Φιλίππου καὶ Μακεδόνων ἐς τοσοῦτο καθεῖλον ὡς ὕστερον Περσέα τὸν Φιλίππου τήν τε ἀρχὴν ἀποβαλεῖν καὶ αὐτὸν αἰχμάλωτον ἐς Ἰταλίαν ἀχθῆναι. Φίλιππος δὲ ἦν οὗτος ὁ Δημητρίου· πρῶτος γὰρ ταύτης τῆς οἰκίας ἔσχε Δημήτριος τὴν Μακεδόνων ἀρχὴν ἀποκτείνας Ἀλέξανδρον τὸν Κασσάνδρου παῖδα, ὡς τὰ πρότερον ἔχει μοι τοῦ λόγου.", "st": "1.36"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Κηφισοδώρου τὸ μνῆμα τέθαπται μὲν Ἡλιόδωρος Ἅλις· τούτου γραφὴν ἰδεῖν ἔστι καὶ ἐν τῷ ναῷ τῷ μεγάλῳ τῆς Ἀθηνᾶς· τέθαπται δὲ Θεμιστοκλῆς Πολιάρχου, τρίτος ἀπόγονος Θεμιστοκλέους τοῦ Ξέρξῃ καὶ Μήδοις ἐναντία ναυμαχήσαντος. τοὺς δὲ κατωτέρω τοῦ γένους πλὴν Ἀκεστίου παρήσω τοὺς ἄλλους· Ἀκεστίῳ δὲ τῇ Ξενοκλέους τοῦ Σοφοκλέους τοῦ Λέοντος τούτους τε ἐς τὸν τέταρτον πρόγονον Λέοντα δᾳδούχους πάντας ὑπῆρξε γενέσθαι ⟨καὶ⟩ παρὰ τὸν βίον τὸν αὑτῆς πρῶτον μὲν τὸν ἀδελφὸν Σοφοκλέα εἶδε δᾳδουχοῦντα, ἐπὶ δὲ τούτῳ τὸν ἄνδρα Θεμιστοκλέα, τελευτήσαντος δὲ καὶ τούτου Θεόφραστον τὸν παῖδα.", "st": "1.37"}, {"sp": "N", "t": "ταύτῃ μὲν τύχην τοιαύτην συμβῆναι λέγουσι· προελθοῦσι δὲ ὀλίγον Λακίου τέμενός ἐστιν ἥρωος καὶ δῆμος ὃν Λακιάδας ὀνομάζουσιν ἀπὸ τούτου, καὶ Νικοκλέους Ταραντίνου ἐστὶ μνῆμα, ὃς ἐπὶ μέγιστον δόξης κιθαρῳδῶν ἁπάντων ἦλθεν. ἔστι δὲ καὶ Ζεφύρου τε βωμὸς καὶ Δήμητρος ἱερὸν καὶ τῆς παιδός· σὺν δέ σφισιν Ἀθηνᾶ καὶ Ποσειδῶν ἔχουσι τιμάς. ἐν τούτῳ τῷ χωρίῳ Φύταλόν φασιν οἴκῳ Δήμητρα δέξασθαι, καὶ τὴν θεὸν ἀντὶ τούτων δοῦναί οἱ τὸ φυτὸν τῆς συκῆς· μαρτυρεῖ δέ μοι τῷ λόγῳ τὸ ἐπίγραμμα τὸ ἐπὶ τῷ Φυτάλου τάφῳ·<br>ἐνθάδ’ ἄναξ ἥρως Φύταλός ποτε δέξατο σεμνὴν<br>Δήμητρα⟨ν⟩, ὅτε πρῶτον ὀπώρας καρπὸν ἔφηνεν,<br>ἣν ἱερὰν συκῆν θνητῶν γένος ἐξονομάζει·<br>ἐξ οὗ δὴ τιμὰς Φυτάλου γένος ἔσχεν ἀγήρως.", "st": "1.37"}, {"sp": "N", "t": "πρὶν δὲ ἢ διαβῆναι τὸν Κηφισὸν Θεοδώρου μνῆμά ἐστι τραγῳδίαν ὑποκριναμένου τῶν καθ’ αὑτὸν ⟨ἄριστα⟩. ἀγάλματα δὲ ἐπὶ τῷ ποταμῷ Μνησιμάχης, τὸ δὲ ἕτερον ἀνάθημα κειρομένου οἱ τὴν κόμην τοῦ παιδός ἐστι τῷ Κηφισῷ· καθεστάναι δὲ ἐκ παλαιοῦ καὶ τοῖς πᾶσι τοῦτο Ἕλλησι τῇ Ὁμήρου τις ἂν τεκμαίροιτο ποιήσει, ὃς τὸν Πηλέα εὔξασθαί ⟨φησι⟩ τῷ Σπερχειῷ κερεῖν ἀνασωθέντος ἐκ Τροίας Ἀχιλλέως τὴν κόμην.", "st": "1.37"}, {"sp": "N", "t": "διαβᾶσι δὲ τὸν Κηφισὸν βωμός ἐστιν ἀρχαῖος Μειλιχίου Διός· ἐπὶ τούτῳ Θησεὺς ὑπὸ τῶν ἀπογόνων τῶν Φυτάλου καθαρσίων ἔτυχε, λῃστὰς καὶ ἄλλους ἀποκτείνας καὶ Σίνιν τὰ πρὸς Πιτθέως συγγενῆ. τάφος δὲ ἔστι μὲν αὐτόθι Θεοδέκτου τοῦ Φασηλίτου, ἔστι δὲ Μνησιθέου· τοῦτον λέγουσιν ἰατρόν τε ἀγαθὸν γενέσθαι καὶ ἀναθεῖναι ἀγάλματα, ἐν οἷς καὶ ὁ Ἴακχος πεποίηται. ᾠκοδόμηται δὲ κατὰ τὴν ὁδὸν ναὸς οὐ μέγας καλούμενος Κυαμίτου· σαφὲς δὲ οὐδὲν ἔχω λέγειν εἴτε πρῶτος κυάμους ἔσπειρεν οὗτος εἴτε τινὰ ἐπεφήμισαν ἥρωα, ὅτι τῶν κυάμων ἀνενεγκεῖν οὐκ ἔστι σφίσιν ἐς Δήμητρα τὴν εὕρεσιν. ὅστις δὲ ἤδη τελετὴν Ἐλευσῖνι εἶδεν ἢ τὰ καλούμενα Ὀρφικὰ ἐπελέξατο, οἶδεν ὃ λέγω.", "st": "1.37"}, {"sp": "N", "t": "μνημάτων δὲ ἃ μάλιστα ἐς μέγεθος καὶ κόσμον ἥκει, τὸ μὲν ἀνδρός ἐστι Ῥοδίου μετοικήσαντος ἐς Ἀθήνας, τὸ δὲ Ἅρπαλος Μακεδὼν ἐποίησεν, ὃς Ἀλέξανδρον ἀποδρὰς ἐκ τῆς Ἀσίας διέβη ναυσὶν ἐς τὴν Εὐρώπην, ἀφικόμενος δὲ παρ’ Ἀθηναίους ὑπ’ αὐτῶν συνελήφθη, διαφθείρας δὲ χρήμασιν ἄλλους τε καὶ τοὺς Ἀλεξάνδρου φίλους ἀπέδρα, πρότερον δὲ ἔτι Πυθ[ι]ονίκην ἔγημε, γένος μὲν οὐκ οἶδα ὁπόθεν, ἑταιροῦσαν δὲ ἔν τε Ἀθήναις καὶ ἐν Κορίνθῳ· ταύτης ἐς τοσοῦτον ἔρωτος προῆλθεν ὡς καὶ μνῆμα ἀποθανούσης ποιῆσαι πάντων ὁπόσα Ἕλλησίν ἐστιν ἀρχαῖα θέας μάλιστα ἄξιον.", "st": "1.37"}, {"sp": "N", "t": "ἔστι δὲ ἱερὸν ἐν ᾧ κεῖται Δήμητρος καὶ τῆς παιδὸς ἀγάλματα καὶ Ἀθηνᾶς τε καὶ Ἀπόλλωνος· Ἀπόλλωνι δὲ ἐποιήθη μόνῳ τὸ ἐξ ἀρχῆς. Κέφαλον γὰρ τὸν Δηίονος συνεξελόντα λέγουσιν Ἀμφιτρύωνι Τηλεβόας τὴν νῆσον οἰκῆσαι πρῶτον, ἣ νῦν ἀπ’ ἐκείνου Κεφαλληνία καλεῖται· μετοικεῖν δὲ αὐτὸν τέως ἐν Θήβαις φεύγοντα ἐξ Ἀθηνῶν διὰ τὸν Πρόκριδος τῆς γυναικὸς φόνον. δεκάτῃ δὲ ὕστερον γενεᾷ Χαλκῖνος καὶ Δαῖτος ἀπόγονοι Κεφάλου πλεύσαντες ἐς Δελφοὺς ᾔτουν τὸν θεὸν κάθοδον ἐς Ἀθήνας·", "st": "1.37"}, {"sp": "N", "t": "ὁ δέ σφισι κελεύει θῦσαι πρῶτον Ἀπόλλωνι ἐνταῦθα τῆς Ἀττικῆς, ἔνθα ἂν ἴδωσιν ἐπὶ τῆς γῆς τριήρη θέουσαν. γενομένοις δὲ αὐτοῖς κατὰ τὸ ποικίλον καλούμενον ὄρος δράκων ἐφάνη σπουδῇ κατὰ τὸν φωλεὸν ἰών· καὶ Ἀπόλλωνί τε θύουσιν ἐν τῷ χωρίῳ τούτῳ καὶ ὕστερον σφᾶς ἐλθόντας ἐς τὴν πόλιν ἀστοὺς ἐποιήσαντο Ἀθηναῖοι. —μετὰ δὲ τοῦτο Ἀφροδίτης ναός ἐστι καὶ πρὸ αὐτοῦ τεῖχος ἀργῶν λίθων θέας ἄξιον.", "st": "1.37"}, {"sp": "N", "t": "οἱ δὲ Ῥειτοὶ καλούμενοι ῥεῦμα μόνον παρέχονται ποταμῶν, ἐπεὶ τό γε ὕδωρ θάλασσά ἐστί σφισι· πείθοιτο δὲ ἄν τις καὶ ὡς ἀπὸ τοῦ Χαλκιδέων Εὐρίπου ῥέουσιν ὑπὸ τῆς γῆς ἐς θάλασσαν κοιλοτέραν ἐμπίπτοντες. λέγονται δὲ οἱ Ῥειτοὶ Κόρης ἱεροὶ καὶ Δήμητρος εἶναι, καὶ τοὺς ἰχθῦς ἐξ αὐτῶν τοῖς ἱερεῦσιν ἔστιν αἱρεῖν μόνοις. οὗτοι τὸ ἀρχαῖον, ὡς ἐγὼ πυνθάνομαι, πρὸς Ἀθηναίους τοὺς ἄλλους ὅροι τῆς γῆς Ἐλευσινίοις ἦσαν, καὶ διαβᾶσι τοὺς Ῥειτοὺς πρῶτος ᾤκει", "st": "1.38"}, {"sp": "N", "t": "Κρόκων, ἔνθα καὶ νῦν ἔτι βασίλεια καλεῖται Κρόκωνος. τοῦτον Ἀθηναῖοι τὸν Κρόκωνα Κελεοῦ θυγατρί συνοικῆσαι Σαισάρᾳ λέγουσι· λέγουσι δὲ οὐ πάντες, ἀλλ’ ὅσοι τοῦ δήμου τοῦ Σκαμβωνιδῶν εἰσιν· ἐγὼ δὲ Κρόκωνος μὲν ἀνευρεῖν τάφον οὐχ οἷός τε ἐγενόμην, τὸ δὲ Εὐμόλπου μνῆμα κατὰ ταὐτὰ Ἐλευσινίοις ἀπέφαινον καὶ Ἀθηναῖοι. τοῦτον τὸν Εὔμολπον ἀφικέσθαι λέγουσιν ἐκ Θρᾴκης Ποσειδῶνος παῖδα ὄντα καὶ Χιόνης· τὴν δὲ Χιόνην Βορέου θυγατέρα τοῦ ἀνέμου καὶ Ὠρειθυίας φασὶν εἶναι. Ὁμήρῳ δὲ ἐς μὲν τὸ γένος ἐστὶν οὐδὲν αὐτοῦ πεποιημένον, ἐπονομάζει δὲ ἀγήνορα ἐν τοῖς ἔπεσι τὸν Εὔμολπον.", "st": "1.38"}, {"sp": "N", "t": "γενομένης δὲ Ἐλευσινίοις μάχης πρὸς Ἀθηναίους ἀπέθανε μὲν Ἐρεχθεὺς Ἀθηναίων βασιλεύς, ἀπέθανε δὲ Ἰμμάραδος Εὐμόλπου· καταλύονται δὲ ἐπὶ τοῖσδε τὸν πόλεμον, ὡς Ἐλευσινίους ἐς τὰ ἄλλα Ἀθηναίων κατηκόους ὄντας ἰδίᾳ τελεῖν τὴν τελετήν. τὰ δὲ ἱερὰ τοῖν θεοῖν Εὔμολπος καὶ αἱ θυγατέρες δρῶσιν αἱ Κελεοῦ, καλοῦσι δὲ σφᾶς Πάμφως τε κατὰ ταὐτὰ καὶ Ὅμηρος Διογένειαν καὶ Παμμερόπην καὶ τρίτην Σαισάραν· τελευτήσαντος δὲ Εὐμόλπου Κήρυξ νεώτερος λείπεται τῶν παίδων, ὃν αὐτοὶ Κήρυκες θυγατρὸς Κέκροπος Ἀγλαύρου καὶ Ἑρμοῦ παῖδα εἶναι λέγουσιν, ἀλλ’ οὐκ Εὐμόλπου.", "st": "1.38"}, {"sp": "N", "t": "ἔστι δὲ Ἱπποθόωντος ἡρῷον, ἀφ’ οὗ τὴν φυλὴν ὀνομάζουσι, καὶ πλησίον Ζάρηκος. τοῦτον μαθεῖν παρὰ Ἀπόλλωνι μουσικήν φασιν, ἐγὼ δὲ ξένον μὲν ἀφικόμενον ἐς τὴν γῆν Λακεδαιμόνιόν τε εἶναι δοκῶ καὶ Ζάρακα ἐν τῇ Λακωνικῇ πόλιν ἀπὸ τούτου πρὸς θαλάσσῃ καλεῖσθαι· εἰ δέ τις Ζάρηξ ἐπιχώριος Ἀθηναίοις ἥρως, οὐδὲν ἐς αὐτὸν ἔχω λέγειν.", "st": "1.38"}, {"sp": "N", "t": "—ῥεῖ δὲ Κηφισὸς πρὸς Ἐλευσῖνι βιαιότερον παρεχόμενος τοῦ προτέρου ῥεῦμα· καὶ παρ’ αὐτῷ καλοῦσιν Ἐρινεόν, λέγοντες τὸν Πλούτωνα ὅτε ἥρπασε τὴν Κόρην καταβῆναι ταύτῃ. πρὸς τούτῳ τῷ Κηφισῷ λῃστὴν Πολυπήμονα ὄνομα, Προκρούστην δὲ ἐπίκλησιν, Θησεὺς ἀπέκτεινεν.", "st": "1.38"}, {"sp": "N", "t": "Ἐλευσινίοις δὲ ἔστι μὲν Τριπτολέμου ναός, ἔστι δὲ Προπυλαίας Ἀρτέμιδος καὶ Ποσειδῶνος Πατρός, φρέαρ τε καλούμενον Καλλίχορον, ἔνθα πρῶτον Ἐλευσινίων αἱ γυναῖκες χορὸν ἔστησαν καὶ ᾖσαν ἐς τὴν θεόν. τὸ δὲ πεδίον τὸ Ῥάριον σπαρῆναι πρῶτον λέγουσι καὶ πρῶτον αὐξῆσαι καρπούς, καὶ διὰ τοῦτο οὐλαῖς ἐξ αὐτοῦ χρῆσθαί σφισι καὶ ποιεῖσθαι πέμματα ἐς τὰς θυσίας καθέστηκεν. ἐνταῦθα ἅλως καλουμένη Τριπτολέμου καὶ βωμὸς δείκνυται·", "st": "1.38"}, {"sp": "N", "t": "τὰ δὲ ἐντὸς τοῦ τείχους τοῦ ἱεροῦ τό τε ὄνειρον ἀπεῖπε γράφειν, καὶ τοῖς οὐ τελεσθεῖσιν, ὁπόσων θέας εἴργονται, δῆλα δήπου μηδὲ πυθέσθαι μετεῖναί σφισιν. Ἐλευσῖνα δὲ ἥρωα, ἀφ’ οὗ τὴν πόλιν ὀνομάζουσιν, οἱ μὲν Ἑρμοῦ παῖδα εἶναι καὶ Δαείρας Ὠκεανοῦ θυγατρὸς λέγουσι, τοῖς δέ ἐστι πεποιημένα Ὤγυγον εἶναι πατέρα Ἐλευσῖνι· οἱ γὰρ ἀρχαῖοι τῶν λόγων ἅτε οὐ προσόντων σφίσιν ἐπῶν ἄλλα τε πλάσασθαι δεδώκασι ⟨καὶ⟩ μάλιστα ἐς τὰ γένη τῶν ἡρώων.", "st": "1.38"}, {"sp": "N", "t": "ἐκ δὲ Ἐλευσῖνος τραπομένοις ἐπὶ Βοιωτῶν, ἐστὶν ὅμορος Ἀθηναίοις ἡ Πλαταιίς. πρότερον μὲν γὰρ Ἐλευθερεῦσιν ὅροι πρὸς τὴν Ἀττικὴν ἦσαν· προσχωρησάντων δὲ Ἀθηναίοις τούτων, οὕτως ἤδη Βοιωτίας ὁ Κιθαιρών ἐστιν ὅρος. προσεχώρησαν δὲ Ἐλευθερεῖς οὐ πολέμῳ βιασθέντες, ἀλλὰ πολιτείας τε ἐπιθυμήσαντες παρὰ Ἀθηναίων καὶ κατ’ ἔχθος τὸ Θηβαίων. ἐν τούτῳ τῷ πεδίῳ ναός ἐστι Διονύσου, καὶ τὸ ξόανον ἐντεῦθεν Ἀθηναίοις ἐκομίσθη τὸ ἀρχαῖον· τὸ δὲ ἐν Ἐλευθεραῖς ⟨τὸ⟩ ἐφ’ ἡμῶν ἐς μίμησιν ἐκείνου πεποίηται.", "st": "1.38"}, {"sp": "N", "t": "ἀπωτέρω δὲ ὀλίγον σπήλαιόν ἐστιν οὐ μέγα, καὶ παρ’ αὐτὸ ὕδατος πηγὴ ψυχροῦ· λέγεται δὲ ἐς μὲν τὸ σπήλαιον ὡς Ἀντιόπη τεκοῦσα κατάθοιτο ἐς αὐτὸ τοὺς παῖδας, περὶ δὲ τῆς πηγῆς τὸν ποιμένα εὑρόντα τοὺς παῖδας ἐνταῦθα σφᾶς λοῦσαι πρῶτον ἀπολύσαντα τῶν σπαργάνων. Ἐλευθερῶν δὲ ἦν μὲν ἔτι τοῦ τείχους, ἦν δὲ καὶ οἰκιῶν ἐρείπια· δήλη δὲ τούτοις ἐστὶ πόλις ὀλίγον ὑπὲρ τοῦ πεδίου πρὸς τῷ Κιθαιρῶνι οἰκισθεῖσα.", "st": "1.38"}, {"sp": "N", "t": "ἑτέρα δὲ ὁδὸς ἐξ Ἐλευσῖνος πρὸς Μέγαρα ἄγει· ταύτην ἐρχομένοις τὴν ὁδὸν φρέαρ ἐστὶν Ἄνθιον καλούμενον. ἐποίησε δὲ Πάμφως ἐπὶ τούτῳ τῷ φρέατι καθῆσθαι Δήμητρα μετὰ τὴν ἁρπαγὴν τῆς παιδὸς γραῒ εἰκασμένην· ἐντεῦθεν δὲ αὐτὴν ἅτε γυναῖκα Ἀργείαν ὑπὸ τῶν θυγατέρων τῶν Κελεοῦ κομισθῆναι παρὰ τὴν μητέρα καί οἱ τὴν Μετάνειραν οὕτω πιστεῦσαι τοῦ παιδὸς τὴν ἀνατροφήν.", "st": "1.39"}, {"sp": "N", "t": "ὀλίγῳ δὲ ἀπωτέρω τοῦ φρέατος ἱερὸν Μετανείρας ἐστὶ καὶ μετ’ αὐτὸ τάφοι τῶν ἐπὶ Θήβας. Κρέων γάρ, ὃς ἐδυνάστευε τότε ἐν Θήβαις Λαοδάμαντα ἐπιτροπεύων τὸν Ἐτεοκλέους, οὐ παρῆκε τοῖς προσήκουσιν ἀνελομένοις θάψαι· ἱκετεύσαντος δὲ Ἀδράστου Θησέα καὶ μάχης Ἀθηναίων γενομένης πρὸς Βοιωτούς, Θησεὺς ὡς ἐκράτησε τῇ μάχῃ κομίσας ἐς τὴν Ἐλευσινίαν τοὺς νεκροὺς ἐνταῦθα ἔθαψε. Θηβαῖοι δὲ τὴν ἀναίρεσιν τῶν νεκρῶν λέγουσιν ἐθελονταὶ δοῦναι καὶ συνάψαι μάχην οὔ φασι.", "st": "1.39"}, {"sp": "N", "t": "—μετὰ δὲ τῶν Ἀργείων τοὺς τάφους ἐστὶν Ἀλόπης μνῆμα, ἣν τεκοῦσαν Ἱπποθόωντα ἐκ Ποσειδῶνος ἀποθανεῖν ἐνταῦθά φασιν ὑπὸ τοῦ πατρὸς Κερκυόνος. εἶναι δὲ ὁ Κερκυὼν λέγεται καὶ τὰ ἄλλα ἄδικος ἐς τοὺς ξένους καὶ παλαίειν οὐ βουλομένοις· καὶ ὁ τόπος οὗτος παλαίστρα καὶ ἐς ἐμὲ ἐκαλεῖτο Κερκυόνος, ὀλίγον τοῦ τάφου τῆς Ἀλόπης ἀπέχων. λέγεται δὲ ὁ Κερκυὼν τοὺς καταστάντας ἐς πάλην διαφθεῖραι πλὴν Θησέως, Θησεὺς δὲ κατεπάλαισεν αὐτὸν σοφίᾳ τὸ πλέον· παλαιστικὴν γὰρ τέχνην εὗρε Θησεὺς πρῶτος καὶ πάλης κατέστη ὕστερον ἀπ’ ἐκείνου διδασκαλία· πρότερον ⟨δὲ⟩ ἐχρῶντο μεγέθει μόνον καὶ ῥώμῃ πρὸς τὰς πάλας. τοσαῦτα κατὰ γνώμην τὴν ἐμὴν Ἀθηναίοις γνωριμώτατα ἦν ἔν τε λόγοις καὶ θεωρήμασιν, ἀπέκρινε δὲ ἀπὸ τῶν πολλῶν ἐξ ἀρχῆς ὁ λόγος μοι τὰ ἐς συγγραφὴν ἀνήκοντα.", "st": "1.39"}, {"sp": "N", "t": "Ἐλευσῖνι δὲ ἤδη πλησιόχωρος ⟨ἡ⟩ καλουμένη Μεγαρίς· τῆς Ἀθηναίων ἦν καὶ αὕτη τὸ ἀρχαῖον, Πύλα τοῦ βασιλέως καταλιπόντος Πανδίονι. μαρτύρια δέ μοι τάφος τε Πανδίονος ἐν τῇ γῇ καὶ Νῖσος Αἰγεῖ μὲν πρεσβυτάτῳ τοῦ παντὸς γένους παραχωρήσας Ἀθηναίων ἄρχειν, αὐτὸς δὲ Μεγάρων καὶ τῆς ἄχρι Κορίνθου βασιλεύειν ἀξιωθείς· Νίσαιά τε ἔτι καὶ νῦν Μεγαρεῦσιν ἐπίνειον ἀπ’ αὐτοῦ καλεῖται. Κόδρου δὲ ὕστερον βασιλεύοντος στρατεύουσιν ἐπ’ Ἀθήνας Πελοποννήσιοι· καὶ ὡς οὐδὲν ἀποδειξάμενοι λαμπρὸν ἐκομίζοντο ὀπίσω, Μέγαρα Ἀθηναίων ἑλόντες Κορινθίων καὶ τῶν ἄλλων συμμάχων τοῖς ἐθέλουσιν ἔδωκαν οἰκῆσαι.", "st": "1.39"}, {"sp": "N", "t": "Μεγαρεῖς μὲν οὕτως ἔθη καὶ φωνὴν μεταβαλόντες Δωριεῖς γεγόνασι, κληθῆναι δὲ οὕτω τὴν πόλιν φασὶν ἐπὶ Καρὸς τοῦ Φορωνέως ἐν τῇ γῇ ταύτῃ βασιλεύοντος· τότε πρῶτον λέγουσιν ἱερὰ γενέσθαι Δήμητρος αὐτοῖς, τότε ἀνθρώπους ὀνομάσαι Μέγαρα. οὕτω μὲν αὐτοὶ περὶ σφῶν Μεγαρεῖς λέγουσι· Βοιωτοὶ δὲ ἐν Ὀγχηστῷ Μεγαρέα τὸν Ποσειδῶνος οἰκοῦντα ἀφικέσθαι στρατιᾷ Βοιωτῶν φασι Νίσῳ τὸν πρὸς Μίνω πόλεμον συνδιοίσοντα, πεσόντα δὲ αὐτὸν ἐν τῇ μάχῃ ταφῆναί τε αὐτοῦ καὶ τῇ πόλει Μέγαρα ὄνομα ἀπὸ τούτου γενέσθαι, πρότερον Νίσᾳ καλουμένῃ.", "st": "1.39"}, {"sp": "N", "t": "δωδεκάτῃ δὲ ὕστερον μετὰ Κᾶρα τὸν Φορωνέως γενεᾷ λέγουσιν οἱ Μεγαρεῖς Λέλεγα ἀφικόμενον ἐξ Αἰγύπτου βασιλεῦσαι καὶ τοὺς ἀνθρώπους κληθῆναι Λέλεγας ἐπὶ τῆς ἀρχῆς αὐτοῦ· Κλήσωνος δὲ τοῦ Λέλεγος γενέσθαι Πύλαν, τοῦ Πύλα ⟨δὲ⟩ Σκίρωνα· ⟨τοῦτον⟩ συνοικῆσαι Πανδίονος θυγατρί, καὶ ὕστερον Νίσῳ τῷ Πανδίονος ἐς ἀμφισβήτησιν ἐλθεῖν περὶ τῆς ἀρχῆς Σκίρωνα καί σφισιν Αἰακὸν δικάσαι, βασιλείαν μὲν διδόντα Νίσῳ καὶ τοῖς ἀπογόνοις, Σκίρωνι δὲ ἡγεμονίαν εἶναι πολέμου. Μεγαρέα δὲ τὸν Ποσειδῶνος θυγατρὶ Νίσου συνοικήσαντα Ἰφινόῃ διαδέξασθαι τὴν τοῦ Νίσου φασὶν ἀρχήν· τὸν δὲ Κρητικὸν πόλεμον καὶ τὴν ἐπὶ Νίσου βασιλεύοντος ἅλωσιν τῆς πόλεως οὐκ ἐθέλουσιν εἰδέναι.", "st": "1.39"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ πόλει κρήνη, ἥν σφισιν ᾠκοδόμησε Θεαγένης, οὗ καὶ πρότερον τούτων ἐπεμνήσθην θυγατέρα αὐτὸν συνοικίσαι Κύλωνι Ἀθηναίῳ. οὗτος ὁ Θεαγένης τυραννήσας ᾠκοδόμησε τὴν κρήνην μεγέθους ἕνεκα καὶ κόσμου καὶ ἐς τὸ πλῆθος τῶν κιόνων θέας ἀξίαν· καὶ ὕδωρ ἐς αὐτὴν ῥεῖ καλούμενον Σιθνίδων νυμφῶν. τὰς δὲ Σιθνίδας νύμφας λέγουσι Μεγαρεῖς εἶναι μέν σφισιν ἐπιχωρίας, μιᾷ δὲ αὐτῶν [θυγατρὶ] συγγενέσθαι Δία, Μέγαρόν τε παῖδα ὄντα Διὸς καὶ ταύτης δὴ τῆς νύμφης ἐκφυγεῖν τὴν ἐπὶ Δευκαλίωνός ποτε ἐπομβρίαν, ἐκφυγεῖν δὲ πρὸς τὰ ἄκρα τῆς Γερανίας, οὐκ ἔχοντός πω τοῦ ὄρους τὸ ὄνομα τοῦτο, ἀλλὰ —νήχεσθαι γὰρ πετομένων γεράνων πρὸς τὴν βοὴν τῶν ὀρνίθων αὐτόν—διὰ τοῦτο Γερανίαν τὸ ὄρος ὀνομασθῆναι.", "st": "1.40"}, {"sp": "N", "t": "τῆς δὲ κρήνης οὐ πόρρω ταύτης ἀρχαῖόν ἐστιν ἱερόν, εἰκόνες δὲ ἐφ’ ἡμῶν ἑστᾶσιν ἐν αὐτῷ βασιλέων Ῥωμαίων καὶ ἄγαλμα [τε] κεῖται χαλκοῦν Ἀρτέμιδος ἐπίκλησιν Σωτείρας. φασὶ δὲ ἄνδρας τοῦ Μαρδονίου στρατοῦ καταδραμόντας τὴν Μεγαρίδα ἀποχωρεῖν ἐς Θήβας ὀπίσω παρὰ Μαρδόνιον ἐθέλειν, γνώμῃ δὲ Ἀρτέμιδος νύκτα τε ὁδοιποροῦσιν ἐπιγενέσθαι καὶ τῆς ὁδοῦ σφᾶς ἁμαρτόντας ἐς τὴν ὀρεινὴν τραπέσθαι τῆς χώρας· πειρωμένους δὲ ⟨εἰ⟩ στράτευμα ἐγγὺς εἴη πολέμιον ἀφιέναι τῶν βελῶν, καὶ τὴν πλησίον πέτραν στένειν βαλλομένην, τοὺς δὲ αὖθις τοξεύειν προθυμίᾳ πλέονι.", "st": "1.40"}, {"sp": "N", "t": "τέλος δὲ αὐτοῖς ἀναλωθῆναι τοὺς ὀιστοὺς ἐς ἄνδρας πολεμίους τοξεύειν [προθυμίᾳ πλέονι] νομίζουσιν· ἡμέρα τε ὑπεφαίνετο καὶ οἱ Μεγαρεῖς ἐπῄεσαν, μαχόμενοι δὲ ὁπλῖται πρὸς ἀνόπλους καὶ οὐδὲ βελῶν εὐποροῦντας ἔτι φονεύουσιν αὐτῶν τοὺς πολλούς· καὶ ἐπὶ τῷδε Σωτείρας ἄγαλμα ἐποιήσαντο Ἀρτέμιδος. ἐνταῦθα καὶ τῶν δώδεκα ὀνομαζομένων θεῶν ἐστιν ἀγάλματα ἔργα εἶναι λεγόμενα Πραξιτέλους· τὴν δὲ Ἄρτεμιν αὐτὴν Στρογγυλίων ἐποίησε.", "st": "1.40"}, {"sp": "N", "t": "μετὰ ταῦτα ἐς τὸ τοῦ Διὸς τέμενος ἐσελθοῦσι καλούμενον Ὀλυμπιεῖον ναός ἐστι θέας ἄξιος· τὸ δὲ ἄγαλμα οὐκ ἐξειργάσθη τοῦ Διός, ἐπιλαβόντος τοῦ Πελοποννησίων πολέμου πρὸς Ἀθηναίους, ἐν ᾧ καὶ ναυσὶν ἀνὰ πᾶν ἔτος καὶ στρατῷ φθείροντες Μεγαρεῦσιν Ἀθηναῖοι τὴν χώραν τά τε κοινὰ ἐκάκωσαν καὶ ἰδίᾳ τοὺς οἴκους ἤγαγον ἐς τὸ ἔσχατον ἀσθενείας. τῷ δὲ ἀγάλματι τοῦ Διὸς πρόσωπον ἐλέφαντος καὶ χρυσοῦ, τὰ δὲ λοιπὰ πηλοῦ τέ ἐστι καὶ γύψου· ποιῆσαι δὲ αὐτὸ Θεόκοσμον λέγουσιν ἐπιχώριον, συνεργάσασθαι δέ οἱ Φειδίαν. ὑπὲρ δὲ τῆς κεφαλῆς τοῦ Διός εἰσιν Ὧραι καὶ Μοῖραι· δῆλα δὲ πᾶσι τὴν πεπρωμένην μόνῳ οἱ πείθεσθαι καὶ τὰς ὥρας τὸν θεὸν τοῦτον νέμειν ἐς τὸ δέον. ὄπισθε δὲ τοῦ ναοῦ κεῖται ξύλα ἡμίεργα· ταῦτα ἔμελλεν ὁ Θεόκοσμος ἐλέφαντι καὶ χρυσῷ κοσμήσας τὸ ἄγαλμα ἐκτελέσειν τοῦ Διός.", "st": "1.40"}, {"sp": "N", "t": "ἐν δὲ αὐτῷ τῷ ναῷ τριήρους ἀνάκειται χαλκοῦν ἔμβολον· ταύτην τὴν ναῦν λαβεῖν φασι περὶ Σαλαμῖνα ναυμαχήσαντες πρὸς Ἀθηναίους· ὁμολογοῦσι δὲ καὶ Ἀθηναῖοι χρόνον τινὰ Μεγαρεῦσιν ἀποστῆναι τῆς νήσου, Σόλωνα δὲ ὕστερόν φασιν ἐλεγεῖα ποιήσαντα προτρέψαι σφᾶς, καταστῆναι δὲ ἐπὶ τούτοις ⟨ἐς⟩ ἀμφισβήτησιν Ἀθηναῖοι, κρατήσαντες δὲ πολέμῳ Σαλαμῖνα αὖθις ἔχειν. Μεγαρεῖς δὲ παρὰ σφῶν λέγουσιν ἄνδρας φυγάδας, οὓς Δορυκλείους ὀνομάζουσιν, ἀφικομένους παρὰ τοὺς ἐν Σαλαμῖνι κληρούχους προδοῦναι Σαλαμῖνα Ἀθηναίοις.", "st": "1.40"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Διὸς τὸ τέμενος ἐς τὴν ἀκρόπολιν ἀνελθοῦσι καλουμένην ἀπὸ Καρὸς τοῦ Φορωνέως καὶ ἐς ἡμᾶς ἔτι Καρίαν, ἔστι μὲν Διονύσου ναὸς Νυκτελίου, πεποίηται δὲ Ἀφροδίτης Ἐπιστροφίας ἱερὸν καὶ Νυκτὸς καλούμενόν ἐστι μαντεῖον καὶ Διὸς Κονίου ναὸς οὐκ ἔχων ὄροφον. τοῦ δὲ Ἀσκληπιοῦ τὸ ἄγαλμα Βρύαξις καὶ αὐτὸ καὶ τὴν Ὑγείαν ἐποίησεν. ἐνταῦθα καὶ τῆς Δήμητρος τὸ καλούμενον μέγαρον· ποιῆσαι δὲ αὐτὸ βασιλεύοντα Κᾶρα ἔλεγον.", "st": "1.40"}, {"sp": "N", "t": "ἐκ δὲ τῆς ἀκροπόλεως κατιοῦσιν, ᾗ πρὸς ἄρκτον τέτραπται τὸ χωρίον, μνῆμά ἐστιν Ἀλκμήνης πλησίον τοῦ Ὀλυμπιείου. βαδίζουσαν γὰρ ἐς Θήβας ἐξ Ἄργους τελευτῆσαι καθ’ ὁδὸν λέγουσιν αὐτὴν ἐν τοῖς Μεγάροις, καὶ τοὺς Ἡρακλείδας ἐς ἀμφισβήτησιν ἐλθεῖν, τοὺς μὲν ἐς Ἄργος ἐθέλοντας ὀπίσω κομίσαι τὸν νεκρὸν τῆς Ἀλκμήνης, τοὺς δ’ αὐτῶν ἐς Θήβας· καὶ γὰρ τοῖς Ἡρακλέους παισὶ τοῖς ἐκ Μεγάρας τάφον εἶναι καὶ Ἀμφιτρύωνος ἐν Θήβαις. ὁ δὲ ἐν Δελφοῖς θεὸς ἔχρησε θάψαι Ἀλκμήνην ἐν τοῖς Μεγάροις ἄμεινον εἶναί σφισιν.", "st": "1.41"}, {"sp": "N", "t": "ἐντεῦθεν ὁ τῶν ἐπιχωρίων ἡμῖν ἐξηγητὴς ἡγεῖτο ἐς χωρίον Ῥοῦν ὡς ἔφασκεν ὀνομαζόμενον, ταύτῃ γὰρ ὕδωρ ποτὲ ἐκ τῶν ὀρῶν τῶν ὑπὲρ τὴν πόλιν ῥυῆναι· Θεαγένης δέ, ὃς τότε ἐτυράννει, τὸ ὕδωρ ἑτέρωσε τρέψας βωμὸν ἐνταῦθα Ἀχελῴῳ ἐποίησε. καὶ Ὕλλου πλησίον τοῦ Ἡρακλέους μνῆμά ἐστιν ἀνδρὶ Ἀρκάδι Ἐχέμῳ τῷ Ἀερόπου μονομαχήσαντος· καὶ ὅστις μὲν Ἔχεμος ὢν ἀπέκτεινεν Ὕλλον, ἑτέρωθι τοῦ λόγου δηλώσω, τέθαπται δὲ καὶ Ὕλλος ἐν τοῖς Μεγάροις. αὕτη καλοῖτο ἂν ὀρθῶς στρατεία τῶν Ἡρακλειδῶν ἐς Πελοπόννησον ἐπὶ Ὀρέστου βασιλεύοντος.", "st": "1.41"}, {"sp": "N", "t": "οὐ πόρρω δὲ τοῦ Ὕλλου μνήματος Ἴσιδος ναὸς καὶ παρ’ αὐτὸν Ἀπόλλωνός ἐστι καὶ Ἀρτέμιδος· Ἀλκάθουν δέ φασι ποιῆσαι ἀποκτείναντα λέοντα τὸν καλούμενον Κιθαιρώνιον. ὑπὸ τούτου τοῦ λέοντος διαφθαρῆναι καὶ ἄλλους καὶ Μεγαρέως φασὶ τοῦ σφετέρου βασιλέως παῖδα Εὔιππον, τὸν δὲ πρεσβύτερον τῶν παίδων αὐτῷ Τίμαλκον ἔτι πρότερον ἀποθανεῖν ὑπὸ Θησέως, στρατεύοντα ἐς Ἄφιδναν σὺν τοῖς Διοσκούροις· Μεγαρέα δὲ γάμον τε ὑποσχέσθαι θυγατρὸς καὶ ὡς διάδοχον ἕξει τῆς ἀρχῆς, ὅστις τὸν Κιθαιρώνιον λέοντα ἀποκτείναι· διὰ ταῦτα Ἀλκάθουν τὸν Πέλοπος ἐπιχειρήσαντα τῷ θηρίῳ κρατῆσαί τε καὶ ὡς ἐβασίλευσε τὸ ἱερὸν ποιῆσαι τοῦτο, Ἀγροτέραν Ἄρτεμιν καὶ Ἀπόλλωνα Ἀγραῖον ἐπονομάσαντα.", "st": "1.41"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω γενέσθαι λέγουσιν· ἐγὼ δὲ γράφειν μὲν ἐθέλω Μεγαρεῦσιν ὁμολογοῦντα, οὐκ ἔχω δὲ ὅπως εὕρωμαι πάντα σφίσιν, ἀλλὰ ἀποθανεῖν μὲν λέοντα ἐν τῷ Κιθαιρῶνι ὑπὸ Ἀλκάθου πείθομαι, Μεγαρέως δὲ Τίμαλκον παῖδα τίς μὲν ἐς Ἄφιδναν ἐλθεῖν μετὰ τῶν Διοσκούρων ἔγραψε; πῶς δ’ ἂν ἀφικόμενος ἀναιρεθῆναι νομίζοιτο ὑπὸ Θησέως, ὅπου καὶ Ἀλκμὰν ποιήσας ᾆσμα ἐς τοὺς Διοσκούρους, ὡς Ἀθήνας ἕλοιεν καὶ τὴν Θησέως ἀγάγοιεν μητέρα αἰχμάλωτον, ὅμως Θησέα φησὶν αὐτὸν ἀπεῖναι;", "st": "1.41"}, {"sp": "N", "t": "Πίνδαρος δὲ τούτοις τε κατὰ ταὐτὰ ἐποίησε καὶ γαμβρὸν τοῖς Διοσκούροις Θησέα εἶναι βουλόμενον ⟨ἁρπασθεῖσαν τὴν Ἑλένην διαφυλάξαι⟩, ἐς ὃ ἀπελθεῖν αὐτὸν Πειρίθῳ τὸν λεγόμενον γάμον συμπράξοντα. ὅστις δὲ ἐγενεαλόγησε, δῆλον ὡς πολλὴν τοῖς Μεγαρεῦσι σύνοιδεν εὐήθειαν, εἴ γε Θησεὺς ἦν ἀπόγονος Πέλοπος· ἀλλὰ γὰρ τὸν ὄντα λόγον οἱ Μεγαρεῖς εἰδότες ἐπικρύπτουσιν, οὐ βουλόμενοι δοκεῖν ἁλῶναί σφισιν ἐπὶ τῆς ἀρχῆς τῆς Νίσου τὴν πόλιν, διαδέξασθαι δὲ τὴν βασιλείαν γαμβρὸν Νίσου τε Μεγαρέα καὶ αὖθις Ἀλκάθουν Μεγαρέως.", "st": "1.41"}, {"sp": "N", "t": "φαίνεται δὲ τελευτήσαντος Νίσου καὶ τῶν πραγμάτων Μεγαρεῦσιν ἐφθαρμένων ὑπὸ τοῦτον Ἀλκάθους ἀφικόμενος τὸν καιρὸν ἐξ Ἤλιδος· μαρτύριον δέ μοι· τὸ γὰρ τεῖχος ᾠκοδόμησεν ἐξ ἀρχῆς ἅτε τοῦ περιβόλου τοῦ ἀρχαίου καθαιρεθέντος ὑπὸ τῶν Κρητῶν. Ἀλκάθου μὲν καὶ τοῦ λέοντος, εἴτε ἐν τῷ Κιθαιρῶνι αὐτὸν εἴτε καὶ ἑτέρωθι ἀποκτείνας ναὸν Ἀγροτέρας Ἀρτέμιδος καὶ Ἀπόλλωνος ἐποίησεν Ἀγραίου, ἐς τοσόνδε ἔστω μνήμη· ἐκ τούτου δὲ τοῦ ἱεροῦ κατιοῦσι Πανδίονός ἐστιν ἡρῷον. καὶ ὅτι μὲν ἐτάφη Πανδίων ἐν Αἰθυίας Ἀθηνᾶς καλουμένῳ σκοπέλῳ, δεδήλωκεν ὁ λόγος ἤδη μοι· τιμὰς δὲ καὶ ἐν τῇ πόλει παρὰ Μεγαρέων ἔχει.", "st": "1.41"}, {"sp": "N", "t": "πλησίον δέ ἐστι τοῦ Πανδίονος ἡρῴου μνῆμα Ἱππολύτης· γράψω δὲ καὶ τὰ ἐς αὐτὴν ὁποῖα Μεγαρεῖς λέγουσιν. ὅτε Ἀμαζόνες ἐπ’ Ἀθηναίους στρατεύσασαι δι’ Ἀντιόπην ἐκρατήθησαν ὑπὸ Θησέως, τὰς μὲν πολλὰς συνέβη μαχομένας αὐτῶν ἀποθανεῖν, Ἱππολύτην δὲ ἀδελφὴν οὖσαν Ἀντιόπης καὶ τότε ἡγουμένην τῶν γυναικῶν ἀποφυγεῖν σὺν ὀλίγαις ἐς Μέγαρα, ἅτε δὲ κακῶς οὕτω πράξασαν τῷ στρατῷ τοῖς τε παροῦσιν ἀθύμως ἔχουσαν καὶ περὶ τῆς οἴκαδε ἐς τὴν Θεμίσκυραν σωτηρίας μᾶλλον ἔτι ἀποροῦσαν ὑπὸ λύπης τελευτῆσαι· καὶ θάψαι αὐτὴν ἀποθανοῦσαν, καί οἱ τοῦ μνήματος σχῆμά ἐστιν Ἀμαζονικῇ ἀσπίδι ἐμφερές.", "st": "1.41"}, {"sp": "N", "t": "τούτου δέ ἐστιν οὐ πόρρω τάφος Τηρέως τοῦ Πρόκνην γήμαντος τὴν Πανδίονος. ἐβασίλευσε δὲ ὁ Τηρεύς, ὡς μὲν λέγουσιν οἱ Μεγαρεῖς, περὶ τὰς Παγὰς τὰς καλουμένας τῆς Μεγαρίδος, ὡς δὲ ἐγώ τε δοκῶ καὶ τεκμήρια ἐς τόδε λείπεται, Δαυλίδος ἦρχε τῆς ὑπὲρ Χαιρωνείας· πάλαι γὰρ τῆς νῦν καλουμένης Ἑλλάδος βάρβαροι τὰ πολλὰ ᾤκησαν. ἐπεὶ δὲ ἦν καὶ Τηρεῖ τὰ ἐς Φιλομήλαν ἐξειργασμένα καὶ ⟨τὰ⟩ περὶ τὸν Ἴτυν ὑπὸ τῶν γυναικῶν, ἑλεῖν σφᾶς ὁ Τηρεὺς οὐκ ἐδύνατο·", "st": "1.41"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐτελεύτησεν ἐν τοῖς Μεγάροις αὐτοχειρίᾳ, καί οἱ τάφον αὐτίκα ἔχωσαν καὶ θύουσιν ἀνὰ πᾶν ἔτος ψηφῖσιν ἐν τῇ θυσίᾳ ἀντὶ οὐλῶν χρώμενοι καὶ τὸν ἔποπα τὸν ὄρνιθα ἐνταῦθα φανῆναι πρῶτον λέγουσιν· αἱ δὲ γυναῖκες ἐς μὲν Ἀθήνας ἀφίκοντο, θρηνοῦσαι δὲ οἷα ἔπαθον καὶ οἷα ἀντέδρασαν ὑπὸ δακρύων διαφθείρονται, καί σφισι τὴν ἐς ἀηδόνα καὶ χελιδόνα μεταβολὴν ἐπεφήμισαν ὅτι οἶμαι καὶ αὗται αἱ ὄρνιθες ἐλεεινὸν καὶ θρήνῳ ὅμοιον ᾄδουσιν.", "st": "1.41"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλη Μεγαρεῦσιν ἀκρόπολις ἀπὸ Ἀλκάθου τὸ ὄνομα ἔχουσα· ἐς ταύτην τὴν ἀκρόπολιν ἀνιοῦσίν ἐστιν ἐν δεξιᾷ Μεγαρέως μνῆμα, ὃς κατὰ τὴν ἐπιστρατείαν τῶν Κρητῶν ξύμμαχός σφισιν ἦλθεν ἐξ Ὀγχηστοῦ. δείκνυται δὲ καὶ ἑστία θεῶν Προδομέων καλουμένων· θῦσαι δέ σφισιν Ἀλκάθουν λέγουσι πρῶτον, ὅτε τῆς οἰκοδομίας τοῦ τείχους ἔμελλεν ἄρχεσθαι.", "st": "1.42"}, {"sp": "N", "t": "τῆς δὲ ἑστίας ἐγγὺς ταύτης ἐστὶ λίθος, ἐφ’ οὗ καταθεῖναι λέγουσιν Ἀπόλλωνα τὴν κιθάραν Ἀλκάθῳ τὸ τεῖχος συνεργαζόμενον. δηλοῖ τέ μοι καὶ τόδε ὡς συνετέλουν ἐς Ἀθηναίους Μεγαρεῖς· φαίνεται γὰρ τὴν θυγατέρα Ἀλκάθους Περίβοιαν ἅμα Θησεῖ πέμψαι κατὰ τὸν δασμὸν ἐς Κρήτην. τότε δὲ αὐτῷ τειχίζοντι, ὥς φασιν οἱ Μεγαρεῖς, συνεργάζεταί τε Ἀπόλλων καὶ τὴν κιθάραν κατέθηκεν ἐπὶ τὸν λίθον· ἢν δὲ τύχῃ βαλών τις ψηφῖδι, κατὰ ταὐτὰ οὗτός τε ἤχησε καὶ κιθάρα κρουσθεῖσα.", "st": "1.42"}, {"sp": "N", "t": "ἐμοὶ δὲ παρέσχε μὲν καὶ τοῦτο θαυμάσαι, παρέσχε δὲ πολλῷ μάλιστα Αἰγυπτίων ὁ κολοσσός. ἐν Θήβαις ταῖς Αἰγυπτίαις, διαβᾶσι τὸν Νεῖλον πρὸς τὰς Σύριγγας καλουμένας, εἶδον ἔτι καθήμενον ἄγαλμα ἠχοῦν—Μέμνονα ὀνομάζουσιν οἱ πολλοί, τοῦτον γάρ φασιν ἐξ Αἰθιοπίας ὁρμηθῆναι ἐς Αἴγυπτον καὶ τὴν ἄχρι Σούσων· ἀλλὰ γὰρ οὐ Μέμνονα οἱ Θηβαῖοι λέγουσι, Φαμένωφα δὲ εἶναι τῶν ἐγχωρίων οὗ τοῦτο ἄγαλμα ἦν, ἤκουσα δὲ ἤδη καὶ Σέσωστριν φαμένων εἶναι [τοῦτο ἄγαλμα]—, ὃ Καμβύσης διέκοψε· καὶ νῦν ὁπόσον ἐκ κεφαλῆς ἐς μέσον σῶμά ἐστιν ἀπερριμμένον, τὸ δὲ λοιπὸν κάθηταί τε καὶ ἀνὰ πᾶσαν ἡμέραν ἀνίσχοντος ἡλίου βοᾷ, καὶ τὸν ἦχον μάλιστα εἰκάσει τις κιθάρας ἢ λύρας ῥαγείσης χορδῆς.", "st": "1.42"}, {"sp": "N", "t": "Μεγαρεῦσι δὲ ἔστι μὲν βουλευτήριον, Τιμάλκου δὲ ἦν ποτε ὡς λέγουσι τάφος, ὃν πρότερον ὀλίγον τούτων οὐκ ἔφην ὑπὸ Θησέως ἀποθανεῖν. ᾠκοδόμηται δὲ ἐπὶ τῇ κορυφῇ τῆς ἀκροπόλεως ναὸς Ραθηνᾶς, ἄγαλμα δέ ἐστιν ἐπίχρυσον πλὴν χειρῶν καὶ ἄκρων ποδῶν· ταῦτα δὲ καὶ τὸ πρόσωπόν ἐστιν ἐλέφαντος. καὶ ἕτερον ἐνταῦθα ἱερὸν Ἀθηνᾶς πεποίηται καλουμένης Νίκης καὶ ἄλλο Αἰαντίδος· τὰ δὲ ἐς αὐτὸ Μεγαρέων μὲν παρεῖται τοῖς ἐξηγηταῖς, ἐγὼ δὲ ὁποῖα νομίζω γενέσθαι γράψω. Τελαμὼν ὁ Αἰακοῦ θυγατρὶ Ἀλκάθου Περιβοίᾳ συνῴκησεν· Αἴαντα οὖν τὴν ἀρχὴν τὴν Ἀλκάθου διαδεξάμενον ποιῆσαι τὸ ἄγαλμα ἡγοῦμαι τῆς Ἀθηνᾶς.", "st": "1.42"}, {"sp": "N", "t": "τοῦ δὲ Ἀπόλλωνος πλίνθου μὲν ἦν ὁ ἀρχαῖος ναός· ὕστερον δὲ βασιλεὺς ᾠκοδόμησεν Ἀδριανὸς λίθου λευκοῦ. ὁ μὲν δὴ Πύθιος καλούμενος καὶ ὁ Δεκατηφόρος τοῖς Αἰγυπτίοις μάλιστα ἐοίκασι ξοάνοις, ὃν δὲ Ἀρχηγέτην ἐπονομάζουσιν, Αἰγινητικοῖς ἔργοις ἐστὶν ὅμοιος· ἐβένου δὲ πάντα ὁμοίως πεποίηται. ἤκουσα δὲ ἀνδρὸς Κυπρίου διακρῖναι πόας ἐς ἀνθρώπων ἴασιν εἰδότος, ὃς τὴν ἔβενον φύλλα οὐκ ἔφη φύειν οὐδὲ εἶναι καρπὸν οὐδένα ἀπ’ αὐτῆς οὐδὲ ὁρᾶσθαι τὸ παράπαν αὐτὴν ὑπὸ ἡλίου, ῥίζας δὲ ὑπογαίους εἶναι, ταύτας δὲ ὀρύσσειν τοὺς Αἰθίοπας καὶ ἄνδρας εἶναί σφισιν οἳ τὴν ἔβενον ἴσασιν εὑρίσκειν.", "st": "1.42"}, {"sp": "N", "t": "ἔστι δὲ καὶ Δήμητρος ἱερὸν Θεσμοφόρου. κατιοῦσι δὲ ἐντεῦθεν Καλλιπόλιδος μνῆμά ἐστιν Ἀλκάθου παιδός. ἐγένετο δὲ καὶ ἄλλος Ἀλκάθῳ πρεσβύτερος υἱὸς Ἰσχέπολις, ὃν ἀπέστειλεν ὁ πατὴρ Μελεάγρῳ τὸ ἐν Αἰτωλίᾳ θηρίον συνεξαιρήσοντα. ἀποθανόντος δὲ ἐνταῦθα πρῶτος τεθνεῶτα ἐπύθετο ὁ Καλλίπολις, ἀναδραμὼν δὲ ἐς τὴν ἀκρόπολιν— τηνικαῦτα δὲ ὁ πατήρ οἱ τῷ Ἀπόλλωνι ἐνέκαεν— ἀπορρίπτει τὰ ξύλα ἀπὸ τοῦ βωμοῦ· Ἀλκάθους δὲ ἀνήκοος ὢν ἔτι τῆς Ἰσχεπόλιδος τελευτῆς κατεδίκαζεν οὐ ποιεῖν ὅσια τὸν Καλλίπολιν καὶ εὐθέως ὡς εἶχεν ὀργῆς ἀπέκτεινε παίσας ἐς τὴν κεφαλὴν τῶν ἀπορριφέντων ἀπὸ τοῦ βωμοῦ ξύλῳ.", "st": "1.42"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς τὸ πρυτανεῖον ὁδὸν Ἰνοῦς ἐστιν ἡρῷον, περὶ δὲ αὐτὸ θριγκὸς λίθων· πεφύκασι δὲ ἐπ’ αὐτῷ καὶ ἐλαῖαι. μόνοι δέ εἰσιν Ἑλλήνων Μεγαρεῖς οἱ λέγοντες τὸν νεκρὸν τῆς Ἰνοῦς ἐς τὰ παραθαλάσσιά σφισιν ἐκπεσεῖν τῆς χώρας, Κλησὼ δὲ καὶ Ταυρόπολιν εὑρεῖν τε καὶ θάψαι—θυγατέρας δὲ αὐτὰς εἶναι Κλήσωνος τοῦ Λέλεγος—, καὶ Λευκοθέαν τε ὀνομασθῆναι παρὰ σφίσι πρώτοις φασὶν αὐτὴν καὶ θυσίαν ἄγειν ἀνὰ πᾶν ἔτος.", "st": "1.42"}, {"sp": "N", "t": "λέγουσι δὲ εἶναι καὶ Ἰφιγενείας ἡρῷον· ἀποθανεῖν γὰρ καὶ ταύτην ἐν Μεγάροις. ἐγὼ δὲ ἤκουσα μὲν καὶ ἄλλον ἐς Ἰφιγένειαν λόγον ὑπὸ Ἀρκάδων λεγόμενον, οἶδα δὲ Ἡσίοδον ποιήσαντα ἐν καταλόγῳ γυναικῶν Ἰφιγένειαν οὐκ ἀποθανεῖν, γνώμῃ δὲ Ἀρτέμιδος Ἑκάτην εἶναι· τούτοις δὲ Ἡρόδοτος ὁμολογοῦντα ἔγραψε Ταύρους τοὺς πρὸς τῇ Σκυθικῇ θύειν παρθένῳ τοὺς ναυαγούς, φάναι δὲ αὐτοὺς τὴν παρθένον Ἰφιγένειαν εἶναι τὴν Ἀγαμέμνονος. ἔχει δὲ παρὰ Μεγαρεῦσι καὶ Ἄδραστος τιμάς· φασὶ δὲ ἀποθανεῖν παρὰ σφίσι καὶ τοῦτον, ὅτε ἑλὼν Θήβας ἀπῆγεν ὀπίσω τὸν στρατόν, αἴτια δέ οἱ τοῦ θανάτου γῆρας καὶ τὴν Αἰγιαλέως γενέσθαι τελευτήν. καὶ Ἀρτέμιδος ἱερὸν ὁ Ἀγαμέμνων ἐποίησεν, ἡνίκα ἦλθε Κάλχαντα οἰκοῦντα ἐν Μεγάροις ἐς Ἴλιον ἕπεσθαι πείσων.", "st": "1.43"}, {"sp": "N", "t": "ἐν δὲ τῷ πρυτανείῳ τεθάφθαι μὲν Εὔιππον Μεγαρέως παῖδα, τεθάφθαι δὲ τὸν Ἀλκάθου λέγουσιν Ἰσχέπολιν. ἔστι δὲ τοῦ πρυτανείου πέτρα πλησίον· Ἀνακληθρίδα τὴν πέτραν ὀνομάζουσιν, ὡς Δημήτηρ, εἴ τῳ πιστά, ὅτε τὴν παῖδα ἐπλανᾶτο ζητοῦσα, καὶ ἐνταῦθα ἀνεκάλεσεν αὐτήν. ἐοικότα δὲ τῷ λόγῳ δρῶσιν ἐς ἡμᾶς ἔτι αἱ Μεγαρέων γυναῖκες.", "st": "1.43"}, {"sp": "N", "t": "εἰσὶ δὲ τάφοι Μεγαρεῦσιν ἐν τῇ πόλει· καὶ τὸν μὲν τοῖς ἀποθανοῦσιν ἐποίησαν κατὰ τὴν ἐπιστρατείαν τοῦ Μήδου, τὸ δὲ Αἰσύμνιον καλούμενον μνῆμα ἦν καὶ τοῦτο ἡρώων. Ὑπερίονος δὲ τοῦ Ἀγαμέμνονος— οὗτος γὰρ Μεγαρέων ἐβασίλευσεν ὕστατος—τούτου τοῦ ἀνδρὸς ἀποθανόντος ὑπὸ Σανδίονος διὰ πλεονεξίαν καὶ ὕβριν, βασιλεύεσθαι μὲν οὐκέτι ὑπὸ ἑνὸς ἐδόκει σφίσιν, εἶναι δὲ ἄρχοντας αἱρετοὺς καὶ ἀνὰ μέρος ἀκούειν ἀλλήλων. ἐνταῦθα Αἴσυμνος οὐδενὸς τὰ ἐς δόξαν Μεγαρέων δεύτερος παρὰ τὸν θεὸν ἦλθεν ἐς Δελφούς, ἐλθὼν δὲ ἠρώτα τρόπον τίνα εὐδαιμονήσουσι· καί οἱ καὶ ἄλλα ὁ θεὸς ἔχρησε καὶ Μεγαρέας εὖ πράξειν, ἢν μετὰ τῶν πλειόνων βουλεύσωνται. τοῦτο τὸ ἔπος ἐς τοὺς τεθνεῶτας ἔχειν νομίζοντες βουλευτήριον ἐνταῦθα ᾠκοδόμησαν, ἵνα σφίσιν ὁ τάφος τῶν ἡρώων ἐντὸς τοῦ βουλευτηρίου γένηται.", "st": "1.43"}, {"sp": "N", "t": "ἐντεῦθεν πρὸς τὸ Ἀλκάθου βαδίζουσιν ἡρῷον, ᾧ Μεγαρεῖς ἐς γραμμάτων φυλακὴν ἐχρῶντο ἐπ’ ἐμοῦ, μνῆμα ἔλεγον τὸ μὲν Πυργοῦς εἶναι γυναικὸς Ἀλκάθου πρὶν ἢ τὴν Μεγαρέως αὐτὸν λαβεῖν Εὐαίχμην, τὸ δὲ Ἰφινόης Ἀλκάθου θυγατρός· ἀποθανεῖν δὲ αὐτήν φασιν ἔτι παρθένον. καθέστηκε δὲ ταῖς κόραις χοὰς πρὸς τὸ τῆς Ἰφινόης μνῆμα προσφέρειν πρὸ γάμου καὶ ἀπάρχεσθαι τῶν τριχῶν, καθὰ καὶ τῇ Ἑκαέργῃ καὶ Ὤπιδι αἱ θυγατέρες ποτὲ ἀπεκείροντο αἱ Δηλίων.", "st": "1.43"}, {"sp": "N", "t": "παρὰ δὲ τὴν ἔσοδον τὴν ἐς τὸ Διονύσιον τάφος ἐστὶν Ἀστυκρατείας καὶ Μαντοῦς· θυγατέρες δὲ ἦσαν Πολυίδου τοῦ Κοιράνου τοῦ Ἄβαντος τοῦ Μελάμποδος ἐς Μέγαρα [δ’] ἐλθόντος Ἀλκάθουν ἐπὶ τῷ φόνῳ τῷ Καλλιπόλιδος καθῆραι τοῦ παιδός. ᾠκοδόμησε δὴ καὶ τῷ Διονύσῳ τὸ ἱερὸν Πολύιδος καὶ ξόανον ἀνέθηκεν ἀποκεκρυμμένον ἐφ’ ἡμῶν πλὴν τοῦ προσώπου· τοῦτο δέ ἐστι τὸ φανερόν. Σάτυρος δὲ παρέστηκεν αὐτῷ Πραξιτέλους ἔργον Παρίου λίθου. τοῦτον μὲν δὴ Πατρῷον καλοῦσιν· ἕτερον δὲ Διόνυσον Δασύλλιον ἐπονομάζοντες Εὐχήνορα τὸν Κοιράνου τοῦ Πολυίδου τὸ ἄγαλμα ἀναθεῖναι λέγουσι.", "st": "1.43"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Διονύσου τὸ ἱερόν ἐστιν Ἀφροδίτης ναός, ἄγαλμα δὲ ἐλέφαντος Ἀφροδίτη πεποιημένον Πρᾶξις ἐπίκλησιν. τοῦτό ἐστιν ἀρχαιότατον ἐν τῷ ναῷ· Πειθὼ δὲ καὶ ἑτέρα θεός, ἣν Παρήγορον ὀνομάζουσιν, ἔργα Πραξιτέλους· Σκόπα δὲ Ἔρως καὶ Ἵμερος καὶ Πόθος, εἰ δὴ διάφορά ἐστι κατὰ ταὐτὸ τοῖς ὀνόμασι καὶ τὰ ἔργα σφίσι. πλησίον δὲ τοῦ τῆς Ἀφροδίτης ναοῦ Τύχης ἐστὶν ἱερόν, Πραξιτέλους καὶ αὕτη τέχνη· καὶ ἐν τῷ ναῷ τῷ πλησίον Μούσας καὶ χαλκοῦν Δία ἐποίησε Λύσιππος.", "st": "1.43"}, {"sp": "N", "t": "ἔστι δὲ Μεγαρεῦσι καὶ Κοροίβου τάφος· τὰ δὲ ἐς αὐτὸν ἔπη κοινὰ ὅμως ὄντα τοῖς Ἀργείων ἐνταῦθα δηλώσω. ἐπὶ Κροτώπου λέγουσιν ἐν Ἄργει βασιλεύοντος Ψαμάθην τὴν Κροτώπου τεκεῖν παῖδα ἐξ Ἀπόλλωνος, ἐχομένην δὲ ἰσχυρῶς τοῦ πατρὸς δείματι τὸν παῖδα ἐκθεῖναι· καὶ τὸν μὲν διαφθείρουσιν ἐπιτυχόντες ἐκ τῆς ποίμνης κύνες τῆς Κροτώπου, Ἀπόλλων δὲ Ἀργείοις ἐς τὴν πόλιν πέμπει Ποινήν. ταύτην τοὺς παῖδας ἀπὸ τῶν μητέρων φασὶν ἁρπάζειν, ἐς ὃ Κόροιβος ἐς χάριν Ἀργείοις φονεύει τὴν Ποινήν. φονεύσας δὲ—οὐ γὰρ ἀνίει σφᾶς δεύτερα ἐπιπεσοῦσα νόσος λοιμώδης—Κόροιβος ἑκὼν ἦλθεν ἐς Δελφοὺς ὑφέξων δίκας τῷ θεῷ τοῦ φόνου τῆς Ποινῆς.", "st": "1.43"}, {"sp": "N", "t": "ἐς μὲν δὴ τὸ Ἄργος ἀναστρέφειν οὐκ εἴα Κόροιβον ἡ Πυθία, τρίποδα δὲ ἀράμενον φέρειν ἐκέλευεν ἐκ τοῦ ἱεροῦ, καὶ ἔνθα ἂν ἐκπέσῃ οἱ φέροντι ὁ τρίπους, ἐνταῦθα Ἀπόλλωνος οἰκοδομῆσαι ναὸν καὶ αὐτὸν οἰκῆσαι. καὶ ὁ τρίπους κατὰ τὸ ὄρος τὴν Γερανίαν ἀπολισθὼν ἔλαθεν αὐτοῦ ἐκπεσών· καὶ Τριποδίσκους κώμην ἐνταῦθα οἰκῆσαι. Κοροίβῳ δέ ἐστι τάφος ἐν τῇ Μεγαρέων ἀγορᾷ· γέγραπται δὲ ἐλεγεῖα τὰ ἐς Ψαμάθην καὶ τὰ ἐς αὐτὸν ἔχοντα Κόροιβον, καὶ δὴ καὶ ἐπίθημά ἐστι τῷ τάφῳ Κόροιβος φονεύων τὴν Ποινήν. ταῦτα ἀγάλματα παλαιότατα, ὁπόσα λίθου πεποιημένα ἐστὶν Ἕλλησιν, ἰδὼν οἶδα.", "st": "1.43"}, {"sp": "N", "t": "Κοροίβου δὲ τέθαπται πλησίον Ὄρσιππος, ὃς περιεζωσμένων ἐν τοῖς ἀγῶσι κατὰ δὴ παλαιὸν ἔθος τῶν ἀθλητῶν Ὀλύμπια ἐνίκα στάδιον δραμὼν γυμνός, φασὶ δὲ καὶ στρατηγοῦντα ὕστερον τὸν Ὄρσιππον ἀποτεμέσθαι χώραν τῶν προσοίκων· δοκῶ δέ οἱ καὶ ἐν Ὀλυμπίᾳ τὸ περίζωμα ἑκόντι περιρρυῆναι, γνόντι ὡς ἀνδρὸς περιεζωσμένου δραμεῖν ῥᾴων ἐστὶν ἀνὴρ γυμνὸς.", "st": "1.44"}, {"sp": "N", "t": "ἐκ δὲ τῆς ἀγορᾶς κατιοῦσι τῆς ὁδοῦ τῆς Εὐθείας καλουμένης Ἀπόλλωνος ἱερόν ἐστιν ἐν δεξιᾷ Προστατηρίου· τοῦτο ὀλίγον ἐκτραπέντα ἔστιν ἐκ τῆς ὁδοῦ ἀνευρεῖν. Ἀπόλλων δὲ ἐν αὐτῷ κεῖται θέας ἄξιος καὶ Ἄρτεμις καὶ Λητὼ καὶ ἄλλα ἀγάλματά ἐστι Πραξιτέλους ποιήσαντος [Λητὼ καὶ οἱ παῖδες]. ἔστι δὲ ἐν τῷ γυμνασίῳ τῷ ἀρχαίῳ πλησίον πυλῶν καλουμένων Νυμφάδων λίθος παρεχόμενος πυραμίδος σχῆμα οὐ μεγάλης· τοῦτον Ἀπόλλωνα ὀνομάζουσι Καρινόν, καὶ Εἰλειθυιῶν ἐστιν ἐνταῦθα ἱερόν. τοσαῦτά σφισιν ⟨ἐς⟩ ἐπίδειξιν παρείχετο ἡ πόλις·", "st": "1.44"}, {"sp": "N", "t": "ἐς δὲ τὸ ἐπίνειον, καλούμενον καὶ ἐς ἡμᾶς ἔτι Νίσαιαν, ἐς τοῦτο κατελθοῦσιν ἱερὸν Δήμητρός ἐστι Μαλοφόρου· λέγεται δὲ καὶ ἄλλα ἐς τὴν ἐπίκλησιν καὶ τοὺς πρώτους πρόβατα ἐν τῇ γῇ θρέψαντας Δήμητρα ὀνομάσαι Μαλοφόρον, καταρρυῆναι δὲ τῷ ἱερῷ τὸν ὄροφον τεκμαίροιτο ἄν τις ὑπὸ τοῦ χρόνου. καὶ ἀκρόπολίς ἐστιν ἐνταῦθα ὀνομαζομένη καὶ αὐτὴ Νίσαια· καταβᾶσι δὲ ἐκ τῆς ἀκροπόλεως μνῆμά ἐστι πρὸς θαλάσσῃ Λέλεγος, ὃν ἀφικόμενον βασιλεῦσαι λέγουσιν ἐξ Αἰγύπτου, παῖδα δὲ εἶναι Ποσειδῶνος καὶ Λιβύης τῆς Ἐπάφου. παρήκει δὲ παρὰ τὴν Νίσαιαν νῆσος οὐ μεγάλη Μινώα· ἐνταῦθα ἐν τῷ πολέμῳ τῷ πρὸς Νῖσον παρώρμει τὸ ναυτικὸν τῶν Κρητῶν.", "st": "1.44"}, {"sp": "N", "t": "ἡ δὲ ὀρεινὴ τῆς Μεγαρίδος τῆς Βοιωτῶν ἐστιν ὅμορος, ἐν ᾗ Μεγαρεῦσι Παγαὶ πόλις, ἑτέρα δὲ Αἰγόσθενα ᾤκισται. ἰοῦσι δὲ ἐς τὰς Παγὰς ἐκτραπομένοις ὀλίγον τῆς λεωφόρου πέτρα δείκνυται διὰ πάσης ἔχουσα ἐμπεπηγότας ὀιστούς, ἐς ἣν οἱ Μῆδοί ποτε ἐτόξευον ἐν τῇ νυκτί. ἐν δὲ ταῖς Παγαῖς θέας ὑπελείπετο ἄξιον Ἀρτέμιδος Σωτείρας ἐπίκλησιν χαλκοῦν ἄγαλμα, μεγέθει τῷ παρὰ Μεγαρεῦσιν ἴσον καὶ σχῆμα οὐδὲν διαφόρως ἔχον. καὶ Αἰγιαλέως ἐνταῦθά ἐστιν ἡρῷον τοῦ Ἀδράστου· τοῦτον γάρ, ὅτε Ἀργεῖοι τὸ δεύτερον ἐς Θήβας ἐστράτευσαν, ὑπὸ τὴν πρώτην μάχην πρὸς Γλισᾶντι ἀποθανόντα οἱ προσήκοντες ἐς Παγὰς τῆς Μεγαρίδος κομίσαντες θάπτουσι, καὶ Αἰγιάλειον ἔτι καλεῖται τὸ ἡρῷον.", "st": "1.44"}, {"sp": "N", "t": "ἐν Αἰγοσθένοις δὲ Μελάμποδος τοῦ Ἀμυθάονός ἐστιν ἱερὸν καὶ ἀνὴρ οὐ μέγας ἐπειργασμένος ἐν στήλῃ· καὶ θύουσι τῷ Μελάμποδι καὶ ἀνὰ πᾶν ἔτος ἑορτὴν ἄγουσι. μαντεύεσθαι δὲ οὔτε δι’ ὀνειράτων αὐτὸν οὔτε ἄλλως λέγουσι. καὶ τόδε ἄλλο ἤκουσα ἐν Ἐρενείᾳ τῇ Μεγαρέων κώμῃ, Αὐτονόην τὴν Κάδμου τῷ τε Ἀκταίωνος θανάτῳ, συμβάντι ὡς λέγεται, καὶ τῇ πάσῃ τοῦ οἴκου τοῦ πατρῴου τύχῃ περισσότερον ἀλγοῦσαν ἐνταῦθα ἐκ Θηβῶν μετοικῆσαι· καὶ Αὐτονόης μνῆμά ἐστιν ἐν τῇ κώμῃ ταύτῃ.", "st": "1.44"}, {"sp": "N", "t": "ἰοῦσι δὲ ἐκ Μεγάρων ἐς Κόρινθον ἄλλοι τέ εἰσι τάφοι καὶ αὐλητοῦ Σαμίου Τηλεφάνους· ποιῆσαι δὲ τὸν τάφον Κλεοπάτραν τὴν Φιλίππου τοῦ Ἀμύντου λέγουσι. καὶ Καρὸς τοῦ Φορωνέως μνῆμά ἐστι, τὸ μὲν ἐξ ἀρχῆς χῶμα γῆς, ὕστερον δὲ τοῦ θεοῦ χρήσαντος ἐκοσμήθη λίθῳ κογχίτῃ. μόνοις δὲ Ἑλλήνων Μεγαρεῦσιν ὁ κογχίτης οὗτός ἐστι, καί σφισι καὶ ἐν τῇ πόλει πεποίηται πολλὰ ἐξ αὐτοῦ. ἔστι δὲ ἄγαν λευκὸς καὶ ἄλλου λίθου μαλακώτερος· κόγχοι δὲ αἱ θαλάσσιαι διὰ παντὸς ἔνεισίν οἱ. αὐτὸς μὲν τοιοῦτός ἐστιν ὁ λίθος· τὴν δὲ ὀνομαζομένην ἀπὸ Σκίρωνος καὶ ἐς τόδε Σκιρωνίδα ⟨Σκίρων⟩, ἡνίκα Μεγαρεῦσιν ἐπολεμάρχει, πρῶτος ὡς λέγουσιν ἐποίησεν ἀνδράσιν ὁδεύειν εὐζώνοις· Ἀδριανὸς δὲ ὁ βασιλεὺς καὶ οὕτως ὡς καὶ ἅρματα ἐναντία ἐλαύνεσθαι κατέστησεν εὐρυχωρῆ τε καὶ ἐπιτηδείαν εἶναι.", "st": "1.44"}, {"sp": "N", "t": "λόγοι δέ εἰσιν ἐς τὰς πέτρας, αἳ κατὰ τὸ στενὸν τῆς ὁδοῦ μάλιστα ἀνέχουσιν, ἐς μὲν τὴν Μολουρίδα, ὡς ἀπὸ ταύτης αὑτὴν ἐς θάλασσαν Ἰνὼ ῥίψαι Μελικέρτην ἔχουσα τῶν παίδων ⟨τὸν⟩ νεώτερον· τὸν γὰρ δὴ πρεσβύτερον αὐτῶν Λέαρχον ἀπέκτεινεν ὁ πατήρ. λέγεται μὲν δὴ καὶ μανέντα δρᾶσαι ταῦτα Ἀθάμαντα, λέγεται δὲ καὶ ὡς ἐς τὴν Ἰνὼ καὶ τοὺς ἐξ αὐτῆς παῖδας χρήσαιτο ἀκρατεῖ τῷ θυμῷ τὸν συμβάντα Ὀρχομενίοις λιμὸν καὶ τὸν δοκοῦντα Φρίξου θάνατον αἰσθόμενος, οὗ τὸ θεῖον αἴτιον οὐ γενέσθαι, βουλεῦσαι δὲ ἐπὶ τούτοις πᾶσιν Ἰνὼ μητρυιὰν οὖσαν·", "st": "1.44"}, {"sp": "N", "t": "τότε δὲ φεύγουσα ἐς θάλασσαν αὑτὴν καὶ τὸν παῖδα ἀπὸ τῆς πέτρας τῆς Μολουρίδος ἀφίησιν, ἐξενεχθέντος δὲ ἐς τὸν Κορινθίων ἰσθμὸν ὑπὸ δελφῖνος ὡς λέγεται τοῦ παιδός, τιμαὶ καὶ ἄλλαι τῷ Μελικέρτῃ δίδονται μετονομασθέντι Παλαίμονι καὶ τῶν Ἰσθμίων ἐπ’ αὐτῷ τὸν ἀγῶνα ἄγουσι. τὴν μὲν δὴ Μολουρίδα πέτραν Λευκοθέας καὶ Παλαίμονος ἱερὰν ἥγηντο· τὰς δὲ μετὰ ταύτην νομίζουσιν ἐναγεῖς, ὅτι παροικῶν σφισιν ὁ Σκίρων, ὁπόσοις τῶν ξένων ἐπετύγχανεν, ἠφίει σφᾶς ἐς τὴν θάλασσαν. χελώνη δὲ ὑπενήχετο ταῖς πέτραις τοὺς ἐσβληθέντας ἁρπάζειν· εἰσὶ δὲ αἱ θαλάσσιαι πλὴν μεγέθους καὶ ποδῶν ὅμοιαι ταῖς χερσαίαις, πόδας δὲ ἐοικότας ἔχουσι ταῖς φώκαις. τούτων περιῆλθεν ἡ δίκη Σκίρωνα ἀφεθέντα ἐς θάλασσαν τὴν αὐτὴν ὑπὸ Θησέως.", "st": "1.44"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ ὄρους τῇ ἄκρᾳ Διός ἐστιν Ἀφεσίου καλουμένου ναός· φασὶ δὲ ἐπὶ τοῦ συμβάντος ποτὲ τοῖς Ἕλλησιν αὐχμοῦ θύσαντος Αἰακοῦ κατά τι δὴ λόγιον τῷ Πανελληνίῳ Διὶ ἐν Αἰγίνῃ †κομίσαντα δὲ ἀφεῖναι καὶ διὰ τοῦτο Ἀφέσιον καλεῖσθαι τὸν Δία. ἐνταῦθα καὶ Ἀφροδίτης ἄγαλμα καὶ Ἀπόλλωνός ἐστι καὶ Πανός.", "st": "1.44"}, {"sp": "N", "t": "προελθοῦσι δὲ ἐς τὸ πρόσω μνῆμά ἐστιν Εὐρυσθέως· φεύγοντα δὲ ἐκ τῆς Ἀττικῆς μετὰ τὴν πρὸς Ἡρακλείδας μάχην ἐνταῦθα ἀποθανεῖν αὐτὸν ὑπὸ Ἰολάου λέγουσιν. ἐκ ταύτης τῆς ὁδοῦ καταβᾶσιν Ἀπόλλωνος ἱερόν ἐστι Λατῴου καὶ μετ’ αὐτὸ Μεγαρεῦσιν ὅροι πρὸς τὴν Κορινθίαν, ἔνθα Ὕλλον τὸν Ἡρακλέους μονομαχῆσαι πρὸς τὸν Ἀρκάδα Ἔχεμον λέγουσιν.", "st": "1.44"}, {"sp": "HDR", "t": "Βιβλίον Βʹ — Κορινθιακά", "st": "2"}, {"sp": "N", "t": "ἡ δὲ Κορινθία χώρα μοῖρα οὖσα τῆς Ἀργείας ἀπὸ Κορίνθου τὸ ὄνομα ἔσχηκε. Διὸς δὲ εἶναι Κόρινθον οὐδένα οἶδα εἰπόντα πω σπουδῇ πλὴν Κορινθίων τῶν πολλῶν· Εὔμηλος δὲ ὁ Ἀμφιλύτου τῶν Βακχιδῶν καλουμένων, ὃς καὶ τὰ ἔπη λέγεται ποιῆσαι, φησὶν ἐν τῇ Κορινθίᾳ συγγραφῇ—εἰ δὲ Εὐμήλου γε ἡ συγγραφή—Ἐφύραν Ὠκεανοῦ θυγατέρα οἰκῆσαι πρῶτον ἐν τῇ γῇ ταύτῃ, Μαραθῶνα δὲ ὕστερον τὸν Ἐπωπέως τοῦ Ἀλωέως τοῦ Ἡλίου φεύγοντα ἀνομίαν καὶ ὕβριν τοῦ πατρὸς ἐς τὰ παραθαλάσσια μετοικῆσαι τῆς Ἀττικῆς, ἀποθανόντος δὲ Ἐπωπέως ἀφικόμενον ἐς Πελοπόννησον καὶ τὴν ἀρχὴν διανείμαντα τοῖς παισὶν αὐτὸν ἐς τὴν Ἀττικὴν αὖθις ἀναχωρῆσαι, καὶ ἀπὸ μὲν Σικυῶνος τὴν Ἀσωπίαν, ἀπὸ δὲ Κορίνθου τὴν Ἐφυραίαν μετονομασθῆναι.", "st": "2.1"}, {"sp": "N", "t": "Κόρινθον δὲ οἰκοῦσι Κορινθίων μὲν οὐδεὶς ἔτι τῶν ἀρχαίων, ἔποικοι δὲ ἀποσταλέντες ὑπὸ Ῥωμαίων. αἴτιον δὲ τὸ συνέδριον τὸ Ἀχαιῶν· συντελοῦντες γὰρ ἐς αὐτὸ καὶ οἱ Κορίνθιοι μετέσχον τοῦ πολέμου τοῦ πρὸς Ῥωμαίους, ὃν Κριτόλαος στρατηγεῖν Ἀχαιῶν ἀποδειχθεὶς παρεσκεύασε γενέσθαι τούς τε Ἀχαιοὺς ἀναπείσας ἀποστῆναι καὶ τῶν ἔξω Πελοποννήσου τοὺς πολλούς. Ῥωμαῖοι δὲ ὡς ἐκράτησαν τῷ πολέμῳ, παρείλοντο μὲν καὶ τῶν ἄλλων Ἑλλήνων τὰ ὅπλα καὶ τείχη περιεῖλον ὅσαι τετειχισμέναι πόλεις ἦσαν· Κόρινθον δὲ ἀνάστατον Μομμίου ποιήσαντος τοῦ τότε ἡγουμένου τῶν ἐπὶ στρατοπέδου Ῥωμαίων, ὕστερον λέγουσιν ἀνοικίσαι Καίσαρα, ὃς πολιτείαν ἐν Ῥώμῃ πρῶτος τὴν ἐφ’ ἡμῶν κατεστήσατο· ἀνοικίσαι δὲ καὶ Καρχηδόνα ἐπὶ τῆς ἀρχῆς τῆς αὐτοῦ.", "st": "2.1"}, {"sp": "N", "t": "τῆς δὲ Κορινθίας ἐστὶ γῆς καὶ ὁ καλούμενος Κρομυὼν ἀπὸ [τοῦ] Κρόμου τοῦ Ποσειδῶνος. ἐνταῦθα τραφῆναί φασι ⟨Φαιὰν⟩, καὶ τῶν λεγομένων Θησέως καὶ τὸ ἐς τὴν ⟨ὗν⟩ ταύτην ἐστὶν ἔργον. προϊοῦσι δὲ ἡ πίτυς ἄχρι γε ἐμοῦ πεφύκει παρὰ τὸν αἰγιαλὸν καὶ Μελικέρτου βωμὸς ἦν. ἐς τοῦτον τὸν τόπον ἐκκομισθῆναι τὸν παῖδα ὑπὸ δελφῖνος λέγουσι· κειμένῳ δὲ ἐπιτυχόντα Σίσυφον θάψαι τε ἐν τῷ ἰσθμῷ καὶ τὸν ἀγῶνα ἐπ’ αὐτῷ ποιῆσαι τῶν Ἰσθμίων.", "st": "2.1"}, {"sp": "N", "t": "ἔστι δὲ ἐπὶ τοῦ ἰσθμοῦ τῆς ἀρχῆς, ἔνθα ὁ λῃστὴς Σίνις λαμβανόμενος πιτύων ἦγεν ἐς τὸ κάτω σφᾶς· ὁπόσων δὲ μάχῃ κρατήσειεν, ἀπ’ αὐτῶν δήσας ἀφῆκεν ἂν τὰ δένδρα ἄνω φέρεσθαι· ἐνταῦθα ἑκατέρα τῶν πιτύων τὸν δεθέντα ἐφ’ αὑτὴν εἷλκε, καὶ τοῦ δεσμοῦ μηδετέρωσε εἴκοντος ἀλλ’ ἀμφοτέρωθεν ἐπ’ ἴσης βιαζομένου διεσπᾶτο ὁ δεδεμένος. τοιούτῳ διεφθάρη τρόπῳ καὶ αὐτὸς ὑπὸ Θησέως ὁ Σίνις· ἐκάθηρε γὰρ Θησεὺς τῶν κακούργων τὴν ὁδὸν τὴν ἐς Ἀθήνας ἐκ Τροιζῆνος, οὕς τε πρότερον κατηρίθμησα ἀνελὼν καὶ ἐν Ἐπιδαύρῳ τῇ ἱερᾷ Περιφήτην Ἡφαίστου νομιζόμενον, κορύνῃ χαλκῇ χρώμενον ἐς τὰς μάχας.", "st": "2.1"}, {"sp": "N", "t": "καθήκει δὲ ὁ τῶν Κορινθίων ἰσθμὸς τῇ μὲν ἐς τὴν ἐπὶ Κεγχρέαις, τῇ δὲ ἐς τὴν ἐπὶ Λεχαίῳ θάλασσαν· τοῦτο γὰρ ἤπειρον ποιεῖ τὴν ἐντὸς χώραν. ὃς δὲ ἐπεχείρησε Πελοπόννησον ἐργάσασθαι νῆσον, προαπέλιπε διορύσσων ἰσθμόν· καὶ ὅθεν μὲν διορύσσειν ἤρξαντο δῆλόν ἐστιν, ἐς δὲ τὸ πετρῶδες οὐ προεχώρησαν ἀρχήν· μένει δὲ ὡς πεφύκει καὶ νῦν ἤπειρος ὤν. Ἀλεξάνδρῳ τε τῷ Φιλίππου διασκάψαι Μίμαντα ἐθελήσαντι μόνον τοῦτο οὐ προεχώρησε ⟨τὸ⟩ ἔργον· Κνιδίους δὲ ἡ Πυθία τὸν ἰσθμὸν ὀρύσσοντας ἔπαυσεν. οὕτω χαλεπὸν ἀνθρώπῳ τὰ θεῖα βιάσασθαι.", "st": "2.1"}, {"sp": "N", "t": "τὸ δὲ οὐ Κορινθίοις μόνον περὶ τῆς χώρας ἐστὶν εἰρημένον, ἀλλὰ ἐμοὶ δοκεῖν Ἀθηναῖοι πρῶτοι περὶ τῆς Ἀττικῆς ἐσεμνολόγησαν· λέγουσι δὲ καὶ οἱ Κορίνθιοι Ποσειδῶνα ἐλθεῖν Ἡλίῳ περὶ τῆς γῆς ἐς ἀμφισβήτησιν, Βριάρεων δὲ διαλλακτὴν γενέσθαι σφίσιν, ἰσθμὸν μὲν καὶ ὅσα ταύτῃ δικάσαντα εἶναι Ποσειδῶνος, τὴν δὲ ἄκραν Ἡλίῳ δόντα τὴν ὑπὲρ τῆς πόλεως. ἀπὸ μὲν τούτου λέγουσιν εἶναι τὸν ἰσθμὸν Ποσειδῶνος·", "st": "2.1"}, {"sp": "N", "t": "θέας δὲ αὐτόθι ἄξια ἔστι μὲν θέατρον, ἔστι δὲ στάδιον λίθου λευκοῦ. ἐλθόντι δὲ ἐς τοῦ θεοῦ τὸ ἱερὸν τοῦτο μὲν ἀθλητῶν νικησάντων· τὰ Ἴσθμια ἑστήκασιν εἰκόνες, τοῦτο δὲ πιτύων δένδρα ἐστὶ πεφυτευμένα ἐπὶ στοίχου, τὰ πολλὰ ἐς εὐθὺ αὐτῶν ἀνήκοντα. τῷ ναῷ δὲ ὄντι μέγεθος οὐ μείζονι ἐφεστήκασι Τρίτωνες χαλκοῖ. καὶ ἀγάλματά ἐστιν ἐν τῷ προνάῳ δύο μὲν Ποσειδῶνος, τρίτον δὲ Ἀμφιτρίτης, καὶ Θάλασσα καὶ αὕτη χαλκῆ. τὰ δὲ ἔνδον ἐφ’ ἡμῶν ἀνέθηκεν Ἡρώδης Ἀθηναῖος, ἵππους τέσσαρας ἐπιχρύσους πλὴν τῶν ὁπλῶν· ὁπλαὶ δέ σφισίν εἰσιν ἐλέφαντος.", "st": "2.1"}, {"sp": "N", "t": "καὶ Τρίτωνες δύο παρὰ τοὺς ἵππους εἰσὶ χρυσοῖ, τὰ μετ’ ἰξὺν ἐλέφαντος καὶ οὗτοι· τῷ δὲ ἅρματι Ἀμφιτρίτη καὶ Ποσειδῶν ἐφεστήκασι, καὶ παῖς ὀρθός ἐστιν ἐπὶ δελφῖνος ὁ Παλαίμων· ἐλέφαντος δὲ καὶ χρυσοῦ καὶ οὗτοι πεποίηνται. τῷ βάθρῳ δὲ ἐφ’ οὗ τὸ ἅρμα μέση μὲν ἐπείργασται Θάλασσα ἀνέχουσα Ἀφροδίτην παῖδα, ἑκατέρωθεν δέ εἰσιν αἱ Νηρηίδες καλούμεναι. ταύταις καὶ ἑτέρωθι τῆς Ἑλλάδος βωμοὺς οἶδα ὄντας, τοὺς δὲ καὶ τεμένη σφίσιν ἀναθέντας †ποιμαίνισιν, ἔνθα καὶ Ἀχιλλεῖ τιμαί· Δωτοῦς δὲ ἐν Γαβάλοις ἱερόν ἐστιν ἅγιον, ἔνθα πέπλος ἔτι ἐλείπετο, ὃν Ἕλληνες Ἐριφύλην λέγουσιν ἐπὶ τῷ παιδὶ λαβεῖν Ἀλκμαίωνι.", "st": "2.1"}, {"sp": "N", "t": "τοῦ Ποσειδῶνος δέ εἰσιν ἐπειργασμένοι τῷ βάθρῳ καὶ οἱ Τυνδάρεω παῖδες, ὅτι δὴ σωτῆρες καὶ οὗτοι νεῶν καὶ ἀνθρώπων εἰσὶ ναυτιλλομένων. τὰ δὲ ἄλλα ἀνάκειται Γαλήνης ἄγαλμα καὶ Θαλάσσης καὶ ἵππος εἰκασμένος κήτει τὰ μετὰ τὸ στέρνον, Ἰνώ τε καὶ Βελλεροφόντης καὶ ὁ ἵππος ὁ Πήγασος.", "st": "2.1"}, {"sp": "N", "t": "τοῦ περιβόλου δέ ἐστιν ἐντὸς Παλαίμονος ἐν ἀριστερᾷ ναός, ἀγάλματα δὲ ἐν αὐτῷ Ποσειδῶν καὶ Λευκοθέα καὶ αὐτὸς ὁ Παλαίμων. ἔστι δὲ καὶ ἄλλο Ἄδυτον καλούμενον, κάθοδος δὲ ἐς αὐτὸ ὑπόγεως, ἔνθα δὴ τὸν Παλαίμονα κεκρύφθαι φασίν· ὃς δ’ ἂν ἐνταῦθα ἢ Κορινθίων ἢ ξένος ἐπίορκα ὀμόσῃ, οὐδεμία ἐστίν οἱ μηχανὴ διαφυγεῖν τοῦ ὅρκου. καὶ δὴ ἱερόν ἐστιν ἀρχαῖον Κυκλώπων καλούμενος βωμός, καὶ θύουσιν ἐπ’ αὐτῷ Κύκλωψι.", "st": "2.2"}, {"sp": "N", "t": "⟨τάφους δὲ⟩ Σισύφου καὶ Νηλέως—καὶ γὰρ Νηλέα ἀφικόμενον ἐς Κόρινθον νόσῳ τελευτῆσαί φασι καὶ περὶ τὸν ἰσθμὸν ταφῆναι—οὐκ ἂν οἶδ’ εἰ ζητοίη τις ἐπιλεξάμενος τὰ Εὐμήλου· Νηλέως μὲν γὰρ οὐδὲ Νέστορι ἐπιδειχθῆναι τὸ μνῆμα ὑπὸ τοῦ Σισύφου φησί, χρῆναι γὰρ ἄγνωστον τοῖς πᾶσιν ὁμοίως εἶναι, Σίσυφον δὲ ταφῆναι μὲν ἐν τῷ ἰσθμῷ, τὸν δέ οἱ τάφον καὶ τῶν ἐφ’ αὑτοῦ Κορινθίων ὀλίγους εἶναι τοὺς εἰδότας. ὁ δὲ Ἰσθμικὸς ἀγὼν οὐδὲ ἀναστάντων ὑπὸ Μομμίου Κορινθίων ἐξέλιπεν, ἀλλ’ ὅσον μὲν χρόνον ἠρήμωτο ἡ πόλις, Σικυωνίοις ἄγειν ἐπετέτραπτο τὰ Ἴσθμια, οἰκισθείσης δὲ αὖθις ἐς τοὺς νῦν οἰκήτορας περιῆλθεν ἡ τιμή.", "st": "2.2"}, {"sp": "N", "t": "Κορινθίοις δὲ τοῖς ἐπινείοις τὰ ὀνόματα Λέχης καὶ Κεγχρίας ἔδοσαν, Ποσειδῶνος εἶναι καὶ Πειρήνης τῆς Ἀχελῴου λεγόμενοι· πεποίηται δὲ ἐν Ἠοίαις μεγάλαις Οἰβάλου θυγατέρα εἶναι Πειρήνην. ἔστι δὲ ἐν Λεχαίῳ μὲν Ποσειδῶνος ἱερὸν καὶ ἄγαλμα χαλκοῦν, τὴν δὲ ἐς Κεγχρέας ἰόντων ἐξ ἰσθμοῦ ναὸς Ἀρτέμιδος καὶ ξόανον ἀρχαῖον. ἐν δὲ Κεγχρέαις Ἀφροδίτης τέ ἐστι ναὸς καὶ ἄγαλμα λίθου, μετὰ δὲ αὐτὸν ἐπὶ τῷ ἐρύματι τῷ διὰ τῆς θαλάσσης Ποσειδῶνος χαλκοῦν, κατὰ δὲ τὸ ἕτερον πέρας τοῦ λιμένος Ἀσκληπιοῦ καὶ Ἴσιδος ἱερά. Κεγχρεῶν δὲ ἀπαντικρὺ τὸ Ἑλένης ἐστὶ λουτρόν· ὕδωρ ἐς θάλασσαν ἐκ πέτρας ῥεῖ πολὺ καὶ ἁλμυρὸν ὕδατι ὅμοιον ἀρχομένῳ θερμαίνεσθαι.", "st": "2.2"}, {"sp": "N", "t": "ἀνιοῦσι δὲ ἐς Κόρινθον καὶ ἄλλα ἐστὶ κατὰ τὴν ὁδὸν μνήματα καὶ πρὸς τῇ πύλῃ Διογένης τέθαπται ὁ Σινωπεύς, ὃν κύνα ἐπίκλησιν καλοῦσιν Ἕλληνες. πρὸ δὲ τῆς πόλεως κυπαρίσσων ἐστὶν ἄλσος ὀνομαζόμενον Κράνειον. ἐνταῦθα Βελλεροφόντου τέ ἐστι τέμενος καὶ Ἀφροδίτης ναὸς Μελαινίδος καὶ τάφος Λαΐδος, ᾧ δὴ λέαινα ἐπίθημά ἐστι κριὸν ἔχουσα ἐν τοῖς προτέροις ποσίν.", "st": "2.2"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλο ἐν Θεσσαλίᾳ Λαΐδος φάμενον μνῆμα εἶναι· παρεγένετο γὰρ καὶ ἐς Θεσσαλίαν ἐρασθεῖσα Ἱπποστράτου. τὸ δὲ ἐξ ἀρχῆς ἐξ Ὑκάρων αὐτὴν τῶν ἐν Σικελίᾳ λέγεται παῖδα οὖσαν ὑπὸ Νικίου καὶ Ἀθηναίων ἁλῶναι, πραθεῖσαν δὲ ἐς Κόρινθον ὑπερβαλέσθαι κάλλει τὰς τότε ἑταίρας, θαυμασθῆναί τε· οὕτω παρὰ Κορινθίοις ὡς ἀμφισβητεῖν σφᾶς καὶ νῦν ἔτι Λαΐδος.", "st": "2.2"}, {"sp": "N", "t": "λόγου δὲ ἄξια ἐν τῇ πόλει τὰ μὲν λειπόμενα ἔτι τῶν ἀρχαίων ἐστίν, τὰ δὲ πολλὰ αὐτῶν ἐπὶ τῆς ἀκμῆς ἐποιήθη τῆς ὕστερον. ἔστιν οὖν ἐπὶ τῆς ἀγορᾶς— ἐνταῦθα γὰρ πλεῖστά ἐστι τῶν ἱερῶν—Ἄρτεμίς τε ἐπίκλησιν Ἐφεσία καὶ Διονύσου ξόανα ἐπίχρυσα πλὴν τῶν προσώπων· τὰ δὲ πρόσωπα ἀλοιφῇ σφισιν ἐρυθρᾷ κεκόσμηται· Λύσιον δέ, τὸν δὲ Βάκχειον ὀνομάζουσι.", "st": "2.2"}, {"sp": "N", "t": "τὰ δὲ λεγόμενα ἐς τὰ ξόανα καὶ ἐγὼ γράφω. Πενθέα ὑβρίζοντα ἐς Διόνυσον καὶ ἄλλα τολμᾶν λέγουσι καὶ τέλος ἐς τὸν Κιθαιρῶνα ἐλθεῖν ἐπὶ κατασκοπῇ τῶν γυναικῶν, ἀναβάντα δὲ ἐς δένδρον θεάσασθαι τὰ ποιούμενα· τὰς δέ, ὡς ἐφώρασαν, καθελκύσαι τε αὐτίκα Πενθέα καὶ ζῶντος ἀποσπᾶν ἄλλο ἄλλην τοῦ σώματος. ὕστερον δέ, ὡς Κορίνθιοι λέγουσιν, ἡ Πυθία χρᾷ σφισιν ἀνευρόντας τὸ δένδρον ἐκεῖνο ἴσα τῷ θεῷ σέβειν· καὶ ἀπ’ αὐτοῦ διὰ τόδε τὰς εἰκόνας πεποίηνται ταύτας.", "st": "2.2"}, {"sp": "N", "t": "ἔστι δὲ καὶ Τύχης ναός· ἄγαλμα ὀρθὸν Παρίου λίθου· παρὰ δὲ αὐτὸν θεοῖς πᾶσίν ἐστιν ἱερόν. πλησίον δὲ ᾠκοδόμηται κρήνη, καὶ Ποσειδῶν ἐπ’ αὐτῇ χαλκοῦς καὶ δελφὶς ὑπὸ τοῖς ποσίν ἐστι τοῦ Ποσειδῶνος ἀφιεὶς ὕδωρ. καὶ Ἀπόλλων ἐπίκλησιν Κλάριος χαλκοῦς ἐστι καὶ ἄγαλμα Ἀφροδίτης Ἑρμογένους Κυθηρίου ποιήσαντος. Ἑρμοῦ τέ ἐστιν ἀγάλματα χαλκοῦ μὲν καὶ ὀρθὰ ἀμφότερα, τῷ δὲ ἑτέρῳ καὶ ναὸς πεποίηται. τὰ δὲ τοῦ Διός, καὶ ταῦτα ὄντα ἐν ὑπαίθρῳ, τὸ μὲν ἐπίκλησιν οὐκ εἶχε, τὸν δὲ αὐτῶν Χθόνιον καὶ τὸν τρίτον καλοῦσιν Ὕψιστον.", "st": "2.2"}, {"sp": "N", "t": "ἐν μέσῳ δὲ τῆς ἀγορᾶς ἐστιν Ἀθηνᾶ χαλκῆ· τῷ βάθρῳ δὲ αὐτῆς ἐστι Μουσῶν ἀγάλματα ἐπειργασμένα. ὑπὲρ δὲ τὴν ἀγοράν ἐστιν Ὀκταβίας ναὸς ἀδελφῆς Αὐγούστου βασιλεύσαντος Ῥωμαίων μετὰ Καίσαρα τὸν οἰκιστὴν Κορίνθου τῆς νῦν.", "st": "2.3"}, {"sp": "N", "t": "ἐκ δὲ τῆς ἀγορᾶς ἐξιόντων τὴν ἐπὶ Λεχαίου προπύλαιά ἐστι καὶ ἐπ’ αὐτῶν ἅρματα ἐπίχρυσα, τὸ μὲν Φαέθοντα Ἡλίου παῖδα, τὸ δὲ Ἥλιον αὐτὸν φέρον. ὀλίγον δὲ ἀπωτέρω τῶν προπυλαίων ἐσιοῦσιν ἐν δεξιᾷ ἐστιν Ἡρακλῆς χαλκοῦς. μετὰ δὲ αὐτὸν ἔσοδός ἐστι τῆς Πειρήνης ἐς τὸ ὕδωρ. ἐπὶ δὲ αὐτῇ λέγουσιν ὡς ἥ Πειρήνη γένοιτο ὑπὸ δακρύων ἐξ ἀνθρώπου πηγή, τὸν παῖδα ὀδυρομένη Κεγχρίαν ὑπὸ Ἀρτέμιδος ἀκούσης ἀποθανόντα.", "st": "2.3"}, {"sp": "N", "t": "κεκόσμηται δὲ ἡ πηγὴ λίθῳ λευκῷ, καὶ πεποιημένα ἐστὶν οἰκήματα σπηλαίοις κατὰ ταὐτά, ἐξ ὧν τὸ ὕδωρ ἐς κρήνην ὕπαιθρον ῥεῖ πιεῖν τε ἡδὺ καὶ τὸν Κορίνθιον χαλκὸν διάπυρον καὶ θερμὸν ὄντα ὑπὸ ὕδατος τούτου βάπτεσθαι λέγουσιν, ἐπεὶ χαλκός … γε οὐκ ἔστι Κορινθίοις. ἔτι γε δὴ καὶ Ἀπόλλωνος ἄγαλμα πρὸς τῇ Πειρήνῃ καὶ περίβολός ἐστιν, ἐν δὲ αὐτῷ γραφὴ τὸ Ὀδυσσέως ἐς τοὺς μνηστῆρας ἔχουσα τόλμημα.", "st": "2.3"}, {"sp": "N", "t": "αὖθις δ’ ἰοῦσιν ἐπὶ Λεχαίου τὴν εὐθεῖαν χαλκοῦς καθήμενός ἐστιν Ἑρμῆς, παρέστηκε δέ οἱ κριός, ὅτι Ἑρμῆς μάλιστα δοκεῖ θεῶν ἐφορᾶν καὶ αὔξειν ποίμνας, καθὰ δὴ καὶ Ὅμηρος ἐν Ἰλιάδι ἐποίησεν<br>υἱὸν Φόρβαντος πολυμήλου, τόν ῥα μάλιστα<br>Ἑρμείας Τρώων ἐφίλει καὶ κτῆσιν ὄπασσε·<br>τὸν δὲ ἐν τελετῇ Μητρὸς ἐπὶ Ἑρμῇ λεγόμενον καὶ τῷ κριῷ λόγον ἐπιστάμενος οὐ λέγω. μετὰ δὲ τὸ ἄγαλμα τοῦ Ἑρμοῦ Ποσειδῶν καὶ Λευκοθέα καὶ ἐπὶ δελφῖνός ἐστιν ὁ Παλαίμων.", "st": "2.3"}, {"sp": "N", "t": "λουτρὰ δὲ ἔστι μὲν πολλαχοῦ Κορινθίοις καὶ ἄλλα, τὰ μὲν ἀπὸ τοῦ κοινοῦ, τὸ δὲ βασιλέως Ἀδριανοῦ κατασκευάσαντος· τὸ δὲ ὀνομαστότατον αὐτῶν πλησίον τοῦ Ποσειδῶνος. τοῦτο δὲ Εὐρυκλῆς ἐποίησεν ἀνὴρ Σπαρτιάτης λίθοις κοσμήσας καὶ ἄλλοις καὶ ὃν ἐν Κροκεαῖς χώρας τῆς Λακωνικῆς ὀρύσσουσιν. ἐν ἀριστερᾷ δὲ τῆς ἐσόδου Ποσειδῶν καὶ μετ’ αὐτὸν Ἄρτεμις θηρεύουσα ἕστηκε. κρῆναι δὲ πολλαὶ μὲν ἀνὰ τὴν πόλιν πεποίηνται πᾶσαν ἅτε ἀφθόνου ῥέοντός σφισιν ὕδατος καὶ ὃ δὴ βασιλεὺς Ἀδριανὸς ἐσήγαγεν ἐκ Στυμφήλου, θέας δὲ μάλιστα ἀξία ⟨ἡ⟩ παρὰ τὸ ἄγαλμα τὸ τῆς Ἀρτέμιδος· καί οἱ Βελλεροφόντης ἔπεστι καὶ τὸ ὕδωρ [ὁ] δι’ ὁπλῆς ἵππου ῥεῖ τοῦ Πηγάσου.", "st": "2.3"}, {"sp": "N", "t": "ἑτέραν δὲ ἐκ τῆς ἀγορᾶς τὴν ἐπὶ Σικυῶνα ἐρχομένοις ἔστιν ἰδεῖν ἐν δεξιᾷ τῆς ὁδοῦ ναὸς καὶ ἄγαλμα χαλκοῦν Ἀπόλλωνος καὶ ὀλίγον ἀπωτέρω κρήνη καλουμένη Γλαύκης· ἐς γὰρ ταύτην ἔρριψεν αὑτήν, ὡς λέγουσι, τῶν Μηδείας ἔσεσθαι φαρμάκων τὸ ὕδωρ νομίζουσα ἴαμα. ὑπὲρ ταύτην πεποίηται τὴν κρήνην καὶ τὸ καλούμενον Ὠιδεῖον, παρὰ δὲ αὐτὸ μνῆμά ἐστι τοῖς Μηδείας παισίν· [ὧν] ὀνόματα μέν σφισι Μέρμερος καὶ Φέρης, καταλιθωθῆναι δὲ ὑπὸ Κορινθίων λέγονται τῶν δώρων ἕνεκα ὧν τῇ Γλαύκῃ κομίσαι φασὶν αὐτούς·", "st": "2.3"}, {"sp": "N", "t": "ἅτε δὲ τοῦ θανάτου βιαίου καὶ οὐ σὺν τῷ δικαίῳ γενομένου, τὰ τέκνα Κορινθίων τὰ νήπια ὑπ’ αὐτῶν ἐφθείρετο, πρὶν ἢ χρήσαντος τοῦ θεοῦ θυσίαι τε αὐτοῖς ἐπέτειοι κατέστησαν καὶ Δεῖμα ἐπεστάθη. τοῦτο μὲν δὴ καὶ ἐς ἡμᾶς ἔτι λείπεται, γυναικὸς ἐς τὸ φοβερώτερον εἰκὼν πεποιημένη· Κορίνθου δὲ ἀναστάτου γενομένης ὑπὸ Ῥωμαίων καὶ Κορινθίων τῶν ἀρχαίων ἀπολομένων, οὐκέτι ἐκεῖναι καθεστήκασιν αὐτοῖς αἱ θυσίαι παρὰ τῶν ἐποίκων οὐδὲ ἀποκείρονταί σφισιν οἱ παῖδες οὐδὲ μέλαιναν φοροῦσιν ἐσθῆτα.", "st": "2.3"}, {"sp": "N", "t": "Μήδεια δὲ τότε μὲν ἐλθοῦσα ἐς Ἀθήνας συνῴκησεν Αἰγεῖ, χρόνῳ δὲ ὕστερον φωραθεῖσα ἐπιβουλεύειν Θησεῖ καὶ ἐξ Ἀθηνῶν ἔφυγε, παραγενομένη δὲ ἐς τὴν λεγομένην τότε Ἀρίαν τοῖς ἀνθρώποις ἔδωκε τὸ ὄνομα καλεῖσθαι Μήδους ἀπ’ αὐτῆς· τὸν δὲ παῖδα, ὃν ἐπήγετο φεύγουσα ἐς τοὺς Ἀρίους, γενέσθαι λέγουσιν ἐξ Αἰγέως, ὄνομα δέ οἱ Μῆδον εἶναι· Ἑλλάνικος δὲ αὐτὸν Πολύξενον καλεῖ καὶ πατρὸς Ἰάσονός φησιν εἶναι.", "st": "2.3"}, {"sp": "N", "t": "ἔπη δὲ ἔστιν ἐν Ἕλλησι Ναυπάκτια ὀνομαζόμενα· πεποίηται δὲ ἐν αὐτοῖς Ἰάσονα ἐξ Ἰωλκοῦ μετὰ τὸν Πελίου θάνατον ἐς Κόρκυραν μετοικῆσαι καί οἱ Μέρμερον μὲν τὸν πρεσβύτερον τῶν παίδων ὑπὸ λεαίνης διαφθαρῆναι θηρεύοντα ἐν τῇ πέραν ἠπείρῳ· Φέρητι δὲ οὐδέν ἐστιν ἐς μνήμην προσκείμενον. Κιναίθων δὲ ὁ Λακεδαιμόνιος—ἐγενεαλόγησε γὰρ καὶ οὗτος ἔπεσι —Μήδειον καὶ θυγατέρα Ἐριῶπιν Ἰάσονι εἶπεν ἐκ Μηδείας γενέσθαι· πέρα δὲ ἐς τοὺς παῖδας οὐδὲ τούτῳ πεποιημένα ἐστίν.", "st": "2.3"}, {"sp": "N", "t": "Εὔμηλος δὲ Ἥλιον ἔφη δοῦναι τὴν χώραν Ἀλωεῖ. μὲν τὴν Ἀσωπίαν, Αἰήτῃ δὲ τὴν Ἐφυραίαν· καὶ Αἰήτην ἀπιόντα ἐς Κόλχους παρακαταθέσθαι Βούνῳ τὴν γῆν, Βοῦνον δὲ Ἑρμοῦ καὶ Ἀλκιδαμείας εἶναι, καὶ ἐπεὶ Βοῦνος ἐτελεύτησεν, οὕτως Ἐπωπέα τὸν Ἀλωέως καὶ τὴν Ἐφυραίων σχεῖν ἀρχήν· Κορίνθου δὲ ὕστερον τοῦ Μαραθῶνος οὐδένα ὑπολ[ε]ιπομένου παῖδα, τοὺς Κορινθίους Μήδειαν μεταπεμψαμένους ἐξ Ἰωλκοῦ παραδοῦναί οἱ τὴν ἀρχήν.", "st": "2.3"}, {"sp": "N", "t": "βασιλεύειν μὲν δὴ δι’ αὐτὴν Ἰάσονα ἐν Κορίνθῳ, Μηδείᾳ δὲ παῖδας μὲν γίνεσθαι, τὸ δὲ ἀεὶ τικτόμενον κατακρύπτειν αὐτὸ ἐς τὸ ἱερὸν φέρουσαν τῆς Ἥρας, κατακρύπτειν δὲ ἀθανάτους ἔσεσθαι νομίζουσαν· τέλος δὲ αὐτήν τε μαθεῖν ὡς ἡμαρτήκοι τῆς ἐλπίδος καὶ ἅμα ὑπὸ τοῦ Ἰάσονος φωραθεῖσαν—οὐ γὰρ αὐτὸν ἔχειν δεομένῃ συγγνώμην, ἀποπλέοντα ⟨δὲ⟩ ἐς Ἰωλκὸν οἴχεσθαι—, τούτων δὲ ἕνεκα ἀπελθεῖν καὶ Μήδειαν παραδοῦσαν Σισύφῳ τὴν ἀρχήν.", "st": "2.3"}, {"sp": "N", "t": "τάδε μὲν οὕτως ἔχοντα ἐπελεξάμην, τοῦ μνήματος δέ ἐστιν οὐ πόρρω Χαλινίτιδος Ἀθηνᾶς ἱερόν· Ἀθηνᾶν γὰρ θεῶν μάλιστα συγκατεργάσασθαι τά τε ἄλλα Βελλεροφόντῃ φασὶ καὶ ὡς τὸν Πήγασόν οἱ παραδοίη χειρωσαμένη τε καὶ ἐνθεῖσα αὐτὴ τῷ ἵππῳ χαλινόν. τὸ δὲ ἄγαλμα τοῦτο ξόανόν ἐστι, πρόσωπον δὲ καὶ χεῖρες καὶ ἀκρόποδες εἰσὶ λευκοῦ λίθου.", "st": "2.4"}, {"sp": "N", "t": "Βελλεροφόντην δὲ οὐκ αὐτοκράτορα ὄντα βασιλεύειν, εἶναι δὲ ἐπὶ Προίτῳ καὶ Ἀργείοις ἐγώ τε πείθομαι καὶ ὅστις τὰ Ὁμήρου μὴ πάρεργον ἐπελέξατο. φαίνονται δὲ καὶ Βελλεροφόντου μετοικήσαντος ἐς Λυκίαν οὐδὲν ἧσσον οἱ Κορίνθιοι τῶν ἐν Ἄργει δυναστῶν ἢ Μυκήναις ὑπακούοντες· ἰδίᾳ τε οὐδένα παρέσχοντο ἄρχοντα τῆς ἐπὶ Τροίαν στρατιᾶς, συντεταγμένοι δὲ Μυκηναίοις καὶ ὅσων ἄλλων Ἀγαμέμνων ἡγεῖτο μετέσχον τοῦ στόλου.", "st": "2.4"}, {"sp": "N", "t": "Σισύφῳ δὲ οὔτι Γλαῦκος μόνον ὁ Βελλεροφόντου πατὴρ ἀλλὰ καὶ ἕτερος υἱὸς ἐγένετο Ὀρνυτίων, ἐπὶ δὲ αὐτῷ Θέρσανδρός τε καὶ Ἄλμος. Ὀρνυτίωνος δὲ ἦν Φῶκος, Ποσειδῶνος δὲ ἐπίκλησιν. καὶ ὁ μὲν ἀπῴκησεν ἐς Τιθορέαν τῆς νῦν καλουμένης Φωκίδος, Θόας δὲ Ὀρνυτίωνος υἱὸς νεώτερος κατέμεινεν ἐν τῇ Κορίνθῳ. Θόαντος δὲ Δαμοφῶν, Δαμοφῶντος δὲ ἦν Προπόδας, Προπόδα δὲ Δωρίδας καὶ Ὑανθίδας. τούτων βασιλευόντων Δωριεῖς στρατεύουσιν ἐπὶ Κόρινθον· ἡγεῖτο δὲ Ἀλήτης Ἱππότου ⟨τοῦ⟩ Φύλαντος τοῦ Ἀντιόχου τοῦ Ἡρακλέους. Δωρίδας μὲν οὖν καὶ Ὑανθίδας παραδόντες τὴν βασιλείαν Ἀλήτῃ καταμένουσιν αὐτοῦ, τῶν δὲ Κορινθίων ὁ δῆμος ἐξέπεσεν ὑπὸ Δωριέων κρατηθεὶς μάχῃ.", "st": "2.4"}, {"sp": "N", "t": "Ἀλήτης δὲ αὐτός τε καὶ οἱ ἀπόγονοι βασιλεύουσιν ἐς μὲν Βάκχιν τὸν Προύμνιδος ἐπὶ γενεὰς πέντε, ἀπὸ τούτου δὲ οἱ Βακχίδαι καλούμενοι πέντε ἄλλας γενεὰς ἐς Τελέστην τὸν Ἀριστοδήμου. καὶ Τελέστην μὲν κατὰ ἔχθος Ἀριεὺς καὶ Περάντας κτείνουσι, βασιλεὺς δὲ οὐδεὶς ἔτι ἐγένετο, πρυτάνεις δὲ ἐκ Βακχιδῶν ἐνιαυτὸν ἄρχοντες, ἐς ὃ Κύψελος τυραννήσας ὁ Ἠετίωνος ἐξέβαλε τοὺς Βακχίδας· ἀπόγονος δὲ ἦν ὁ Κύψελος Μέλανος τοῦ Ἀντάσου. Μέλανα δὲ ἐκ Γονούσσης τῆς ὑπὲρ Σικυῶνος στρατεύοντα σὺν Δωριεῦσιν ἐπὶ Κόρινθον Ἀλήτης τὸ μὲν παραυτίκα ἀπειπόντος τοῦ θεοῦ παρ’ ἄλλους τῶν Ἑλλήνων ἐκέλευσεν ἀποχωρεῖν, ὕστερον δὲ ἁμαρτὼν τοῦ χρησμοῦ δέχεται σύνοικον. τοιαῦτα μὲν ἐς τοὺς Κορινθίων βασιλέας συμβάντα εὕρισκον·", "st": "2.4"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τῆς Ἀθηνᾶς τῆς Χαλινίτιδος πρὸς τῷ θεάτρῳ σφίσιν ἐστὶν καὶ πλησίον ξόανον γυμνὸν Ἡρακλέους, Δαιδάλου δὲ αὐτό φασιν εἶναι τέχνην. Δαίδαλος δὲ ὁπόσα εἰργάσατο, ἀτοπώτερα μέν ἐστιν ἐς τὴν ὄψιν, ἐπιπρέπει δὲ ὅμως τι καὶ ἔνθεον τούτοις. ὑπὲρ δὲ τὸ θέατρόν ἐστιν ἱερὸν Διὸς Καπετωλίου φωνῇ τῇ Ῥωμαίων· κατὰ Ἑλλάδα δὲ γλῶσσαν Κορυφαῖος ὀνομάζοιτο ἄν. τοῦ θεάτρου δέ ἐστι τοῦδε ⟨οὐ⟩ πόρρω γυμνάσιον τὸ ἀρχαῖον καὶ πηγὴ καλουμένη Λέρνα· κίονες δὲ ἑστήκασι περὶ αὐτὴν καὶ καθέδραι πεποίηνται τοὺς ἐσελθόντας ἀναψύχειν ὥρᾳ θέρους. πρὸς τούτῳ τῷ γυμνασίῳ ναοὶ θεῶν εἰσιν ὁ μὲν Διός, ὁ δὲ Ἀσκληπιοῦ· τὰ δὲ ἀγάλματα Ἀσκληπιὸς μὲν καὶ Ὑγεία λευκοῦ λίθου, τὸ δὲ τοῦ Διὸς χαλκοῦν ἐστιν.", "st": "2.4"}, {"sp": "N", "t": "ἀνιοῦσι δὲ ἐς τὸν Ἀκροκόρινθον—ἡ δέ ἐστιν ὄρους ὑπὲρ τὴν πόλιν κορυφή, Βριάρεω μὲν Ἡλίῳ δόντος αὐτὴν ὅτε ἐδίκαζεν, Ἡλίου δὲ ὡς οἱ Κορίνθιοί φασιν Ἀφροδίτῃ παρέντος—ἐς δὴ τὸν Ἀκροκόρινθον τοῦτον ἀνιοῦσίν ἐστιν Ἴσιδος τεμένη, ὧν τὴν μὲν Πελαγίαν, τὴν δὲ Αἰγυπτίαν αὐτῶν ἐπονομάζουσιν, καὶ δύο Σαράπιδος, ἐν Κανώβῳ καλουμένου τὸ ἕτερον. μετὰ δὲ αὐτὰ Ἡλίῳ πεποίηνται βωμοί, καὶ Ἀνάγκης καὶ Βίας ἐστὶν ἱερόν· ἐσιέναι δὲ ἐς αὐτὸ οὐ νομίζουσιν.", "st": "2.4"}, {"sp": "N", "t": "ὑπὲρ τοῦτο Μητρὸς θεῶν ναός ἐστι καὶ στήλη καὶ θρόνος· λίθων καὶ αὐτὴ καὶ ὁ θρόνος. ὁ δὲ τῶν Μοιρῶν καὶ ⟨ὁ⟩ Δήμητρος καὶ Κόρης οὐ φανερὰ ἔχουσι τὰ ἀγάλματα. ταύτῃ καὶ τὸ τῆς Βουναίας ἐστὶν Ἥρας ἱερὸν ἱδρυσαμένου Βούνου τοῦ Ἑρμοῦ· καὶ δι’ αὐτὸ ἡ θεὸς καλεῖται Βουναία.", "st": "2.4"}, {"sp": "N", "t": "ἀνελθοῦσι δὲ ἐς τὸν Ἀκροκόρινθον ναός ἐστιν Ἀφροδίτης· ἀγάλματα δὲ αὐτή τε ὡπλισμένη καὶ Ἥλιος καὶ Ἔρως ἔχων τόξον. τὴν δὲ πηγήν, ἥ ἐστιν ὄπισθεν τοῦ ναοῦ, δῶρον μὲν Ἀσωποῦ λέγουσιν εἶναι, δοθῆναι δὲ Σισύφῳ· τοῦτον γὰρ εἰδότα, ὡς εἴη Ζεὺς ἡρπακὼς Αἴγιναν θυγατέρα Ἀσωποῦ, μὴ πρότερον φάναι ζητοῦντι μηνύσειν πρὶν ἤ οἱ καὶ ἐν Ἀκροκορίνθῳ γένοιτο ὕδωρ· δόντος δὲ Ἀσωποῦ μηνύει τε οὕτως καὶ ἀντὶ τοῦ μηνύματος δίκην—ὅτῳ πιστὰ—ἐν Ἅιδου δίδωσιν. ἤκουσα δὲ ἤδη τὴν Πειρήνην φαμένων εἶναι ταύτην καὶ τὸ ὕδωρ αὐτόθεν ὑπορρεῖν τὸ ἐν τῇ πόλει.", "st": "2.5"}, {"sp": "N", "t": "ὁ δὲ Ἀσωπὸς οὗτος ἄρχεται μὲν ἐκ τῆς Φλιασίας, ῥεῖ δὲ διὰ τῆς Σικυωνίας ⟨καὶ⟩ ἐκδίδωσιν ἐς τὴν ταύτῃ θάλασσαν. θυγατέρας δὲ αὐτοῦ γενέσθαι Φλιάσιοί φασι Κόρκυραν καὶ Αἴγιναν καὶ Θήβην· ἀπὸ μὲν δὴ Κορκύρας καὶ Αἰγίνης τὰς νήσους Σχερίαν καὶ Οἰνώνην καλουμένας μετονομασθῆναι, ἀπὸ δὲ Θήβης τὴν ὑπὸ τῇ Καδμείᾳ κληθῆναι. Θηβαῖοι δὲ οὐχ ὁμολογοῦσι, φάμενοι τοῦ Βοιωτίου τὴν Θήβην Ἀσωποῦ καὶ οὐ τοῦ [παρὰ] Φλιασίου εἶναι.", "st": "2.5"}, {"sp": "N", "t": "τὰ δὲ ἄλλα ἐς τὸν ποταμὸν Φλιάσιοι καὶ Σικυώνιοι λέγουσι, τὸ ὕδωρ ἔπηλυ καὶ οὐκ ἐγχώριον εἶναί οἱ· Μαίανδρον γὰρ κατιόντα ἐκ Κελαινῶν διὰ Φρυγίας καὶ Καρίας καὶ ἐκδιδόντα ἐς τὴν πρὸς Μιλήτῳ θάλασσαν ἐς Πελοπόννησον ἔρχεσθαι καὶ ποιεῖν τὸν Ἀσωπόν. οἶδα δὲ καὶ Δηλίων τοιοῦτο ἀκούσας ἕτερον, ὕδωρ ὃ καλοῦσιν Ἰνωπὸν εἶναί σφισιν ἐκ τοῦ Νείλου· καὶ δὴ καὶ αὐτὸν ἔχει τὸν Νεῖλον λόγος Εὐφράτην ὄντα ἐς ἕλος ἀφανίζεσθαι καὶ αὖθις ἀνιόντα ὑπὲρ Αἰθιοπίας Νεῖλον γίνεσθαι. Ἀσωποῦ μὲν πέρι τοιαῦτα ἤκουσα, ἐκ δὲ τοῦ Ἀκροκορίνθου", "st": "2.5"}, {"sp": "N", "t": "τραπεῖσι τὴν ὀρεινὴν πύλη τέ ἐστιν ἡ Τενεατικὴ καὶ Εἰληθυίας ἱερόν· ἑξήκοντα δὲ ἀπέχει μάλιστα στάδια ἡ καλουμένη Τενέα. οἱ δὲ ἄνθρωποί φασιν οἱ ταύτῃ Τρῶες εἶναι, αἰχμάλωτοι δὲ ὑπὸ Ἑλλήνων ἐκ Τενέδου γενόμενοι ἐνταῦθα Ἀγαμέμνονος δόντος οἰκῆσαι· καὶ διὰ τοῦτο θεῶν μάλιστα Ἀπόλλωνα τιμῶσιν.", "st": "2.5"}, {"sp": "N", "t": "ἐκ Κορίνθου δὲ οὐκ ἐς μεσόγαιαν ἀλλὰ τὴν ἐπὶ Σικυῶνα ἰοῦσι ναὸς ἐμπεπρησμένος ἐστὶν οὐ πόρρω τῆς πόλεως, ἐν ἀριστερᾷ δὲ τῆς ὁδοῦ. γεγόνασι μὲν δὴ καὶ ἄλλοι πόλεμοι περὶ τὴν Κορινθίαν καὶ πῦρ ἐπέλαβεν ὡς τὸ εἰκὸς καὶ οἰκίας καὶ ἱερὰ τὰ ἔξω τείχους· ἀλλὰ τοῦτόν γε τὸν ναὸν Ἀπόλλωνος εἶναι λέγουσι καὶ ὅτι Πύρρος κατακαύσειεν ὁ Ἀχιλλέως αὐτόν. χρόνῳ δὲ ὕστερον ἤκουσα καὶ ἄλλο τοιόνδε, ὡς οἱ Κορίνθιοι Διὶ ποιήσαιντο Ὀλυμπίῳ τὸν ναὸν καὶ ὡς ἐξαίφνης πῦρ ποθὲν ἐμπεσὸν διαφθείρειεν αὐτόν.", "st": "2.5"}, {"sp": "N", "t": "Σικυώνιοι δὲ—οὗτοι γὰρ ταύτῃ Κορινθίοις εἰσὶν ὅμοροι—περὶ τῆς χώρας τῆς σφετέρας λέγουσιν ὡς Αἰγιαλεὺς αὐτόχθων πρῶτος ἐν αὐτῇ γένοιτο, καὶ Πελοποννήσου δὲ ὅσον ἔτι καλεῖται καὶ νῦν Αἰγιαλὸς ἀπ’ ἐκείνου βασιλεύοντος ὀνομασθῆναι, καὶ Αἰγιάλειαν αὐτὸν οἰκίσαι πρῶτον ἐν τῷ πεδίῳ πόλιν· οὗ δέ ἐστι νῦν σφίσι τὸ ἱερὸν τῆς Ἀθηνᾶς, ἀκρόπολιν τοῦτο εἶναι. Αἰγιαλέως δὲ Εὔρωπα γενέσθαι φασίν, Εὔρωπος δὲ Τελχῖνα, Τελχῖνος δὲ Ἆπιν.", "st": "2.5"}, {"sp": "N", "t": "οὗτος ὁ Ἆπις ἐς τοσόνδε ηὐξήθη δυνάμεως, πρὶν ἢ Πέλοπα ἐς Ὀλυμπίαν ἀφικέσθαι, ὡς τὴν ἐντὸς Ἰσθμοῦ χώραν Ἀπίαν ἀπ’ ἐκείνου καλεῖσθαι. Ἄπιδος δὲ ἦν Θελξίων, Θελξίονος δὲ Αἴγυρος, τοῦ δὲ Θουρίμαχος, Θουριμάχου δὲ Λεύκιππος· Λευκίππῳ δὲ ἄρρενες παῖδες οὐκ ἐγένοντο, θυγάτηρ δὲ Καλχινία. ταύτῃ τῇ Καλχινίᾳ Ποσειδῶνα συγγενέσθαι φασὶ καὶ τὸν τεχθέντα ὑπ’ αὐτῆς ἔθρεψεν ὁ Λεύκιππος καὶ τελευτῶν παρέδωκέν οἱ τὴν ἀρχήν·", "st": "2.5"}, {"sp": "N", "t": "ὄνομα δὲ ἦν Πέρατος τῷ παιδί. τὰ δὲ ἐς Πλημναῖον τὸν Περάτου μάλιστα ἐφαίνετό μοι θαύματος ἄξια· τὰ γάρ οἱ τικτόμενα ὑπὸ τῆς γυναικὸς αὐτίκα ὁπότε πρῶτον κλαύσειεν ἠφίει τὴν ψυχήν, ἐς ὃ Δημήτηρ ἔλεον ἴσχει Πλημναίου, παραγενομένη δὲ ἐς τὴν Αἰγιάλειαν ὡς δὴ γυνὴ ξένη Πλημναίῳ παῖδα ἀνέθρεψεν Ὀρθόπολιν. Ὀρθοπόλιδι δὲ θυγάτηρ γίνεται Χρυσόρθη· ταύτην τεκεῖν νομίζουσιν ἐξ Ἀπόλλωνος καὶ ὁ παῖς ὠνομάσθη Κόρωνος, Κορώνου δὲ γίνονται Κόραξ καὶ νεώτερος Λαμέδων.", "st": "2.5"}, {"sp": "N", "t": "Κόρακος δὲ ἀποθανόντος ἄπαιδος ὑπὸ τοῦτον τὸν καιρὸν Ἐπωπεὺς ἀφικόμενος ἐκ Θεσσαλίας ἔσχε τὴν ἀρχήν. ἐπὶ τούτου βασιλεύοντος στρατόν σφισι πολέμιον λέγουσιν ἐς τὴν χώραν τότε ἐλθεῖν πρῶτον, τὰ πρὸ τοῦ πάντα τὸν χρόνον διατελέσασιν ἐν εἰρήνῃ. αἰτία δὲ ἥδε· Ἀντιόπης ἐν Ἕλλησι τῆς Νυκτέως ὄνομα ἦν ἐπὶ κάλλει, καί οἱ καὶ φήμη προσῆν Ἀσωποῦ θυγατέρα, ὃς τὴν Θηβαΐδα καὶ Πλαταιίδα ὁρίζει, καὶ οὐ Νυκτέως εἶναι.", "st": "2.6"}, {"sp": "N", "t": "ταύτην οὐκ οἶδα εἴτε γυναῖκα αἰτήσας εἴτε θρασύτερα ἐξ ἀρχῆς βουλευσάμενος Ἐπωπεὺς ἁρπάζει· ὡς δὲ οἱ Θηβαῖοι σὺν ὅπλοις ἦλθον, ἐνταῦθα τιτρώσκεται μὲν Νυκτεύς, ἐτρώθη δὲ κρατῶν τῇ μάχῃ καὶ Ἐπωπεύς. Νυκτέα μὲν δὴ κάμνοντα ὀπίσω κομίζουσιν ἐς Θήβας, καὶ ὡς ἔμελλε τελευτᾶν, Λύκον ἀδελφὸν ὄντα παραδίδωσι Θηβαίων ἐν τῷ παρόντι ἄρχειν· Λάβδακον γὰρ τὸν Πολυδώρου τοῦ Κάδμου παῖδα ἔτι αὐτός τε ἐπετρόπευεν ὁ Νυκτεὺς καὶ τότε ἀπέλιπεν ἐπιτροπεύειν ἐκείνῳ. τοῦτον οὖν τὸν Λύκον ἱκέτευσε στρατῷ μείζονι ἐπὶ τὴν Αἰγιάλειαν ἐλάσαντα τιμωρήσασθαι μὲν Ἐπωπέα, κακοῦν δὲ εἰ λάβοι καὶ αὐτὴν Ἀντιόπην.", "st": "2.6"}, {"sp": "N", "t": "Ἐπωπεὺς δὲ τὸ μὲν παραυτίκα ἐπινίκια ἔθυε καὶ Ἀθηνᾶς ᾠκοδόμει ναόν, ἐπ’ ἐξειργασμένῳ δὲ εὔξατο ἐνδείξασθαι τὴν θεὸν εἴ οἱ τετελεσμένος ἐστὶν ὁ ναὸς κατὰ γνώμην· μετὰ δὲ τὴν εὐχὴν ἔλαιον λέγουσι ῥυῆναι πρὸ τοῦ ναοῦ. ὕστερον δὲ καὶ Ἐπωπέα κατέλαβεν ἀποθανεῖν ὑπὸ τοῦ τραύματος ἀμεληθέντος κατ’ ἀρχάς, ὡς μηδὲν ἔτι Λύκῳ δεῆσαι πολέμου· Λαμέδων γὰρ ὁ Κορώνου βασιλεύσας μετὰ Ἐπωπέα ἐξέδωκεν Ἀντιόπην. ἡ δὲ ὡς ἐς Θήβας ἤγετο τὴν ἐπ’ Ἐλευθερῶν, ἐνταῦθα καθ’ ὁδὸν τίκτει.", "st": "2.6"}, {"sp": "N", "t": "καὶ ἐπὶ τούτῳ πεποίηκεν Ἄσιος ὁ Ἀμφιπτολέμου·<br>Ἀντιόπη δ’ ἔτεκε Ζῆθον καὶ Ἀμφίονα δῖον<br>Ἀσωποῦ κούρη ποταμοῦ βαθυδινήεντος,<br>Ζηνί τε κυσαμένη καὶ Ἐπωπέι ποιμένι λαῶν.<br>Ὅμηρος δὲ σφᾶς ἀνήγαγεν ἐπὶ τὸ σεμνότερον τοῦ γένους καὶ Θήβας φησὶν οἰκίσαι πρώτους, ἀποκρίνων τὴν κάτω πόλιν ἐμοὶ δοκεῖν ἀπὸ τῆς Καδμείας.", "st": "2.6"}, {"sp": "N", "t": "Λαμέδων δὲ βασιλεύσας ἔγημεν ἐξ Ἀθηνῶν γυναῖκα Φηνὼ Κλυτίου· καὶ ὕστερον γενομένου οἱ πολέμου πρὸς Ἄρχανδρον καὶ Ἀρχιτέλην τοὺς Ἀχαιοῦ συμμαχήσοντα ἐπηγάγετο Σικυῶνα ἐκ τῆς Ἀττικῆς, καὶ θυγατέρα τε συνῴκισεν αὐτῷ Ζευξίππην καὶ ἀπὸ τούτου βασιλεύσαντος ἡ γῆ Σικυωνία καὶ Σικυὼν ἀντὶ Αἰγιάλης ἡ πόλις ὠνομάσθη. Σικυῶνα δὲ οὐ Μαραθῶνος τοῦ Ἐπωπέως, Μητίονος δὲ εἶναι τοῦ Ἐρεχθέως φασίν. ὁμολογεῖ δέ σφισι καὶ Ἄσιος, ἐπεὶ Ἡσίοδός γε καὶ Ἴβυκος, ὁ μὲν ἐποίησεν ὡς Ἐρεχθέως εἴη Σικυών, Ἴβυκος δὲ εἶναι Πέλοπός φησιν αὐτόν.", "st": "2.6"}, {"sp": "N", "t": "Σικυῶνος δὲ γίνεται Χθονοφύλη, Χθονοφύλης δὲ καὶ Ἑρμοῦ Πόλυβον γενέσθαι λέγουσιν· ὕστερον δὲ αὐτὴν Φλίας ὁ Διονύσου γαμεῖ, καί οἱ παῖς Ἀνδροδάμας γίνεται. Πόλυβος δὲ Ταλαῷ τῷ Βίαντος βασιλεύοντι Ἀργείων Λυσιάνασσαν τὴν θυγατέρα ἔδωκε· καὶ ὅτε Ἄδραστος ἔφευγεν ἐξ Ἄργους, παρὰ Πόλυβον ἦλθεν ἐς Σικυῶνα καὶ ὕστερον ἀποθανόντος Πολύβου τὴν ἐν Σικυῶνι ἀρχὴν ἔσχεν. Ἀδράστου δὲ ἐς Ἄργος κατελθόντος Ἰανίσκος ἀπόγονος Κλυτίου τοῦ Λαμέδοντι κηδεύσαντος ἐλθὼν ἐκ τῆς Ἀττικῆς ἐβασίλευσεν, ἀποθανόντος δὲ Ἰανίσκου Φαῖστος τῶν Ἡρακλέους λεγόμενος παίδων καὶ οὗτος εἶναι.", "st": "2.6"}, {"sp": "N", "t": "Φαίστου δὲ κατὰ μαντείαν μετοικήσαντος ἐς Κρήτην βασιλεῦσαι λέγεται Ζεύξιππος Ἀπόλλωνος υἱὸς καὶ νύμφης Συλλίδος. μετὰ δὲ Ζεύξιππον τελευτήσαντα Ἀγαμέμνων στρατὸν ἤγαγεν ἐπὶ Σικυῶνα καὶ τὸν βασιλέα Ἱππόλυτον Ῥοπάλου παῖδα τοῦ Φαίστου· δείσας δὲ τὸν στρατὸν ἐπιόντα Ἱππόλυτος συνεχώρησεν Ἀγαμέμνονος κατήκοος καὶ Μυκηναίων εἶναι. Ἱππολύτου δὲ ἦν τούτου Λακεστάδης. Φάλκης [ταμφάλκης] δὲ ὁ Τημένου καταλαβὼν νύκτωρ Σικυῶνα σὺν Δωριεῦσι κακὸν μὲν ἅτε Ἡρακλείδην καὶ αὐτὸν ἐποίησεν οὐδέν, κοινωνὸν δὲ ἔσχε τῆς ἀρχῆς.", "st": "2.6"}, {"sp": "N", "t": "καὶ Δωριεῖς μὲν Σικυώνιοι γεγόνασιν ἀπὸ τούτου καὶ μοῖρα τῆς Ἀργείας· τὴν δὲ τοῦ Αἰγιαλέως ἐν τῷ πεδίῳ πόλιν Δημήτριος καθελὼν ὁ Ἀντιγόνου τῇ πάλαι ποτὲ ἀκροπόλει προσῴκισε τὴν νῦν πόλιν. ἐχόντων δὲ ἀσθενῶς ἤδη τῶν Σικυωνίων—αἰτίαν δὲ οὐκ ὀρθῶς ποιοῖ τις ἂν ζητῶν, ἀποχρῷτο δὲ τῷ Ὁμήρῳ λεγομένῳ περὶ Διός,<br>ὃς δὴ πολλάων πολίων κατέλυσε κάρηνα—,<br>διακειμένοις οὖν ἀδυνάτως ἐπιγενόμενος σεισμὸς ὀλίγου τὴν πόλιν ἐποίησεν ἀνδρῶν ἔρημον, πολλὰ δὲ σφᾶς καὶ τῶν ἐς ἐπίδειξιν ἀφείλετο. ἐκάκωσε δὲ καὶ περὶ Καρίαν καὶ Λυκίαν τὰς πόλεις καὶ Ῥοδίοις ἐσείσθη μάλιστα ἡ νῆσος, ὥστε καὶ τὸ λόγιον τετελέσθαι Σιβύλλῃ τὸ ἐς τὴν Ῥόδον ἔδοξεν.", "st": "2.7"}, {"sp": "N", "t": "ἐκ δὲ τῆς Κορινθίας ἐλθοῦσιν ἐς τὴν Σικυωνίαν Λύκου Μεσσηνίου μνῆμά ἐστιν, ὅστις δὴ οὗτος ὁ Λύκος· οὐ γάρ τινα Λύκον εὑρίσκω Μεσσήνιον ἀσκήσαντα πένταθλον οὐδὲ Ὀλυμπικὴν ἀνῃρημένον νίκην. τοῦτο μὲν δὴ χῶμά ἐστι γῆς, αὐτοὶ δὲ Σικυώνιοι τὰ πολλὰ ἐοικότι τρόπῳ θάπτουσι. τὸ μὲν σῶμα γῇ κρύπτουσι, λίθου δὲ ἐποικοδομήσαντες κρηπῖδα κίονας ἐφιστᾶσι καὶ ἐπ’ αὐτοῖς ἐπίθημα ποιοῦσι κατὰ τοὺς ἀετοὺς μάλιστα τοὺς ἐν τοῖς ναοῖς· ἐπίγραμμα δὲ ἄλλο μὲν ἐπιγράφουσιν οὐδέν, τὸ δὲ ὄνομα ἐφ’ αὑτοῦ καὶ οὐ πατρόθεν ὑπειπόντες κελεύουσι τὸν νεκρὸν χαίρειν.", "st": "2.7"}, {"sp": "N", "t": "μετὰ δὲ τὸ μνῆμα τοῦ Λύκου διαβεβηκόσιν ἤδη τὸν Ἀσωπόν, ἔστιν ἐν δεξιᾷ τὸ Ὀλύμπιον, ὀλίγον δὲ ἔμπροσθεν ἐν ἀριστερᾷ τῆς ὁδοῦ τάφος Εὐπόλιδι Ἀθηναίῳ ποιήσαντι κωμῳδίαν. προελθοῦσι δὲ καὶ ἐπιστρέψασιν ὡς ἐπὶ τὴν πόλιν Ξενοδίκης μνῆμά ἐστιν ἀποθανούσης ἐν ὠδῖσι· πεποίηται δὲ οὐ κατὰ τὸν ἐπιχώριον τρόπον, ἀλλ’ ὡς ἂν τῇ γραφῇ μάλιστα ἁρμόζοι· γραφὴ δὲ εἴπερ ἄλλη τις καὶ αὕτη ἐστὶ θέας ἀξία.", "st": "2.7"}, {"sp": "N", "t": "προελθοῦσι δὲ ἐντεῦθεν τάφος Σικυωνίοις ἐστίν, ὅσοι περὶ Πελλήνην καὶ Δύμην τὴν Ἀχαιῶν καὶ ἐν Μεγάλῃ πόλει καὶ περὶ Σελλασίαν ἐτελεύτησαν· τὰ δὲ ἐς αὐτοὺς σαφέστερον ἐν τοῖς ἐφεξῆς δηλώσω. πρὸς δὲ τῇ πύλῃ πηγή ἐστί σφισιν ἐν σπηλαίῳ, ἧς τὸ ὕδωρ οὐκ ἄνεισιν ἐκ γῆς, ἐπιρρεῖ δὲ ἐκ τοῦ ὀρόφου τοῦ σπηλαίου· καὶ καλεῖται δι’ αὐτὸ Στάζουσα ἡ πηγή.", "st": "2.7"}, {"sp": "N", "t": "ἐν δὲ τῇ νῦν ἀκροπόλει Τύχης ἱερόν ἐστιν Ἀκραίας, μετὰ δὲ αὐτὸ Διοσκούρων· ξόανα δὲ οὗτοί τε καὶ τὸ ἄγαλμα τῆς Τύχης ἐστί. τοῦ θεάτρου δὲ ὑπὸ τὴν ἀκρόπολιν ᾠκοδομημένου τὸν ἐν τῇ σκηνῇ πεποιημένον ἄνδρα ἀσπίδα ἔχοντα Ἄρατόν φασιν εἶναι τὸν Κλεινίου. μετὰ δὲ τὸ θέατρον Διονύσου ναός ἐστι· χρυσοῦ μὲν καὶ ἐλέφαντος ὁ θεός, παρὰ δὲ αὐτὸν Βάκχαι λίθου λευκοῦ. ταύτας τὰς γυναῖκας ἱερὰς εἶναι καὶ Διονύσῳ μαίνεσθαι λέγουσιν. ἄλλα δὲ ἀγάλματα ἐν ἀπορρήτῳ Σικυωνίοις ἐστί· ταῦτα μιᾷ καθ’ ἕκαστον ἔτος νυκτὶ ἐς τὸ Διονύσιον ἐκ τοῦ καλουμένου κοσμητηρίου κομίζουσι, κομίζουσι δὲ μετὰ δᾴδων τε ἡμμένων καὶ ὕμνων ἐπιχωρίων.", "st": "2.7"}, {"sp": "N", "t": "ἡγεῖται μὲν οὖν ὃν Βάκχειον ὀνομάζουσιν—Ἀνδροδάμας σφίσιν ὁ Φλάντος τοῦτον ἱδρύσατο—, ἕπεται δὲ ὁ καλούμενος Λύσιος, ὃν Θηβαῖος Φάνης εἰπούσης τῆς Πυθίας ἐκόμισεν ἐκ Θηβῶν. ἐς δὲ Σικυῶνα ἦλθεν ὁ Φάνης, ὅτε Ἀριστόμαχος ὁ Κλεοδαίου τῆς γενομένης μαντείας ἁμαρτὼν δι’ αὐτὸ καὶ καθόδου τῆς ἐς Πελοπόννησον ἥμαρτεν. ἐκ δὲ τοῦ Διονυσίου βαδίζουσιν ἐς τὴν ἀγοράν, ἔστι ναὸς Ἀρτέμιδος ἐν δεξιᾷ Λιμναίας. καὶ ὅτι μὲν κατερρύηκεν ὁ ὄροφος, δῆλά ἐστιν ἰδόντι· περὶ δὲ τοῦ ἀγάλματος οὔτε ὡς κομισθέντος ἑτέρωσε οὔτε ὅντινα αὐτοῦ διεφθάρη τρόπον εἰπεῖν ἔχουσιν.", "st": "2.7"}, {"sp": "N", "t": "ἐς δὲ τὴν ἀγορὰν ἐσελθοῦσι Πειθοῦς ἐστιν ἱερὸν οὐδὲ τοῦτο ἄγαλμα ἔχον. Πειθὼ δὲ ἐπὶ λόγῳ τοιῷδε αὐτοῖς κατέστη σέβεσθαι. Ἀπόλλων καὶ Ἄρτεμις ἀποκτείναντες Πύθωνα παρεγένοντο ἐς τὴν Αἰγιάλειαν καθαρσίων ἕνεκα. γενομένου δέ σφισι δείματος, ἔνθα καὶ νῦν Φόβον ὀνομάζουσι τὸ χωρίον, οἱ μὲν ἐς Κρήτην παρὰ Καρμάνορα ἀπετράποντο, τοὺς δὲ ἀνθρώπους ἐν τῇ Αἰγιαλείᾳ νόσος ἐπέλαβε· καὶ σφᾶς ἐκέλευον οἱ μάντεις Ἀπόλλωνα ἱλάσασθαι καὶ Ἄρτεμιν.", "st": "2.7"}, {"sp": "N", "t": "οἱ δὲ παῖδας ἑπτὰ καὶ ἴσας παρθένους ἐπὶ τὸν Σύθαν ποταμὸν ἀποστέλλουσιν ἱκετεύοντας· ὑπὸ τούτων δὲ πεισθέντας τοὺς θεούς φασιν ἐς τὴν τότε ἀκρόπολιν ἐλθεῖν, καὶ ὁ τόπος ἔνθα πρῶτον ἀφίκοντο Πειθοῦς ἐστιν ἱερόν. τούτοις δὲ ἐοικότα καὶ νῦν ἔτι ποιεῖται· καὶ γὰρ ἐπὶ τὸν Σύθαν ἴασιν οἱ παῖδες τῇ ἑορτῇ τοῦ Ἀπόλλωνος, καὶ ἀγαγόντες δὴ τοὺς θεοὺς ἐς τὸ τῆς Πειθοῦς ἱερὸν αὖθις ἀπάγειν ἐς τὸν ναόν φασι τοῦ Ἀπόλλωνος. ὁ δὲ ναὸς ἔστι μὲν ἐν τῇ νῦν ἀγορᾷ, τὸ δὲ ἐξ ἀρχῆς λέγουσιν αὐτὸν ὑπὸ Προίτου ποιηθῆναι· τὰς γάρ οἱ θυγατέρας ἐνταῦθα τῆς μανίας παύσασθαι.", "st": "2.7"}, {"sp": "N", "t": "λέγουσι δὲ καὶ τάδε, ὡς Μελέαγρος ἐς τοῦτον τὸν ναὸν ἀνέθηκε τὴν λόγχην ᾗ τὸν ὗν κατειργάσατο. καὶ αὐλοὺς ἀνατεθῆναί φασιν ἐνταῦθα τοὺς Μαρσύου· γενομένης γὰρ τῷ Σιληνῷ τῆς συμφορᾶς τὸν ποταμὸν τὸν Μαρσύαν κατενεγκεῖν αὐτοὺς ἐς τὸν Μαίανδρον, ἀναφανέντας δὲ ἐν τῷ Ἀσωπῷ καὶ κατὰ τὴν Σικυωνίαν ἐκπεσόντας ὑπὸ ποιμένος τοῦ εὑρόντος δοθῆναι τῷ Ἀπόλλωνι. τούτων τῶν ἀναθημάτων οὐδὲν ἔτι ἐλείπετο, συγκατεκαύθη γὰρ ἐμπιπραμένῳ τῷ ναῷ· τὸν δὲ ἐπ’ ἐμοῦ ναὸν καὶ τὸ ἄγαλμα Πυθοκλῆς ἀνέθηκεν.", "st": "2.7"}, {"sp": "N", "t": "τῷ δὲ τῆς Πειθοῦς ἱερῷ τὸ ἐγγὺς τέμενος ἀνειμένον βασιλεῦσι Ῥωμαίων οἰκία ποτὲ ἦν Κλέωνος τυράννου· Κλεισθένης μὲν γὰρ ὁ Ἀριστωνύμου τοῦ Μύρωνος ἐχόντων ἔτι τὴν κάτω πόλιν Σικυωνίων ἐτυράννησε, Κλέων δὲ ἐν τῇ νῦν πόλει. πρὸ ταύτης τῆς οἰκίας ἡρῷόν ἐστιν Ἀράτου μέγιστα Ἑλλήνων ἐργασαμένου τῶν ἐφ’ αὑτοῦ· ἔχει δὲ ὧδε τὰ ἐς αὐτόν.", "st": "2.8"}, {"sp": "N", "t": "μετὰ Κλέωνα μοναρχήσαντα ἐνέπεσε τῶν ἐν τέλει πολλοῖς ἐπιθυμία τυραννίδος οὕτω δή τι ἀκάθεκτος ὡς καὶ ἄνδρας δύο Εὐθύδημον καὶ Τιμοκλείδαν ὁμοῦ τυραννῆσαι. τούτους μὲν οὖν ἐξέβαλεν ὁ δῆμος, Κλεινίαν τὸν πατέρα Ἀράτου προστησάμενος· ἔτεσι δὲ ὕστερον οὐ πολλοῖς ἐτυράννησεν Ἀβαντίδας. Κλεινίᾳ μὲν οὖν συνεβεβήκει πρότερον ἔτι ἡ τελευτή· Ἄρατον δὲ Ἀβαντίδας φυγάδα ἐποίησεν, ἢ καὶ αὐτὸς ἀπεχώρησεν Ἄρατος ἐθελοντής. Ἀβαντίδαν μὲν οὖν κτείνουσιν ἄνδρες τῶν ἐπιχωρίων, τύραννος δὲ αὐτίκα ἐγεγόνει ὁ Ἀβαντίδου πατὴρ Πασέας·", "st": "2.8"}, {"sp": "N", "t": "Νικοκλῆς δὲ ἐκεῖνον ἀνελὼν ἐτυράννησεν αὐτός. ἐπὶ τοῦτον τὸν Νικοκλέα Ἄρατος ἀφικόμενος Σικυωνίων φυγάσι καὶ Ἀργείοις μισθωτοῖς τοὺς μὲν ἔλαθεν ἅτε ἐν σκότῳ—νύκτωρ γὰρ δὴ τὴν ἐπιχείρησιν ἐποιεῖτο—, τοὺς δὲ καὶ βιασάμενος τῶν φυλασσόντων ἐγένετο ἐντὸς τείχους· καὶ —ὑπέφαινε γὰρ ἕως ἤδη—προσλαβὼν τὸν δῆμον ἐπὶ τὴν οἰκίαν σπουδῇ τὴν τυραννικὴν τρέπεται. καὶ ταύτην μὲν εἷλεν οὐ χαλεπῶς, ὁ δὲ Νικοκλῆς αὐτὸς ἔλαθεν ἀποδράς. Σικυωνίοις δὲ ἀπέδωκεν Ἄρατος ἐξ ἴσου πολιτεύεσθαι διαλλάξας τοῖς φεύγουσιν, οἰκίας μὲν φυγάσι καὶ ὅσα τῶν κτημάτων ἄλλα [ἃ] ἐπέπρατο ἀποδούς, τιμὴν δὲ τοῖς πριαμένοις διέλυσεν αὐτός.", "st": "2.8"}, {"sp": "N", "t": "καὶ—ἦν γὰρ δέος τοῖς πᾶσιν Ἕλλησι Μακεδόνων καὶ Ἀντιγόνου Φίλιππον ἐπιτροπεύοντος τὸν Δημητρίου—, τοῦδε ἕνεκα τοὺς Σικυωνίους ἐς τὸ Ἀχαιῶν συνέδριον ἐσήγαγε Δωριεῖς ὄντας. αὐτίκα δὲ στρατηγὸς ὑπὸ τῶν Ἀχαιῶν ᾕρητο, καὶ σφᾶς ἐπὶ Λοκροὺς τοὺς Ἀμφισσέας ἀγαγὼν καὶ ἐς τὴν Αἰτωλῶν πολεμίων ὄντων τὴν γῆν ἐπόρθησε· Κόρινθον δὲ ἔχοντος Ἀντιγόνου καὶ φρουρᾶς Μακεδόνων ἐνούσης τοὺς Μακεδόνας τῷ αἰφνιδίῳ τῆς ἐπιθέσεως κατέπληξε καὶ ἄλλους τε κρατήσας μάχῃ διέφθειρε καὶ Περσαῖον ἐπὶ τῇ φρουρᾷ τεταγμένον, ὃς παρὰ Ζήνωνα τὸν Μνασέου κατὰ μάθησιν σοφίας ἐφοίτησεν.", "st": "2.8"}, {"sp": "N", "t": "ἐλευθερώσαντος δὲ Ἀράτου Κόρινθον προσεχώρησαν μὲν ἐς τὸ συνέδριον Ἐπιδαύριοι καὶ Τροιζήνιοι οἱ τὴν Ἀργολίδα Ἀκτὴν οἰκοῦντες καὶ τῶν ἐκτὸς ἰσθμοῦ Μεγαρεῖς, συμμαχίαν δὲ πρὸς Ἀχαιοὺς Πτολεμαῖος ἐποιήσατο. Λακεδαιμόνιοι δὲ καὶ Ἆγις ὁ Εὐδαμίδου βασιλεὺς ἔφθησαν μὲν Πελλήνην ἑλόντες ἐξ ἐπιδρομῆς, ἥκοντι δὲ Ἀράτῳ καὶ τῇ στρατιᾷ συμβαλόντες ἐκρατήθησαν καὶ τὴν Πελλήνην ἐκλιπόντες ἀναχωροῦσιν οἴκαδε ὑπόσπονδοι.", "st": "2.8"}, {"sp": "N", "t": "Ἄρατος δέ, ὥς οἱ τὰ ἐν Πελοποννήσῳ προεκεχωρήκει, δεινὸν ἡγεῖτο Πειραιᾶ καὶ Μουνυχίαν, ἔτι δὲ Σαλαμῖνα καὶ Σούνιον ἐχόμενα ὑπὸ Μακεδόνων περιοφθῆναι, καὶ—οὐ γὰρ ἤλπιζε δύνασθαι πρὸς βίαν αὐτὰ ἐξελεῖν—Διογένην πείθει τὸν ἐν τοῖς φρουροῖς ἄρχοντα ἀφεῖναι τὰ χωρία ἐπὶ ταλάντοις πεντήκοντα καὶ ἑκατόν, καὶ τῶν χρημάτων συνετέλεσεν αὐτὸς Ἀθηναίοις ἕκτον μέρος. ἔπεισε δὲ καὶ Ἀριστόμαχον τυραννοῦντα ἐν Ἄργει δημοκρατίαν ἀποδόντα Ἀργείοις ἐς τὸ Ἀχαϊκὸν συντελεῖν, Μαντίνειάν τε Λακεδαιμονίων ἐχόντων εἷλεν. ἀλλὰ γὰρ οὐ πάντα ἀνθρώπῳ τελεῖται κατὰ γνώμην, εἰ δὴ καὶ Ἄρατον κατέλαβεν ἀνάγκη γενέσθαι Μακεδόνων καὶ Ἀντιγόνου σύμμαχον· ἐγένετο δὲ οὕτως.", "st": "2.8"}, {"sp": "N", "t": "Κλεομένης ὁ Λεωνίδου τοῦ Κλεωνύμου παραλαβὼν τὴν βασιλείαν ἐν Σπάρτῃ Παυσανίαν ἐμιμεῖτο τυραννίδος τε ἐπιθυμῶν καὶ νόμοις τοῖς καθεστηκόσιν οὐκ ἀρεσκόμενος. ἅτε δὲ ὄντι αὐτῷ Παυσανίου θερμοτέρῳ καὶ οὐ φιλοψύχῳ ταχὺ τὰ πάντα ὑπὸ φρονήματος καὶ τόλμης κατείργαστο, καὶ βασιλέα τε οἰκίας τῆς ἑτέρας Εὐρυδαμίδαν παῖδα ἔτι ἀνελὼν φαρμάκῳ διὰ τῶν ἐφορευόντων ἐς Ἐπικλείδαν τὸν ἀδελφὸν μετέστησε τὴν ἀρχὴν καὶ τὸ κράτος τῆς γερουσίας καταλύσας πατρονόμους τῷ λόγῳ κατέστησεν ἀντ’ αὐτῶν. ἐπιθυμῶν δὲ πραγμάτων μειζόνων καὶ ἀρχῆς τῶν Ἑλλήνων, ἐπέθετο Ἀχαιοῖς πρώτοις, συμμάχους ἐλπίζων ἕξειν ἢν κρατήσῃ καὶ μάλιστα ἐμποδὼν οὐκ ἐθέλων εἶναί οἱ τοῖς δρωμένοις.", "st": "2.9"}, {"sp": "N", "t": "συμβαλὼν δὲ περὶ Δύμην τὴν ὑπὲρ Πατρῶν, Ἀράτου καὶ τότε ἡγουμένου τῶν Ἀχαιῶν, νικᾷ τῇ μάχῃ. τοῦτο Ἄρατον ἠνάγκασεν ὑπέρ τε Ἀχαιῶν καὶ αὐτῆς Σικυῶνος δείσαντα Ἀντίγονον ἐπάγεσθαι. Κλεομένους δὲ παραβάντος ἣν πρὸς Ἀντίγονον συνέθετο εἰρήνην καὶ παράσπονδα ἐκ τοῦ φανεροῦ καὶ ἄλλα δράσαντος καὶ Μεγαλοπολίτας ποιήσαντος ἀναστάτους, οὕτω διαβάντος ἐς Πελοπόννησον Ἀντιγόνου συμβάλλουσιν Ἀχαιοὶ Κλεομένει περὶ Σελλασίαν. νικησάντων δὲ τῶν Ἀχαιῶν Σελλασία τε ἠνδραποδίσθη καὶ αὐτὴ Λακεδαίμων ἑάλω. Λακεδαιμονίοις μὲν οὖν ἀπέδωκεν Ἀντίγονος καὶ Ἀχαιοὶ πολιτείαν τὴν πάτριον·", "st": "2.9"}, {"sp": "N", "t": "τῶν δὲ Λεωνίδου παίδων Ἐπικλείδας μὲν ἀπέθανεν ἐν τῇ μάχῃ, Κλεομένην δὲ φεύγοντα ἐς Αἴγυπτον καὶ τιμῆς παρὰ Πτολεμαίῳ πρῶτα ἔχοντα συνέβη δεθῆναι, καταγνωσθέντα Αἰγυπτίων ἄνδρας ἐπὶ τὸν βασιλέα συνιστάναι. καὶ ἀπέδρα μὲν ἐκ τοῦ δεσμωτηρίου καὶ τοῖς Ἀλεξανδρεῦσιν ἀρχὴν θορύβου παρέσχε· τέλος δέ, ὡς ἡλίσκετο, ἀπέσφαξεν αὑτόν. Λακεδαιμόνιοι δὲ ἄσμενοι Κλεομένους ἀπαλλαγέντες βασιλεύεσθαι μὲν οὐκέτι ἠξίωσαν, τὰ δὲ λοιπὰ καὶ ἐς τόδε διαμένει σφίσιν ἐκείνης τῆς πολιτείας. Ἀράτῳ δὲ Ἀντίγονος ἅτε ἀνδρὶ εὐεργέτῃ καὶ συγκατειργασμένῳ λαμπρὰ οὕτω διέμεινεν εὔνους.", "st": "2.9"}, {"sp": "N", "t": "Φίλιππος δὲ ὡς παρέλαβε τὴν ἀρχήν —οὐ γὰρ αὐτὸν Ἄρατος θυμῷ πολλὰ ἐς τοὺς ἀρχομένους χρώμενον ἐπῄνει, τὰ δὲ καὶ ὡρμημένον ἐπεῖχε μὴ ποιεῖν—, τούτων ἕνεκεν ἀπέκτεινεν Ἄρατον, οὐδὲν προϊδομένῳ δούς οἱ φάρμακον. καὶ τὸν μὲν ἐξ Αἰγίου —ταύτῃ γὰρ τὸ χρεὼν ἐπέλαβεν αὐτὸν—ἐς Σικυῶνα κομίσαντες θάπτουσι, καὶ τὸ ἡρῷον Ἀράτειον ἔτι ὀνομάζεται· Φιλίππῳ δὲ καὶ ἐς Εὐρυκλείδην καὶ Μίκωνα Ἀθηναίους ὅμοια εἰργάσθη· καὶ γὰρ τούσδε ὄντας ῥήτορας καὶ οὐκ ἀπιθάνους τῷ δήμῳ φαρμάκοις ἔκτεινεν.", "st": "2.9"}, {"sp": "N", "t": "ἔμελλε δὲ ἄρα καὶ αὐτῷ Φιλίππῳ τὸ ἀνδροφόνον φάρμακον ἔσεσθαι συμφορά· τὸν γάρ οἱ παῖδα Δημήτριον ὁ νεώτερος τῶν Φιλίππου παίδων Περσεὺς φαρμάκῳ διέφθειρε καὶ δι’ αὐτὸ καὶ τῷ πατρὶ ἀθυμήσαντι παρέσχεν αἰτίαν ἀποθανεῖν. παρεδήλωσα δὲ τάδε ἀπιδὼν ἐς ⟨τὸ⟩ Ἡσιόδου σὺν θεῷ πεποιημένον, τὸν ἐπ’ ἄλλῳ βουλεύοντα ἄδικα ἐς αὑτὸν πρῶτον τρέπειν.", "st": "2.9"}, {"sp": "N", "t": "μετὰ δὲ ⟨τὸ⟩ Ἀράτου ἡρῷον ἔστι μὲν Ποσειδῶνι Ἰσθμίῳ βωμός, ἔστι δὲ Ζεὺς Μειλίχιος καὶ Ἄρτεμις ὀνομαζομένη Πατρῴα, σὺν τέχνῃ πεποιημένα οὐδεμιᾷ· πυραμίδι δὲ ὁ Μειλίχιος, ἡ δὲ κίονί ἐστιν εἰκασμένη. ἐνταῦθα καὶ βουλευτήριόν σφισι πεποίηται καὶ στοὰ καλουμένη Κλεισθένειος ἀπὸ τοῦ οἰκοδομήσαντος· ᾠκοδόμησε δὲ ἀπὸ λαφύρων ὁ Κλεισθένης αὐτὴν τὸν πρὸς Κίρρᾳ πόλεμον συμπολεμήσας Ἀμφικτύοσι. τῆς δὲ ἀγορᾶς ἐστιν ἐν τῷ ὑπαίθρῳ Ζεὺς χαλκοῦς, τέχνη Λυσίππου, παρὰ δὲ αὐτὸν Ἄρτεμις ἐπίχρυσος.", "st": "2.9"}, {"sp": "N", "t": "πλησίον δὲ Ἀπόλλωνός ἐστιν ἱερὸν Λυκίου, κατερρυηκός τε ἤδη καὶ ἥκιστα θέας ἄξιον. φοιτώντων γὰρ λύκων σφίσιν ἐπὶ τὰς ποίμνας ὡς μηδένα εἶναι καρπὸν ἔτι ἀπ’ αὐτῶν, ὁ θεὸς τόπον τινὰ εἰπὼν ἔνθα ἔκειτο αὖον ξύλον, τούτου φλοιὸν ἔχρησε τοῦ ξύλου καὶ κρέας ὁμοῦ προθεῖναι τοῖς θηρίοις· καὶ τοὺς μὲν αὐτίκα ὡς ἐγεύσαντο διέφθειρεν ὁ φλοιός, τὸ ξύλον δὲ ἐκεῖνο ἔκειτο μὲν ἐν τῷ ἱερῷ τοῦ Λυκίου, ὅ τι δὲ ἦν δένδρον οὐδὲ οἱ τῶν Σικυωνίων ἐξηγηταὶ συνίεσαν.", "st": "2.9"}, {"sp": "N", "t": "τούτου δέ εἰσιν εἰκόνες ἐφεξῆς χαλκαῖ· τὰς Προίτου θυγατέρας λέγουσιν εἶναι σφᾶς, τὸ δὲ ἐπίγραμμα ἐς γυναῖκας ἄλλας εἶχεν. ἐνταῦθα Ἡρακλῆς χαλκοῦς ἐστι· Λύσιππος ἐποίησεν αὐτὸν Σικυώνιος, καὶ πλησίον Ἑρμῆς ἕστηκεν Ἀγοραῖος.", "st": "2.9"}, {"sp": "N", "t": "ἐν δὲ τῷ γυμνασίῳ τῆς ἀγορᾶς ὄντι οὐ μακρὰν Ἡρακλῆς ἀνάκειται λίθου, Σκόπα ποίημα. ἔστι δὲ καὶ ἑτέρωθι ἱερὸν Ἡρακλέους· τὸν μὲν πάντα ἐνταῦθα περίβολον Παιδιζὴν ὀνομάζουσιν, ἐν μέσῳ δέ ἐστι τῷ περιβόλῳ τὸ ἱερόν, ἐν δὲ αὐτῷ ξόανον ἀρχαῖον, τέχνη Φλιασίου Λαφάους. ἐπὶ δὲ τῇ θυσίᾳ τοιάδε δρᾶν νομίζουσι. Φαῖστον ἐν Σικυωνίᾳ λέγουσιν ἐλθόντα καταλαβεῖν Ἡρακλεῖ σφᾶς ὡς ἥρωι ἐναγίζοντας· οὔκουν ἠξίου δρᾶν οὐδὲν ὁ Φαῖστος τῶν αὐτῶν, ἀλλ’ ὡς θεῷ θύειν. καὶ νῦν ἔτι ἄρνα οἱ Σικυώνιοι σφάξαντες καὶ τοὺς μηροὺς ἐπὶ τοῦ βωμοῦ καύσαντες τὰ μὲν ἐσθίουσιν ὡς ἀπὸ ἱερείου, τὰ δὲ ὡς ἥρωι τῶν κρεῶν ἐναγίζουσι. τῆς ἑορτῆς δέ, ἣν ἄγουσι τῷ Ἡρακλεῖ, τὴν προτέραν τῶν ἡμερῶν †ὀνόματα ὀνομάζοντες Ἡράκλεια δὴ καλοῦσι τὴν ὑστέραν.", "st": "2.10"}, {"sp": "N", "t": "ἐντεῦθέν ἐστιν ὁδὸς ἐς ἱερὸν Ἀσκληπιοῦ. παρελθοῦσι δὲ ἐς τὸν περίβολον ἐν ἀριστερᾷ διπλοῦν ἐστιν οἴκημα· κεῖται δὲ Ὕπνος ἐν τῷ προτέρῳ, καί οἱ πλὴν τῆς κεφαλῆς ἄλλο οὐδὲν ἔτι λείπεται. τὸ ἐνδοτέρω δὲ Ἀπόλλωνι ἀνεῖται Καρνείῳ, καὶ ἐς αὐτὸ οὐκ ἔστι πλὴν τοῖς ἱερεῦσιν ἔσοδος. κεῖται δὲ ἐν τῇ στοᾷ κήτους ὀστοῦν θαλασσίου μεγέθει μέγα καὶ μετ’ αὐτὸ ἄγαλμα Ὀνείρου καὶ Ὕπνος κατακοιμίζων λέοντα, Ἐπιδώτης δὲ ἐπίκλησιν. ἐς δὲ τὸ Ἀσκληπιεῖον ἐσιοῦσι καθ’ ἕτερον τῆς ἐσόδου τῇ μὲν Πανὸς καθήμενον ἄγαλμά ἐστι, τῇ δὲ Ἄρτεμις ἕστηκεν.", "st": "2.10"}, {"sp": "N", "t": "ἐσελθοῦσι δὲ ὁ θεός ἐστιν οὐκ ἔχων γένεια, χρυσοῦ καὶ ἐλέφαντος, Καλάμιδος δὲ ἔργον· ἔχει δὲ καὶ σκῆπτρον καὶ ἐπὶ τῆς ἑτέρας χειρὸς πίτυος καρπὸν τῆς ἡμέρου. φασὶ δέ σφισιν ἐξ Ἐπιδαύρου κομισθῆναι τὸν θεὸν ἐπὶ ζεύγους ἡμιόνων δράκοντι εἰκασμένον, τὴν δὲ ἀγαγοῦσαν Νικαγόραν εἶναι Σικυωνίαν Ἀγασικλέους μητέρα, γυναῖκα δὲ Ἐχετίμου. ἐνταῦθα ἀγάλματά ἐστιν οὐ μεγάλα ἀπηρτημένα τοῦ ὀρόφου· τὴν δὲ ἐπὶ τῷ δράκοντι Ἀριστοδάμαν Ἀράτου μητέρα εἶναι λέγουσι καὶ Ἄρατον Ἀσκληπιοῦ παῖδα εἶναι νομίζουσιν.", "st": "2.10"}, {"sp": "N", "t": "οὗτος μὲν δὴ παρείχετο ὁ περίβολος τοσάδε ἐς μνήμην, ⟨πέραν δὲ⟩ [δι’] αὐτοῦ [δὲ] ἄλλος ἐστὶν Ἀφροδίτης ἱερός· ἐν δὲ αὐτῷ πρῶτον ἄγαλμά ἐστιν Ἀντιόπης· εἶναι γάρ οἱ τοὺς παῖδας Σικυωνίους καὶ δι’ ἐκείνους ἐθέλουσι καὶ αὐτὴν Ἀντιόπην προσήκειν σφίσι. μετὰ τοῦτο ἤδη τὸ τῆς Ἀφροδίτης ἐστὶν ἱερόν. ἐσίασι μὲν δὴ ἐς αὐτὸ γυνή τε νεωκόρος, ᾗ μηκέτι θέμις παρ’ ἄνδρα φοιτῆσαι, καὶ παρθένος ἱερωσύνην ἐπέτειον ἔχουσα· λουτροφόρον τὴν παρθένον ὀνομάζουσι· τοῖς δὲ ἄλλοις κατὰ ταὐτὰ καὶ ὁρᾶν ἀπὸ τῆς ἐσόδου τὴν θεὸν καὶ αὐτόθεν προσεύχεσθαι.", "st": "2.10"}, {"sp": "N", "t": "τὸ μὲν δὴ ἄγαλμα καθήμενον Κάναχος Σικυώνιος ἐποίησεν, ὃς καὶ τὸν ἐν Διδύμοις τοῖς Μιλησίων καὶ Θηβαίοις τὸν Ἰσμήνιον εἰργάσατο Ἀπόλλωνα· πεποίηται δὲ ἔκ τε χρυσοῦ καὶ ἐλέφαντος, φέρουσα ἐπὶ τῇ κεφαλῇ πόλον, τῶν χειρῶν δὲ ἔχει τῇ μὲν μήκωνα τῇ δὲ ἑτέρᾳ μῆλον. τῶν δὲ ἱερείων τοὺς μηροὺς θύουσι πλὴν ὑῶν, τἄλλα δὲ ἀρκεύθου ξύλοις καθαγίζουσι, καιομένοις δὲ ὁμοῦ τοῖς μηροῖς φύλλον τοῦ παιδέρωτος συγκαθαγίζουσιν.", "st": "2.10"}, {"sp": "N", "t": "ἔνεστι δὲ ὁ παιδέρως ἐν ὑπαίθρῳ τοῦ περιβόλου πόα, φύεται δὲ ἀλλαχόθι οὐδαμοῦ γῆς, οὔτε ἄλλης οὔτε τῆς Σικυωνίας. τὰ δέ οἱ φύλλα ἐλάσσονα ἢ φηγοῦ, μείζονα δέ ἐστιν ἢ πρίνου, σχῆμα δέ σφισιν οἷον τοῖς τῆς δρυός· καὶ τὸ μὲν ὑπομελαίνει, τὸ δὲ ἕτερον λευκόν ἐστι· φύλλοις δ’ ἂν λεύκης μάλιστα εἰκάζοις τὴν χροιάν.", "st": "2.10"}, {"sp": "N", "t": "ἀπὸ τούτων δὲ ἀνιοῦσιν ἐς τὸ γυμνάσιον, ἔστιν ἐν δεξιᾷ Φεραίας ἱερὸν Ἀρτέμιδος· κομισθῆναι δὲ τὸ ξόανον λέγουσιν ἐκ Φερῶν. τὸ δέ σφισι γυμνάσιον τοῦτο Κλεινίας ᾠκοδόμησε, καὶ παιδεύουσιν ἐνταῦθα ἔτι τοὺς ἐφήβους. κεῖται δὲ λίθου λευκοῦ καὶ Ἄρτεμις τὰ ἐς ἰξὺν μόνον εἰργασμένη καὶ Ἡρακλῆς τὰ κάτω τοῖς Ἑρμαῖς τοῖς τετραγώνοις εἰκασμένος.", "st": "2.10"}, {"sp": "N", "t": "ἐντεῦθεν δὲ ἀποτραπεῖσιν ἐπὶ πύλην καλουμένην Ἱεράν, οὐ πόρρω τῆς πύλης ναός ἐστιν Ἀθηνᾶς, ὃν Ἐπωπεύς ποτε ἀνέθηκε μεγέθει καὶ κόσμῳ τοὺς τότε ὑπερβεβλημένον. ἔδει δὲ ἄρα χρόνῳ καὶ τοῦδε ἀφανισθῆναι τὴν μνήμην· κεραυνοῖς θεὸς αὐτὸν ⟨κατέκαυσε,⟩ βωμὸς δὲ ἐκεῖνος—οὐ γάρ τι ἐς αὐτὸν κατέσκηψε— μένει καὶ ἐς τόδε οἷον Ἐπωπεὺς ἐποίησε. πρὸ τοῦ βωμοῦ δὲ αὐτῷ μνῆμα Ἐπωπεῖ κέχωσται, καὶ τοῦ τάφου πλησίον εἰσὶν Ἀποτρόπαιοι θεοί· παρὰ τούτοις δρῶσιν ὅσα Ἕλληνες ἐς ἀποτροπὴν κακῶν νομίζουσιν. Ἐπωπέα δὲ καὶ Ἀρτέμιδι καὶ Ἀπόλλωνι τὸ πλησίον ἱερὸν ποιῆσαι λέγουσι, τὸ δὲ μετ’ αὐτὸ Ἥρας Ἄδραστον· ἀγάλματα δὲ ὑπελείπετο οὐδετέρῳ. βωμοὺς δὲ ὄπισθεν τοῦ Ἡραίου τὸν μὲν Πανὶ ᾠκοδόμησεν, Ἡλίῳ δὲ λίθου λευκοῦ.", "st": "2.11"}, {"sp": "N", "t": "καταβαίνουσι δὲ ὡς ἐπὶ τὸ πεδίον, ἱερόν ἐστιν ἐνταῦθα Δήμητρος· ἱδρῦσαι δέ φασιν αὐτὸ Πλημναῖον ἀποδιδόντα χάριν τῇ θεῷ τοῦ παιδὸς τῆς τροφῆς. τοῦ δὲ ἱεροῦ τῆς Ἥρας, ἣν ἱδρύσατο Ἄδραστος, ὀλίγον ἀπωτέρω Καρνείου ναός ἐστιν Ἀπόλλωνος· κίονες δὲ ἑστήκασιν ἐν αὐτῷ μόνοι, τοίχους δὲ οὐκέτι οὐδὲ ὄροφον οὔτε ἐνταῦθα εὑρήσεις οὔτε ἐν τῷ τῆς Προδρομίας Ἥρας. τοῦτον γὰρ δὴ Φάλκης ἱδρύσατο ὁ Τημένου, τῆς ὁδοῦ οἱ τῆς ἐς Σικυῶνα Ἥραν φάμενος ὁδηγὸν γενέσθαι.", "st": "2.11"}, {"sp": "N", "t": "ἐκ Σικυῶνος δὲ τὴν κατ’ εὐθὺ ἐς Φλιοῦντα ἐρχομένοις καὶ ἐν ἀριστερᾷ τῆς ὁδοῦ δέκα μάλιστα ἐκτραπεῖσι στάδια, Πυραία καλούμενόν ἐστιν ἄλσος, ἱερὸν δὲ ἐν αὐτῷ Προστασίας Δήμητρος καὶ Κόρης. ἐνταῦθα ἐφ’ αὑτῶν οἱ ἄνδρες ἑορτὴν ἄγουσι, τὸν δὲ Νυμφῶνα καλούμενον ταῖς γυναιξὶν ἑορτάζειν παρείκασι· καὶ ἀγάλματα Διονύσου καὶ Δήμητρος καὶ Κόρης τὰ πρόσωπα φαίνοντα ἐν τῷ Νυμφῶνί ἐστιν. ἡ δὲ ἐς Τιτάνην ὁδὸς σταδίων μέν ἐστιν ἑξήκοντα καὶ ζεύγεσιν ἄβατος διὰ στενότητα·", "st": "2.11"}, {"sp": "N", "t": "σταδίους ⟨δὲ⟩ προελθοῦσιν ἐμοὶ δοκεῖν εἴκοσι καὶ ἐν ἀριστερᾷ διαβᾶσι τὸν Ἀσωπόν, ἔστιν ἄλσος πρίνων καὶ ναὸς θεῶν ἃς Ἀθηναῖοι Σεμνὰς, Σικυώνιοι δὲ Εὐμενίδας ὀνομάζουσι· κατὰ δὲ ἔτος ἕκαστον ἑορτὴν ἡμέρᾳ μιᾷ σφισιν ἄγουσι θύοντες πρόβατα ἐγκύμονα, μελικράτῳ δὲ σπονδῇ καὶ ἄνθεσιν ἀντὶ στεφάνων χρῆσθαι νομίζουσιν. ἐοικότα δὲ καὶ ἐπὶ τῷ βωμῷ τῶν Μοιρῶν δρῶσιν· ὁ δέ σφισιν ἐν ὑπαίθρῳ τοῦ ἄλσους ἐστίν.", "st": "2.11"}, {"sp": "N", "t": "ἀναστρέψασι δὲ ἐς τὴν ὁδὸν διαβᾶσί τε αὖθις τὸν Ἀσωπὸν καὶ ἐς κορυφὴν ὄρους ἥξασιν, ἐνταῦθα λέγουσιν οἱ ἐπιχώριοι Τιτᾶνα οἰκῆσαι πρῶτον· εἶναι δὲ αὐτὸν ἀδελφὸν Ἡλίου καὶ ἀπὸ τούτου κληθῆναι Τιτάνην τὸ χωρίον. δοκεῖν δὲ ἐμοὶ δεινὸς ἐγένετο ὁ Τιτὰν τὰς ὥρας τοῦ ἔτους φυλάξας καὶ ὁπότε ἥλιος σπέρματα καὶ δένδρων αὔξει καὶ πεπαίνει καρπούς, καὶ ἐπὶ τῷδε ἀδελφὸς ἐνομίσθη τοῦ Ἡλίου. ὕστερον δὲ Ἀλεξάνωρ ὁ Μαχάονος τοῦ Ἀσκληπιοῦ παραγενόμενος ἐς Σικυωνίαν ἐν Τιτάνῃ τὸ Ἀσκληπιεῖον ἐποίησε.", "st": "2.11"}, {"sp": "N", "t": "περιοικοῦσι μὲν δὴ καὶ ἄλλοι καὶ τὸ πολὺ οἰκέται τοῦ θεοῦ, καὶ κυπαρίσσων ἐστὶν ἐντὸς τοῦ περιβόλου δένδρα ἀρχαῖα· τὸ δὲ ἄγαλμα οὔτε ὁποίου ξύλου γέγονεν ἢ μετάλλου μαθεῖν ἔστιν οὔτε τὸν ποιήσαντα ἴσασι, πλὴν εἰ μή τις ἄρα ἐς αὐτὸν τὸν Ἀλεξάνορα ἀναφέροι. φαίνεται δὲ τοῦ ἀγάλματος πρόσωπον μόνον καὶ ἄκραι χεῖρες καὶ πόδες· χιτὼν γάρ οἱ λευκὸς ἐρεοῦς καὶ ἱμάτιον ἐπιβέβληται. καὶ Ὑγείας δ’ ἔστι κατὰ ταὐτὸν ἄγαλμα· οὐκ ἂν οὐδὲ τοῦτο ἴδοις ῥᾳδίως, οὕτω περιέχουσιν αὐτὸ κόμαι τε γυναικῶν αἳ κείρονται τῇ θεῷ καὶ ἐσθῆτος Βαβυλωνίας τελαμῶνες. ᾧ δ’ ἂν ἐνταῦθα τούτων ἱλάσασθαι θελήσῃ τις, ἀποδέδεικταί οἱ τὸ αὐτὸ σέβεσθαι τοῦτο ὃ δὴ καὶ Ὑγείαν καλοῦσι.", "st": "2.11"}, {"sp": "N", "t": "τῷ δὲ Ἀλεξάνορι καὶ Εὐαμερίωνι—καὶ γὰρ τούτοις ἀγάλματά ἐστι—τῷ μὲν ὡς ἥρωι μετὰ ἥλιον δύναντα ἐναγίζουσιν, Εὐαμερίωνι δὲ ὡς θεῷ θύουσιν. εἰ δὲ ὀρθῶς εἰκάζω, τὸν Εὐαμερίωνα τοῦτον Περγαμηνοὶ Τελεσφόρον ἐκ μαντεύματος, Ἐπιδαύριοι δὲ Ἄκεσιν ὀνομάζουσι. τῆς δὲ Κορωνίδος ἔστι μὲν καὶ ταύτης ξόανον, καθίδρυται δὲ οὐδαμοῦ τοῦ ναοῦ· θυομένων δὲ τῷ θεῷ ταύρου καὶ ἀρνὸς καὶ ὑὸς ἐς Ἀθηνᾶς ἱερὸν τὴν Κορωνίδα μετενεγκόντες ἐνταῦθα τιμῶσιν. ὁπόσα δὲ τῶν θυομένων καθαγίζουσιν, οὐδὲ ἀποχρᾷ σφισιν ἐκτέμνειν τοὺς μηρούς· χαμαὶ δὲ καίουσι πλὴν τοὺς ὄρνιθας, τούτους δὲ ἐπὶ τοῦ βωμοῦ.", "st": "2.11"}, {"sp": "N", "t": "τὰ δὲ ἐν τοῖς ἀετοῖς Ἡρακλῆς καὶ Νῖκαι πρὸς τοῖς πέρασίν εἰσιν. ἀνάκειται δὲ ἀγάλματα ἐν τῇ στοᾷ Διονύσου καὶ Ἑκάτης, Ἀφροδίτη τε καὶ Μήτηρ θεῶν καὶ Τύχη· ταῦτα μὲν ξόανα, λίθου δὲ Ἀσκληπιὸς ἐπίκλησιν Γορτύνιος. παρὰ δὲ τοὺς δράκοντας ἐσιέναι τοὺς ἱεροὺς οὐκ ἐθέλουσιν ὑπὸ δείματος· καταθέντες δέ σφισι πρὸ τῆς ἐσόδου τροφὴν οὐκέτι πολυπραγμονοῦσι. κεῖται δὲ χαλκοῦς ἀνὴρ ἐντὸς τοῦ περιβόλου Γρανιανὸς Σικυώνιος, ὃς νίκας ἀνείλετο Ὀλυμπίασι δύο μὲν πεντάθλου καὶ σταδίου τὴν τρίτην, διαύλου δὲ ἀμφότερα καὶ γυμνὸς καὶ μετὰ τῆς ἀσπίδος.", "st": "2.11"}, {"sp": "N", "t": "ἐν δὲ Τιτάνῃ καὶ Ἀθηνᾶς ἱερόν ἐστιν, ἐς ὃ τὴν Κορωνίδα ἀνάγουσιν· ἐν δὲ αὐτῷ ξόανον Ἀθηνᾶς ἐστιν ἀρχαῖον, κεραυνωθῆναι δὲ καὶ τοῦτο ἐλέγετο· ἐκ τούτου τοῦ λόφου καταβᾶσιν—ᾠκοδόμηται γὰρ ἐπὶ λόφῳ τὸ ἱερὸν—βωμός ἐστιν ἀνέμων, ἐφ’ οὗ τοῖς ἀνέμοις ὁ ἱερεὺς μιᾷ νυκτὶ ἀνὰ πᾶν ἔτος θύει. δρᾷ δὲ καὶ ἄλλα ἀπόρρητα ἐς βόθρους τέσσαρας, ἡμερούμενος τῶν πνευμάτων τὸ ἄγριον, καὶ δὴ καὶ Μηδείας ὡς λέγουσιν ἐπῳδὰς ἐπᾴδει.", "st": "2.12"}, {"sp": "N", "t": "ἐκ δὲ Τιτάνης ἐς Σικυῶνα ἀφικομένοις καὶ καταβαίνουσιν ἐς θάλασσαν ἐν ἀριστερᾷ τῆς ὁδοῦ ναός ⟨ἐστιν⟩ Ἥρας οὐκ ἔχων ἔτι οὔτε ἄγαλμα οὔτε ὄροφον· τὸν δὲ ἀναθέντα Προῖτον εἶναι τὸν Ἄβαντός φασι. καταβᾶσι δὲ ἐς τὸν Σικυωνίων καλούμενον λιμένα καὶ τραπεῖσιν ἐπ’ Ἀριστοναύτας τὸ ἐπίνειον τὸ Πελληνέων, ἔστιν ὀλίγον ὑπὲρ τὴν ὁδὸν ἐν ἀριστερᾷ Ποσειδῶνος ἱερόν· προελθοῦσι δὲ κατὰ τὴν λεωφόρον Ἑλισσών τε καλούμενος ποταμὸς καὶ μετ’ αὐτὸν Σύθας ἐστίν, ἐκδιδόντες ἐς θάλασσαν.", "st": "2.12"}, {"sp": "N", "t": "ἡ δὲ Φλιασία τῆς Σικυωνίων ἐστὶν ὅμορος· καὶ Τιτάνης μὲν τεσσαράκοντα σταδίους ἀπέχει μάλιστα ἡ πόλις, ἐκ Σικυῶνος δὲ ἐς αὐτὴν ὁδός ἐστιν εὐθεῖα. καὶ ὅτι μὲν Ἀρκάσι Φλιάσιοι προσήκουσιν οὐδέν, δηλοῖ τὰ ἐς τὸν Ἀρκάδων κατάλογον τῆς Ὁμήρου ποιήσεως, ὅτι οὐκ εἰσὶν Ἀρκάσι καὶ οὗτοι συγκατειλεγμένοι· ὡς δὲ Ἀργεῖοί τε ἦσαν ἐξ ἀρχῆς καὶ ὕστερον Δωριεῖς γεγόνασιν Ἡρακλειδῶν κατελθόντων ἐς Πελοπόννησον, φανεῖται προϊόντι ὁμοῦ τῷ λόγῳ. διάφορα δὲ ἐς τοὺς Φλιασίους τὰ πολλὰ εἰδὼς εἰρημένα, τοῖς μάλιστα αὐτῶν ὡμολογημένοις χρήσομαι.", "st": "2.12"}, {"sp": "N", "t": "ἐν τῇ γῇ ταύτῃ γενέσθαι πρῶτον Ἄραντά φασιν ἄνδρα αὐτόχθονα· καὶ πόλιν τε ᾤκισε περὶ τὸν βουνὸν τοῦτον, ὃς Ἀραντῖνος ἔτι καλεῖται καὶ ἐς ἡμᾶς, οὐ πολὺ ἑτέρου λόφου διεστηκώς, ἐφ’ οὗ Φλιασίοις ἥ τε ἀκρόπολις καὶ τῆς Ἥβης ἐστὶ τὸ ἱερόν. ἐνταῦθά τε δὴ πόλιν ᾤκισε καὶ ἀπ’ αὐτοῦ τὸ ἀρχαῖον ἡ γῆ καὶ ἡ πόλις Ἀραντία ἐκλήθησαν. τούτῳ βασιλεύοντι Ἀσωπὸς Κηλούσης εἶναι λεγόμενος καὶ Ποσειδῶνος ἐξεῦρε τοῦ ποταμοῦ τὸ ὕδωρ, ὅντινα οἱ νῦν ἀπὸ τοῦ εὑρόντος καλοῦσιν Ἀσωπόν. τὸ δὲ μνῆμα τοῦ Ἄραντός ἐστιν ἐν χωρίῳ Κελεαῖς, ἔνθα δὴ καὶ Δυσαύλην ἄνδρα Ἐλευσίνιον τεθάφθαι λέγουσιν.", "st": "2.12"}, {"sp": "N", "t": "Ἄραντος δὲ υἱὸς Ἄορις καὶ θυγάτηρ ἐγένετο Ἀραιθυρέα. τούτους φασὶ Φλιάσιοι θηρᾶσαί τε ἐμπείρους γενέσθαι καὶ τὰ ἐς πόλεμον ἀνδρείους. προαποθανούσης δὲ Ἀραιθυρέας Ἄορις ἐς μνήμην τῆς ἀδελφῆς μετωνόμασεν Ἀραιθυρέαν τὴν χώραν· καὶ ἐπὶ τῷδε Ὅμηρος τοὺς Ἀγαμέμνονος ὑπηκόους καταλέγων τὸ ἔπος ἐποίησεν<br>Ὀρνειάς τ’ ἐνέμοντο Ἀραιθυρέην τ’ ἐρατεινήν.<br>τάφους δὲ τῶν Ἄραντος παίδων οὐχ ἑτέρωθι ἡγοῦμαι τῆς χώρας, ἐπὶ τῷ λόφῳ δὲ εἶναι τῷ Ἀραντίνῳ· καί σφισιν ἐπίθημα στῆλαι περιφανεῖς εἰσι, καὶ πρὸ τῆς τελετῆς ἣν τῇ Δήμητρι ἄγουσιν Ἄραντα καὶ τοὺς παῖδας καλοῦσιν ἐπὶ τὰς σπονδὰς ἐς ταῦτα βλέποντες τὰ μνήματα.", "st": "2.12"}, {"sp": "N", "t": "Φλίαντα δέ, ὃς τρίτον τοῦτο ἐποίησεν ὄνομα ἀφ’ αὑτοῦ τῇ γῇ, Κείσου μὲν παῖδα εἶναι τοῦ Τημένου κατὰ δὴ τὸν Ἀργείων λόγον οὐδὲ ἀρχὴν ἔγωγε προσίεμαι, Διονύσου δὲ οἶδα καλούμενον καὶ τῶν πλευσάντων ἐπὶ τῆς Ἀργοῦς καὶ τοῦτον γενέσθαι λεγόμενον. ὁμολογεῖ δέ μοι καὶ τοῦ Ῥοδίου ποιητοῦ τὰ ἔπη·<br>Φλίας αὖτ’ ἐπὶ τοῖσιν Ἀραιθυρέηθεν ἵκανεν,<br>ἔνθ’ ἀφνειὸς ἔναιε Διωνύσοιο ἕκητι<br>πατρὸς ἑοῦ, πηγῇσιν ἐφέστιος Ἀσωποῖο.<br>τοῦ δὲ Φλίαντος Ἀραιθυρέαν εἶναι μητέρα, ἀλλ’ οὐ Χθονοφύλην· Χθονοφύλην δέ οἱ συνοικῆσαι καὶ Ἀνδροδάμαν γενέσθαι Φλίαντι ἐξ αὐτῆς.", "st": "2.12"}, {"sp": "N", "t": "Ἡρακλειδῶν δὲ κατελθόντων Πελοπόννησος ἐταράχθη πᾶσα πλὴν Ἀρκάδων, ὡς πολλὰς μὲν τῶν πόλεων συνοίκους ἐκ τοῦ Δωρικοῦ προσλαβεῖν, πλείονας δὲ ἔτι γενέσθαι τὰς μεταβολὰς τοῖς οἰκήτορσι. τὰ δὲ κατὰ Φλιοῦντα οὕτως ἔχει. Ῥηγνίδας ἐπ’ αὐτὴν ὁ Φάλκου τοῦ Τημένου Δωριεὺς ἐκ τε Ἄργους στρατεύει καὶ ἐκ τῆς Σικυωνίας. τῶν δὲ Φλιασίων τοῖς μὲν ἃ προεκαλεῖτο Ῥηγνίδας ἐφαίνετο ἀρεστά, μένοντας ἐπὶ τοῖς αὑτῶν βασιλέα Ῥηγνίδαν καὶ τοὺς σὺν ἐκείνῳ Δωριεῖς ἐπὶ ἀναδασμῷ γῆς δέχεσθαι·", "st": "2.13"}, {"sp": "N", "t": "Ἵππασος δὲ καὶ οἱ σὺν αὐτῷ διεκελεύοντο ἀμύνεσθαι μηδὲ πολλῶν καὶ ἀγαθῶν ἀμαχεὶ τοῖς Δωριεῦσιν ἀφίστασθαι. προσεμένου δὲ τοῦ δήμου τὴν ἐναντίαν [ταύτην] γνώμην, οὕτως Ἵππασος σὺν τοῖς ἐθέλουσιν ἐς Σάμον φεύγει. Ἱππάσου δὲ τούτου τέταρτος ἦν ἀπόγονος Πυθαγόρας ὁ λεγόμενος γενέσθαι σοφός· Μνησάρχου γὰρ Πυθαγόρας ἦν τοῦ Εὔφρονος τοῦ Ἱππάσου. ταῦτα μὲν Φλιάσιοι λέγουσι περὶ αὑτῶν, ὁμολογοῦσι δέ σφισι τὰ πολλὰ καὶ Σικυώνιοι.", "st": "2.13"}, {"sp": "N", "t": "προσέσται δὲ ἤδη καὶ τῶν ἐς ἐπίδειξιν ἡκόντων τὰ ἀξιολογώτατα. ἔστι γὰρ ἐν τῇ Φλιασίων ἀκροπόλει κυπαρίσσων ἄλσος καὶ ἱερὸν ἁγιώτατον ἐκ παλαιοῦ· τὴν δὲ θεὸν ἧς ἐστι τὸ ἱερὸν οἱ μὲν ἀρχαιότατοι Φλιασίων Γανυμήδαν, οἱ δὲ ὕστερον Ἥβην ὀνομάζουσιν· ἧς καὶ Ὅμηρος μνήμην ἐποιήσατο ἐν τῇ Μενελάου πρὸς Ἀλέξανδρον μονομαχίᾳ φάμενος οἰνοχόον τῶν θεῶν εἶναι, καὶ αὖθις ⟨ἐν⟩ Ὀδυσσέως ἐς Ἅιδου καθόδῳ γυναῖκα Ἡρακλέους εἶπεν εἶναι. Ὠλῆνι δὲ ἐν Ἥρας ἐστὶν ὕμνῳ πεποιημένα τραφῆναι τὴν Ἥραν ὑπὸ Ὡρῶν, εἶναι δέ οἱ παῖδας Ἄρην τε καὶ Ἥβην.", "st": "2.13"}, {"sp": "N", "t": "παρὰ δὲ Φλιασίοις τῇ θεῷ ταύτῃ καὶ ἄλλαι τιμαὶ καὶ μέγιστον τὸ ἐς τοὺς ἱκέτας ἐστί· δεδώκασι γὰρ δὴ ἄδειαν ἐνταῦθα ἱκετεύουσι, λυθέντες δὲ οἱ δεσμῶται τὰς πέδας πρὸς τὰ ἐν τῷ ἄλσει δένδρα ἀνατιθέασιν. ἄγεται δὲ καὶ ἑορτή σφισιν ἐπέτειος, ἣν καλοῦσι Κισσοτόμους. ἄγαλμα δὲ οὔτε ἐν ἀπορρήτῳ φυλάσσουσιν οὐδὲν οὔτε ἐστὶν ἐν φανερῷ δεικνύμενον—ἐφ’ ὅτῳ δὲ οὕτω νομίζουσιν, ἱερός ἐστιν αὐτοῖς λόγος—, ἐπεὶ τῆς γε Ἥρας ἐστὶν ἐξιόντων ἐν ἀριστερᾷ ναὸς ἄγαλμα ἔχων Παρίου λίθου.", "st": "2.13"}, {"sp": "N", "t": "ἐν δὲ τῇ ἀκροπόλει καὶ ἄλλος περίβολός ἐστιν ἱερὸς Δήμητρος, ἐν δὲ αὐτῷ ναός τε καὶ ἄγαλμα Δήμητρος καὶ τῆς παιδός· τὸ δὲ τῆς Ἀρτέμιδος—ἔστι γὰρ καὶ Ἀρτέμιδος ἐνταῦθα χαλκοῦν ἄγαλμα—ἐφαίνετο ἀρχαῖον εἶναί μοι. κατιόντων δὲ ἐκ τῆς ἀκροπόλεώς ἐστιν Ἀσκληπιοῦ ναὸς ἐν δεξιᾷ καὶ ἄγαλμα οὐκ ἔχον πω γένεια. ὑπὸ τοῦτον τὸν ναὸν θέατρον πεποίηται· τούτου δὲ οὐ πόρρω Δήμητρός ἐστιν ἱερὸν καὶ καθήμενα ἀγάλματα ἀρχαῖα.", "st": "2.13"}, {"sp": "N", "t": "ἀνάκειται δὲ ἐπὶ τῆς ἀγορᾶς αἲξ χαλκῆ, τὰ πολλὰ ἐπίχρυσος· παρὰ δὲ Φλιασίοις τιμὰς ἐπὶ τῷδε εἴληφε. τὸ ἄστρον ἣν ὀνομάζουσιν αἶγα ἀνατέλλουσα τὰς ἀμπέλους λυμαίνεται συνεχῶς· ἵνα δὲ ἄχαρι μηδὲν ἀπ’ αὐτῆς γένηται, οἱ δὲ τὴν ἐπὶ τῆς ἀγορᾶς χαλκῆν αἶγα ἄλλοις τε τιμῶσι καὶ χρυσῷ τὸ ἄγαλμα ἐπικοσμοῦντες. ἐνταῦθά ἐστι καὶ Ἀριστίου μνῆμα τοῦ Πρατίνου· τούτῳ τῷ Ἀριστίᾳ σάτυροι καὶ Πρατίνᾳ τῷ πατρί εἰσι πεποιημένοι πλὴν τῶν Αἰχύλου δοκιμώτατοι.", "st": "2.13"}, {"sp": "N", "t": "ὄπισθεν δὲ τῆς ἀγορᾶς ἐστιν οἶκος ὀνομαζόμενος ὑπὸ Φλιασίων μαντικός. ἐς τοῦτον Ἀμφιάραος ἐλθὼν καὶ τὴν νύκτα ἐγκατακοιμηθεὶς μαντεύεσθαι τότε πρῶτον, ὡς οἱ Φλιάσιοί φασιν, ἤρξατο· τέως δὲ ἦν Ἀμφιάραος τῷ ἐκείνων λόγῳ ἰδιώτης τε καὶ οὐ μάντις. καὶ τὸ οἴκημα ἀπὸ τούτου συγκέκλεισται τὸν πάντα ἤδη χρόνον. οὐ πόρρω δέ ἐστιν ὁ καλούμενος Ὀμφαλός, Πελοποννήσου δὲ πάσης μέσον, εἰ δὴ τὰ ὄντα εἰρήκασιν. ἀπὸ δὲ τοῦ Ὀμφαλοῦ προελθοῦσι Διονύσου σφίσιν ἱερόν ἐστιν ἀρχαῖον, ἔστι δὲ καὶ Ἀπόλλωνος καὶ ἄλλο Ἴσιδος. τὸ μὲν δὴ ἄγαλμα τοῦ Διονύσου δῆλον πᾶσιν, ὡσαύτως δὲ καὶ τὸ τοῦ Ἀπόλλωνος· τὸ δὲ τῆς Ἴσιδος τοῖς ἱερεῦσι θεάσασθαι μόνον ἔστι.", "st": "2.13"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὧδε ὑπὸ Φλιασίων λόγος· Ἡρακλέα, ὅτ’ ἐκ Λιβύης ἀνεσώθη κομίζων τὰ μῆλα τὰ Ἑσπερίδων καλούμενα, ἐς Φλιοῦντα ἐλθεῖν κατὰ δή τι ἴδιον, διαιτωμένου δὲ ἐνταῦθα Οἰνέα ἐξ Αἰτωλίας ἀφικέσθαι παρ’ αὐτόν· ἐγεγόνει δὲ τῷ Ἡρακλεῖ πρότερον ἔτι κηδεστής, τότε δὲ ἀφιγμένος εἱστία τὸν Ἡρακλέα ἢ αὐτὸς εἱστιᾶτο ὑπὸ ἐκείνου. Κύαθον δ’ οὖν παῖδα οἰνοχόον Οἰνέως οὐκ ἀρεσθεὶς τῷ δοθέντι πώματι παίει τῶν δακτύλων ἑνὶ ἐς τὴν κεφαλήν· ἀποθανόντος δὲ αὐτίκα ὑπὸ τῆς πληγῆς Φλιασίοις ἐστὶν οἴκημα ἐς μνήμην. τοῦτο ᾠκοδόμηται μὲν παρὰ τὸ ἱερὸν τοῦ Ἀπόλλωνος, ἀγάλματα δὲ λίθου πεποιημένα ἔχει, κύλικα ὀρέγοντα Ἡρακλεῖ τὸν Κύαθον.", "st": "2.13"}, {"sp": "N", "t": "τῆς δὲ πόλεως αἱ Κελεαὶ πέντε που σταδίους μάλιστα ἀπέχουσι, καὶ τῇ Δήμητρι ἐνταῦθα δι’ ἐνιαυτοῦ τετάρτου τὴν τελετὴν καὶ οὐ κατὰ ἔτος ἄγουσιν. ἱεροφάντης δὲ οὐκ ἐς τὸν βίον πάντα ἀποδέδεικται, κατὰ δὲ ἑκάστην τελετὴν ἄλλοτέ ἐστιν ἄλλος σφίσιν αἱρετός, λαμβάνων ἢν ἐθέλῃ καὶ γυναῖκα. καὶ ταῦτα μὲν διάφορα τῶν Ἐλευσῖνι νομίζουσι, τὰ δὲ ἐς αὐτὴν τὴν τελετὴν ἐκείνων ἐστὶν ἐς μίμησιν· ὁμολογοῦσι δὲ καὶ αὐτοὶ μιμεῖσθαι Φλιάσιοι τὰ ἐν Ἐλευσῖνι δρώμενα.", "st": "2.14"}, {"sp": "N", "t": "Δυσαύλην δέ φασιν ἀδελφὸν Κελεοῦ παραγενόμενόν σφισιν ἐς τὴν χώραν καταστήσασθαι τὴν τελετήν, ἐκβληθῆναι δὲ αὐτὸν ἐξ Ἐλευσῖνος ὑπὸ Ἴωνος, ὅτε Ἴων Ἀθηναίοις ὁ Ξούθου πολέμαρχος τοῦ πρὸς Ἐλευσινίους ᾑρέθη πολέμου. τοῦτο μὲν δὴ Φλιασίοις οὐκ ἔστιν ὅπως ὁμολογήσω, κρατηθέντα μάχῃ τινὰ Ἐλευσινίων φυγάδα ἀπελαθέντα οἴχεσθαι, τοῦ πολέμου τε ἐπὶ συνθήκαις καταλυθέντος πρὶν ἢ διαπολεμηθῆναι καὶ ἐν Ἐλευσῖνι αὐτοῦ καταμείναντος Εὐμόλπου.", "st": "2.14"}, {"sp": "N", "t": "δύναιτο δ’ ἂν κατὰ ἄλλην τινὰ ἐνταῦθα ὁ Δυσαύλης ἀφικέσθαι πρόφασιν καὶ οὐχ ὡς οἱ Φλιάσιοί φασιν. οὐ μὴν οὐδὲ Κελεῷ προσήκων ἐμοὶ δοκεῖν οὐδὲ ἄλλως ἦν ἐν τοῖς ἐπιφανέσιν Ἐλευσινίων· οὐ γὰρ ἄν ποτε Ὅμηρος παρῆκεν αὐτὸν ἐν τοῖς ἔπεσιν. ἔστι γὰρ καὶ Ὁμήρῳ πεποιημένα ἐς Δήμητραν· ἐν δὲ αὐτοῖς καταλέγων τοὺς διδαχθέντας ὑπὸ τῆς θεοῦ τὴν τελετὴν Δυσαύλην οὐδένα οἶδεν Ἐλευσίνιον. ἔχει δὲ οὕτω τὰ ἔπη·<br>δεῖξεν Τριπτολέμῳ τε Διοκλεῖ τε πληξίππῳ<br>Εὐμόλπου τε βίῃ Κελεῷ θ’ ἡγήτορι λαῶν<br>δρησμοσύνην ἱερῶν καὶ ἐπέφραδεν ὄργια πᾶσιν.", "st": "2.14"}, {"sp": "N", "t": "οὗτος δ’ οὖν, ὡς οἱ Φλιάσιοί φασιν, ὁ Δυσαύλης κατεστήσατο ἐνταῦθα τὴν τελετὴν καὶ οὗτος ἦν ὁ τῷ χωρίῳ τὸ ὄνομα παραθέμενος Κελεάς· Δυσαύλου τέ ἐστιν ἐνταῦθα, ὡς εἴρηταί μοι, μνῆμα. πρότερον δὲ ἄρα ἐπεποίητο ⟨ὁ⟩ Ἀράντειος τάφος· ὕστερον γὰρ κατὰ τὸν Φλιασίων λόγον καὶ οὐκ ἐπὶ τῆς Ἄραντος βασιλείας ἀφίκετο ὁ Δυσαύλης. Φλιάσιοι γὰρ Προμηθεῖ γενέσθαι τῷ Ἰαπετοῦ κατὰ τὸν αὐτὸν χρόνον φασὶν Ἄραντα καὶ τρισὶν ἀνθρώπων γενεαῖς Πελασγοῦ τε εἶναι πρεσβύτερον τοῦ Ἀρκάδος καὶ τῶν λεγομένων Ἀθήνῃσιν αὐτοχθόνων. —τοῦ δὲ Ἀνακτόρου καλουμένου πρὸς τῷ ὀρόφῳ Πέλοπος ἅρμα λέγουσιν ἀνακεῖσθαι.", "st": "2.14"}, {"sp": "N", "t": "Φλιασίοις μὲν δὴ τοσαῦτα λόγου μάλιστα ἦν ἄξια· ἐκ Κορίνθου δ’ ἐς Ἄργος ἐρχομένῳ Κλεωναὶ πόλις ἐστὶν οὐ μεγάλη. παῖδα δὲ εἶναι Πέλοπος Κλεώνην λέγουσιν, οἱ δὲ τῷ παρὰ Σικυῶνα ῥέοντι Ἀσωπῷ θυγατέρα ἐπὶ ταῖς ἄλλαις Κλεώνην γενέσθαι· τὸ δ’ οὖν ὄνομα ἀπὸ τοῦ ἑτέρου τούτων ἐτέθη τῇ πόλει. ἐνταῦθά ἐστιν ἱερὸν Ἀθηνᾶς, τὸ δὲ ἄγαλμα Σκύλλιδος τέχνη καὶ Διποίνου· μαθητὰς δὲ εἶναι Δαιδάλου σφᾶς, οἱ δὲ καὶ γυναῖκα ⟨ἐκ⟩ Γόρτυνος ἐθέλουσι λαβεῖν Δαίδαλον καὶ τὸν Δίποινον καὶ Σκύλλιν ἐκ τῆς γυναικός οἱ ταύτης γενέσθαι. ἐν Κλεωναῖς δὲ τοῦτό ἐστι τὸ ἱερὸν καὶ μνῆμα Εὐρύτου καὶ Κτεάτου· θεωροὺς γὰρ ἐξ Ἤλιδος ἐς τὸν ἀγῶνα ἰόντας τῶν Ἰσθμίων αὐτοὺς ἐνταῦθα Ἡρακλῆς κατετόξευσεν, ἔγκλημα ποιούμενος ὅτι οἱ πρὸς Αὐγείαν πολεμοῦντι ἀντετάχθησαν.", "st": "2.15"}, {"sp": "N", "t": "ἐκ Κλεωνῶν δέ εἰσιν ἐς Ἄργος ὁδοὶ δύο, ἡ μὲν ἀνδράσιν εὐζώνοις καὶ ἔστιν ἐπίτομος, ἡ δὲ ἐπὶ τοῦ καλουμένου Τρητοῦ, στενὴ μὲν καὶ αὐτὴ περιεχόντων ὀρῶν, ὀχήμασι δέ ἐστιν ὅμως ἐπιτηδειοτέρα. ἐν τούτοις τοῖς ὄρεσι τὸ σπήλαιον ἔτι δείκνυται τοῦ λέοντος, καὶ ἡ Νεμέα τὸ χωρίον ἀπέχει σταδίους πέντε που καὶ δέκα. ἐν δὲ αὐτῇ Νεμείου [τε] Διὸς ναός ἐστι θέας ἄξιος, πλὴν ὅσον κατερρυήκει τε ὁ ὄροφος καὶ ἄγαλμα οὐδὲν ἔτι ἐλείπετο· κυπαρίσσων τε ἄλσος ἐστὶ περὶ τὸν ναόν, καὶ τὸν Ὀφέλτην ἐνταῦθα ὑπὸ τῆς τροφοῦ τεθέντα ἐς τὴν πόαν διαφθαρῆναι λέγουσιν ὑπὸ τοῦ δράκοντος.", "st": "2.15"}, {"sp": "N", "t": "θύουσι δὲ Ἀργεῖοι τῷ Διὶ καὶ ἐν τῇ Νεμέᾳ καὶ Νεμείου Διὸς ἱερέα αἱροῦνται, καὶ δὴ καὶ δρόμου προτιθέασιν ἀγῶνα ἀνδράσιν ὡπλισμένοις Νεμείων πανηγύρει τῶν χειμερινῶν. ἐνταῦθα ἔστι μὲν Ὀφέλτου τάφος, περὶ δὲ αὐτὸν θριγκὸς λίθων καὶ ἐντὸς τοῦ περιβόλου βωμοί· ἔστι δὲ χῶμα γῆς Λυκούργου μνῆμα τοῦ Ὀφέλτου πατρός. τὴν δὲ πηγὴν Ἀδράστειαν ὀνομάζουσιν εἴτε ἐπ’ ἄλλῃ τινὶ αἰτίᾳ εἴτε καὶ ἀνευρόντος αὐτὴν Ἀδράστου· τὸ δὲ ὄνομα λέγουσι τῇ χώρᾳ Νεμέαν δοῦναι θυγατέρα Ἀσωποῦ καὶ ταύτην. καὶ ὄρος Ἀπέσας ἐστὶν ὑπὲρ τὴν Νεμέαν, ἔνθα Περσέα πρῶτον Διὶ θῦσαι λέγουσιν Ἀπεσαντίῳ. —", "st": "2.15"}, {"sp": "N", "t": "ἀνελθοῦσι δὲ ἐς τὸν Τρητὸν καὶ αὖθις τὴν ἐς Ἄργος ἰοῦσίν ἐστι Μυκηνῶν ἐρείπια ἐν ἀριστερᾷ. καὶ ὅτι μὲν Περσεὺς ἐγένετο Μυκηνῶν οἰκιστής, ἴσασιν Ἕλληνες· ἐγὼ δὲ αἰτίαν τε γράψω τοῦ οἰκισμοῦ καὶ δι’ ἥντινα πρόφασιν Ἀργεῖοι Μυκηναίους ὕστερον ἀνέστησαν. ἐν γὰρ τῇ νῦν Ἀργολίδι ὀνομαζομένῃ τὰ μὲν ἔτι παλαιότερα οὐ μνημονεύουσιν, Ἴναχον δὲ βασιλεύοντα τόν τε ποταμὸν ἀφ’ αὑτοῦ λέγουσιν ὀνομάσαι καὶ θῦσαι τῇ Ἥρᾳ.", "st": "2.15"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὧδε λόγος· Φορωνέα ἐν τῇ γῇ ταύτῃ γενέσθαι πρῶτον, Ἴναχον δὲ οὐκ ἄνδρα ἀλλὰ τὸν ποταμὸν πατέρα εἶναι Φορωνεῖ· τοῦτον δὲ Ποσειδῶνι καὶ Ἥρᾳ δικάσαι περὶ τῆς χώρας, σὺν δὲ αὐτῷ Κηφισόν τε καὶ Ἀστερίωνα [καὶ τὸν Ἴναχον] ποταμόν· κρινάντων δὲ Ἥρας εἶναι τὴν γῆν, οὕτω σφίσιν ἀφανίσαι τὸ ὕδωρ Ποσειδῶνα. καὶ διὰ τοῦτο οὔτε Ἴναχος ὕδωρ οὔτε ἄλλος παρέχεται τῶν εἰρημένων ποταμῶν ὅτι μὴ ὕσαντος τοῦ θεοῦ· θέρους δὲ αὖά σφισίν ἐστι τὰ ῥεύματα πλὴν τῶν ἐν Λέρνῃ. Φορωνεὺς δὲ ὁ Ἰνάχου τοὺς ἀνθρώπους συνήγαγε πρῶτον ἐς κοινόν, σποράδας τέως καὶ ἐφ’ ἑαυτῶν ἑκάστοτε οἰκοῦντας· καὶ τὸ χωρίον ἐς ὃ πρῶτον ἠθροίσθησαν ἄστυ ὠνομάσθη Φορωνικόν.", "st": "2.15"}, {"sp": "N", "t": "Ἄργος δὲ Φορωνέως θυγατριδοῦς βασιλεύσας μετὰ Φορωνέα ὠνόμασεν ἀφ’ αὑτοῦ τὴν χώραν. Ἄργου δὲ Πείρασος γίνεται καὶ Φόρβας, Φόρβαντος δὲ Τριόπας, Τριόπα δὲ Ἴασος καὶ Ἀγήνωρ. Ἰὼ μὲν οὖν Ἰάσου θυγάτηρ, εἴτε ὡς Ἡρόδοτος ἔγραψεν εἴτε καθ’ ὃ λέγουσιν Ἕλληνες, ἐς Αἴγυπτον ἀφικνεῖται Κρότωπος δὲ ὁ Ἀγήνορος ἔσχε μετὰ Ἴασον τὴν ἀρχήν, Κροτώπου δὲ Σθενέλας γίνεται, Δαναὸς δ’ ἀπ’ Αἰγύπτου πλεύσας ἐπὶ Γελάνορα τὸν Σθενέλα τοὺς ἀπογόνους τοὺς Ἀγήνορος βασιλείας ἔπαυσεν. τὰ δὲ ἀπὸ τούτου καὶ οἱ πάντες ὁμοίως ἴσασι, θυγατέρων τῶν Δαναοῦ τὸ ἐς τοὺς ἀνεψιοὺς τόλμημα καὶ ὡς ἀποθανόντος Δαναοῦ τὴν ἀρχὴν Λυγκεὺς ἔσχεν.", "st": "2.16"}, {"sp": "N", "t": "οἱ δὲ Ἄβαντος τοῦ Λυγκέως παῖδες τὴν βασιλείαν ἐνείμαντο, καὶ Ἀκρίσιος μὲν αὐτοῦ κατέμεινεν ἐν τῷ Ἄργει, Προῖτος δὲ τὸ Ἡραῖον καὶ Μιδείαν καὶ Τίρυνθα ἔσχε καὶ ὅσα πρὸς θαλάσσῃ τῆς Ἀργείας· σημεῖά τε τῆς ἐν Τίρυνθι οἰκήσεως Προίτου καὶ ἐς τόδε λείπεται. χρόνῳ δὲ ὕστερον Ἀκρίσιος Περσέα αὐτόν τε περιεῖναι πυνθανόμενος καὶ ἔργα ἀποδείκνυσθαι, ἐς Λάρισαν ἀπεχώρησε τὴν ἐπὶ τῷ Πηνειῷ. Περσεὺς δὲ—ἰδεῖν γὰρ πάντως ἤθελε τὸν γονέα τῆς μητρὸς καὶ λόγοις τε χρηστοῖς καὶ ἔργοις δεξιώσασθαι—ἔρχεται παρ’ αὐτὸν ἐς τὴν Λάρισαν· καὶ ὁ μὲν οἷα ἡλικίᾳ τε ἀκμάζων καὶ τοῦ δίσκου χαίρων τῷ εὑρήματι ἐπεδείκνυτο ἐς ἅπαντας, Ἀκρίσιος δὲ λανθάνει κατὰ δαίμονα ὑποπεσὼν τοῦ δίσκου τῇ ὁρμῇ.", "st": "2.16"}, {"sp": "N", "t": "καὶ Ἀκρισίῳ μὲν ἡ πρόρρησις τοῦ θεοῦ τέλος ἔσχεν, οὐδὲ ἀπέτρεψέν οἱ τὸ χρεὼν τὰ ἐς τὴν παῖδα καὶ τὸν θυγατριδοῦν παρευρήματα· Περσεὺς δὲ ὡς ἀνέστρεψεν ἐς Ἄργος—ᾐσχύνετο γὰρ τοῦ φόνου τῇ φήμῃ—, Μεγαπένθην τὸν Προίτου πείθει οἱ τὴν ἀρχὴν ἀντιδοῦναι, παραλαβὼν δὲ αὐτὸς τὴν ἐκείνου Μυκήνας κτίζει. τοῦ ξίφους γὰρ ἐνταῦθα ἐξέπεσεν ὁ μύκης αὐτῷ, καὶ τὸ σημεῖον ἐς οἰκισμὸν ἐνόμιζε συμβῆναι πόλεως. ἤκουσα δὲ καὶ ὡς διψῶντι ἐπῆλθεν ἀνελέσθαι οἱ μύκητα ἐκ τῆς γῆς, ῥυέντος δὲ ὕδατος πιὼν καὶ ἡσθεὶς Μυκήνας ἔθετο τὸ ὄνομα τῷ χωρίῳ.", "st": "2.16"}, {"sp": "N", "t": "Ὅμηρος δὲ ἐν Ὀδυσσείᾳ γυναικὸς Μυκήνης ἐν ἔπει τῷδε ἐμνήσθη<br>Τυρώ τ’ Ἀλκμήνη τε ἐυστέφανός τε Μυκήνη.<br>ταύτην εἶναι θυγατέρα Ἰνάχου γυναῖκα δὲ Ἀρέστορος τὰ ἔπη λέγει, ἃ δὴ Ἕλληνες καλοῦσιν Ἠοίας μεγάλας· ἀπὸ ταύτης οὖν γεγονέναι καὶ τὸ ὄνομα τῇ πόλει φασίν. ὃν δὲ προσποιοῦσιν Ἀκουσιλάῳ λόγον, Μυκηνέα υἱὸν εἶναι Σπάρτωνος, Σπάρτωνα δὲ Φορωνέως, οὐκ ἂν ἔγωγε ἀποδεξαίμην, διότι μηδὲ αὐτοὶ Λακεδαιμόνιοι. Λακεδαιμονίοις γὰρ Σπάρτης μὲν γυναικὸς εἰκών ἐστιν ἐν Ἀμύκλαις, Σπάρτωνα δὲ Φορωνέως παῖδα θαυμάζοιεν ἂν καὶ ἀρχὴν ἀκούσαντες.", "st": "2.16"}, {"sp": "N", "t": "Μυκήνας δὲ Ἀργεῖοι καθεῖλον ὑπὸ ζηλοτυπίας. ἡσυχαζόντων γὰρ τῶν Ἀργείων κατὰ τὴν ἐπιστρατείαν τοῦ Μήδου, Μυκηναῖοι πέμπουσιν ἐς Θερμοπύλας ὀγδοήκοντα ἄνδρας, οἳ Λακεδαιμονίοις μετέσχον τοῦ ἔργου· τοῦτο ἤνεγκεν ὄλεθρόν σφισι τὸ φιλοτίμημα παροξῦναν Ἀργείους. λείπεται δὲ ὅμως ἔτι καὶ ἄλλα τοῦ περιβόλου καὶ ἡ πύλη, λέοντες δὲ ἐφεστήκασιν αὐτῇ· Κυκλώπων δὲ καὶ ταῦτα ἔργα εἶναι λέγουσιν, οἳ Προίτῳ τὸ τεῖχος ἐποίησαν ἐν Τίρυνθι.", "st": "2.16"}, {"sp": "N", "t": "Μυκηνῶν δὲ ἐν τοῖς ἐρειπίοις κρήνη τέ ἐστι καλουμένη Περσεία καὶ Ἀτρέως καὶ τῶν παίδων ὑπόγαια οἰκοδομήματα, ἔνθα οἱ θησαυροί σφισι τῶν χρημάτων ἦσαν. τάφος δὲ ἔστι μὲν Ἀτρέως, εἰσὶ δὲ καὶ ὅσους σὺν Ἀγαμέμνονι ἐπανήκοντας ἐξ Ἰλίου δειπνίσας κατεφόνευσεν Αἴγισθος. τοῦ μὲν δὴ Κασσάνδρας μνήματος ἀμφισβητοῦσι Λακεδαιμονίων οἱ περὶ Ἀμύκλας οἰκοῦντες· ἕτερον δέ ἐστιν Ἀγαμέμνονος, τὸ δὲ Εὐρυμέδοντος τοῦ ἡνιόχου, καὶ Τελεδάμου τὸ αὐτὸ καὶ Πέλοπος— τούτους γὰρ τεκεῖν διδύμους Κασσάνδραν φασί,", "st": "2.16"}, {"sp": "N", "t": "νηπίους δὲ ἔτι ὄντας ἐπικατέσφαξε τοῖς γονεῦσιν Αἴγισθος—⟨καὶ Ἠλέκτρας⟩· Πυλάδῃ γὰρ συνῴκησεν Ὀρέστου δόντος. Ἑλλάνικος δὲ καὶ τάδε ἔγραψε, Μέδοντα καὶ Στρόφιον γενέσθαι Πυλάδῃ παῖδας ἐξ Ἠλέκτρας. Κλυταιμνήστρα δὲ ἐτάφη καὶ Αἴγισθος ὀλίγον ἀπωτέρω τοῦ τείχους· ἐντὸς δὲ ἀπηξιώθησαν, ἔνθα Ἀγαμέμνων τε αὐτὸς ἔκειτο καὶ οἱ σὺν ἐκείνῳ φονευθέντες.", "st": "2.16"}, {"sp": "N", "t": "Μυκηνῶν δὲ ἐν ἀριστερᾷ πέντε ἀπέχει καὶ δέκα στάδια τὸ Ἡραῖον. ῥεῖ δὲ κατὰ τὴν ὁδὸν ὕδωρ Ἐλευθέριον καλούμενον· χρῶνται δὲ αὐτῷ πρὸς καθάρσια αἱ περὶ τὸ ἱερὸν καὶ τῶν θυσιῶν ἐς τὰς ἀπορρήτους. αὐτὸ δὲ τὸ ἱερόν ἐστιν ἐν χθαμαλωτέρῳ τῆς Εὐβοίας· τὸ γὰρ δὴ ὄρος τοῦτο ὀνομάζουσιν Εὔβοιαν, λέγοντες Ἀστερίωνι γενέσθαι τῷ ποταμῷ θυγατέρας Εὔβοιαν καὶ Πρόσυμναν καὶ Ἀκραίαν, εἶναι δὲ σφᾶς τροφοὺς τῆς Ἥρας·", "st": "2.17"}, {"sp": "N", "t": "καὶ ἀπὸ μὲν Ἀκραίας τὸ ὄρος καλοῦσι τὸ ἀπαντικρὺ τοῦ Ἡραίου, ἀπὸ δὲ Εὐβοίας ὅσον περὶ τὸ ἱερόν, Πρόσυμναν δὲ τὴν ὑπὸ τὸ Ἡραῖον χώραν. ὁ δὲ Ἀστερίων οὗτος ῥέων ὑπὲρ τὸ Ἡραῖον ἐς φάραγγα ἐσπίπτων ἀφανίζεται. φύεται δὲ αὐτοῦ πόα πρὸς ταῖς ὄχθαις· ἀστερίωνα ὀνομάζουσι καὶ τὴν πόαν· ταύτην τῇ Ἥρᾳ καὶ αὐτὴν φέρουσι καὶ ἀπὸ τῶν φύλλων αὐτῆς στεφάνους πλέκουσιν.", "st": "2.17"}, {"sp": "N", "t": "ἀρχιτέκτονα μὲν δὴ γενέσθαι τοῦ ναοῦ λέγουσιν Εὐπόλεμον Ἀργεῖον· ὁπόσα δὲ ὑπὲρ τοὺς κίονάς ἐστιν εἰργασμένα, τὰ μὲν ἐς τὴν Διὸς γένεσιν καὶ θεῶν καὶ γιγάντων μάχην ἔχει, τὰ δὲ ἐς τὸν πρὸς Τροίαν πόλεμον καὶ Ἰλίου τὴν ἅλωσιν. ἀνδριάντες τε ἑστήκασι πρὸ τῆς ἐσόδου καὶ γυναικῶν, αἳ γεγόνασιν ἱέρειαι τῆς Ἥρας, καὶ ἡρώων ἄλλων τε καὶ Ὀρέστου· τὸν γὰρ ἐπίγραμμα ἔχοντα, ὡς εἴη βασιλεὺς Αὔγουστος, Ὀρέστην εἶναι λέγουσιν. ἐν δὲ τῷ προνάῳ τῇ μὲν Χάριτες ἀγάλματά ἐστιν ἀρχαῖα, ἐν δεξιᾷ δὲ κλίνη τῆς Ἥρας καὶ ἀνάθημα ἀσπὶς ἣν Μενέλαός ποτε ἀφείλετο Εὔφορβον ἐν Ἰλίῳ.", "st": "2.17"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα τῆς Ἥρας ἐπὶ θρόνου κάθηται μεγέθει μέγα, χρυσοῦ μὲν καὶ ἐλέφαντος, Πολυκλείτου δὲ ἔργον· ἔπεστι δέ οἱ στέφανος Χάριτας ἔχων καὶ Ὥρας ἐπειργασμένας, καὶ τῶν χειρῶν τῇ μὲν καρπὸν φέρει ῥοιᾶς, τῇ δὲ σκῆπτρον. τὰ μὲν οὖν ἐς τὴν ῥοιὰν—ἀπορρητότερος γάρ ἐστιν ὁ λόγος—ἀφείσθω μοι· κόκκυγα δὲ ἐπὶ τῷ σκήπτρῳ καθῆσθαί φασι λέγοντες τὸν Δία, ὅτε ἤρα παρθένου τῆς Ἥρας, ἐς τοῦτον τὸν ὄρνιθα ἀλλαγῆναι, τὴν δὲ ἅτε παίγνιον θηρᾶσαι. τοῦτον τὸν λόγον καὶ ὅσα ἐοικότα εἴρηται περὶ θεῶν οὐκ ἀποδεχόμενος γράφω, γράφω δὲ οὐδὲν ἧσσον.", "st": "2.17"}, {"sp": "N", "t": "λέγεται δὲ παρεστηκέναι τῇ Ἥρᾳ τέχνη Ναυκύδους ἄγαλμα Ἥβης, ἐλέφαντος καὶ τοῦτο καὶ χρυσοῦ· παρὰ δὲ αὐτήν ἐστιν ἐπὶ κίονος ἄγαλμα Ἥρας ἀρχαῖον. τὸ δὲ ἀρχαιότατον πεποίηται μὲν ἐξ ἀχράδος, ἀνετέθη δὲ ἐς Τίρυνθα ὑπὸ Πειράσου τοῦ Ἄργου, Τίρυνθα δὲ ἀνελόντες Ἀργεῖοι κομίζουσιν ἐς τὸ Ἡραῖον· ὃ δὴ καὶ αὐτὸς εἶδον, καθήμενον ἄγαλμα οὐ μέγα.", "st": "2.17"}, {"sp": "N", "t": "ἀναθήματα δὲ τὰ ἄξια λόγου βωμὸς ἔχων ἐπειργασμένον τὸν λεγόμενον Ἥβης καὶ Ἡρακλέους γάμον· οὗτος μὲν ἀργύρου, χρυσοῦ δὲ καὶ λίθων λαμπόντων Ἀδριανὸς βασιλεὺς ταὼν ⟨ἀνέθηκεν·⟩ ἀνέθηκε δέ, ὅτι τὴν ὄρνιθα ἱερὰν τῆς Ἥρας νομίζουσι. κεῖται δὲ καὶ στέφανος χρυσοῦς καὶ πέπλος πορφύρας, Νέρωνος ταῦτα ἀναθήματα.", "st": "2.17"}, {"sp": "N", "t": "ἔστι δὲ ὑπὲρ τὸν ναὸν τοῦτον τοῦ προτέρου ναοῦ θεμέλιά τε καὶ εἰ δή τι ἄλλο ὑπελίπετο ἡ φλόξ. κατεκαύθη δὲ τὴν ἱέρειαν τῆς Ἥρας Χρυσηίδα ὕπνου καταλαβόντος, ὅτε ὁ λύχνος πρὸ τῶν στεφανωμάτων ἥπτετο. καὶ Χρυσηὶς μὲν ἀπελθοῦσα ἐς Τεγέαν τὴν Ἀθηνᾶν τὴν Ἀλέαν ἱκέτευεν· Ἀργεῖοι δὲ καίπερ κακοῦ τηλικούτου παρόντος σφίσι τὴν εἰκόνα οὐ καθεῖλον τῆς Χρυσηίδος, ἀνάκειται δὲ καὶ ἐς τόδε τοῦ ναοῦ τοῦ κατακαυθέντος ἔμπροσθεν.", "st": "2.17"}, {"sp": "N", "t": "ἐκ Μυκηνῶν δὲ ἐς Ἄργος ἐρχομένοις ἐν ἀριστερᾷ Περσέως παρὰ τὴν ὁδόν ἐστιν ἡρῷον. ἔχει μὲν δὴ καὶ ἐνταῦθα τιμὰς παρὰ τῶν προσχωρίων, μεγίστας δὲ ἔν τε Σερίφῳ καὶ παρ’ Ἀθηναίοις⟨, οἷς⟩ Περσέως τέμενος καὶ Δίκτυος καὶ Κλυμένης βωμὸς σωτήρων καλουμένων Περσέως. ἐν δὲ τῇ Ἀργείᾳ προελθοῦσιν ὀλίγον ἀπὸ τοῦ ἡρῴου τούτου Θυέστου τάφος ἐστὶν ἐν δεξιᾷ· λίθου δὲ ἔπεστιν αὐτῷ κριός, ὅτι τὴν ἄρνα ὁ Θυέστης ἔσχε τὴν χρυσῆν, μοιχεύσας τοῦ ἀδελφοῦ τὴν γυναῖκα. Ἀτρέα δὲ οὐκ ἐπέσχεν ὁ λογισμὸς μετρῆσαι τὴν ἴσην, ἀλλὰ τῶν Θυέστου παίδων σφαγὰς καὶ τὰ ᾀδόμενα δεῖπνα ἐξειργάσατο.", "st": "2.18"}, {"sp": "N", "t": "ὕστερον δὲ οὐκ ἔχω σαφὲς εἰπεῖν πότερον ἀδικίας ἦρξεν Αἴγισθος ἢ προϋπῆρξεν Ἀγαμέμνονι φόνος Ταντάλου τοῦ Θυέστου· συνοικεῖν δέ φασιν αὐτὸν Κλυταιμνήστρᾳ παρθένῳ παρὰ Τυνδάρεω λαβόντα. ἐγὼ δὲ καταγνῶναι μὲν οὐκ ἐθέλω φύσει σφᾶς γενέσθαι κακούς· εἰ δὲ ἐπὶ τοσοῦτον αὐτοῖς τὸ μίασμα τὸ Πέλοπος καὶ ὁ Μυρτίλου προστρόπαιος ἠκολούθησε, τούτοις ἦν ἄρα ὁμολογοῦντα, ἡνίκα ἡ Πυθία Γλαύκῳ τῷ Ἐπικύδους Σπαρτιάτῃ, βουλεύσαντι ἐπίορκα ὀμόσαι, καὶ τοῦδε εἶπεν ἐς τοὺς ἀπογόνους κατιέναι τὴν δίκην.", "st": "2.18"}, {"sp": "N", "t": "ἀπὸ δὲ τῶν Κριῶν—οὕτω γὰρ τοῦ Θυέστου τὸ μνῆμα ὀνομάζουσι—προελθοῦσιν ὀλίγον ἐστὶν ἐν ἀριστερᾷ χωρίον Μυσία καὶ Δήμητρος Μυσίας ἱερὸν ἀπὸ ἀνδρὸς Μυσίου τὸ ὄνομα, γενομένου καὶ τούτου, καθάπερ λέγουσιν Ἀργεῖοι, ξένου τῇ Δήμητρι. τούτῳ μὲν οὖν οὐκ ἔπεστιν ὄροφος· ἐν δὲ αὐτῷ ναός ἐστιν ἄλλος ὀπτῆς πλίνθου, ξόανα δὲ Κόρης καὶ Πλούτωνος καὶ Δήμητρός ἐστι. προελθοῦσι δὲ ποταμός ἐστιν Ἴναχος, καὶ διαβᾶσιν Ἡλίου βωμός. ἐντεῦθεν δὲ ἐπὶ πύλην ἥξεις καλουμένην ἀπὸ τοῦ πλησίον ἱεροῦ· τὸ δὲ ἱερόν ἐστιν Εἰλειθυίας.", "st": "2.18"}, {"sp": "N", "t": "μόνους δὲ Ἑλλήνων οἶδα Ἀργείους ἐς τρεῖς βασιλείας νεμηθέντας. ἐπὶ γὰρ τῆς ἀρχῆς τῆς Ἀναξαγόρου τοῦ Ἀργείου τοῦ Μεγαπένθους μανία ταῖς γυναιξὶν ἐνέπεσεν, ἐκφοιτῶσαι δὲ ἐκ τῶν οἰκιῶν ἐπλανῶντο ἀνὰ τὴν χώραν, ἐς ὃ Μελάμπους ὁ Ἀμυθάονος ἔπαυσε σφᾶς τῆς νόσου, ἐφ’ ᾧ τε αὐτὸς καὶ ὁ ἀδελφὸς Βίας Ἀναξαγόρᾳ τὸ ἴσον ἕξουσιν. ἀπὸ μὲν δὴ Βίαντος βασιλεύουσι πέντε ἄνδρες ἐπὶ γενεὰς τέσσαρας ἐς Κυάνιππον τὸν Αἰγιαλέως, ὄντες Νηλεῖδαι τὰ πρὸς μητρός, ἀπὸ δὲ Μελάμποδος γενεαί τε ἓξ καὶ ἄνδρες ἴσοι μέχρις Ἀμφιλόχου τοῦ Ἀμφιαράου·", "st": "2.18"}, {"sp": "N", "t": "τὸ δὲ ἐγχώριον γένος οἱ Ἀναξαγορίδαι βασιλεύουσι πλέον. Ἶφις μὲν γὰρ ὁ Ἀλέκτορος τοῦ Ἀναξαγόρου Σθενέλῳ τῷ Καπανέως ἀδελφοῦ παιδὶ ἀπέλιπε τὴν ἀρχήν· Ἀμφιλόχου δὲ μετὰ ἅλωσιν Ἰλίου μετοικήσαντος ἐς τοὺς νῦν Ἀμφιλόχους, Κυανίππου ⟨δ’⟩ ἄπαιδος τελευτήσαντος, οὕτω Κυλαράβης ὁ Σθενέλου μόνος τὴν βασιλείαν ἔσχεν. οὐ μέντοι παῖδας κατέλιπεν οὐδ’ οὗτος, ἀλλὰ Ὀρέστης ὁ Ἀγαμέμνονος τὸ Ἄργος κατέσχε παροικῶν τε ἐγγὺς αὐτῷ καὶ ἄνευ τῆς πατρῴας ἀρχῆς προσπεποιημένος μὲν Ἀρκάδων τοὺς πολλούς, παρειληφὼς δὲ καὶ τὴν ἐν Σπάρτῃ βασιλείαν, συμμαχικοῦ δὲ ἐκ Φωκέων ἀεί ποτε ἐπ’ ὠφελείᾳ ἑτοίμου παρόντος.", "st": "2.18"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἐβασίλευσεν Ὀρέστης Λακεδαιμονίων ἐφέντων αὐτῷ· τοὺς γὰρ Τυνδάρεω θυγατριδοῦς τὴν ἀρχὴν ἔχειν [οὐκ] ἠξίουν πρὸ Νικοστράτου καὶ Μεγαπένθους Μενελάῳ γεγενημένων ἐκ δούλης. Ὀρέστου δὲ ἀποθανόντος ἔσχε Τισαμενὸς τὴν ἀρχήν, Ἑρμιόνης τῆς Μενελάου καὶ Ὀρέστου παῖς. τὸν δὲ Ὀρέστου νόθον Πενθίλον Κιναίθων ἔγραψεν ἐν τοῖς ἔπεσιν Ἠριγόνην τὴν Αἰγίσθου τεκεῖν.", "st": "2.18"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ Τισαμενοῦ τούτου κατίασιν ἐς Πελοπόννησον Ἡρακλεῖδαι, Τήμενος μὲν καὶ Κρεσφόντης Ἀριστομάχου, τοῦ τρίτου δὲ Ἀριστοδήμου προτεθνεῶτος εἵποντο οἱ παῖδες. Ἄργους μὲν δὴ καὶ τῆς ἐν Ἄργει βασιλείας ὀρθότατα ἐμοὶ δοκεῖν ἠμφισβήτουν, ὅτι ἦν Πελοπίδης ὁ Τισαμενός, οἱ δὲ Ἡρακλεῖδαι τὸ ἀνέκαθέν εἰσι Περσεῖδαι· Τυνδάρεω δὲ καὶ αὐτὸν ἐκπεσόντα ἀπέφαινον ὑπὸ Ἱπποκόωντος, Ἡρακλέα δὲ ἔφασαν ἀποκτείναντα Ἱπποκόωντα καὶ τοὺς παῖδας παρακαταθέσθαι Τυνδάρεῳ τὴν χώραν· τοιαῦτα δὲ καὶ περὶ τῆς Μεσσηνίας ἕτερα ἔλεγον, παρακαταθήκην Νέστορι δοθῆναι καὶ ταύτην ὑπὸ Ἡρακλέους ἑλόντος Πύλον.", "st": "2.18"}, {"sp": "N", "t": "ἐκβάλλουσιν οὖν ἐκ μὲν Λακεδαίμονος καὶ Ἄργους Τισαμενόν, ἐκ δὲ τῆς Μεσσηνίας τοὺς Νέστορος ἀπογόνους, Ἀλκμαίωνα Σίλλου τοῦ Θρασυμήδους καὶ Πεισίστρατον τὸν Πεισιστράτου καὶ τοὺς Παίονος τοῦ Ἀντιλόχου παῖδας, σὺν δὲ αὐτοῖς Μέλανθον τὸν Ἀνδροπόμπου τοῦ Βώρου τοῦ Πενθίλου τοῦ Περικλυμένου. Τισαμενὸς μὲν οὖν ἦλθε σὺν τῇ στρατιᾷ καὶ οἱ παῖδες ἐς τὴν νῦν Ἀχαΐαν·", "st": "2.18"}, {"sp": "N", "t": "οἱ δὲ Νηλεῖδαι πλὴν Πεισιστράτου—τοῦτον γὰρ οὐκ οἶδα παρ’ οὕστινας ἀπεχώρησεν—ἐς Ἀθήνας ἀφίκοντο οἱ λοιποί, καὶ τὸ Παιονιδῶν γένος καὶ Ἀλκμαιωνιδῶν ἀπὸ τούτων ὠνομάσθησαν. Μέλανθος δὲ καὶ τὴν βασιλείαν ἔσχεν ἀφελόμενος Θυμοίτην τὸν Ὀξύντου· Θυμοίτης γὰρ Θησειδῶν ἔσχατος ἐβασίλευσεν Ἀθηναίων.", "st": "2.18"}, {"sp": "N", "t": "τὰ μὲν οὖν Κρεσφόντου καὶ τῶν Ἀριστοδήμου παίδων οὐκ ἤπειγεν ὁ λόγος με ἐνταῦθα δηλῶσαι· Τήμενος δὲ ἐκ μὲν τοῦ φανεροῦ Δηιφόντῃ τῷ Ἀντιμάχου τοῦ Θρασυάνορος τοῦ Κτησίππου τοῦ Ἡρακλέους στρατηγῷ πρὸς τὰς μάχας ἐχρήσατο ἀντὶ τῶν υἱῶν καὶ σύμβουλον ἐς πάντα εἶχεν, ἅτε αὐτόν τε ἐκεῖνον πεποιημένος πρότερον ἔτι γαμβρὸν καὶ τῶν παίδων ἀρεσκόμενος τῇ Ὑρνηθοῖ μάλιστα, ὑπωπτεύετο δὲ ἤδη καὶ τὴν βασιλείαν ἐς ἐκείνην καὶ Δηιφόντην τρέπειν. ἐπεβουλεύθη δὲ τούτων ἕνεκα ὑπὸ τῶν υἱῶν· ἐκείνων δὲ αὐτῷ Κεῖσος πρεσβύτατος ὢν ἔσχε τὴν ἀρχήν.", "st": "2.19"}, {"sp": "N", "t": "Ἀργεῖοι δέ, ἅτε ἰσηγορίαν καὶ τὸ αὐτόνομον ἀγαπῶντες ἐκ παλαιοτάτου, τὰ τῆς ἐξουσίας τῶν βασιλέων ἐς ἐλάχιστον προήγαγον, ὡς Μήδωνι τῷ Κείσου καὶ τοῖς ἀπογόνοις τὸ ὄνομα λειφθῆναι τῆς βασιλείας μόνον. Μέλταν δὲ τὸν Λακήδου δέκατον ἀπόγονον Μήδωνος τὸ παράπαν ἔπαυσεν ἀρχῆς καταγνοὺς ὁ δῆμος.", "st": "2.19"}, {"sp": "N", "t": "Ἀργείοις δὲ τῶν ἐν τῇ πόλει τὸ ἐπιφανέστατόν ἐστιν Ἀπόλλωνος ἱερὸν Λυκίου. τὸ μὲν οὖν ἄγαλμα τὸ ἐφ’ ἡμῶν Ἀττάλου ποίημα ἦν Ἀθηναίου, τὸ δὲ ἐξ ἀρχῆς Δαναοῦ καὶ ὁ ναὸς καὶ τὸ ξόανον ἀνάθημα ἦν· ξόανα γὰρ δὴ τότε εἶναι πείθομαι πάντα καὶ μάλιστα τὰ Αἰγύπτια. Δαναὸς δὲ ἱδρύσατο Λύκιον Ἀπόλλωνα ἐπ’ αἰτίᾳ τοιαύτῃ. παραγενόμενος ἐς τὸ Ἄργος ἠμφισβήτει πρὸς Γελάνορα τὸν Σθενέλα περὶ τῆς ἀρχῆς. ῥηθέντων δὲ ἐπὶ τοῦ δήμου παρ’ ἀμφοτέρων πολλῶν τε καὶ ἐπαγωγῶν καὶ οὐχ ἧσσον δίκαια λέγειν τοῦ Γελάνορος δόξαντος, ὁ μὲν δῆμος ὑπερέθετο—φασὶν— ἐς τὴν ἐπιοῦσαν κρίνειν·", "st": "2.19"}, {"sp": "N", "t": "ἀρχομένης δὲ ἡμέρας ἐς βοῶν ἀγέλην νεμομένην πρὸ τοῦ τείχους ἐσπίπτει λύκος, προσπεσὼν δὲ ἐμάχετο πρὸς ταῦρον ἡγεμόνα τῶν βοῶν. παρίσταται δὴ τοῖς Ἀργείοις τῷ μὲν Γελάνορα, Δαναὸν δὲ εἰκάσαι τῷ λύκῳ, ὅτι οὔτε τὸ θηρίον τοῦτό ἐστιν ἀνθρώποις σύντροφον οὔτε Δαναός σφισιν ἐς ἐκεῖνο τοῦ χρόνου. ἐπεὶ δὲ τὸν ταῦρον κατειργάσατο ὁ λύκος, διὰ τοῦτο ὁ Δαναὸς ἔσχε τὴν ἀρχήν. οὕτω δὴ νομίζων Ἀπόλλωνα ἐπὶ τὴν ἀγέλην ἐπαγαγεῖν τῶν βοῶν τὸν λύκον, ἱδρύσατο Ἀπόλλωνος ἱερὸν Λυκίου.", "st": "2.19"}, {"sp": "N", "t": "ἐνταῦθα ἀνάκειται μὲν θρόνος Δαναοῦ, κεῖται δὲ εἰκὼν Βίτωνος, ἀνὴρ ἐπὶ τῶν ὤμων φέρων ταῦρον· ὡς δὲ Λυκέας ἐποίησεν, ἐς Νεμέαν Ἀργείων ἀγόντων θυσίαν τῷ Διὶ ὁ Βίτων ὑπὸ ῥώμης τε καὶ ἰσχύος ταῦρον ἀράμενος ἤνεγκεν. ἑξῆς δὲ τῆς εἰκόνος ταύτης πῦρ καίουσιν ὀνομάζοντες Φορωνέως εἶναι· οὐ γάρ τι ὁμολογοῦσι δοῦναι πῦρ Προμηθέα ἀνθρώποις, ἀλλὰ ἐς Φορωνέα τοῦ πυρὸς μετάγειν ἐθέλουσι τὴν εὕρεσιν.", "st": "2.19"}, {"sp": "N", "t": "τὰ δὲ ξόανα Ἀφροδίτης καὶ Ἑρμοῦ, τὸ μὲν Ἐπειοῦ λέγουσιν ἔργον εἶναι, τὸ δὲ Ὑπερμήστρας ἀνάθημα. ταύτην γὰρ τῶν θυγατέρων μόνην τὸ πρόσταγμα ὑπεριδοῦσαν ὑπήγαγεν ὁ Δαναὸς ἐς δικαστήριον, τοῦ τε Λυγκέως οὐκ ἀκίνδυνον αὑτῷ τὴν σωτηρίαν ἡγούμενος καὶ ὅτι τοῦ τολμήματος οὐ μετασχοῦσα ταῖς ἀδελφαῖς καὶ τῷ βουλεύσαντι τὸ ὄνειδος ηὔξησε. κριθεῖσα δὲ ἐν τοῖς Ἀργείοις ἀποφεύγει τε καὶ Ἀφροδίτην ἐπὶ τῷδε ἀνέθηκε Νικηφόρον.", "st": "2.19"}, {"sp": "N", "t": "τοῦ ναοῦ δέ ἐστιν ἐντὸς Λάδας ποδῶν ὠκύτητι ὑπερβαλλόμενος τοὺς ἐφ’ αὑτοῦ καὶ Ἑρμῆς ἐς λύρας ποίησιν χελώνην ᾑρηκώς. ἔστι δὲ ἔμπροσθεν τοῦ ναοῦ βόθρος πεποιημένα ἐν τύπῳ ταύρου μάχην ἔχων καὶ λύκου, σὺν δὲ αὐτοῖς παρθένον ἀφιεῖσαν πέτραν ἐπὶ τὸν ταῦρον· Ἄρτεμιν [δὲ] εἶναι νομίζουσι τὴν παρθένον. Δαναὸς δὲ ταῦτά τε ἀνέθηκε καὶ πλησίον κίονας καὶ Διὸς καὶ Ἀρτέμιδος ξόανον.", "st": "2.19"}, {"sp": "N", "t": "τάφοι δέ εἰσιν ὁ μὲν Λίνου τοῦ Ἀπόλλωνος καὶ Ψαμάθης τῆς Κροτώπου, τὸν δὲ λέγουσιν εἶναι Λίνου τοῦ ποιήσαντος τὰ ἔπη. τὰ μὲν οὖν ἐς τοῦτον οἰκειότερα ὄντα ἑτέρῳ λόγῳ παρίημι τῷδε, τὰ δὲ ἐς τὸν Ψαμάθης ἡ Μεγαρική μοι συγγραφὴ προεδήλωσεν. ἐπὶ τούτοις ἐστὶν Ἀπόλλων Ἀγυιεὺς καὶ βωμὸς Ὑετίου Διός, ἔνθα οἱ συσπεύδοντες Πολυνείκει τὴν ἐς Θήβας κάθοδον ἀποθανεῖσθαι συνώμοσαν, ἢν μὴ τὰς Θήβας γένηταί σφισιν ἑλεῖν. ἐς δὲ τοῦ Προμηθέως τὸ μνῆμα ἧσσόν μοι δοκοῦσιν Ὀπουντίων εἰκότα λέγειν, λέγουσι δὲ ὅμως.", "st": "2.19"}, {"sp": "N", "t": "παρέντι δὲ Κρεύγα τε εἰκόνα ἀνδρὸς πύκτου ⟨καὶ⟩ τρόπαιον ἐπὶ Κορινθίοις ἀνασταθέν, ἄγαλμά ἐστι καθήμενον Διὸς Μειλιχίου, λίθου λευκοῦ, Πολυκλείτου δὲ ἔργον. ποιηθῆναι δὲ ἐπυνθανόμην αὐτὸ ἐπ’ αἰτίᾳ τοιαύτῃ. Λακεδαιμονίοις πολεμεῖν πρὸς Ἀργείους ἀρξαμένοις οὐδεμία ἦν ἔτι ἀπαλλαγή, πρὶν ἢ Φίλιππος σφᾶς ἠνάγκασεν ὁ Ἀμύντου μένειν ἐπὶ τοῖς καθεστηκόσιν ἐξ ἀρχῆς ὅροις τῆς χώρας. τὸν δὲ ἔμπροσθεν χρόνον οἱ Λακεδαιμόνιοι μηδὲν ἔξω Πελοποννήσου περιεργαζόμενοι τῆς Ἀργείας ἀεί τι ἀπετέμνοντο, ἢ οἱ Ἀργεῖοι τετραμμένων πρὸς πόλεμον ἐκείνων ὑπερόριον ἐν τῷ τοιούτῳ καὶ αὐτοί σφισιν ἐνέκειντο.", "st": "2.20"}, {"sp": "N", "t": "προηγμένου δὲ ἀμφοτέροις ἐς ἄκρον τοῦ μίσους ἔδοξεν Ἀργείοις λογάδας τρέφειν χιλίους· ἡγεμὼν δὲ ἐτέτακτο ἐπ’ αὐτοῖς Βρύας Ἀργεῖος, ὃς ἄλλα τε ἐς ἄνδρας ὕβρισε τοῦ δήμου καὶ παρθένον κομιζομένην παρὰ τὸν νυμφίον ᾔσχυνεν ἀφελόμενος τοὺς ἄγοντας. ἐπιλαβούσης δὲ τῆς νυκτὸς τυφλοῖ τὸν Βρύαντα ἡ παῖς φυλάξασα ὑπνωμένον· φωραθεῖσα δὲ ὡς ἐπέσχεν ἡμέρα, κατέφυγεν ἱκέτις ἐς τὸν δῆμον. οὐ προεμένων δὲ αὐτὴν τιμωρήσασθαι τοῖς χιλίοις καὶ ἀπὸ τούτου προαχθέντων ἐς μάχην ἀμφοτέρων, κρατοῦσιν οἱ τοῦ δήμου, κρατήσαντες δὲ οὐδένα ὑπὸ τοῦ θυμοῦ τῶν ἐναντίων ἔλιπον. ὕστερον δὲ ἄλλα τε ἐπηγάγοντο καθάρσια ὡς ἐπὶ αἵματι ἐμφυλίῳ καὶ ἄγαλμα ἀνέθηκαν Μειλιχίου Διός.", "st": "2.20"}, {"sp": "N", "t": "πλησίον δέ εἰσιν ἐπειργασμένοι λίθῳ Κλέοβις καὶ Βίτων αὐτοί τε ἕλκοντες τὴν ἅμαξαν καὶ ἐπ’ αὐτῇ ἄγοντες τὴν μητέρα ἐς τὸ Ἡραῖον. τούτων δὲ ἀπαντικρὺ Νεμείου Διός ἐστιν ἱερόν, ἄγαλμα ὀρθὸν χαλκοῦν, τέχνη Λυσίππου. μετὰ δὲ αὐτὸ προελθοῦσιν ἐν δεξιᾷ Φορωνέως τάφος ἐστίν· ἐναγίζουσι δὲ καὶ ἐς ἡμᾶς ἔτι τῷ Φορωνεῖ. πέραν δὲ τοῦ Νεμείου Διὸς Τύχης ἐστὶν ἐκ παλαιοτάτου ναός, εἰ δὴ Παλαμήδης κύβους εὑρὼν ἀνέθηκεν ἐς τοῦτον τὸν ναόν.", "st": "2.20"}, {"sp": "N", "t": "τὸ δὲ μνῆμα τὸ πλησίον Χορείας μαινάδος ὀνομάζουσι, Διονύσῳ λέγοντες καὶ ἄλλας γυναῖκας καὶ ταύτην ἐς Ἄργος συστρατεύσασθαι, Περσέα δέ, ὡς ἐκράτει τῆς μάχης, φονεῦσαι τῶν γυναικῶν τὰς πολλάς· τὰς μὲν οὖν λοιπὰς θάπτουσιν ἐν κοινῷ, ταύτῃ δὲ—ἀξιώματι γὰρ δὴ προεῖχεν—ἰδίᾳ τὸ μνῆμα ἐποίησαν.", "st": "2.20"}, {"sp": "N", "t": "ἀπωτέρω δὲ ὀλίγον Ὡρῶν ἱερόν ἐστιν. ἐπανιόντι δὲ ἐκεῖθεν ἀνδριάντες ἑστήκασι Πολυνείκους τοῦ Οἰδίποδος καὶ ὅσοι σὺν ἐκείνῳ τῶν ἐν τέλει πρὸς τὸ τεῖχος μαχόμενοι τὸ Θηβαίων ἐτελεύτησαν. τούτους τοὺς ἄνδρας ἐς μόνων ἑπτὰ ἀριθμὸν κατήγαγεν Αἰσχύλος, πλειόνων ἔκ τε Ἄργους ἡγεμόνων καὶ Μεσσήνης καί τινων καὶ Ἀρκάδων στρατευσαμένων. τούτων δὲ τῶν ἑπτὰ—ἐπηκολουθήκασι γὰρ καὶ Ἀργεῖοι τῇ Αἰσχύλου ποιήσει—πλησίον κεῖνται καὶ οἱ τὰς Θήβας ἑλόντες Αἰγιαλεὺς Ἀδράστου καὶ Πρόμαχος ὁ Παρθενοπαίου τοῦ Ταλαοῦ καὶ Πολύδωρος Ἱππομέδοντος καὶ Θέρσανδρος καὶ οἱ Ἀμφιαράου παῖδες, Ἀλκμαίων τε καὶ Ἀμφίλοχος, Διομήδης τε καὶ Σθένελος· παρῆν δὲ ἔτι καὶ ἐπὶ τούτων Εὐρύαλος Μηκιστέως καὶ Πολυνείκους Ἄδραστος καὶ Τιμέας.", "st": "2.20"}, {"sp": "N", "t": "τῶν δὲ ἀνδριάντων οὐ πόρρω δείκνυται Δαναοῦ μνῆμα καὶ Ἀργείων τάφος κενὸς ὁπόσους ἔν τε Ἰλίῳ καὶ ὀπίσω κομιζομένους ἐπέλαβεν ἡ τελευτή. καὶ Διός ἐστιν ἐνταῦθα ἱερὸν Σωτῆρος καὶ παριοῦσίν ἐστιν οἴκημα· ἐνταῦθα τὸν Ἄδωνιν αἱ γυναῖκες Ἀργείων ὀδύρονται. ἐν δεξιᾷ δὲ τῆς ἐσόδου τῷ Κηφισῷ πεποίηται τὸ ἱερόν· τῷ δὲ ποταμῷ τούτῳ τὸ ὕδωρ φασὶν οὐ καθάπαξ ὑπὸ τοῦ Ποσειδῶνος ἀφανισθῆναι, ἀλλὰ ἐνταῦθα δὴ μάλιστα, ἔνθα καὶ τὸ ἱερόν ἐστι, συνιᾶσιν ὑπὸ γῆν ῥέοντος.", "st": "2.20"}, {"sp": "N", "t": "παρὰ δὲ τὸ ἱερὸν τοῦ Κηφισοῦ Μεδούσης λίθου πεποιημένη κεφαλή· Κυκλώπων φασὶν εἶναι καὶ τοῦτο ἔργον. τὸ δὲ χωρίον τὸ ὄπισθεν καὶ ἐς τόδε Κριτήριον ὀνομάζουσιν, Ὑπερμήστραν ἐνταῦθα ὑπὸ Δαναοῦ κριθῆναι λέγοντες. τούτου δέ ἐστιν οὐ πόρρω θέατρον· ἐν δὲ αὐτῷ καὶ ἄλλα θέας ἄξια καὶ ἀνὴρ φονεύων ἐστὶν ἄνδρα, Ὀθρυάδαν τὸν Σπαρτιάτην Περίλαος Ἀργεῖος ὁ Ἀλκήνορος· Περιλάῳ δὲ τούτῳ καὶ πρότερον ἔτι ὑπῆρχε Νεμείων ἀνῃρῆσθαι νίκην παλαίοντι.", "st": "2.20"}, {"sp": "N", "t": "ὑπὲρ δὲ τὸ θέατρον Ἀφροδίτης ἐστὶν ἱερόν, ἔμπροσθεν δὲ τοῦ ἕδους Τελέσιλλα ἡ ποιήσασα τὰ ᾄσματα ἐπείργασται στήλῃ· καὶ βιβλία μὲν ἐκεῖνα ἔρριπταί οἱ πρὸς τοῖς ποσίν, αὐτὴ δὲ ἐς κράνος ὁρᾷ κατέχουσα τῇ χειρὶ καὶ ἐπιτίθεσθαι τῇ κεφαλῇ μέλλουσα. ἦν δὲ ἡ Τελέσιλλα καὶ ἄλλως ἐν ταῖς γυναιξὶν εὐδόκιμος καὶ μᾶλλον ἐτιμᾶτο ἔτι ἐπὶ τῇ ποιήσει. συμβάντος δὲ Ἀργείοις ἀτυχῆσαι λόγου μειζόνως πρὸς Κλεομένην τὸν Ἀναξανδρίδου καὶ Λακεδαιμονίους, καὶ τῶν μὲν ἐν αὐτῇ πεπτωκότων τῇ μάχῃ, ὅσοι δὲ ἐς τὸ ἄλσος τοῦ Ἄργου κατέφευγον διαφθαρέντων καὶ τούτων, τὰ μὲν πρῶτα ἐξιόντων κατὰ ὁμολογίαν, ὡς δὲ ἔγνωσαν ἀπατώμενοι συγκατακαυθέντων τῷ ἄλσει τῶν λοιπῶν, οὕτω τοὺς Λακεδαιμονίους Κλεομένης ἦγεν ἐπὶ ἔρημον ἀνδρῶν τὸ Ἄργος.", "st": "2.20"}, {"sp": "N", "t": "Τελέσιλλα δὲ οἰκέτας μὲν καὶ ὅσοι διὰ νεότητα ἢ γῆρας ὅπλα ἀδύνατοι φέρειν ἦσαν, τούτους μὲν πάντας ἀνεβίβασεν ἐπὶ τὸ τεῖχος, αὐτὴ δὲ ὁπόσα ἐν ταῖς οἰκίαις ὑπελείπετο καὶ τὰ ἐκ τῶν ἱερῶν ὅπλα ἀθροίσασα τὰς ἀκμαζούσας ἡλικίᾳ τῶν γυναικῶν ὥπλιζεν, ὁπλίσασα δὲ ἔτασσε κατὰ τοῦτο ᾗ τοὺς πολεμίους προσιόντας ἠπίστατο. ὡς δὲ ⟨ἐγγὺς⟩ ἐγίνοντο οἱ Λακεδαιμόνιοι καὶ αἱ γυναῖκες οὔτε τῷ ἀλαλαγμῷ κατεπλάγησαν δεξάμεναί τε ἐμάχοντο ἐρρωμένως, ἐνταῦθα οἱ Λακεδαιμόνιοι, φρονήσαντες ὡς καὶ διαφθείρασί σφισι τὰς γυναῖκας ἐπιφθόνως τὸ κατόρθωμα ἕξει καὶ σφαλεῖσι μετὰ ὀνειδῶν γενήσοιτο ἡ συμφορά, ὑπείκουσι ταῖς γυναιξί.", "st": "2.20"}, {"sp": "N", "t": "πρότερον δὲ ἔτι τὸν ἀγῶνα τοῦτον προεσήμηνεν ἡ Πυθία, καὶ τὸ λόγιον εἴτε ἄλλως εἴτε καὶ ὡς συνεὶς ἐδήλωσεν Ἡρόδοτος·<br>ἀλλ’ ὅταν ἡ θήλεια τὸν ἄρρενα νικήσασα<br>ἐξελάσῃ καὶ κῦδος ἐν Ἀργείοισιν ἄρηται,<br>πολλὰς Ἀργείων ἀμφιδρυφέας τότε θήσει.<br>τὰ μὲν ἐς τὸ ἔργον τῶν γυναικῶν ἔχοντα τοῦ χρησμοῦ ταῦτα ἦν·", "st": "2.20"}, {"sp": "N", "t": "κατελθοῦσι δὲ ἐντεῦθεν καὶ τραπεῖσιν αὖθις ἐπὶ τὴν ἀγοράν, ἔστι μὲν Κερδοῦς Φορωνέως γυναικὸς μνῆμα, ἔστι δὲ ναὸς Ἀσκληπιοῦ. τὸ δὲ τῆς Ἀρτέμιδος ἱερὸν ἐπίκλησιν Πειθοῦς, Ὑπερμήστρα καὶ τοῦτο ἀνέθηκε νικήσασα τῇ δίκῃ τὸν πατέρα ἣν τοῦ Λυγκέως ἕνεκα ἔφυγε. καὶ Αἰνείου ἐνταῦθα χαλκοῦς ἀνδριάς ἐστι καὶ χωρίον καλούμενον Δέλτα· ἐφ’ ὅτῳ δέ—οὐ γάρ μοι τὰ λεγόμενα ἤρεσκεν—, ἑκὼν παρίημι.", "st": "2.21"}, {"sp": "N", "t": "πρὸ δὲ αὐτοῦ πεποίηται Διὸς Φυξίου βωμὸς καὶ πλησίον Ὑπερμήστρας μνῆμα Ἀμφιαράου μητρός, τὸ δὲ ἕτερον Ὑπερμήστρας τῆς Λαναοῦ· σὺν δὲ αὐτῇ καὶ Λυγκεὺς τέθαπται. τούτων δὲ ἀπαντικρὺ Ταλαοῦ τοῦ Βίαντός ἐστι τάφος· τὰ δὲ ἐς Βίαντα καὶ ἀπογόνους τοῦ Βίαντος ἤδη λέλεκταί μοι.", "st": "2.21"}, {"sp": "N", "t": "Ἀθηνᾶς δὲ ἱδρύσασθαι Σάλπιγγος ἱερόν φασιν Ἡγέλεων. Τυρσηνοῦ δὲ τοῦτον ⟨τὸν⟩ Ἡγέλεων, τὸν δὲ Ἡρακλέους εἶναι καὶ γυναικὸς λέγουσι τῆς Λυδῆς, Τυρσηνὸν δὲ σάλπιγγα εὑρεῖν πρῶτον, Ἡγέλεων δὲ τὸν Τυρσηνοῦ διδάξαι τοὺς σὺν Τημένῳ Δωριέας τοῦ ὀργάνου τὸν ψόφον καὶ δι’ αὐτὸ Ἀθηνᾶν ἐπονομάσαι Σάλπιγγα. πρὸ δὲ τοῦ ναοῦ τῆς Ἀθηνᾶς Ἐπιμενίδου λέγουσιν εἶναι τάφον· Λακεδαιμονίους γὰρ πολεμήσαντας πρὸς Κνωσσίους ἑλεῖν ζῶντα Ἐπιμενίδην, λαβόντας δὲ ἀποκτεῖναι, διότι σφίσιν οὐκ αἴσια ἐμαντεύετο, αὐτοὶ δὲ ἀνελόμενοι θάψαι ταύτῃ φασί.", "st": "2.21"}, {"sp": "N", "t": "τὸ δὲ οἰκοδόμημα λευκοῦ λίθου κατὰ μέσον μάλιστα τῆς ἀγορᾶς οὐ τρόπαιον ἐπὶ Πύρρῳ τῷ Ἠπειρώτῃ, καθὰ λέγουσιν οἱ Ἀργεῖοι, καυθέντος δὲ ἐνταῦθα τοῦ νεκροῦ μνῆμα καὶ τοῦτο ἂν εὕροι τις, ἐν ᾧ τά τε ἄλλα ὅσοις ὁ Πύρρος ἐχρῆτο ἐς τὰς μάχας καὶ οἱ ἐλέφαντές εἰσιν ἐπειργασμένοι. τοῦτο μὲν δὴ κατὰ τὴν πυρὰν ⟨τὸ⟩ οἰκοδόμημα ἐγένετο· αὐτὰ δὲ κεῖται τοῦ Πύρρου τὰ ὀστᾶ ἐν τῷ ἱερῷ τῆς Δήμητρος, παρ’ ᾧ συμβῆναί οἱ καὶ τὴν τελευτὴν ἐδήλωσα ἐν τῇ Ἀτθίδι συγγραφῇ. τοῦ δὲ τῆς Δήμητρος ἱεροῦ τούτου κατὰ τὴν ἔσοδον ἀσπίδα ἰδεῖν Πύρρου χαλκῆν ἔστιν ὑπὲρ τῶν θυρῶν ἀνακειμένην.", "st": "2.21"}, {"sp": "N", "t": "τοῦ δὲ ἐν τῇ ἀγορᾷ τῶν Ἀργείων οἰκοδομήματος οὐ μακρὰν χῶμα γῆς ἐστιν· ἐν δὲ αὐτῷ κεῖσθαι τὴν Μεδούσης λέγουσι τῆς Γοργόνος κεφαλήν. ἀπόντος δὲ τοῦ μύθου τάδε ἄλλα ἐς αὐτήν ἐστιν εἰρημένα· Φόρκου μὲν θυγατέρα εἶναι, τελευτήσαντος δέ οἱ τοῦ πατρὸς βασιλεύειν τῶν περὶ τὴν λίμνην τὴν Τριτωνίδα οἰκούντων καὶ ἐπὶ θήραν τε ἐξιέναι καὶ ἐς τὰς μάχας ἡγεῖσθαι τοῖς Λίβυσι καὶ δὴ καὶ τότε ἀντικαθημένην στρατῷ πρὸς τὴν Περσέως δύναμιν—ἕπεσθαι γὰρ καὶ τῷ Περσεῖ λογάδας ἐκ Πελοποννήσου— δολοφονηθῆναι νύκτωρ, καὶ τὸν Περσέα τὸ κάλλος ἔτι καὶ ἐπὶ νεκρῷ θαυμάζοντα οὕτω τὴν κεφαλὴν ἀποτεμόντα αὐτῆς ἄγειν τοῖς Ἕλλησιν ἐς ἐπίδειξιν.", "st": "2.21"}, {"sp": "N", "t": "Καρχηδονίῳ δὲ ἀνδρὶ Προκλεῖ τῷ Εὐκράτους ἕτερος λόγος ὅδε ἐφαίνετο εἶναι τοῦ προτέρου πιθανώτερος. Λιβύης ἡ ἔρημος καὶ ἄλλα παρέχεται θηρία ἀκούσασιν οὐ πιστὰ καὶ ἄνδρες ἐνταῦθα ἄγριοι καὶ ἄγριαι γίνονται γυναῖκες· ἔλεγέ τε ὁ Προκλῆς ἀπ’ αὐτῶν ἄνδρα ἰδεῖν κομισθέντα ἐς Ῥώμην. εἴκαζεν οὖν πλανηθεῖσαν γυναῖκα ἐκ τούτων καὶ ἀφικομένην ἐπὶ τὴν λίμνην τὴν Τριτωνίδα λυμαίνεσθαι τοὺς προσοίκους, ἐς ὃ Περσεὺς ἀπέκτεινεν αὐτήν· Ἀθηνᾶν δέ οἱ συνεπιλαβέσθαι δοκεῖν τοῦ ἔργου, ὅτι οἱ περὶ τὴν λίμνην τὴν Τριτωνίδα ἄνθρωποι ταύτης εἰσὶν ἱεροί.", "st": "2.21"}, {"sp": "N", "t": "ἐν δὲ Ἄργει παρὰ τοῦτο δὴ τὸ μνῆμα τῆς Γοργόνος Γοργοφόνης τάφος ἐστὶ τῆς Περσέως. καὶ ἐφ’ ὅτῳ μὲν αὐτῇ τὸ ὄνομα ἐτέθη, δῆλον εὐθὺς ἀκούσαντι· γυναικῶν δὲ πρώτην αὐτήν φασι τελευτήσαντος τοῦ ἀνδρὸς Περιήρους τοῦ Αἰόλου—τούτῳ γὰρ παρθένος συνῴκησε—, τὴν δὲ αὖθις Οἰβάλῳ γήμασθαι· πρότερον δὲ καθεστήκει ταῖς γυναιξὶν ἐπὶ ἀνδρὶ ἀποθανόντι χηρεύειν.", "st": "2.21"}, {"sp": "N", "t": "τοῦ τάφου δὲ ἔμπροσθεν τρόπαιον λίθου πεποίηται κατὰ ἀνδρὸς Ἀργείου Λαφάους· τοῦτον γὰρ—γράφω δὲ ὁπόσα λέγουσιν αὐτοὶ περὶ σφῶν Ἀργεῖοι—τυραννοῦντα ἐξέβαλεν ἐπαναστὰς ὁ δῆμος, φυγόντα δὲ ἐς Σπάρτην Λακεδαιμόνιοι κατάγειν ἐπειρῶντο ἐπὶ τυραννίδι, νικήσαντες δὲ οἱ Ἀργεῖοι τῇ μάχῃ Λαφάην τε καὶ τῶν Λακεδαιμονίων τοὺς πολλοὺς ἀπέκτειναν. τὸ δὲ ἱερὸν τῆς Λητοῦς ἔστι μὲν οὐ μακρὰν τοῦ τροπαίου, τέχνη δὲ τὸ ἄγαλμα Πραξιτέλους.", "st": "2.21"}, {"sp": "N", "t": "τὴν δὲ εἰκόνα παρὰ τῇ θεῷ τῆς παρθένου Χλῶριν ὀνομάζουσι, Νιόβης μὲν θυγατέρα εἶναι λέγοντες, Μελίβοιαν δὲ καλεῖσθαι τὸ ἐξ ἀρχῆς· ἀπολλυμένων δὲ ὑπὸ Ἀρτέμιδος καὶ Ἀπόλλωνος τῶν Ἀμφίονος παίδων περιγενέσθαι μόνην τῶν ἀδελφῶν ταύτην καὶ Ἀμύκλαν, περιγενέσθαι δὲ εὐξαμένους τῇ Λητοῖ. Μελίβοιαν δὲ οὕτω δή τι παραυτίκα τε χλωρὰν τὸ δεῖμα ἐποίησε καὶ ἐς τὸ λοιπὸν τοῦ βίου παρέμεινεν ὡς καὶ τὸ ὄνομα ἐπὶ τῷ συμβάντι ἀντὶ Μελιβοίας αὐτῇ γενέσθαι Χλῶριν.", "st": "2.21"}, {"sp": "N", "t": "τούτους δή φασιν Ἀργεῖοι τὸ ἐξ ἀρχῆς οἰκοδομῆσαι τῇ Λητοῖ τὸν ναόν· ἐγὼ δὲ—πρόσκειμαι γὰρ πλέον τι ἢ οἱ λοιποὶ τῇ Ὁμήρου ποιήσει—δοκῶ τῇ Νιόβῃ τῶν παίδων μηδένα ὑπόλοιπον γενέσθαι. μαρτυρεῖ δέ μοι τὸ ἔπος<br>τὼ δ’ ἄρα καὶ δοιώ περ ἐόντ’ ἀπὸ πάντας ὄλεσσαν.<br>οὗτος μὲν δὴ τὸν οἶκον τὸν Ἀμφίονος ἐκ βάθρων ἀνατραπέντα οἶδε·", "st": "2.21"}, {"sp": "N", "t": "τῆς δὲ Ἥρας ὁ ναὸς τῆς Ἀνθείας ἐστὶ τοῦ ἱεροῦ τῆς Λητοῦς ἐν δεξιᾷ καὶ πρὸ αὐτοῦ γυναικῶν τάφος. ἀπέθανον δὲ αἱ γυναῖκες ἐν μάχῃ πρὸς Ἀργείους τε καὶ Περσέα, ἀπὸ νήσων τῶν ἐν Αἰγαίῳ Διονύσῳ συνεστρατευμέναι· καὶ διὰ τοῦτο Ἁλίας αὐτὰς ἐπονομάζουσιν. ἀντικρὺ δὲ τοῦ μνήματος τῶν γυναικῶν Δήμητρός ἐστιν ἱερὸν ἐπίκλησιν Πελασγίδος ἀπὸ τοῦ ἱδρυσαμένου Πελασγοῦ τοῦ Τριόπα, καὶ οὐ πόρρω τοῦ ἱεροῦ τάφος Πελασγοῦ.", "st": "2.22"}, {"sp": "N", "t": "πέραν δὲ τοῦ τάφου χαλκεῖόν ἐστιν οὐ μέγα, ἀνέχει δὲ αὐτὸ ἀγάλματα ἀρχαῖα Ἀρτέμιδος καὶ Διὸς καὶ Ἀθηνᾶς. Λυκέας μὲν οὖν ἐν τοῖς ἔπεσιν ἐποίησε Μηχανέως τὸ ἄγαλμα εἶναι Διός, καὶ Ἀργείων ἔφη τοὺς ἐπὶ Ἴλιον στρατεύσαντας ἐνταῦθα ὀμόσαι παραμενεῖν πολεμοῦντας, ἔστ’ ἂν ἢ τὸ Ἴλιον ἕλωσιν ἢ μαχομένους τελευτὴ σφᾶς ἐπιλάβῃ· ἑτέροις δέ ἐστιν εἰρημένον ὀστᾶ ἐν τῷ χαλκείῳ κεῖσθαι Ταντάλου.", "st": "2.22"}, {"sp": "N", "t": "τὸν μὲν δὴ Θυέστου παῖδα ἢ Βροτέου—λέγεται γὰρ ἀμφότερα—, ὃς Κλυταιμνήστρᾳ πρότερον ἢ Ἀγαμέμνων συνῴκησε, τοῦτον μὲν ⟨τὸν⟩ Τάνταλον οὐ διοίσομαι ταφῆναι ταύτῃ· τοῦ δὲ λεγομένου Διός τε εἶναι καὶ Πλουτοῦς ἰδὼν οἶδα ἐν Σιπύλῳ τάφον θέας ἄξιον. πρὸς δὲ οὐδὲ ἀνάγκη συνέπεσεν ἐκ τῆς Σιπύλου φυγεῖν αὐτόν, ὡς Πέλοπα ἐπέλαβεν ὕστερον ἐλαύνοντος Ἴλου τοῦ Φρυγὸς ἐπ’ αὐτὸν στρατείᾳ. τάδε μὲν ἐς τοσοῦτον ἐξητάσθω· τὰ δὲ ἐς τὸν βόθρον τὸν πλησίον δρώμενα Νικόστρατον ἄνδρα ἐπιχώριον καταστήσασθαι λέγουσιν. ἀφιᾶσι δὲ καὶ νῦν ἔτι ἐς τὸν βόθρον καιομένας λαμπάδας Κόρῃ τῇ Δήμητρος.", "st": "2.22"}, {"sp": "N", "t": "ἐνταῦθα Ποσειδῶνός ἐστιν ἱερὸν ἐπίκλησιν Προσκλυστίου· τῆς γὰρ χώρας τὸν Ποσειδῶνά ⟨φασιν⟩ ἐπικλύσαι τὴν πολλήν, ὅτι Ἥρας εἶναι καὶ οὐκ αὐτοῦ τὴν γῆν Ἴναχος καὶ οἱ συνδικάσαντες ἔγνωσαν. Ἥρα μὲν δὴ παρὰ Ποσειδῶνος εὕρετο ἀπελθεῖν ὀπίσω τὴν θάλασσαν· Ἀργεῖοι δέ, ὅθεν τὸ κῦμα ἀνεχώρησεν, ἱερὸν Ποσειδῶνι ἐποίησαν Προσκλυστίῳ.", "st": "2.22"}, {"sp": "N", "t": "προελθόντι δὲ οὐ πολὺ τάφος ἐστὶν Ἄργου Διὸς εἶναι δοκοῦντος καὶ τῆς Φορωνέως Νιόβης· μετὰ δὲ ταῦτα Διοσκούρων ναός. ἀγάλματα δὲ αὐτοί τε καὶ οἱ παῖδές εἰσιν Ἄναξις καὶ Μνασίνους, σὺν δέ σφισιν αἱ μητέρες Ἱλάειρα καὶ Φοίβη, τέχνη μὲν Διποίνου καὶ Σκύλλιδος, ξύλου δὲ ἐβένου· τοῖς δ’ ἵπποις τὰ μὲν πολλὰ ἐβένου καὶ τούτοις, ὀλίγα δὲ καὶ ἐλέφαντος πεποίηται.", "st": "2.22"}, {"sp": "N", "t": "πλησίον δὲ τῶν Ἀνάκτων Εἰληθυίας ἐστὶν ἱερὸν ἀνάθημα Ἑλένης, ὅτε σὺν Πειρίθῳ Θησέως ἀπελθόντος ἐς Θεσπρωτοὺς Ἄφιδνά τε ὑπὸ Διοσκούρων ἑάλω καὶ ἤγετο ἐς Λακεδαίμονα Ἑλένη. ἔχειν μὲν γὰρ αὐτὴν λέγουσιν ἐν γαστρί, τεκοῦσαν δὲ ἐν Ἄργει καὶ τῆς Εἰληθυίας ἱδρυσαμένην τὸ ἱερὸν τὴν μὲν παῖδα ἣν ἔτεκε Κλυταιμνήστρᾳ δοῦναι—συνοικεῖν γὰρ ἤδη Κλυταιμνήστραν Ἀγαμέμνονι—, αὐτὴν δὲ ὕστερον τούτων Μενελάῳ γήμασθαι.", "st": "2.22"}, {"sp": "N", "t": "καὶ ἐπὶ τῷδε Εὐφορίων Χαλκιδεὺς καὶ Πλευρώνιος Ἀλέξανδρος ἔπη ποιήσαντες, πρότερον δὲ ἔτι Στησίχορος ὁ Ἱμεραῖος, κατὰ ταὐτά φασιν Ἀργείοις Θησέως εἶναι θυγατέρα Ἰφιγένειαν. τοῦ δὲ ἱεροῦ τῆς Εἰληθυίας πέραν ἐστὶν Ἑκάτης ναός, Σκόπα δὲ τὸ ἄγαλμα ἔργον. τοῦτο μὲν λίθου· τὰ δ’ ἀπαντικρὺ χαλκᾶ, Ἑκάτης καὶ ταῦτα ἀγάλματα, τὸ μὲν Πολύκλειτος ἐποίησε, τὸ δὲ ἀδελφὸς Πολυκλείτου Ναυκύδης †Μόθωνος.", "st": "2.22"}, {"sp": "N", "t": "ἐρχομένῳ δὲ ὁδὸν εὐθεῖαν ἐς γυμνάσιον Κυλάραβιν, ἀπὸ τοῦ παιδὸς ὀνομαζόμενον τοῦ Σθενέλου, τέθαπται δὴ Λικύμνιος ὁ Ἠλεκτρύωνος· ἀποθανεῖν δ’ αὐτὸν Ὅμηρος ὑπὸ Τληπτολέμου φησὶ τοῦ Ἡρακλέους, καὶ διὰ τὸν φόνον τοῦτον ἔφυγεν ἐξ Ἄργους Τληπτόλεμος. ὀλίγον δὲ τῆς ἐπὶ Κυλάραβιν καὶ τὴν ταύτῃ πύλην ἀποτραπεῖσι Σακάδα μνῆμά ἐστιν, ὃς τὸ αὔλημα τὸ Πυθικὸν πρῶτος ηὔλησεν ἐν Δελφοῖς·", "st": "2.22"}, {"sp": "N", "t": "καὶ τὸ ἔχθος τὸ Ἀπόλλωνι διαμένον ἐς τοὺς αὐλητὰς ἔτι ἀπὸ Μαρσύου καὶ τῆς ἁμίλλης τοῦ Σιληνοῦ παυθῆναι διὰ τοῦτον δοκεῖ τὸν Σακάδαν. ἐν δὲ τῷ γυμνασίῳ τῷ Κυλαράβου καὶ Πανία ἐστὶν Ἀθηνᾶ καλουμένη καὶ τάφον Σθενέλου δεικνύουσι, τὸν δὲ αὐτοῦ Κυλαράβου. πεποίηται δὲ οὐ πόρρω τοῦ γυμνασίου πολυάνδριον τοῖς μετὰ Ἀθηναίων πλεύσασιν Ἀργείοις ἐπὶ καταδουλώσει Συρακουσῶν τε καὶ Σικελίας.", "st": "2.22"}, {"sp": "N", "t": "ἐντεῦθεν ἐρχομένοις ὁδὸν καλουμένην ⟨Κοίλην⟩ ναός ἐστιν ἐν δεξιᾷ Διονύσου· τὸ δὲ ἄγαλμα εἶναι λέγουσιν ἐξ Εὐβοίας. συμβάσης γὰρ τοῖς Ἕλλησιν, ὡς ἐκομίζοντο ἐξ Ἰλίου, τῆς πρὸς τῷ Καφηρεῖ ναυαγίας, τοὺς δυνηθέντας ἐς τὴν γῆν διαφυγεῖν τῶν Ἀργείων ῥῖγός τε πιέζει καὶ λιμός. εὐξαμένοις δὲ θεῶν τινα ἐν τοῖς παροῦσιν ἀπόροις γενέσθαι σωτῆρα, αὐτίκα ὡς προῄεσαν ἐφάνη σφίσι Διονύσου σπήλαιον, καὶ ἄγαλμα ἦν ἐν τῷ σπηλαίῳ τοῦ θεοῦ· τότε δὲ αἶγες ἄγριαι φεύγουσαι τὸν χειμῶνα ἐς αὐτὸ ἦσαν ἠθροισμέναι. ταύτας οἱ Ἀργεῖοι σφάξαντες τά τε κρέα ἐδείπνησαν καὶ δέρμασιν ἐχρήσαντο ἀντὶ ἐσθῆτος. ἐπεὶ δὲ ὁ χειμὼν ἐπαύσατο καὶ ἐπισκευάσαντες τὰς ναῦς οἴκαδε ἐκομίζοντο, ἐπάγονται τὸ ἐκ τοῦ σπηλαίου ξόανον·", "st": "2.23"}, {"sp": "N", "t": "καὶ διατελοῦσιν ἐς τόδε τιμῶντες ἔτι. τοῦ Διονύσου δὲ ἐγγυτάτω οἰκίαν ὄψει τὴν Ἀδράστου καὶ ἀπωτέρω ταύτης ἱερὸν Ἀμφιαράου καὶ τοῦ ἱεροῦ πέραν Ἐριφύλης μνῆμα. ἑξῆς δὲ τούτων ἐστὶν Ἀσκληπιοῦ τέμενος καὶ μετὰ ταῦτα ἱερὸν Βάτωνος. ἦν δὲ ὁ Βάτων γένους Ἀμφιαράῳ τοῦ αὐτοῦ τῶν Μελαμποδιδῶν καὶ ἐς μάχην ἐξιόντι ἡνιόχει τοὺς ἵππους· γενομένης δὲ τῆς τροπῆς ἀπὸ τοῦ Θηβαίων τείχους χάσμα γῆς Ἀμφιάραον καὶ τὸ ἅρμα ὑποδεξάμενον ἠφάνισεν ὁμοῦ καὶ τοῦτον τὸν Βάτωνα.", "st": "2.23"}, {"sp": "N", "t": "ἐπανιόντι δὲ ἐκ τῆς Κοίλης Ὑρνηθοῦς τάφον λέγουσιν εἶναι. εἰ μὲν δὴ κενὸν καὶ ἄλλως ἐς μνήμην τῆς γυναικός, εἰκότα λέγουσιν· εἰ δὲ τῆς Ὑρνηθοῦς κεῖσθαι τὸν νεκρὸν νομίζουσιν ἐνταῦθα, ἐγὼ μέν σφισιν οὐ πείθομαι, πειθέσθω δὲ ὅστις τὰ Ἐπιδαυρίων οὐ πέπυσται.", "st": "2.23"}, {"sp": "N", "t": "τὸ δ’ ἐπιφανέστατον Ἀργείοις τῶν Ἀσκληπιείων ἄγαλμα ἐφ’ ἡμῶν ἔχει καθήμενον Ἀσκληπιὸν λίθου λευκοῦ, καὶ παρ’ αὐτὸν ἕστηκεν Ὑγεία· κάθηνται δὲ καὶ οἱ ποιήσαντες τὰ ἀγάλματα Ξενόφιλος καὶ Στράτων. ἐξ ἀρχῆς δὲ ἱδρύσατο Σφῦρος τὸ ἱερόν, Μαχάονος μὲν υἱός, ἀδελφὸς δὲ Ἀλεξάνορος τοῦ παρὰ Σικυωνίοις ἐν Τιτάνῃ τιμὰς ἔχοντος.", "st": "2.23"}, {"sp": "N", "t": "τῆς δὲ Ἀρτέμιδος τῆς Φεραίας—σέβουσι γὰρ καὶ Ἀργεῖοι Φεραίαν Ἄρτεμιν κατὰ ταὐτὰ Ἀθηναίοις καὶ Σικυωνίοις—τὸ ἄγαλμα καὶ οὗτοί φασιν ἐκ Φερῶν τῶν ἐν Θεσσαλίᾳ κομισθῆναι. τάδε δὲ αὐτοῖς οὐχ ὁμολογῶ· λέγουσι γὰρ Ἀργεῖοι Δηιανείρας ἐν Ἄργει μνῆμα εἶναι τῆς Οἰνέως τό τε Ἑλένου τοῦ Πριάμου, καὶ ἄγαλμα κεῖσθαι παρὰ σφίσιν Ἀθηνᾶς τὸ ἐκκομισθὲν ἐξ Ἰλίου καὶ ἁλῶναι ποιῆσαν Ἴλιον. τὸ μὲν δὴ Παλλάδιον—καλεῖται γὰρ οὕτω—δῆλόν ἐστιν ἐς Ἰταλίαν κομισθὲν ὑπὸ Αἰνείου· Δηιανείρᾳ δὲ τὴν τελευτὴν περὶ Τραχῖνα ἴσμεν καὶ οὐκ ἐν Ἄργει γενομένην, καὶ ἔστιν ὁ τάφος αὐτῇ πλησίον Ἡρακλείας τῆς ὑπὸ τῇ Οἴτῃ.", "st": "2.23"}, {"sp": "N", "t": "τὰ δὲ ἐς Ἕλενον τὸν Πριάμου δεδήλωκεν ὁ λόγος ἤδη μοι, μετὰ Πύρρου τοῦ Ἀχιλλέως αὐτὸν ἐλθεῖν ἐς Ἤπειρον καὶ ἐπιτροπεῦσαί τε τοὺς Πύρρου παῖδας συνοικοῦντα Ἀνδρομάχῃ καὶ τὴν Κεστρίνην καλουμένην ἀπὸ Κεστρίνου τοῦ Ἑλένου λαβεῖν τὸ ὄνομα. οὐ μὴν οὐδὲ αὐτῶν λέληθεν Ἀργείων τοὺς ἐξηγητὰς ὅτι μὴ πάντα ἐπ’ ἀληθείᾳ λέγεταί σφισι, λέγουσι δὲ ὅμως· οὐ γάρ τι ἕτοιμον μεταπεῖσαι τοὺς πολλοὺς ἐναντία ὧν δοξάζουσιν.", "st": "2.23"}, {"sp": "N", "t": "ἄλλα δέ ἐστιν Ἀργείοις θέας ἄξια· κατάγαιον οἰκοδόμημα, ἐπ’ αὐτῷ δὲ ἦν ὁ χαλκοῦς θάλαμος, ὃν Ἀκρίσιός ποτε ἐπὶ φρουρᾷ τῆς θυγατρὸς ἐποίησε· Περίλαος δὲ καθεῖλεν αὐτὸν τυραννήσας. τοῦτό τε οὖν τὸ οἰκοδόμημά ἐστι καὶ Κροτώπου μνῆμα καὶ Διονύσου ναὸς Κρησίου. Περσεῖ γὰρ πολεμήσαντα αὐτὸν καὶ αὖθις ἐλθόντα ἐς λύσιν τοῦ ἔχθους τά τε ἄλλα τιμηθῆναι μεγάλως λέγουσιν ὑπὸ Ἀργείων καὶ τέμενός οἱ δοθῆναι τοῦτο ἐξαίρετον·", "st": "2.23"}, {"sp": "N", "t": "Κρησίου δὲ ὕστερον ὠνομάσθη, διότι Ἀριάδνην ἀποθανοῦσαν ἔθαψεν ἐνταῦθα. Λυκέας δὲ λέγει κατασκευαζομένου δεύτερον τοῦ ναοῦ κεραμέαν εὑρεθῆναι σορόν, εἶναι δὲ Ἀριάδνης αὐτήν· καὶ αὐτός τε καὶ ἄλλους Ἀργείων ἰδεῖν ἔφη τὴν σορόν. πλησίον δὲ τοῦ Διονύσου καὶ Ἀφροδίτης ναός ἐστιν Οὐρανίας.", "st": "2.23"}, {"sp": "N", "t": "τὴν δὲ ἀκρόπολιν Λάρισαν μὲν καλοῦσιν ἀπὸ τῆς Πελασγοῦ θυγατρός· ἀπὸ ταύτης δὲ καὶ δύο τῶν ἐν Θεσσαλίᾳ πόλεων, ἥ τε ἐπὶ θαλάσσῃ καὶ ἡ παρὰ τὸν Πηνειόν, ὠνομάσθησαν. ἀνιόντων δὲ ἐς τὴν ἀκρόπολιν ἔστι μὲν τῆς Ἀκραίας Ἥρας τὸ ἱερόν, ἔστι δὲ καὶ ναὸς Ἀπόλλωνος, ὃν Πυθαεὺς πρῶτος παραγενόμενος ἐκ Δελφῶν λέγεται ποιῆσαι. τὸ δὲ ἄγαλμα τὸ νῦν χαλκοῦν ἐστιν ὀρθόν, Δειραδιώτης Ἀπόλλων καλούμενος, ὅτι καὶ ὁ τόπος οὗτος καλεῖται Δειράς. ἡ δέ οἱ μαντικὴ—μαντεύεται γὰρ ἔτι καὶ ἐς ἡμᾶς— καθέστηκε τρόπον τοῦτον. γυνὴ μὲν προφητεύουσά ἐστιν, ἀνδρὸς εὐνῆς εἰργομένη· θυομένης δὲ ἐν νυκτὶ ἀρνὸς κατὰ μῆνα ἕκαστον, γευσαμένη δὴ τοῦ αἵματος ἡ γυνὴ κάτοχος ἐκ τοῦ θεοῦ γίνεται.", "st": "2.24"}, {"sp": "N", "t": "τοῦ Δειραδιώτου δὲ Ἀπόλλωνος ἔχεται μὲν ἱερὸν Ἀθηνᾶς Ὀξυδερκοῦς καλουμένης, Διομήδους ἀνάθημα, ὅτι οἱ μαχομένῳ ποτὲ ἐν Ἰλίῳ τὴν ἀχλὺν ἀφεῖλεν ἡ θεὸς ἀπὸ τῶν ὀφθαλμῶν· ἔχεται δὲ τὸ στάδιον, ἐν ᾧ τὸν ἀγῶνα τῷ Νεμείῳ Διὶ καὶ τὰ Ἡραῖα ἄγουσιν. ἐς δὲ τὴν ἀκρόπολιν ἰοῦσίν ἐστιν ἐν ἀριστερᾷ τῆς ὁδοῦ τῶν Αἰγύπτου παίδων καὶ ταύτῃ μνῆμα. χωρὶς μὲν γὰρ ἀπὸ τῶν σωμάτων ἐνταῦθα αἱ κεφαλαί, χωρὶς δὲ ἐν Λέρνῃ σώματα τὰ λοιπά· ἐν Λέρνῃ γὰρ καὶ ὁ φόνος ἐξειργάσθη τῶν νεανίσκων, ἀποθανόντων δὲ ἀποτέμνουσιν αἱ γυναῖκες τὰς κεφαλὰς ἀπόδειξιν πρὸς τὸν πατέρα ὧν ἐτόλμησαν.", "st": "2.24"}, {"sp": "N", "t": "ἐπ’ ἄκρᾳ δέ ἐστι τῇ Λαρίσῃ Διὸς ἐπίκλησιν Λαρισαίου ναός, οὐκ ἔχων ὄροφον· τὸ δὲ ἄγαλμα ξύλου πεποιημένον οὐκέτι ἑστηκὸς ἦν ἐπὶ τῷ βάθρῳ. καὶ Ἀθηνᾶς δὲ ναός ἐστι θέας ἄξιος· ἐνταῦθα ἀναθήματα κεῖται καὶ ἄλλα καὶ Ζεὺς ξόανον, δύο μὲν ᾗ πεφύκαμεν ἔχον ὀφθαλμούς, τρίτον δὲ ἐπὶ τοῦ μετώπου. τοῦτον τὸν Δία Πριάμῳ φασὶν εἶναι τῷ Λαομέδοντος πατρῷον ἐν ὑπαίθρῳ τῆς αὐλῆς ἱδρυμένον, καὶ ὅτε ἡλίσκετο ὑπὸ Ἑλλήνων Ἴλιον, ἐπὶ τούτου κατέφυγεν ὁ Πρίαμος τὸν βωμόν. ἐπεὶ δὲ τὰ λάφυρα ἐνέμοντο, λαμβάνει Σθένελος ὁ Καπανέως αὐτόν, καὶ ἀνάκειται μὲν διὰ τοῦτο ἐνταῦθα·", "st": "2.24"}, {"sp": "N", "t": "τρεῖς δὲ ὀφθαλμοὺς ἔχειν ἐπὶ τῷδε ἄν τις τεκμαίροιτο αὐτόν. Δία γὰρ ἐν οὐρανῷ βασιλεύειν, οὗτος μὲν λόγος κοινὸς πάντων ἐστὶν ἀνθρώπων. ὃν δὲ ἄρχειν φασὶν ὑπὸ γῆς, ἔστιν ἔπος τῶν Ὁμήρου Δία ὀνομάζον καὶ τοῦτον·<br>Ζεύς τε καταχθόνιος καὶ ἐπαινὴ Περσεφόνεια.<br>Αἰσχύλος δὲ ὁ Εὐφορίωνος καλεῖ Δία καὶ τὸν ἐν θαλάσσῃ. τρισὶν οὖν ὁρῶντα ἐποίησεν ὀφθαλμοῖς ὅστις δὴ ἦν ὁ ποιήσας, ἅτε ἐν ταῖς τρισὶ ταῖς λεγομέναις λήξεσιν ἄρχοντα τὸν αὐτὸν τοῦτον θεόν.", "st": "2.24"}, {"sp": "N", "t": "ὁδοὶ δὲ ἐξ Ἄργους καὶ κατ’ ἄλλα εἰσὶ τῆς Πελοποννήσου καὶ πρὸς Ἀρκαδίας ἐπὶ Τεγέαν. ἐν δεξιᾷ δὲ ὄρος ἐστὶν ἡ Λυκώνη, δένδρα κυπαρίσσου μάλιστα ἔχουσα. ᾠκοδόμηται δὲ ἐπὶ κορυφῇ τοῦ ὄρους Ἀρτέμιδος Ὀρθίας ἱερόν, καὶ ἀγάλματα Ἀπόλλωνος καὶ Λητοῦς καὶ Ἀρτέμιδος πεποίηται λευκοῦ λίθου· Πολυκλείτου δέ φασιν εἶναι ἔργα. καταβάντων δὲ ἐκ τοῦ ὄρους αὖθίς ἐστιν ἐν ἀριστερᾷ τῆς λεωφόρου ναὸς Ἀρτέμιδος.", "st": "2.24"}, {"sp": "N", "t": "ὀλίγον δὲ ἀπωτέρω ἐν δεξιᾷ τῆς ὁδοῦ Χάον ἐστὶν ὄρος ὀνομαζόμενον, ὑπὸ δὲ αὐτῷ δένδρα πέφυκεν ἥμερα καὶ ἄνεισι τοῦ Ἐρασίνου φανερὸν ἐνταῦθα δὴ τὸ ὕδωρ· τέως δὲ ἐκ Στυμφάλου ῥεῖ τῆς Ἀρκάδων ὥσπερ ἐξ Εὐρίπου κατὰ Ἐλευσῖνα καὶ τὴν ταύτῃ θάλασσαν οἱ Ῥειτοί. πρὸς δὲ τοῦ Ἐρασίνου ταῖς κατὰ τὸ ὄρος ἐκβολαῖς Διονύσῳ καὶ Πανὶ θύουσι, τῷ Διονύσῳ δὲ καὶ ἑορτὴν ἄγουσι καλουμένην Τύρβην.", "st": "2.24"}, {"sp": "N", "t": "ἐπανελθοῦσι δὲ ἐς τὴν ἐπὶ Τεγέας ὁδόν ἐστιν ἐν δεξιᾷ τοῦ ὀνομαζομένου Τρόχου Κεγχρεαί. τὸ δὲ ὄνομα ἐφ’ ὅτῳ τῷ χωρίῳ γέγονεν, οὐ λέγουσι, πλὴν εἰ μὴ καὶ τοῦτο ἄρα ὠνομάσθη διὰ τὸν Πειρήνης παῖδα Κεγχρίαν. καὶ πολυάνδρια ἐνταῦθά ἐστιν Ἀργείων νικησάντων μάχῃ Λακεδαιμονίους περὶ Ὑσιάς. τὸν δὲ ἀγῶνα τοῦτον συμβάντα εὕρισκον Ἀθηναίοις ἄρχοντος Πεισιστράτου, τετάρτῳ δὲ ἔτει τῆς ⟨ἑβδόμης καὶ εἰκοστῆς⟩ Ὀλυμπιάδος ἣν Εὐρύβοτος Ἀθηναῖος ἐνίκα στάδιον. καταβάντος δὲ ἐς τὸ χθαμαλώτερον ἐρείπια Ὑσιῶν ἐστι πόλεώς ποτε ἐν τῇ Ἀργολίδι, καὶ τὸ πταῖσμα Λακεδαιμονίοις ἐνταῦθα γενέσθαι λέγουσιν.", "st": "2.24"}, {"sp": "N", "t": "ἡ δ’ ἐς Μαντίνειαν ἄγουσα ἐξ Ἄργους ἐστὶν οὐχ ἥπερ καὶ ἐπὶ Τεγέαν, ἀλλὰ ἀπὸ τῶν πυλῶν τῶν πρὸς τῇ Δειράδι. ἐπὶ δὲ τῆς ὁδοῦ ταύτης ἱερὸν διπλοῦν πεποίηται, καὶ πρὸς ἡλίου δύνοντος ἔσοδον καὶ κατὰ ἀνατολὰς ἑτέραν ἔχον. κατὰ μὲν δὴ τοῦτο Ἀφροδίτης κεῖται ξόανον, πρὸς δὲ ἡλίου δυσμὰς Ἄρεως· εἶναι δὲ τὰ ἀγάλματα· Πολυνείκους λέγουσιν ἀναθήματα καὶ Ἀργείων, ὅσοι τιμωρήσοντες αὐτῷ συνεστρατεύοντο.", "st": "2.25"}, {"sp": "N", "t": "προελθοῦσι δὲ αὐτόθεν διαβάντων ποταμὸν χείμαρρον Χάραδρον καλούμενον ἔστιν Οἰνόη, τὸ ὄνομα ἔχουσα, ὡς Ἀργεῖοί φασιν, ἀπὸ Οἰνέως. Οἰνέα γὰρ τὸν βασιλεύσαντα ἐν Αἰτωλίᾳ λέγουσιν ὑπὸ τῶν Ἀγρίου παίδων ἐκβληθέντα τῆς ἀρχῆς παρὰ Διομήδην ἐς Ἄργος ἀφικέσθαι. ὁ δὲ τὰ μὲν ἄλλα ἐτιμώρησεν αὐτῷ στρατεύσας ἐς τὴν Καλυδωνίαν, παραμένειν δὲ οὐκ ἔφη οἱ δύνασθαι· συνακολουθεῖν δέ, εἰ βούλοιτο, ἐς Ἄργος ἐκεῖνον ἐκέλευεν. ἀφικόμενον δὲ τά τε ἄλλα ἐθεράπευεν, ὡς πατρὸς θεραπεύειν πατέρα εἰκὸς ἦν, καὶ ἀποθανόντα ἔθαψεν ἐνταῦθα. ἀπὸ τούτου μὲν Οἰνόη χωρίον ἐστὶν Ἀργείοις·", "st": "2.25"}, {"sp": "N", "t": "ὑπὲρ δὲ Οἰνόης ὄρος ἐστὶν Ἀρτεμίσιον καὶ ἱερὸν Ἀρτέμιδος ἐπὶ κορυφῇ τοῦ ὄρους. ἐν τούτῳ δέ εἰσι τῷ ὄρει καὶ αἱ πηγαὶ τοῦ Ἰνάχου· πηγαὶ γὰρ δὴ τῷ ὄντι εἰσὶν αὐτῷ, τὸ δὲ ὕδωρ οὐκ ἐπὶ πολὺ ἐξικνεῖται τῆς γῆς.", "st": "2.25"}, {"sp": "N", "t": "ταύτῃ μὲν δὴ θέας οὐδὲν ἔτι ἦν ἄξιον· ἑτέρα δὲ ὁδὸς ἀπὸ τῶν πυλῶν τῶν πρὸς τῇ Δειράδι ἐστὶν ἐπὶ Λύρκειαν. ἐς τοῦτο λέγεται τὸ χωρίον Λυγκέα ἀποσωθῆναι τῶν πεντήκοντα ἀδελφῶν μόνον· καὶ ἡνίκα ἐσώθη, πυρσὸν ἀνέσχεν ἐντεῦθεν. συνέκειτο δὲ ἄρα αὐτῷ πρὸς τὴν Ὑπερμήστραν ἀνασχεῖν τὸν πυρσόν, ἢν διαφυγὼν Δαναὸν ἐς ἀσφαλὲς ἀφίκηταί ποι· τὴν δὲ καὶ αὐτὴν ἀνάψαι λέγουσιν ἕτερον ἀπὸ τῆς Λαρίσης, δῆλα καὶ ταύτην ποιοῦσαν ὅτι ἐν οὐδενὶ οὐδὲ αὐτὴ καθέστηκεν ἔτι κινδύνῳ. ἐπὶ τούτῳ δὲ Ἀργεῖοι κατὰ ἔτος ἕκαστον πυρσῶν ἑορτὴν ἄγουσι.", "st": "2.25"}, {"sp": "N", "t": "τὸ δὲ χωρίον τότε μὲν Λυγκεία ἐκαλεῖτο, οἰκήσαντος δὲ ὕστερον ἐν αὐτῷ Λύρκου—παῖς δὲ ἦν Ἄβαντος νόθος— τὸ ὄνομα δι’ αὐτὸν ἔσχηκε· καὶ ἄλλα τέ ἐστιν οὐκ ἀξιόλογα ἐν τοῖς ἐρειπίοις καὶ εἰκὼν ἐπὶ στήλῃ τοῦ Λύρκου. ἐς μὲν δὴ ταύτην ἐστὶν ἐξ Ἄργους ἑξήκοντα μάλιστά που στάδια, ἐκ δὲ Λυρκείας ἕτερα τοσαῦτα ἐς Ὀρνεάς. Λυρκείας μὲν δὴ πόλεως, ἅτε ἠρημωμένης ἤδη κατὰ τὴν Ἑλλήνων στρατείαν ἐπὶ Ἴλιον, οὐκ ἐποιήσατο Ὅμηρος ἐν καταλόγῳ μνήμην· Ὀρνεὰς δέ—ἔτι γὰρ ᾠκοῦντο—, ὥσπερ τῷ τόπῳ τῆς Ἀργείας ἔκειντο, οὕτω καὶ ἐν τοῖς ἔπεσι προτέρας ἢ Φλιοῦντά τε καὶ Σικυῶνα κατέλεξεν.", "st": "2.25"}, {"sp": "N", "t": "ἐκαλοῦντο δὲ ἀπὸ Ὀρνέως τοῦ Ἐρεχθέως· τοῦ δὲ Ὀρνέως ἦν τούτου Πετεώς, τοῦ δὲ Μενεσθεύς, ὃς Ἀγαμέμνονι μετὰ Ἀθηναίων τὴν Πριάμου συγκαθεῖλεν ἀρχήν. ἀπὸ μὲν δὴ τούτου τὸ ὄνομα ἐγένετο τῇ πόλει, Ἀργεῖοι δὲ ὕστερον τούτων Ὀρνεάτας ἀνέστησαν· ἀναστάντες δὲ σύνοικοι γεγόνασιν Ἀργείοις. ἔστι δὲ ἐν ταῖς Ὀρνεαῖς Ἀρτέμιδός τε ἱερὸν καὶ ξόανον ὀρθὸν καὶ ἕτερος ναὸς θεοῖς πᾶσιν ἐς κοινὸν ἀνειμένος. τὰ δὲ ἐπέκεινα Ὀρνεῶν ἥ τε Σικυωνία καὶ ἡ Φλιασία ἐστίν.", "st": "2.25"}, {"sp": "N", "t": "ἐρχομένοις δὲ ἐξ Ἄργους ἐς τὴν Ἐπιδαυρίαν ἐστὶν οἰκοδόμημα ἐν δεξιᾷ πυραμίδι μάλιστα εἰκασμένον, ἔχει δὲ ἀσπίδας σχῆμα Ἀργολικὰς ἐπειργασμένας. ἐνταῦθα Προίτῳ περὶ τῆς ἀρχῆς πρὸς Ἀκρίσιον μάχη γίνεται, καὶ τέλος μὲν ἴσον τῷ ἀγῶνι συμβῆναί φασι καὶ ἀπ’ αὐτοῦ διαλλαγὰς ὕστερον, ὡς οὐδέτεροι βεβαίως κρατεῖν ἐδύναντο· συμβάλλειν δὲ σφᾶς λέγουσιν ἀσπίσι πρῶτον τότε καὶ αὐτοὺς καὶ τὸ στράτευμα ὡπλισμένους. τοῖς δὲ πεσοῦσιν ἀφ’ ἑκατέρων— πολῖται γὰρ καὶ συγγενεῖς ἦσαν—ἐποιήθη ταύτῃ μνῆμα ἐν κοινῷ.", "st": "2.25"}, {"sp": "N", "t": "προϊοῦσι δὲ ἐντεῦθεν καὶ ἐκτραπεῖσιν ἐς δεξιὰν Τίρυνθός ἐστιν ἐρείπια. ἀνέστησαν δὲ καὶ Τιρυνθίους Ἀργεῖοι, συνοίκους προσλαβεῖν καὶ τὸ Ἄργος ἐπαυξῆσαι θελήσαντες. Τίρυνθα δὲ ἥρωα, ἀφ’ οὗ τῇ πόλει τὸ ὄνομα ἐγένετο, παῖδα Ἄργου τοῦ Διὸς εἶναι λέγουσι. τὸ δὲ τεῖχος, ὃ δὴ μόνον τῶν ἐρειπίων λείπεται, Κυκλώπων μέν ἐστιν ἔργον, πεποίηται δὲ ἀργῶν λίθων, μέγεθος ἔχων ἕκαστος λίθος ὡς ἀπ’ αὐτῶν μηδ’ ἂν ἀρχὴν κινηθῆναι τὸν μικρότατον ὑπὸ ζεύγους ἡμιόνων· λιθία δὲ ἐνήρμοσται πάλαι, ὡς μάλιστα αὐτῶν ἕκαστον ἁρμονίαν τοῖς μεγάλοις λίθοις εἶναι.", "st": "2.25"}, {"sp": "N", "t": "καταβάντων δὲ ὡς ἐπὶ θάλασσαν, ἐνταῦθα οἱ θάλαμοι τῶν Προίτου θυγατέρων εἰσίν· ἐπανελθόντων δὲ ἐς τὴν λεωφόρον, ἐπὶ Μήδειαν ἐς ἀριστερὰν ἥξεις. βασιλεῦσαι δέ φασιν Ἠλεκτρύωνα ἐν τῇ Μηδείᾳ τὸν πατέρα Ἀλκμήνης· ἐπ’ ἐμοῦ δὲ Μηδείας πλὴν τὸ ἔδαφος ἄλλο οὐδὲν ἐλείπετο.", "st": "2.25"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς Ἐπίδαυρον εὐθεῖάν ἐστι κώμη Λῆσσα, ναὸς δὲ Ἀθηνᾶς ἐν αὐτῇ καὶ ξόανον οὐδέν τι διάφορον ἢ τὸ ἐν ἀκροπόλει τῇ Λαρίσῃ. ἔστι δὲ ὄρος ὑπὲρ τῆς Λήσσης τὸ Ἀραχναῖον, πάλαι δὲ †σάπυς ἐλάτων ἐπὶ Ἰνάχου τὸ ὄνομα εἰλήφει. βωμοὶ δέ εἰσιν ἐν αὐτῷ Διός τε καὶ Ἥρας· δεῆσαν ὄμβρου σφίσιν ἐνταῦθα θύουσι.", "st": "2.25"}, {"sp": "N", "t": "κατὰ δὲ τὴν Λῆσσαν ἔχεται τῆς Ἀργείας ἡ Ἐπιδαυρίων· πρὶν δὲ ἢ κατ’ αὐτὴν γενέσθαι τὴν πόλιν, ἐπὶ τὸ ἱερὸν ἀφίξῃ τοῦ Ἀσκληπιοῦ. ταύτην τὴν χώραν οὐκ οἶδα οἵτινες πρότερον ᾤκησαν πρὶν Ἐπίδαυρον ἐλθεῖν ἐς αὐτήν· οὐ μὴν οὐδὲ τοὺς ἀπογόνους Ἐπιδαύρου πυθέσθαι παρὰ τῶν ἐπιχωρίων ἐδυνάμην. τελευταῖον δὲ πρὶν ἢ παραγενέσθαι Δωριέας ἐς Πελοπόννησον βασιλεῦσαί φασι Πιτυρέα Ἴωνος ἀπόγονον τοῦ Ξούθου. τοῦτον παραδοῦναι λέγουσιν ἀμαχεὶ τὴν γῆν Δηιφόντῃ καὶ Ἀργείοις·", "st": "2.26"}, {"sp": "N", "t": "καὶ ὁ μὲν ἐς Ἀθήνας ὁμοῦ τοῖς πολίταις ἀφικόμενος ἐνταῦθα ᾤκησε, Δηιφόντης δὲ καὶ Ἀργεῖοι τὴν Ἐπιδαυρίαν ἔσχον. ἀπεσχίσθησαν δὲ οὗτοι τῶν ἄλλων Ἀργείων Τημένου τελευτήσαντος, Δηιφόντης μὲν καὶ Ὑρνηθὼ κατ’ ἔχθος τῶν Τημένου παίδων, ὁ δὲ σὺν αὐτοῖς στρατὸς Δηιφόντῃ καὶ Ὑρνηθοῖ πλέον ἢ Κείσῳ καὶ τοῖς ἀδελφοῖς νέμοντες. Ἐπίδαυρος δέ, ἀφ’ οὗ τὸ ὄνομα τῇ γῇ ἐτέθη, ὡς μέν φασιν Ἠλεῖοι, Πέλοπος ἦν· κατὰ δὲ Ἀργείων δόξαν καὶ τὰ ἔπη τὰς μεγάλας Ἠοίας ἦν Ἐπιδαύρῳ πατὴρ Ἄργος ὁ Διός· Ἐπιδαύριοι δὲ Ἀπόλλωνι Ἐπίδαυρον παῖδα προσποιοῦσιν.", "st": "2.26"}, {"sp": "N", "t": "Ἀσκληπιοῦ δὲ ἱερὰν μάλιστα εἶναι τὴν γῆν ἐπὶ λόγῳ συμβέβηκε τοιῷδε. Φλεγύαν Ἐπιδαύριοί φασιν ἐλθεῖν ἐς Πελοπόννησον πρόφασιν μὲν ἐπὶ θέᾳ τῆς χώρας, ἔργῳ δὲ κατάσκοπον πλήθους τῶν ἐνοικούντων καὶ εἰ τὸ πολὺ μάχιμον εἴη τῶν ἀνθρώπων· ἦν γὰρ δὴ Φλεγύας πολεμικώτατος τῶν τότε καὶ ἐπιὼν ἑκάστοτε ἐφ’ οὓς τύχοι τοὺς καρποὺς ἔφερε καὶ ἤλαυνε τὴν λείαν.", "st": "2.26"}, {"sp": "N", "t": "ὅτε δὲ παρεγένετο ἐς Πελοπόννησον, εἵπετο ἡ θυγάτηρ αὐτῷ, λεληθυῖα ἔτι τὸν πατέρα ὅτι ἐξ Ἀπόλλωνος εἶχεν ἐν γαστρί. ὡς δὲ ἐν τῇ γῇ τῇ Ἐπιδαυρίων ἔτεκεν, ἐκτίθησι τὸν παῖδα ἐς τὸ ὄρος τοῦτο ὃ δὴ Τίτθιον ὀνομάζουσιν ἐφ’ ἡμῶν, τηνικαῦτα δὲ ἐκαλεῖτο Μύρτιον· ἐκκειμένῳ δὲ ἐδίδου μέν οἱ γάλα μία τῶν περὶ τὸ ὄρος ποιμαινομένων αἰγῶν, ἐφύλασσε δὲ ὁ κύων ὁ τοῦ αἰπολίου φρουρός.", "st": "2.26"}, {"sp": "N", "t": "Ἀρεσθάνας δὲ—ὄνομα γὰρ τῷ ποιμένι τοῦτο ἦν—ὡς τὸν ἀριθμὸν οὐχ εὕρισκεν ὁμολογοῦντα τῶν αἰγῶν καὶ ὁ κύων ἅμα ἀπεστάτει τῆς ποίμνης, οὕτω τὸν Ἀρεσθάναν ἐς πᾶν φασιν ἀφικνεῖσθαι ζητήσεως, εὑρόντα δὲ ἐπιθυμῆσαι τὸν παῖδα ἀνελέσθαι· καὶ ὡς ἐγγὺς ἐγίνετο, ἀστραπὴν ἰδεῖν ἐκλάμψασαν ἀπὸ τοῦ παιδός, νομίσαντα δὲ εἶναι θεῖόν τι, ὥσπερ ἦν, ἀποτραπέσθαι. ὁ δὲ αὐτίκα ἐπὶ γῆν καὶ θάλασσαν πᾶσαν ἠγγέλλετο τά τε ἄλλα ὁπόσα βούλοιτο εὑρίσκειν ἐπὶ τοῖς κάμνουσι καὶ ὅτι ἀνίστησι τεθνεῶτας.", "st": "2.26"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἄλλος ἐπ’ αὐτῷ λόγος, Κορωνίδα κύουσαν Ἀσκληπιὸν Ἴσχυι τῷ Ἐλάτου συγγενέσθαι, καὶ τὴν μὲν ἀποθανεῖν ὑπὸ Ἀρτέμιδος ἀμυνομένης τῆς ἐς τὸν Ἀπόλλωνα ὕβρεως, ἐξημμένης δὲ ἤδη τῆς πυρᾶς ἁρπάσαι λέγεται τὸν παῖδα Ἑρμῆς ἀπὸ τῆς φλογός.", "st": "2.26"}, {"sp": "N", "t": "ὁ δὲ τρίτος τῶν λόγων ἥκιστα ἐμοὶ δοκεῖν ἀληθής ἐστιν, Ἀρσινόης ποιήσας εἶναι τῆς Λευκίππου παῖδα Ἀσκληπιόν. Ἀπολλοφάνει γὰρ τῷ Ἀρκάδι ἐς Δελφοὺς ἐλθόντι καὶ ἐρομένῳ τὸν θεὸν εἰ γένοιτο ἐξ Ἀρσινόης Ἀσκληπιὸς καὶ Μεσσηνίοις πολίτης εἴη, ἔχρησεν ἡ Πυθία·<br>ὦ μέγα χάρμα βροτοῖς βλαστὼν Ἀσκληπιὲ πᾶσιν,<br>ὃν Φλεγυηὶς ἔτικτεν ἐμοὶ φιλότητι μιγεῖσα<br>ἱμερόεσσα Κορωνὶς ἐνὶ κραναῇ Ἐπιδαύρῳ.<br>οὗτος ὁ χρησμὸς δηλοῖ μάλιστα οὐκ ὄντα Ἀσκληπιὸν Ἀρσινόης, ἀλλὰ Ἡσίοδον ἢ τῶν τινα ἐμπεποιηκότων ἐς τὰ Ἡσιόδου τὰ ἔπη συνθέντα ἐς τὴν Μεσσηνίων χάριν.", "st": "2.26"}, {"sp": "N", "t": "μαρτυρεῖ δέ μοι καὶ τόδε ἐν Ἐπιδαύρῳ τὸν θεὸν γενέσθαι· τὰ γὰρ Ἀσκληπιεῖα εὑρίσκω τὰ ἐπιφανέστατα ⟨γεγονότα⟩ ἐξ Ἐπιδαύρου. τοῦτο μὲν γὰρ Ἀθηναῖοι, τῆς τελετῆς λέγοντες Ἀσκληπιῷ μεταδοῦναι, τὴν ἡμέραν ταύτην Ἐπιδαύρια ὀνομάζουσι καὶ θεὸν ἀπ’ ἐκείνου φασὶν Ἀσκληπιόν σφισι νομισθῆναι· τοῦτο δὲ Ἀρχίας ὁ Ἀρισταίχμου, τὸ συμβὰν σπάσμα θηρεύοντί οἱ περὶ τὸν Πίνδασον ἰαθεὶς ἐν τῇ Ἐπιδαυρίᾳ, τὸν θεὸν ἐπηγάγετο ἐς Πέργαμον.", "st": "2.26"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ Περγαμηνῶν Σμυρναίοις γέγονεν ἐφ’ ἡμῶν Ἀσκληπιεῖον τὸ ἐπὶ θαλάσσῃ. τὸ δ’ ἐν Βαλάγραις ταῖς Κυρηναίων ἐστὶν Ἀσκληπιὸς καλούμενος Ἰατρὸς ἐξ Ἐπιδαύρου καὶ οὗτος. ἐκ δὲ τοῦ παρὰ Κυρηναίοις τὸ ἐν Λεβήνῃ τῇ Κρητῶν ἐστιν Ἀσκληπιεῖον. διάφορον δὲ Κυρηναίοις τοσόνδε ἐς Ἐπιδαυρίους ἐστίν, ὅτι αἶγας οἱ Κυρηναῖοι θύουσιν, Ἐπιδαυρίοις οὐ καθεστηκότος.", "st": "2.26"}, {"sp": "N", "t": "θεὸν δὲ Ἀσκληπιὸν νομισθέντα ἐξ ἀρχῆς καὶ οὐκ ἀνὰ χρόνον λαβόντα τὴν φήμην τεκμηρίοις καὶ ἄλλοις εὑρίσκω καὶ Ὁμήρου μαρτυρεῖ μοι τὰ περὶ Μαχάονος ὑπὸ Ἀγαμέμνονος εἰρημένα<br>Ταλθύβι’, ὅττι τάχιστα Μαχάονα δεῦρο κάλεσσον<br>φῶτ’ Ἀσκληπιοῦ υἱόν,<br>ὡς ἂν εἰ λέγοι θεοῦ παῖδα ἄνθρωπον.", "st": "2.26"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν ἄλσος τοῦ Ἀσκληπιοῦ περιέχουσιν ὅροι πανταχόθεν· οὐδὲ ἀποθνήσκουσιν ⟨ἄνθρωποι⟩ οὐδὲ τίκτουσιν αἱ γυναῖκές σφισιν ἐντὸς τοῦ περιβόλου, καθὰ καὶ ἐπὶ Δήλῳ τῇ νήσῳ τὸν αὐτὸν νόμον. τὰ δὲ θυόμενα, ἤν τέ τις Ἐπιδαυρίων αὐτῶν ἤν τε ξένος ὁ θύων ᾖ, καταναλίσκουσιν ἐντὸς τῶν ὅρων· τὸ δὲ αὐτὸ γινόμενον οἶδα καὶ ἐν Τιτάνῃ.", "st": "2.27"}, {"sp": "N", "t": "τοῦ δὲ Ἀσκληπιοῦ τὸ ἄγαλμα μεγέθει μὲν τοῦ Ἀθήνῃσιν Ὀλυμπίου Διὸς ἥμισυ ἀποδεῖ, πεποίηται δὲ ἐλέφαντος καὶ χρυσοῦ· μηνύει δὲ ἐπίγραμμα τὸν εἰργασμένον εἶναι Θρασυμήδην Ἀριγνώτου Πάριον. κάθηται δὲ ἐπὶ θρόνου βακτηρίαν κρατῶν, τὴν δὲ ἑτέραν τῶν χειρῶν ὑπὲρ κεφαλῆς ἔχει τοῦ δράκοντος, καί οἱ καὶ κύων παρακατακείμενος πεποίηται. τῷ θρόνῳ δὲ ἡρώων ἐπειργασμένα Ἀργείων ἐστὶν ἔργα, Βελλεροφόντου τὸ ἐς τὴν Χίμαιραν καὶ Περσεὺς ἀφελὼν τὴν Μεδούσης κεφαλήν. τοῦ ναοῦ δέ ἐστι πέραν ἔνθα οἱ ἱκέται τοῦ θεοῦ καθεύδουσιν.", "st": "2.27"}, {"sp": "N", "t": "οἴκημα δὲ περιφερὲς λίθου λευκοῦ καλούμενον Θόλος ᾠκοδόμηται πλησίον, θέας ἄξιον· ἐν δὲ αὐτῷ Παυσίου γράψαντος βέλη μὲν καὶ τόξον ἐστὶν ἀφεικὼς Ἔρως, λύραν δὲ ἀντ’ αὐτῶν ἀράμενος φέρει. γέγραπται δὲ ἐνταῦθα καὶ Μέθη, Παυσίου καὶ τοῦτο ἔργον, ἐξ ὑαλίνης φιάλης πίνουσα· ἴδοις δὲ κἂν ἐν τῇ γραφῇ φιάλην τε ὑάλου καὶ δι’ αὐτῆς γυναικὸς πρόσωπον. στῆλαι δὲ εἱστήκεσαν ἐντὸς τοῦ περιβόλου τὸ μὲν ἀρχαῖον καὶ πλέονες, ἐπ’ ἐμοῦ δὲ ἓξ λοιπαί· ταύταις ἐγγεγραμμένα καὶ ἀνδρῶν καὶ γυναικῶν ἐστιν ὀνόματα ἀκεσθέντων ὑπὸ τοῦ Ἀσκληπιοῦ, προσέτι δὲ καὶ νόσημα ὅ τι ἕκαστος ἐνόσησε καὶ ὅπως ἰάθη·", "st": "2.27"}, {"sp": "N", "t": "γέγραπται δὲ φωνῇ τῇ Δωρίδι. χωρὶς δὲ ἀπὸ τῶν ἄλλων ἐστὶν ἀρχαία στήλη· ἵππους δὲ Ἱππόλυτον ἀναθεῖναι τῷ θεῷ φησιν εἴκοσι. ταύτης τῆς στήλης τῷ ἐπιγράμματι ὁμολογοῦντα λέγουσιν Ἀρικιεῖς, ὡς τεθνεῶτα Ἱππόλυτον ἐκ τῶν Θησέως ἀρῶν ἀνέστησεν Ἀσκληπιός· ὁ δὲ ὡς αὖθις ἐβίω, οὐκ ἠξίου νέμειν τῷ πατρὶ συγγνώμην, ἀλλὰ ὑπεριδὼν τὰς δεήσεις ἐς Ἰταλίαν ἔρχεται παρὰ τοὺς Ἀρικιεῖς, καὶ ἐβασίλευσέ τε αὐτόθι καὶ ἀνῆκε τῇ Ἀρτέμιδι τέμενος, ἔνθα ἄχρι ἐμοῦ μονομαχίας ἆθλα ἦν καὶ ἱερᾶσθαι τῇ θεῷ τὸν νικῶντα· ὁ δὲ ἀγὼν ἐλευθέρων μὲν προέκειτο οὐδενί, οἰκέταις δὲ ἀποδρᾶσι τοὺς δεσπότας.", "st": "2.27"}, {"sp": "N", "t": "Ἐπιδαυρίοις δέ ἐστι θέατρον ἐν τῷ ἱερῷ μάλιστα ἐμοὶ δοκεῖν θέας ἄξιον· τὰ μὲν γὰρ Ῥωμαίων πολὺ δή τι [καὶ] ὑπερῆρ⟨κ⟩ε τῶν πανταχοῦ τῷ κόσμῳ, μεγέθει δὲ Ἀρκάδων τὸ ἐν Μεγάλῃ πόλει· ἁρμονίας δὲ ἢ κάλλους ἕνεκα ἀρχιτέκτων ποῖος ἐς ἅμιλλαν Πολυκλείτῳ γένοιτ’ ἂν ἀξιόχρεως; Πολύκλειτος γὰρ καὶ θέατρον τοῦτο καὶ οἴκημα τὸ περιφερὲς ὁ ποιήσας ἦν. ἐντὸς δὲ τοῦ ἄλσους ναός τέ ἐστιν Ἀρτέμιδος καὶ ἄγαλμα Ἠπιόνης καὶ Ἀφροδίτης ἱερὸν καὶ Θέμιδος καὶ στάδιον, οἷα Ἕλλησι τὰ πολλὰ γῆς χῶμα, καὶ κρήνη τῷ τε ὀρόφῳ καὶ κόσμῳ τῷ λοιπῷ θέας ἀξία.", "st": "2.27"}, {"sp": "N", "t": "ὁπόσα δὲ Ἀντωνῖνος ἀνὴρ τῆς συγκλήτου βουλῆς ἐφ’ ἡμῶν ἐποίησεν, ἔστι μὲν Ἀσκληπιοῦ λουτρόν, ἔστι δὲ ἱερὸν θεῶν οὓς Ἐπιδώτας ὀνομάζουσιν· ἐποίησε δὲ καὶ Ὑγείᾳ ναὸν καὶ Ἀσκληπιῷ καὶ Ἀπόλλωνι ἐπίκλησιν Αἰγυπτίοις. καὶ ἦν γὰρ στοὰ καλουμένη Κότυος, καταρρυέντος δέ οἱ τοῦ ὀρόφου διέφθαρτο ἤδη πᾶσα ἅτε ὠμῆς τῆς πλίνθου ποιηθεῖσα· ἀνῳκοδόμησε καὶ ταύτην. Ἐπιδαυρίων δὲ οἱ περὶ τὸ ἱερὸν μάλιστα ἐταλαιπώρουν, ὅτι μήτε αἱ γυναῖκες ἐν σκέπῃ σφίσιν ἔτικτον καὶ ἡ τελευτὴ τοῖς κάμνουσιν ὑπαίθριος ἐγίνετο· ὁ δὲ καὶ ταῦτα ἐπανορθούμενος κατεσκευάσατο οἴκησιν· ἐνταῦθα ἤδη καὶ ἀποθανεῖν ἀνθρώπῳ καὶ τεκεῖν γυναικὶ ὅσιον.", "st": "2.27"}, {"sp": "N", "t": "ὄρη δέ ἐστιν ὑπὲρ τὸ ἄλσος τό τε Τίτθιον καὶ ἕτερον ὀνομαζόμενον Κυνόρτιον, Μαλεάτου δὲ Ἀπόλλωνος ἱερὸν ἐν αὐτῷ. τοῦτο μὲν δὴ τῶν ἀρχαίων· τὰ δὲ ἄλλα ὅσα περὶ τὸ ἱερὸν τοῦ Μαλεάτου καὶ ἔλυτρον κρήνης, ἐς ὃ τὸ ὕδωρ συλλέγεταί σφισι τὸ ἐκ τοῦ θεοῦ, Ἀντωνῖνος καὶ ταῦτα Ἐπιδαυρίοις ἐποίησεν.", "st": "2.27"}, {"sp": "N", "t": "δράκοντες δὲ—οἱ λοιποὶ καὶ ἕτερον γένος—ἐς τὸ ξανθότερον ῥέποντες χρόας ἱεροὶ μὲν τοῦ Ἀσκληπιοῦ νομίζονται καὶ εἰσὶν ἀνθρώποις ἥμεροι, τρέφει δὲ μόνη σφᾶς ἡ τῶν Ἐπιδαυρίων γῆ. τὸ δὲ αὐτὸ εὑρίσκω καὶ ἄλλαις χώραις συμβεβηκός· Λιβύη μέν γε μόνη κροκοδείλους τρέφει χερσαίους διπήχεων οὐκ ἐλάσσονας, παρὰ δὲ Ἰνδῶν μόνων ἄλλα τε κομίζεται καὶ ὄρνιθες οἱ ψιττακοί. τοὺς δὲ ὄφεις οἱ Ἐπιδαύριοι τοὺς μεγάλους ἐς πλέον πηχῶν καὶ τριάκοντα προήκοντας, οἷοι παρά τε Ἰνδοῖς τρέφονται καὶ ἐν Λιβύῃ, ἄλλο δή τι γένος φασὶν εἶναι καὶ οὐ δράκοντας.", "st": "2.28"}, {"sp": "N", "t": "ἐς δὲ τὸ ὄρος ἀνιοῦσι τὸ Κόρυφον, ἔστι καθ’ ὁδὸν Στρεπτῆς καλουμένης ἐλαίας φυτόν, αἰτίου τοῦ περιαγαγόντος τῇ χειρὶ Ἡρακλέους ἐς τοῦτο τὸ σχῆμα. εἰ δὲ καὶ Ἀσιναίοις τοῖς ἐν τῇ Ἀργολίδι ἔθηκεν ὅρον τοῦτον, οὐκ ἂν ἔγωγε εἰδείην, ἐπεὶ μηδὲ ἑτέρωθι ἀναστάτου γενομένης χώρας τὸ σαφὲς ἔτι οἷόν τε τῶν ὅρων ἐξευρεῖν. ἐπὶ δὲ τῇ ἄκρᾳ τοῦ ὄρους Κορυφαίας ἐστὶν ἱερὸν Ἀρτέμιδος, οὗ καὶ Τελέσιλλα ἐποιήσατο ἐν ᾄσματι μνήμην.", "st": "2.28"}, {"sp": "N", "t": "κατιοῦσι δὲ ἐς τῶν Ἐπιδαυρίων τὴν πόλιν χωρίον ἐστὶ πεφυκυίας ἀγριελαίους ἔχον· Ὑρνήθιον δὲ καλοῦσι τὸ χωρίον. τὰ δὲ ἐς αὐτό, ὡς Ἐπιδαύριοί τε λέγουσι καὶ εἰκὸς ἔχει, γράψω. Κεῖσος καὶ οἱ λοιποὶ Τημένου παῖδες μάλιστα ᾔδεσαν Δηιφόντην λυπήσοντες, εἰ διαλῦσαί πως ἀπ’ αὐτοῦ τὴν Ὑρνηθὼ δυνηθεῖεν. ἀφίκοντο οὖν ἐς Ἐπίδαυρον Κερύνης καὶ Φάλκης· Ἀγραίῳ γὰρ τῷ νεωτάτῳ τὰ ποιούμενα οὐκ ἤρεσκεν. οὗτοι δὲ στήσαντες τὸ ἅρμα ὑπὸ τὸ τεῖχος κήρυκα ἀποστέλλουσι παρὰ τὴν ἀδελφήν, ἐλθεῖν δῆθεν ἐς λόγους αὐτῇ βουλόμενοι.", "st": "2.28"}, {"sp": "N", "t": "ὡς δὲ ὑπήκουσε καλοῦσιν, ἐνταῦθα οἱ νεανίσκοι πολλὰ μὲν Δηιφόντου κατηγόρουν, πολλὰ δὲ αὐτὴν ἱκέτευον ἐκείνην ἐπανήκειν ἐς Ἄργος, ἄλλα τε ἐπαγγελλόμενοι καὶ ἀνδρὶ δώσειν αὐτὴν Δηιφόντου τὰ πάντα ἀμείνονι καὶ ἀνθρώπων πλειόνων καὶ γῆς ἄρχοντι εὐδαιμονεστέρας. Ὑρνηθὼ δὲ τοῖς λεχθεῖσιν ἀλγήσασα ἀπεδίδου σφίσι τὴν ἴσην, Δηιφόντην μὲν αὑτῇ τε ἄνδρα ἀρεστὸν εἶναι φήσασα καὶ Τημένῳ γενέσθαι γαμβρὸν οὐ μεμπτόν, ἐκείνοις δὲ Τημένου προσήκειν σφαγεῦσιν ὀνομάζεσθαι μᾶλλον ἢ παισίν.", "st": "2.28"}, {"sp": "N", "t": "καὶ τὴν μὲν οὐδὲν ἔτι ἀποκρινάμενοι συλλαμβάνουσιν, ἀναθέντες δὲ ἐς τὸ ἅρμα ἀπήλαυνον· Δηιφόντῃ δὲ ἀγγέλλει τις τῶν Ἐπιδαυρίων ὡς Κερύνης καὶ Φάλκης ἄγοντες οἴχοιντο ἄκουσαν Ὑρνηθώ. ὁ δὲ αὐτός τε ὡς τάχους εἶχεν ἤμυνε καὶ οἱ Ἐπιδαύριοι πυνθανόμενοι προσεβοήθουν. Δηιφόντης δὲ Κερύνην μὲν ὡς κατελάμβανεν ἀναιρεῖ βαλών, Φάλκην δὲ ἐχόμενον Ὑρνηθοῦς βαλεῖν μὲν ἔδεισε, μὴ ἁμαρτὼν γένοιτο αὐτῆς ἐκείνης φονεύς, συμπλακεὶς δὲ ἐπειρᾶτο ἀφαιρεῖσθαι. Φάλκης δὲ ἀντεχόμενος καὶ ἕλκων βιαιότερον ἀπέκτεινεν ἔχουσαν ἐν γαστρί.", "st": "2.28"}, {"sp": "N", "t": "καὶ ὁ μὲν συνείς, οἷα ἐς τὴν ἀδελφὴν ἐξειργασμένος ἔργα ἦν, ἤλαυνε τὸ ἅρμα ἀφειδέστερον, προλαβεῖν τῆς ὁδοῦ σπεύδων πρὶν ἢ πάντας ἐπ’ αὐτὸν συλλεχθῆναι τοὺς Ἐπιδαυρίους· Δηιφόντης δὲ σὺν τοῖς παισίν—ἐγεγόνεσαν γὰρ καὶ παῖδες αὐτῷ πρότερον ἔτι υἱοὶ μὲν Ἀντιμένης καὶ Ξάνθιππός τε καὶ Ἀργεῖος, θυγάτηρ δὲ Ὀρσοβία· ταύτην Πάμφυλον τὸν Αἰγιμίου λέγουσιν ὕστερον γῆμαι·—τότε δὲ ἀναλαβόντες τὸν νεκρὸν τῆς Ὑρνηθοῦς κομίζουσιν ἐς τοῦτο τὸ χωρίον τὸ ἀνὰ χρόνον Ὑρνήθιον κληθέν.", "st": "2.28"}, {"sp": "N", "t": "καί οἱ ποιήσαντες ἡρῷον τιμὰς καὶ ἄλλας δεδώκασι καὶ ἐπὶ τοῖς πεφυκόσιν ἐλαίοις, καὶ εἰ δή τι ἄλλο δένδρον ἔσω, καθέστηκε νόμος τὰ θραυόμενα μηδένα ἐς οἶκον φέρεσθαι μηδὲ χρᾶσθαί σφισιν ἐς μηδέν, κατὰ χώραν δ’ αὐτοῦ λείπουσιν ἱερὰ εἶναι τῆς Ὑρνηθοῦς.", "st": "2.28"}, {"sp": "N", "t": "οὐ πόρρω δὲ τῆς πόλεως Μελίσσης μνῆμά ἐστιν, ἣ Περιάνδρῳ συνῴκησε τῷ Κυψέλου, καὶ ἕτερον Προκλέους πατρὸς τῆς Μελίσσης. ἐτυράννει δὲ καὶ οὗτος Ἐπιδαυρίων, καθὰ δὴ καὶ ὁ γαμβρός οἱ Περίανδρος Κορίνθου.", "st": "2.28"}, {"sp": "N", "t": "αὐτὴ δὲ τῶν Ἐπιδαυρίων ἡ πόλις παρείχετο ἐς μνήμην τάδε ἀξιολογώτατα· τέμενος δή ἐστιν Ἀσκληπιοῦ καὶ ἀγάλματα ὁ θεὸς αὐτὸς καὶ Ἠπιόνη, γυναῖκα δὲ εἶναι τὴν Ἠπιόνην Ἀσκληπιοῦ φασι· ταῦτά ἐστιν ἐν ὑπαίθρῳ λίθου Παρίου. ναοὶ δὲ ἐν τῇ πόλει καὶ Διονύσου καὶ Ἀρτέμιδός ἐστιν ἄλσος· εἰκάσαις ἂν θηρευούσῃ τὴν Ἄρτεμιν. Ἀφροδίτης τε ἱερὸν πεποίηται· τὸ δὲ πρὸς τῷ λιμένι ἐπὶ ἄκρας ἀνεχούσης ἐς θάλασσαν λέγουσιν Ἥρας εἶναι. τὴν δὲ Ἀθηνᾶν ἐν τῇ ἀκροπόλει, ξόανον θέας ἄξιον, Κισσαίαν ἐπονομάζουσιν.", "st": "2.29"}, {"sp": "N", "t": "Αἰγινῆται δὲ οἰκοῦσιν ἔχοντες τὴν νῆσον ἀπαντικρὺ τῆς Ἐπιδαυρίας. ἀνθρώπους δ’ οὐκ εὐθὺς ἐξ ἀρχῆς λέγουσιν ἐν αὐτῇ γενέσθαι· Διὸς δὲ ἐς ἔρημον κομίσαντος Αἴγιναν τὴν Ἀσωποῦ τῇ μὲν τὸ ὄνομα ἐτέθη τοῦτο ἀντὶ Οἰνώνης, Αἰακοῦ δὲ αἰτήσαντος ὡς ηὐξήθη παρὰ Διὸς οἰκήτορας, οὕτω οἱ τὸν Δία ἀνεῖναι τοὺς ἀνθρώπους φασὶν ἐκ τῆς γῆς. βασιλεύσαντα δὲ ἐν τῇ γῇ πλὴν Αἰακὸν οὐδένα εἰπεῖν ἔχουσιν, ἐπεὶ μηδὲ τῶν Αἰακοῦ παίδων τινὰ ἴσμεν καταμείναντα, Πηλεῖ μὲν συμβὰν καὶ Τελαμῶνι ἐπὶ φόνῳ φεύγειν τῷ Φώκου, τῶν δὲ αὖ Φώκου παίδων περὶ τὸν Παρνασσὸν οἰκησάντων ἐν τῇ νῦν καλουμένῃ Φωκίδι.", "st": "2.29"}, {"sp": "N", "t": "τὸ δὲ ὄνομα προϋπῆρχεν ἤδη τῇ χώρᾳ, Φώκου τοῦ Ὀρνυτίωνος γενεᾷ πρότερον ἐς αὐτὴν ἐλθόντος. ἐπὶ μὲν δὴ Φώκου τούτου ⟨ἡ⟩ περὶ Τιθορέαν τε καὶ Παρνασσὸν ἐκαλεῖτο [ἡ] Φωκίς· ἐπὶ δὲ τοῦ Αἰακοῦ καὶ πᾶσιν ἐξενίκησεν, ὅσοι Μινύαις τέ εἰσιν Ὀρχομενίοις ὅμοροι καὶ ἐπὶ Σκάρφειαν τὴν Λοκρῶν καθήκουσι.", "st": "2.29"}, {"sp": "N", "t": "γεγόνασι δὲ ἀπὸ μὲν Πηλέως οἱ ἐν Ἠπείρῳ βασιλεῖς, Τελαμῶνος δὲ τῶν παίδων Αἴαντος μέν ἐστιν ἀφανέστερον γένος οἷα ἰδιωτεύσαντος ἀνθρώπου, πλὴν ὅσον Μιλτιάδης, ὃς Ἀθηναίοις ἐς Μαραθῶνα ἡγήσατο, καὶ Κίμων ὁ Μιλτιάδου προῆλθον ἐς δόξαν· οἱ δὲ Τευκρίδαι βασιλεῖς διέμειναν Κυπρίων ἄρχοντες ἐς Εὐαγόραν. Φώκῳ δὲ Ἄσιος ὁ τὰ ἔπη ποιήσας γενέσθαι φησὶ Πανοπέα καὶ Κρῖσον· καὶ Πανοπέως μὲν ἐγένετο Ἐπειὸς ὁ τὸν ἵππον τὸν δούρειον, ὡς Ὅμηρος ἐποίησεν, ἐργασάμενος, Κρίσου δὲ ἦν ἀπόγονος τρίτος Πυλάδης, Στροφίου τε ὢν τοῦ Κρίσου καὶ Ἀναξιβίας ἀδελφῆς Ἀγαμέμνονος. γένη μὲν τοσαῦτα τῶν καλουμένων Αἰακιδῶν, ἐξεχώρησε δὲ ἑτέρωσε ἀπ’ ἀρχῆς.", "st": "2.29"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον μοῖρα Ἀργείων τῶν Ἐπίδαυρον ὁμοῦ Δηιφόντῃ κατασχόντων, διαβᾶσα ἐς Αἴγιναν καὶ Αἰγινήταις τοῖς ἀρχαίοις γενόμενοι σύνοικοι, τὰ Δωριέων ἔθη καὶ φωνὴν κατεστήσαντο ἐν τῇ νήσῳ. προελθοῦσι δὲ Αἰγινήταις ἐς μέγα δυνάμεως, ὡς Ἀθηναίων γενέσθαι ναυσὶν ἐπικρατεστέρους καὶ ἐν τῷ Μηδικῷ πολέμῳ παρασχέσθαι πλοῖα μετά γε Ἀθηναίους πλεῖστα, οὐ παρέμεινεν ἐς ἅπαν ἡ εὐδαιμονία, γενόμενοι δὲ ὑπὸ Ἀθηναίων ἀνάστατοι Θυρέαν τὴν ἐν τῇ Ἀργολίδι Λακεδαιμονίων δόντων ᾤκησαν. καὶ ἀπέλαβον μὲν τὴν νῆσον, ὅτε περὶ Ἑλλήσποντον αἱ Ἀθηναίων τριήρεις ἐλήφθησαν, πλούτου δὲ ἢ δυνάμεως οὐκέτι ἐξεγένετο ἐς ἴσον προελθεῖν σφισιν.", "st": "2.29"}, {"sp": "N", "t": "προσπλεῦσαι δὲ Αἴγινά ἐστι νήσων τῶν Ἑλληνίδων ἀπορωτάτη· πέτραι τε γὰρ ὕφαλοι περὶ πᾶσαν καὶ χοιράδες ἀνεστήκασι. μηχανήσασθαι δὲ ἐξεπίτηδες ταῦτα Αἰακόν φασι λῃστειῶν τῶν ἐκ θαλάσσης φόβῳ, καὶ πολεμίοις ἀνδράσι μὴ ἄνευ κινδύνου εἶναι. πλησίον δὲ τοῦ λιμένος ἐν ᾧ μάλιστα ὁρμίζονται ναός ἐστιν Ἀφροδίτης, ἐν ἐπιφανεστάτῳ δὲ τῆς πόλεως τὸ Αἰάκειον καλούμενον, περίβολος τετράγωνος λευκοῦ λίθου.", "st": "2.29"}, {"sp": "N", "t": "ἐπειργασμένοι δέ εἰσι κατὰ τὴν ἔσοδον οἱ παρὰ Αἰακόν ποτε ὑπὸ τῶν Ἑλλήνων σταλέντες· αἰτίαν δὲ τὴν αὐτὴν Αἰγινήταις καὶ οἱ λοιποὶ λέγουσιν. αὐχμὸς τὴν Ἑλλάδα ἐπὶ χρόνον ἐπίεζε καὶ οὔτε τὴν ἐκτὸς ἰσθμοῦ χώραν οὔτε Πελοποννησίοις ὗεν ὁ θεός, ἐς ὃ ἐς Δελφοὺς ἀπέστειλαν ἐρησομένους τὸ αἴτιον ὅ τι εἴη καὶ αἰτήσοντας ἅμα λύσιν τοῦ κακοῦ. τούτοις ἡ Πυθία εἶπε Δία ἱλάσκεσθαι, χρῆναι δέ, εἴπερ ὑπακούσει σφίσιν, Αἰακὸν τὸν ἱκετεύσαντα εἶναι.", "st": "2.29"}, {"sp": "N", "t": "οὕτως Αἰακοῦ δεησομένους ἀποστέλλουσιν ἀφ’ ἑκάστης πόλεως· καὶ ὁ μὲν τῷ Πανελληνίῳ Διὶ θύσας καὶ εὐξάμενος τὴν Ἑλλάδα γῆν ἐποίησεν ὕεσθαι, τῶν δὲ ἐλθόντων ὡς αὐτὸν εἰκόνας ταύτας ἐποιήσαντο οἱ Αἰγινῆται. τοῦ περιβόλου δὲ ἐντὸς ἐλαῖαι πεφύκασιν ἐκ παλαιοῦ καὶ βωμός ἐστιν οὐ πολὺ ἀνέχων ἐκ τῆς γῆς· ὡς δὲ καὶ μνῆμα οὗτος ὁ βωμὸς εἴη Αἰακοῦ, λεγόμενόν ἐστιν ἐν ἀπορρήτῳ.", "st": "2.29"}, {"sp": "N", "t": "παρὰ δὲ τὸ Αἰάκειον Φώκου τάφος χῶμά ἐστι περιεχόμενον κύκλῳ κρηπῖδι, ἐπίκειται δέ οἱ λίθος τραχύς· καὶ ἡνίκα Φῶκον Τελαμὼν καὶ Πηλεὺς προηγάγοντο ἐς ἀγῶνα πεντάθλου καὶ περιῆλθεν ἐς Πηλέα ἀφεῖναι τὸν λίθον—οὗτος γὰρ ἀντὶ δίσκου σφίσιν ἦν—, ἑκὼν τυγχάνει τοῦ Φώκου. ταῦτα δὲ ἐχαρίζοντο τῇ μητρί· αὐτοὶ μὲν γὰρ ἐγεγόνεσαν ἐκ τῆς Σκίρωνος θυγατρός, Φῶκος δὲ οὐκ ἐκ τῆς αὐτῆς, ἀλλ’ ἐξ ἀδελφῆς Θέτιδος ἦν, εἰ δὴ τὰ ὄντα λέγουσιν Ἕλληνες. Πυλάδης τέ μοι καὶ διὰ ταῦτα φαίνεται καὶ οὐκ Ὀρέστου φιλίᾳ μόνον βουλεῦσαι Νεοπτολέμῳ τὸν φόνον.", "st": "2.29"}, {"sp": "N", "t": "τότε δὲ ὡς τῷ δίσκῳ πληγεὶς ἀπέθανεν ὁ Φῶκος, φεύγουσιν ἐπιβάντες νεὼς οἱ Ἐνδηίδος παῖδες· Τελαμὼν δὲ ὕστερα κήρυκα ἀποστέλλων ἠρνεῖτο μὴ βουλεῦσαι Φώκῳ θάνατον. Αἰακὸς δὲ ἐς μὲν τὴν νῆσον ἀποβαίνειν αὐτὸν οὐκ εἴα, ἑστηκότα δὲ ἐπὶ νεώς, εἰ δὲ ἐθέλοι, χῶμα ἐν τῇ θαλάσσῃ χώσαντα ἐκέλευεν ἐντεῦθεν ἀπολογήσασθαι. οὕτως ἐς τὸν Κρυπτὸν καλούμενον λιμένα ἐσπλεύσας νύκτωρ ἐποίει χῶμα. καὶ τοῦτο μὲν ἐξεργασθὲν καὶ ἐς ἡμᾶς ἔτι μένει· καταγνωσθεὶς δὲ οὐκ ἀναίτιος εἶναι Φώκῳ τῆς τελευτῆς, τὸ δεύτερον ἐς Σαλαμῖνα ἀπέπλευσε.", "st": "2.29"}, {"sp": "N", "t": "τοῦ λιμένος δὲ οὐ πόρρω τοῦ Κρυπτοῦ θέατρόν ἐστι θέας ἄξιον, κατὰ τὸ Ἐπιδαυρίων μάλιστα μέγεθος καὶ ἐργασίαν τὴν λοιπήν. τούτου δὲ ὄπισθεν ᾠκοδόμηται σταδίου πλευρὰ μία, ἀνέχουσά τε αὐτὴ τὸ θέατρον καὶ ἀντὶ ἐρείσματος ἀνάλογον ἐκείνῳ χρωμένη.", "st": "2.29"}, {"sp": "N", "t": "ναοὶ δὲ οὐ πολὺ ἀλλήλων ἀφεστηκότες ὁ μὲν Ἀπόλλωνός ἐστιν, ὁ δὲ Ἀρτέμιδος, Διονύσῳ δὲ αὐτῶν ὁ τρίτος. Ἀπόλλωνι μὲν δὴ ξόανον γυμνόν ἐστι τέχνης τῆς ἐπιχωρίου, τῇ δὲ Ἀρτέμιδί ἐστιν ἐσθής, κατὰ ταὐτὰ δὲ καὶ τῷ Διονύσῳ· καὶ γένεια Διόνυσος ἔχων πεποίηται. τοῦ δὲ Ἀσκληπιοῦ τὸ ἱερὸν ἔστι μὲν ἑτέρωθι καὶ οὐ ταύτῃ, λίθου δὲ ἄγαλμα καθήμενον.", "st": "2.30"}, {"sp": "N", "t": "θεῶν δὲ Αἰγινῆται τιμῶσιν Ἑκάτην μάλιστα καὶ τελετὴν ἄγουσιν ἀνὰ πᾶν ἔτος Ἑκάτης, Ὀρφέα σφίσι τὸν Θρᾷκα καταστήσασθαι τὴν τελετὴν λέγοντες. τοῦ περιβόλου δὲ ἐντὸς ναός ἐστι, ξόανον δὲ ἔργον Μύρωνος, ὁμοίως ἓν πρόσωπόν τε καὶ τὸ λοιπὸν σῶμα. Ἀλκαμένης δὲ ἐμοὶ δοκεῖν πρῶτος ἀγάλματα Ἑκάτης τρία ἐποίησε προσεχόμενα ἀλλήλοις, ἣν Ἀθηναῖοι καλοῦσιν Ἐπιπυργιδίαν· ἕστηκε δὲ παρὰ τῆς Ἀπτέρου Νίκης τὸν ναόν.", "st": "2.30"}, {"sp": "N", "t": "ἐν Αἰγίνῃ δὲ πρὸς τὸ ὄρος τοῦ Πανελληνίου Διὸς ἰοῦσιν, ἔστιν Ἀφαίας ἱερόν, ἐς ἣν καὶ Πίνδαρος ᾆσμα Αἰγινήταις ἐποίησε. φασὶ δὲ οἱ Κρῆτες— τούτοις γάρ ἐστι τὰ ἐς αὐτὴν ἐπιχώρια—Καρμάνορος τοῦ καθήραντος Ἀπόλλωνα ἐπὶ φόνῳ τῶ Πύθωνος παῖδα Εὔβουλον εἶναι, Διὸς δὲ καὶ Κάρμης τῆς Εὐβούλου Βριτόμαρτιν γενέσθαι· χαίρειν δὲ αὐτὴν δρόμοις τε καὶ θήραις καὶ Ἀρτέμιδι μάλιστα φίλην εἶναι· Μίνω δὲ ἐρασθέντα φεύγουσα ἔρριψεν ἑαυτὴν ἐς δίκτυα ἀφειμένα ἐπ’ ἰχθύων θήρᾳ. ταύτην μὲν θεὸν ἐποίησεν Ἄρτεμις, σέβουσι δὲ οὐ Κρῆτες μόνον ἀλλὰ καὶ Αἰγινῆται, λέγοντες φαίνεσθαί σφισιν ἐν τῇ νήσῳ τὴν Βριτόμαρτιν. ἐπίκλησις δέ οἱ παρά τε Αἰγινήταις ἐστὶν Ἀφαία καὶ Δίκτυννα ἐν Κρήτῃ.", "st": "2.30"}, {"sp": "N", "t": "τὸ δὲ Πανελλήνιον, ὅτι μὴ τοῦ Διὸς τὸ ἱερόν, ἄλλο τὸ ὄρος ἀξιόλογον εἶχεν οὐδέν. τοῦτο δὲ τὸ ἱερὸν λέγουσιν Αἰακὸν ποιῆσαι τῷ Διί· τὰ δὲ ἐς τὴν Αὐξησίαν καὶ Δαμίαν, ὡς οὐχ ὗεν ὁ θεὸς Ἐπιδαυρίοις, ὡς τὰ ξόανα ταῦτα ἐκ μαντείας ἐποιήσαντο ἐλαίας παρ’ Ἀθηναίων λαβόντες, ὡς Ἐπιδαύριοι μὲν οὐκ ἀπέφερον ἔτι Ἀθηναίοις ἃ ἐτάξαντο οἷα Αἰγινητῶν ἐχόντων τὰ ἀγάλματα, Ἀθηναίων δὲ ἀπώλοντο οἱ διαβάντες διὰ ταῦτα ἐς Αἴγιναν, ταῦτα εἰπόντος Ἡροδότου καθ’ ἕκαστον αὐτῶν ἐπ’ ἀκριβὲς οὔ μοι γράφειν κατὰ γνώμην ἦν εὖ προειρημένα, πλὴν τοσοῦτό γε ὅτι εἶδόν τε τὰ ἀγάλματα καὶ ἔθυσά σφισι κατὰ ⟨τὰ⟩ αὐτὰ καθὰ δὴ καὶ Ἐλευσῖνι θύειν νομίζουσιν.", "st": "2.30"}, {"sp": "N", "t": "Αἰγίνης μὲν ⟨δὴ⟩ Αἰακοῦ ἕνεκα καὶ ἔργων ὁπόσα ἀπεδείξατο ἐς τοσόνδε ἔστω μνήμη· τῆς δὲ Ἐπιδαυρίας ἔχονται Τροιζήνιοι, σεμνύνοντες εἴπερ καὶ ἄλλοι τινὲς τὰ ἐγχώρια· φασὶ δὲ Ὦρον γενέσθαι σφίσιν ἐν τῇ γῆ πρῶτον. ἐμοὶ μὲν οὖν Αἰγύπτιον φαίνεται καὶ οὐδαμῶς Ἑλληνικὸν ὄνομα Ὦρος εἶναι· βασιλεῦσαι δ’ οὖν φασιν αὐτὸν καὶ Ὠραίαν ἀπ’ αὐτοῦ καλεῖσθαι τὴν γῆν, Ἄλθηπον δὲ Ποσειδῶνος παῖδα καὶ Ληίδος τῆς Ὤρου, παραλαβόντα μετὰ Ὦρον τὴν ἀρχήν, Ἀλθηπίαν ὀνομάσαι τὴν γῆν.", "st": "2.30"}, {"sp": "N", "t": "ἐπὶ τούτου βασιλεύοντος Ἀθηνᾶν καὶ Ποσειδῶνα ἀμφισβητῆσαι λέγουσι περὶ τῆς χώρας, ἀμφισβητήσαντας δὲ ἔχειν ἐν κοινῷ· προστάξαι γὰρ οὕτω Δία σφίσι. καὶ διὰ τοῦτο Ἀθηνᾶν τε σέβουσι Πολιάδα καὶ Σθενιάδα ὀνομάζοντες τὴν αὐτὴν καὶ Ποσειδῶνα Βασιλέα ἐπίκλησιν· καὶ δὴ καὶ νόμισμα αὐτοῖς τὸ ἀρχαῖον ἐπίσημα ἔχει τρίαιναν καὶ Ἀθηνᾶς πρόσωπον.", "st": "2.30"}, {"sp": "N", "t": "μετὰ δὲ Ἄλθηπον Σάρων ἐβασίλευσεν. ἔλεγον δὲ ὅτι οὗτος τῇ Σαρωνίδι τὸ ἱερὸν Ἀρτέμιδι ᾠκοδόμησεν ἐπὶ θαλάσσῃ τελματώδει καὶ ἐπιπολῆς μᾶλλον, ὥστε καὶ Φοιβαία λίμνη διὰ τοῦτο ἐκαλεῖτο. Σάρωνα δὲ—θηρεύειν γὰρ δὴ μάλιστα ᾕρητο—κατέλαβεν ἔλαφον διώκοντα ἐς θάλασσαν συνεσπεσεῖν φευγούσῃ· καὶ ἥ τε ἔλαφος ἐνήχετο ἀπωτέρω τῆς γῆς καὶ ὁ Σάρων εἴχετο τῆς ἄγρας, ἐς ὃ ὑπὸ προθυμίας ἀφίκετο ἐς τὸ πέλαγος· ἤδη δὲ κάμνοντα αὐτὸν καὶ ὑπὸ τῶν κυμάτων κατακλυζόμενον ἐπέλαβε τὸ χρεών. ἐκπεσόντα δὲ τὸν νεκρὸν κατὰ τὴν· Φοιβαίαν λίμνην ἐς τὸ ἄλσος τῆς Ἀρτέμιδος ἐντὸς τοῦ ἱεροῦ περιβόλου θάπτουσι, καὶ λίμνην ἀπὸ τούτου Σαρωνίδα τὴν ταύτῃ θάλασσαν καλοῦσιν ἀντὶ Φοιβαίας.", "st": "2.30"}, {"sp": "N", "t": "τοὺς δὲ ὕστερον βασιλεύσαντας οὐκ ἴσασιν ἄχρι Ὑπέρητος καὶ Ἄνθα· τούτους δὲ εἶναι Ποσειδῶνος καὶ Ἀλκυόνης Ἄτλαντος θυγατρός, καὶ πόλεις αὐτοὺς ἐν τῇ χώρᾳ φασὶν Ὑπέρειάν τε καὶ Ἄνθειαν οἰκίσαι· Ἀέτιον δὲ τὸν Ἄνθα τοῦ πατρὸς καὶ τοῦ θείου παραλαβόντα τὴν ἀρχὴν τὴν ἑτέραν τῶν πόλεων Ποσειδωνιάδα ὀνομάσαι. Τροίζηνος δὲ καὶ Πιτθέως παρὰ Ἀέτιον ἐλθόντων βασιλεῖς μὲν τρεῖς ἀντὶ ἑνὸς ἐγένοντο, ἴσχυον δὲ οἱ παῖδες μᾶλλον οἱ Πέλοπος.", "st": "2.30"}, {"sp": "N", "t": "σημεῖον δέ· ἀποθανόντος γὰρ Τροίζηνος Πιτθεὺς ⟨ἐς⟩ τὴν νῦν πόλιν συναγαγὼν τοὺς ἀνθρώπους ὠνόμασεν ἀπὸ τοῦ ἀδελφοῦ Τροίζηνα, συλλαβὼν ⟨Ὑπέρειάν τε⟩ καὶ Ἄνθ⟨ει⟩αν. πολλοῖς δὲ ἔτεσιν ὕστερον ἐς ἀποικίαν ἐκ Τροιζῆνος σταλέντες Ἁλικαρνασσὸν ἐν τῇ Καρίᾳ καὶ Μύνδον ἀπῴκισαν οἱ γεγονότες ἀπ’ Ἀετίου τοῦ Ἄνθα. Τροίζηνος δὲ οἱ παῖδες Ἀνάφλυστος καὶ Σφῆττος μετοικοῦσιν ἐς τὴν Ἀττικήν, καὶ οἱ δῆμοι τὰ ὀνόματα ἔχουσιν ἀπὸ τούτων. τὰ δὲ ἐς Θησέα θυγατριδοῦν Πιτθέως εἰδόσι τὰ ἐς αὐτὸν οὐ γράφω, δεῖ δέ με τοσόνδε ἔτι δηλῶσαι.", "st": "2.30"}, {"sp": "N", "t": "Ἡρακλειδῶν γὰρ κατελθόντων ἐδέξαντο καὶ οἱ Τροιζήνιοι συνοίκους Δωριέων τῶν ἐξ Ἄργους καὶ πρότερον ἔτι Ἀργείων ὄντες κατήκοοι· καὶ σφᾶς καὶ Ὅμηρος ἐν καταλόγῳ φησὶν ὑπὸ Διομήδους ἄρχεσθαι. Διομήδης γὰρ καὶ Εὐρύαλος ὁ Μηκιστέως Κυάνιππον τὸν Αἰγιαλέως παῖδα ὄντα ἐπιτροπεύοντες Ἀργείων ἡγήσαντο ἐς Τροίαν. Σθένελος δέ, ὡς ἐδήλωσα ἐν τοῖς πρότερον, οἰκίας τε ἦν ἐπιφανεστέρας, τῶν Ἀναξαγοριδῶν καλουμένων, καὶ ἡ βασιλεία τούτῳ μάλιστα ἦν ἡ Ἀργείων προσήκουσα. τοσαῦτα Τροιζηνίοις ἐχόμενα ἱστορίας ἦν, παρὲξ ἢ ὅσαι πόλεις παρ’ αὐτῶν φασιν ἀποικισθῆναι· κατασκευὴν δὲ ἱερῶν καὶ ὅσα ἄλλα ἐς ἐπίδειξιν, τὸ ἐντεῦθεν ἐπέξειμι.", "st": "2.30"}, {"sp": "N", "t": "ἐν τῇ ἀγορᾷ Τροιζηνίων ναὸς καὶ ἀγάλματα Ἀρτέμιδός ἐστι Σωτείρας· Θησέα δὲ ἐλέγετο ἱδρύσασθαι καὶ ὀνομάσαι Σώτειραν, ἡνίκα Ἀστερίωνα τὸν Μίνω καταγωνισάμενος ἀνέστρεψεν ἐκ τῆς Κρήτης. ἀξιολογώτατον δὲ εἶναι τοῦτο ἔδοξέν οἱ τῶν κατειργασμένων, οὐ τοσοῦτον ἐμοὶ δοκεῖν ὅτι ἀνδρείᾳ τοὺς ἀποθανόντας ὑπὸ Θησέως ὑπερέβαλεν ὁ Ἀστερίων, ἀλλὰ τό τε [ἐκ] τοῦ λαβυρίνθου δυσέξοδον καὶ ⟨τὸ⟩ λαθόντα ἀποδρᾶναι μετὰ τὸ ἔργον ἐποίησεν εἰκότα τὸν λόγον ὡς προνοίᾳ θείᾳ καὶ αὐτὸς ἀνασωθείη Θησεὺς καὶ οἱ σὺν αὐτῷ.", "st": "2.31"}, {"sp": "N", "t": "ἐν τούτῳ δέ εἰσι τῷ ναῷ βωμοὶ θεῶν τῶν λεγομένων ὑπὸ γῆν ἄρχειν, καί φασιν ἐξ Ἅιδου Σεμέλην τε ὑπὸ Διονύσου κομισθῆναι ταύτῃ καὶ ὡς Ἡρακλῆς ἀναγάγοι τὸν κύνα τοῦ Ἅιδου· ἐγὼ δὲ Σεμέλην μὲν οὐδὲ ἀποθανεῖν ἀρχὴν πείθομαι Διός γε οὖσαν γυναῖκα, τὰ δὲ ἐς τὸν ὀνομαζόμενον Ἅιδου κύνα ἑτέρωθι ἔσται μοι δῆλα ὁποῖα εἶναί μοι δοκεῖ.", "st": "2.31"}, {"sp": "N", "t": "ὄπισθεν δὲ τοῦ ναοῦ Πιτθέως μνῆμά ἐστι, τρεῖς δὲ ἐπ’ αὐτῷ θρόνοι κεῖνται λίθου λευκοῦ· δικάζειν δὲ Πιτθέα καὶ ἄνδρας δύο σὺν αὐτῷ λέγουσιν ἐπὶ τῶν θρόνων. οὐ πόρρω δὲ ἱερὸν Μουσῶν ἐστι, ποιῆσαι δὲ ἔλεγον αὐτὸ Ἄρδαλον παῖδα Ἡφαίστου· καὶ αὐλόν τε εὑρεῖν νομίζουσι τὸν Ἄρδαλον τοῦτον καὶ τὰς Μούσας ἀπ’ αὐτοῦ καλοῦσιν Ἀρδαλίδας. ἐνταῦθα Πιτθέα διδάξαι λόγων τέχνην φασί, καί τι βιβλίον Πιτθέως δὴ σύγγραμμα ὑπὸ ἀνδρὸς ἐκδοθὲν Ἐπιδαυρίου καὶ αὐτὸς ἐπελεξάμην. τοῦ Μουσείου δὲ ⟨οὐ⟩ πόρρω βωμός ἐστιν ἀρχαῖος, Ἀρδάλου καὶ τοῦτον ὥς φασιν ἀναθέντος· ἐπὶ δὲ αὐτῷ Μούσαις καὶ Ὕπνῳ θύουσι, λέγοντες τὸν Ὕπνον θεὸν μάλιστα εἶναι φίλον ταῖς Μούσαις.", "st": "2.31"}, {"sp": "N", "t": "πλησίον δὲ τοῦ θεάτρου Λυκείας ναὸν Ἀρτέμιδος ἐποίησεν Ἱππόλυτος· ἐς δὲ τὴν ἐπίκλησιν οὐδὲν εἶχον πυθέσθαι παρὰ τῶν ἐξηγητῶν, ἀλλὰ ἢ λύκους ἐφαίνετό μοι τὴν Τροιζηνίαν λυμαινομένους ἐξελεῖν ὁ Ἱππόλυτος ἢ Ἀμαζόσι, παρ’ ὧν τὰ πρὸς μητρὸς ἦν, ἐπίκλησις τῆς Ἀρτέμιδός ἐστιν αὕτη· εἴη δ’ ἂν ἔτι καὶ ἄλλο οὐ γινωσκόμενον ὑπὸ ἐμοῦ. τὸν δὲ ἔμπροσθεν τοῦ ναοῦ λίθον, καλούμενον δὲ ἱερόν, εἶναι λέγουσιν ἐφ’ οὗ ποτε ἄνδρες Τροιζηνίων ἐννέα Ὀρέστην ἐκάθηραν ἐπὶ τῷ φόνῳ τῆς μητρός.", "st": "2.31"}, {"sp": "N", "t": "εἰσὶ δὲ οὐ μακρὰν τῆς Λυκείας Ἀρτέμιδος βωμοὶ διεστηκότες οὐ πολὺ ἀπ’ ἀλλήλων· ὁ μὲν πρῶτός ἐστιν αὐτῶν Διονύσου κατὰ δή τι μάντευμα ἐπίκλησιν Σαώτου, δεύτερος δὲ Θεμίδων ὀνομαζόμενος· Πιτθεὺς τοῦτον ἀνέθηκεν, ὡς λέγουσιν. Ἡλίου δὲ Ἐλευθερίου καὶ σφόδρα εἰκότι λόγῳ δοκοῦσί μοι ποιῆσαι βωμόν, ἐκφυγόντες δουλείαν ἀπὸ Ξέρξου τε καὶ Περσῶν.", "st": "2.31"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τοῦ Ἀπόλλωνος τοῦ Θεαρίου κατασκευάσαι μὲν Πιτθέα ἔφασαν, ἔστι δὲ ὧν οἶδα παλαιότατον. ἀρχαῖος μὲν οὖν καὶ Φωκαεῦσι τοῖς ἐν Ἰωνίᾳ ναός ἐστιν Ἀθηνᾶς, ὃν Ἅρπαγός ποτε ὁ Μῆδος ἐνέπρησεν, ἀρχαῖος δὲ καὶ [ὁ] Σαμίοις Ἀπόλλωνος Πυθίου· πλὴν πολύ γε ὕστερον τοῦ παρὰ Τροιζηνίοις ἐποιήθησαν. ἄγαλμα δέ ἐστι τὸ ἐφ’ ἡμῶν ἀνάθημα Αὐλίσκου, τέχνη δὲ Ἕρμωνος Τροιζηνίου· τοῦ δὲ Ἕρμωνος τούτου καὶ τὰ τῶν Διοσκούρων ξόανά ἐστι.", "st": "2.31"}, {"sp": "N", "t": "κεῖνται δὲ ἐν στοᾷ τῆς ἀγορᾶς γυναῖκες λίθου καὶ αὐταὶ καὶ οἱ παῖδες. εἰσὶ δὲ ἃς Ἀθηναῖοι Τροιζηνίοις γυναῖκας καὶ τέκνα ἔδωκαν σώζειν, ἐκλιπεῖν σφισιν ἀρέσαν τὴν πόλιν μηδὲ στρατῷ πεζῷ τὸν Μῆδον ἐπιόντα ὑπομεῖναι. λέγονται δὲ οὐ πασῶν τῶν γυναικῶν—οὐ γὰρ δὴ πολλαί τινες ἐκεῖναι—, ὁπόσαι δὲ ἀξιώματι προεῖχον, τούτων εἰκόνας ἀναθεῖναι μόνων.", "st": "2.31"}, {"sp": "N", "t": "τοῦ δὲ ἱεροῦ τοῦ Ἀπόλλωνός ἐστιν οἰκοδόμημα ἔμπροσθεν, Ὀρέστου καλούμενον σκηνή. πρὶν γὰρ ἐπὶ τῷ αἵματι καθαρθῆναι τῆς μητρός, Τροιζηνίων οὐδεὶς πρότερον ἤθελεν αὐτὸν οἴκῳ δέξασθαι· καθίσαντες δὲ ἐνταῦθα ἐκάθαιρον καὶ εἱστίων, ἐς ὃ ἀφήγνισαν. καὶ νῦν ἔτι οἱ ἀπόγονοι τῶν καθηράντων ἐνταῦθα δειπνοῦσιν ἐν ἡμέραις ῥηταῖς. κατορυχθέντων δὲ ὀλίγον ἀπὸ τῆς σκηνῆς τῶν καθαρσίων φασὶν ἀπ’ αὐτῶν ἀναφῦναι δάφνην, ἣ δὴ καὶ ἐς ἡμᾶς ἔστιν, ἡ πρὸ τῆς σκηνῆς ταύτης.", "st": "2.31"}, {"sp": "N", "t": "καθῆραι δέ φασιν Ὀρέστην καθαρσίοις καὶ ἄλλοις καὶ ὕδατι ⟨τῷ⟩ ἀπὸ τῆς Ἵππου κρήνης. ἔστι γὰρ καὶ Τροιζηνίοις Ἵππου καλουμένη κρήνη, καὶ ὁ λόγος ἐς αὐτὴν διαφόρως τῷ Βοιωτῶν ἔχει· Πηγάσῳ γὰρ τῷ ἵππῳ καὶ οὗτοι λέγουσι τὸ ὕδωρ ἀνεῖναι τὴν γῆν θιγόντι τοῦ ἐδάφους τῇ ὁπλῇ, Βελλεροφόντην δὲ ἐλθεῖν ἐς Τροιζῆνα γυναῖκα αἰτήσοντα Αἴθραν παρὰ Πιτθέως, πρὶν δὲ γῆμαι συμβῆναί οἱ φυγεῖν ἐκ Κορίνθου.", "st": "2.31"}, {"sp": "N", "t": "καὶ Ἑρμῆς ἐνταῦθά ἐστι Πολύγιος καλούμενος. πρὸς τούτῳ τῷ ἀγάλματι τὸ ῥόπαλον θεῖναί φασιν Ἡρακλέα· καὶ—ἦν γὰρ κοτίνου—τοῦτο μὲν ὅτῳ πιστὰ ἐνέφυ τῇ γῇ καὶ ἀνεβλάστησεν αὖθις καὶ ἔστιν ὁ κότινος πεφυκὼς ἔτι, τὸν δὲ Ἡρακλέα λέγουσιν ἀνευρόντα τὸν πρὸς τῇ Σαρωνίδι κότινον ἀπὸ τούτου τεμεῖν ῥόπαλον. ἔστι δὲ καὶ Διὸς ἱερὸν ἐπίκλησιν Σωτῆρος· ποιῆσαι δὲ αὐτὸ βασιλεύοντα Ἀέτιον τὸν Ἄνθα λέγουσιν. ὕδωρ δὲ ὀνομάζουσι Χρυσορόαν· αὐχμοῦ δὲ ἐπὶ ἔτη συμβάντος σφίσιν ἐννέα, ἐν οἷς οὐχ ὗεν ὁ θεός, τὰ μὲν ἄλλα ἀναξηρανθῆναί φασιν ὕδατα, τὸν δὲ Χρυσορόαν τοῦτον καὶ τότε ὁμοίως διαμεῖναι ῥέοντα.", "st": "2.31"}, {"sp": "N", "t": "Ἱππολύτῳ δὲ τῷ Θησέως τέμενός τε ἐπιφανέστατον ἀνεῖται καὶ ναὸς ἐν αὐτῷ καὶ ἄγαλμά ἐστιν ἀρχαῖον. ταῦτα μὲν Διομήδην λέγουσι ποιῆσαι καὶ προσέτι θῦσαι τῷ Ἱππολύτῳ πρῶτον· Τροιζηνίοις δὲ ἱερεὺς μέν ἐστιν Ἱππολύτου τὸν χρόνον τοῦ βίου πάντα ἱερώμενος καὶ θυσίαι καθεστήκασιν ἐπέτειοι, δρῶσι δὲ καὶ ἄλλο τοιόνδε· ἑκάστη παρθένος πλόκαμον ἀποκείρεταί οἱ πρὸ γάμου, κειραμένη δὲ ἀνέθηκεν ἐς τὸν ναὸν φέρουσα. ἀποθανεῖν δὲ αὐτὸν οὐκ ἐθέλουσι συρέντα ὑπὸ τῶν ἵππων οὐδὲ τὸν τάφον ἀποφαίνουσιν εἰδότες· τὸν δὲ ἐν οὐρανῷ καλούμενον ἡνίοχον, τοῦτον εἶναι νομίζουσιν ἐκεῖνον Ἱππόλυτον τιμὴν παρὰ θεῶν ταύτην ἔχοντα.", "st": "2.32"}, {"sp": "N", "t": "τούτου δὲ ἐντὸς τοῦ περιβόλου ναός ἐστιν Ἀπόλλωνος Ἐπιβατηρίου, Διομήδους ἀνάθημα ἐκφυγόντος τὸν χειμῶνα ὃς τοῖς Ἕλλησιν ἐπεγένετο ἀπὸ Ἰλίου κομιζομένοις· καὶ τὸν ἀγῶνα τῶν Πυθίων Διομήδην πρῶτον θεῖναί φασι τῷ Ἀπόλλωνι. ἐς δὲ τὴν Δαμίαν καὶ Αὐξησίαν—καὶ γὰρ Τροιζηνίοις μέτεστιν αὐτῶν—οὐ τὸν αὐτὸν λέγουσιν ὃν Ἐπιδαύριοι καὶ Αἰγινῆται λόγον, ἀλλὰ ἀφικέσθαι παρθένους ἐκ Κρήτης· στασιασάντων δὲ ὁμοίως τῶν ἐν τῇ πόλει ἁπάντων καὶ ταύτας φασὶν ὑπὸ τῶν ἀντιστασιωτῶν καταλευσθῆναι, καὶ ἑορτὴν ἄγουσί σφισι Λιθοβόλια ὀνομάζοντες.", "st": "2.32"}, {"sp": "N", "t": "κατὰ δὲ τὸ ἕτερον τοῦ περιβόλου μέρος στάδιόν ἐστιν Ἱππολύτου καλούμενον καὶ ναὸς ὑπὲρ αὐτοῦ Ἀφροδίτης Κατασκοπίας· αὐτόθεν γάρ, ὁπότε γυμνάζοιτο ὁ Ἱππόλυτος, ἀπέβλεπεν ἐς αὐτὸν ἐρῶσα ἡ Φαίδρα. ἐνταῦθα ἔτι πεφύκει ἡ μυρσίνη, τὰ φύλλα ὡς καὶ πρότερον ἔγραψα ἔχουσα τετρυπημένα· καὶ ἡνίκα ἠπορεῖτο ἡ Φαίδρα καὶ ῥᾳστώνην τῷ ἔρωτι οὐδεμίαν εὕρισκεν, ἐς ταύτης τὰ φύλλα ἐσιναμώρει τῆς μυρσίνης.", "st": "2.32"}, {"sp": "N", "t": "ἔστι δὲ καὶ τάφος Φαίδρας, ἀπέχει δὲ οὐ πολὺ τοῦ Ἱππολύτου μνήματος· τὸ δὲ οὐ πόρρω κέχωσται τῆς μυρσίνης. τοῦ δὲ Ἀσκληπιοῦ τὸ ἄγαλμα ἐποίησε μὲν Τιμόθεος, Τροιζήνιοι δὲ οὐκ Ἀσκληπιὸν ἀλλὰ εἰκόνα Ἱππολύτου φασὶν εἶναι. καὶ οἰκίαν ἰδὼν οἶδα Ἱππολύτου· πρὸ δὲ αὐτῆς ἐστιν Ἡράκλειος καλουμένη κρήνη, τὸ ὕδωρ ὡς οἱ Τροιζήνιοι λέγουσιν ἀνευρόντος Ἡρακλέους.", "st": "2.32"}, {"sp": "N", "t": "ἐν δὲ τῇ ἀκροπόλει τῆς Σθενιάδος καλουμένης ναός ἐστιν Ἀθηνᾶς, αὐτὸ δὲ εἰργάσατο τῆς θεοῦ τὸ ξόανον Κάλλων Αἰγινήτης· μαθητὴς δὲ ὁ Κάλλων ἦν Τεκταίου καὶ Ἀγγελίωνος, οἳ Δηλίοις ἐποίησαν τὸ ἄγαλμα τοῦ Ἀπόλλωνος· ὁ δὲ Ἀγγελίων καὶ Τεκταῖος παρὰ Διποίνῳ καὶ Σκύλλιδι ἐδιδάχθησαν.", "st": "2.32"}, {"sp": "N", "t": "κατιόντων δὲ αὐτόθεν Λυτηρίου Πανός ἐστιν ἱερόν· Τροιζηνίων γὰρ τοῖς τὰς ἀρχὰς ἔχουσιν ἔδειξεν ὀνείρατα ἃ εἶχεν ἄκεσιν λοιμοῦ πιέσαντος ⟨τὴν Τροιζηνίαν,⟩ Ἀθηναίους δὲ μάλιστα. διαβὰς δὲ καὶ [ἐς τὴν Τροιζηνίαν] ναὸν ⟨ἂν⟩ ἴδοις Ἴσιδος καὶ ὑπὲρ αὐτὸν Ἀφροδίτης Ἀκραίας· τὸν μὲν ἅτε ἐν μητροπόλει τῇ Τροιζῆνι Ἁλικαρνασσεῖς ἐποίησαν, τὸ δὲ ἄγαλμα τῆς Ἴσιδος ἀνέθηκε Τροιζηνίων δῆμος.", "st": "2.32"}, {"sp": "N", "t": "ἰοῦσι δὲ τὴν διὰ τῶν ὀρέων ἐς Ἑρμιόνην πηγή τέ ἐστι τοῦ Ὑλλικοῦ ποταμοῦ, Ταυρίου δὲ τὸ ἐξ ἀρχῆς καλουμένου, καὶ πέτρα Θησέως ὀνομαζομένη, μεταβαλοῦσα καὶ αὐτὴ τὸ ὄνομα ἀνελομένου Θησέως ὑπ’ αὐτῇ κρηπῖδας τὰς Αἰγέως καὶ ξίφος· πρότερον δὲ βωμὸς ἐκαλεῖτο Σθενίου Διός. τῆς δὲ πέτρας πλησίον Ἀφροδίτης ἐστὶν ἱερὸν Νυμφίας, ποιήσαντος Θησέως ἡνίκα ἔσχε γυναῖκα Ἑλένην.", "st": "2.32"}, {"sp": "N", "t": "ἔστι δὲ ἔξω τείχους καὶ Ποσειδῶνος ἱερὸν Φυταλμίου· μηνίσαντα γάρ σφισι τὸν Ποσειδῶνα ποιεῖν φασιν ἄκαρπον τὴν χώραν ἅλμης ἐς τὰ σπέρματα καὶ τῶν φυτῶν τὰς ῥίζας καθικνουμένης, ἐς ὃ θυσίαις τε εἴξας καὶ εὐχαῖς οὐκέτι ἅλμην ἀνῆκεν ἐς τὴν γῆν. ὑπὲρ δὲ τοῦ Ποσειδῶνος τὸν ναόν ἐστι Δημήτηρ Θεσμοφόρος, Ἀλθήπου καθὰ λέγουσιν ἱδρυσαμένου.", "st": "2.32"}, {"sp": "N", "t": "καταβαίνουσι δὲ ἐπὶ τὸν πρὸς τῇ Κελενδέρει καλουμένῃ λιμένα χωρίον ἐστὶν ὃ Γενέθλιον ὀνομάζουσι, τεχθῆναι Θησέα ἐνταῦθα λέγοντες. πρὸ δὲ τοῦ χωρίου τούτου ναός ἐστιν Ἄρεως, Θησέως καὶ ἐνταῦθα Ἀμαζόνας μάχῃ κρατήσαντος· αὗται δ’ ἂν εἴησαν τῶν ἐν τῇ Ἀττικῇ πρὸς Θησέα καὶ Ἀθηναίους ἀγωνισαμένων.", "st": "2.32"}, {"sp": "N", "t": "ἐπὶ θάλασσαν δὲ τὴν Ψιφαίαν πορευομένοις κότινος πέφυκεν ὀνομαζόμενος ῥᾶχος στρεπτός. ῥάχους μὲν δὴ καλοῦσι Τροιζήνιοι πᾶν ὅσον ἄκαρπον ἐλαίας, κότινον καὶ φυλλίαν καὶ ἔλαιον· στρεπτὸν δὲ ἐπονομάζουσι τοῦτον, ὅτι ἐνσχεθεισῶν αὐτῷ τῶν ἡνιῶν ἀνετράπη τοῦ Ἱππολύτου τὸ ἅρμα. τούτου δὲ οὐ πολὺ τῆς Σαρωνίας Ἀρτέμιδος ἀφέστηκε τὸ ἱερόν, καὶ τὰ ἐς αὐτὸ ἐμήνυσεν ὁ λόγος ἤδη μοι. τοσόνδε δὲ ἔτι δηλώσω· Σαρώνια γὰρ δὴ κατὰ ἔτος τῇ Ἀρτέμιδι ἑορτὴν ἄγουσι.", "st": "2.32"}, {"sp": "N", "t": "νῆσοι δέ εἰσι Τροιζηνίοις μία μὲν πλησίον τῆς ἠπείρου, καὶ διαβῆναι ποσὶν ἐς αὐτὴν ἔστιν· αὕτη Σφαιρία ὀνομαζομένη πρότερον Ἱερὰ δι’ αἰτίαν ἐκλήθη τοιαύτην. ἔστιν ἐν αὐτῇ Σφαίρου μνῆμα· Πέλοπος δὲ ἡνίοχον εἶναι λέγουσι τὸν Σφαῖρον. τούτῳ κατὰ δή τι ἐξ Ἀθηνᾶς ὄνειρον κομίζουσα Αἴθρα [ἐς] χοὰς διέβαινεν ἐς τὴν νῆσον, διαβάσῃ δὲ ἐνταῦθα λέγεται Ποσειδῶνα μιχθῆναι. ἱδρύσατο μὲν διὰ τοῦτο Αἴθρα ναὸν ἐνταῦθα Ἀθηνᾶς Ἀπατουρίας καὶ Ἱερὰν ἀντὶ Σφαιρίας ὠνόμασε τὴν νῆσον· κατεστήσατο δὲ καὶ ταῖς Τροιζηνίων παρθένοις ἀνατιθέναι πρὸ γάμου τὴν ζώνην τῇ Ἀθηνᾷ τῇ Ἀπατουρίᾳ.", "st": "2.33"}, {"sp": "N", "t": "Καλαύρειαν δὲ Ἀπόλλωνος ἱερὰν τὸ ἀρχαῖον εἶναι λέγουσιν, ὅτε περ ἦσαν καὶ οἱ Δελφοὶ Ποσειδῶνος· λέγεται δὲ καὶ τοῦτο, ἀντιδοῦναι τὰ χωρία σφᾶς ἀλλήλοις. φασὶ δὲ ἔτι καὶ λόγιον μνημονεύουσιν·<br>ἶσόν τοι Δῆλόν τε Καλαύρειάν τε νέμεσθαι<br>Πυθώ τ’ ἠγαθέην καὶ Ταίναρον ἠνεμόεσσαν.<br>ἔστι δ’ οὖν Ποσειδῶνος ἱερὸν ἐνταῦθα ἅγιον, ἱερᾶται δὲ αὐτῷ παρθένος, ἔστ’ ἂν ἐς ὥραν προέλθῃ γάμου.", "st": "2.33"}, {"sp": "N", "t": "τοῦ περιβόλου δὲ ἐντὸς καὶ τὸ Δημοσθένους μνῆμά ἐστι. καί μοι τὸ δαιμόνιον δεῖξαι μάλιστα ἐπὶ τούτου δοκεῖ καὶ Ὁμήρου πρότερον ὡς εἴη βάσκανον, εἰ δὴ Ὅμηρον μὲν προδιεφθαρμένον τοὺς ὀφθαλμοὺς ἐπὶ τοσούτῳ κακῷ κακὸν δεύτερον πενία πιέζουσα ἐπὶ πᾶσαν γῆν πτωχεύοντα ἦγε, Δημοσθένει δὲ φυγῆς τε συνέπεσεν ἐν γήρᾳ λαβεῖν πεῖραν καὶ ὁ θάνατος ἐγένετο οὕτω βίαιος. εἴρηται μὲν οὖν περὶ αὐτοῦ καὶ ἄλλοις καὶ αὐτῷ Δημοσθένει πλεῖστα, ἦ μὴν τῶν χρημάτων ἃ ἐκ τῆς Ἀσίας ἤγαγεν Ἅρπαλος μὴ μεταλαβεῖν αὐτόν·", "st": "2.33"}, {"sp": "N", "t": "τὸ δὲ ὕστερον λεχθὲν ἐπέξειμι ὁποῖον ἐγένετο. Ἅρπαλος μὲν ὡς ἐξ Ἀθηνῶν ἀπέδρα διαβὰς ναυσὶν ἐς Κρήτην, οὐ πολὺ ὕστερον ὑπὸ τῶν θεραπευόντων ἀπέθανεν οἰκετῶν· οἱ δὲ ὑπὸ ἀνδρὸς Μακεδόνος Παυσανίου δολοφονηθῆναί φασιν αὐτόν. τὸν δέ οἱ τῶν χρημάτων διοικητὴν φυγόντα ἐς Ῥόδον Φιλόξενος Μακεδὼν συνέλαβεν, ὃς καὶ αὐτὸν παρὰ Ἀθηναίων ἐξῄτησεν Ἅρπαλον. τὸν δὲ παῖδα τοῦτον ἔχων ἤλεγχεν ἐς ὃ πάντα ἐπύθετο, ὅσοι τῶν Ἁρπάλου τι ἔτυχον εἰληφότες·", "st": "2.33"}, {"sp": "N", "t": "μαθὼν δὲ ἐς Ἀθήνας γράμματα ἐπέστελλεν. ἐν τούτοις τοῖς γράμμασι τοὺς λαβόντας παρὰ Ἁρπάλου καταριθμῶν καὶ αὐτοὺς καὶ ὁπόσον αὐτῶν ἔλαβεν ἕκαστος οὐδὲ ἐμνημόνευσεν ἀρχὴν Δημοσθένους, Ἀλεξάνδρῳ τε ἐς τὰ μάλιστα ἀπεχθανομένου καὶ αὐτὸς ἰδίᾳ προσκρούσας. Δημοσθένει μὲν οὖν τιμαὶ καὶ ἑτέρωθι τῆς Ἑλλάδος καὶ παρὰ τῶν Καλαυρείας εἰσὶν οἰκητόρων·", "st": "2.33"}, {"sp": "N", "t": "τῆς δὲ Τροιζηνίας γῆς ἐστιν ἰσθμὸς ἐπὶ πολὺ διέχων ἐς θάλασσαν, ἐν δὲ αὐτῷ πόλισμα οὐ μέγα ἐπὶ θαλάσσῃ Μέθανα ᾤκισται. Ἴσιδος δὲ ἐνταῦθα ἱερόν ἐστι καὶ ἄγαλμα ἐπὶ τῆς ἀγορᾶς Ἑρμοῦ, τὸ δὲ ἕτερον Ἡρακλέους. τοῦ δὲ πολίσματος τριάκοντά που στάδια ἀπέχει θερμὰ λουτρά· φασὶ δὲ Ἀντιγόνου τοῦ Δημητρίου Μακεδόνων βασιλεύοντος τότε πρῶτον τὸ ὕδωρ φανῆναι, φανῆναι δὲ οὐχ ὕδωρ εὐθὺς ἀλλὰ πῦρ ἀναζέσαι πολὺ ἐκ τῆς γῆς, ἐπὶ δὲ τούτῳ μαρανθέντι ῥυῆναι τὸ ὕδωρ, ὃ δὴ καὶ ἐς ἡμᾶς ἄνεισι θερμόν τε καὶ δεινῶς ἁλμυρόν. λουσαμένῳ δὲ ἐνταῦθα οὔτε ὕδωρ ἐστὶν ἐγγὺς ψυχρὸν οὔτε ἐσπεσόντα ἐς τὴν θάλασσαν ἀκινδύνως νήχεσθαι· θηρία γὰρ καὶ ἄλλα καὶ κύνας παρέχεται πλείστους.", "st": "2.34"}, {"sp": "N", "t": "ὃ δὲ ἐθαύμασα ἐν τοῖς Μεθάνοις μάλιστα, γράψω καὶ τοῦτο. ἄνεμος ὁ Λὶψ βλαστανούσαις ταῖς ἀμπέλοις ἐμπίπτων ἐκ τοῦ Σαρωνικοῦ κόλπου τὴν βλάστην σφῶν ἀφαυαίνει· κατιόντος οὖν ἔτι τοῦ πνεύματος ἀλεκτρυόνα τὰ πτερὰ ἔχοντα διὰ παντὸς λευκὰ διελόντες ἄνδρες δύο ἐναντίοι περιθέουσι τὰς ἀμπέλους, ἥμισυ ἑκάτερος τοῦ ἀλεκτρυόνος φέρων· ἀφικόμενοι δ’ ἐς τὸ αὐτὸ ὅθεν ὡρμήθησαν, κατορύσσουσιν ἐνταῦθα.", "st": "2.34"}, {"sp": "N", "t": "τοῦτο μὲν πρὸς τὸν Λίβα σφίσιν ἐστὶν εὑρημένον· τὰς δὲ νησῖδας αἳ πρόκεινται τῆς χώρας ἀριθμὸν ἐννέα οὔσας Πέλοπος μὲν καλοῦσι, τοῦ θεοῦ δὲ ὕοντος μίαν ἐξ αὐτῶν οὔ φασιν ὕεσθαι. τοῦτο δὲ εἰ τοιοῦτόν ἐστιν οὐκ οἶδα, ἔλεγον δὲ οἱ περὶ τὰ Μέθανα, ἐπεὶ χάλαζάν γε ἤδη θυσίαις εἶδον καὶ ἐπῳδαῖς ἀνθρώπους ἀποτρέποντας.", "st": "2.34"}, {"sp": "N", "t": "τὰ μὲν δὴ Μέθανα ἰσθμός ἐστι τῆς Πελοποννήσου· ἐντὸς δὲ τοῦ ἰσθμοῦ τῆς Τροιζηνίων ὅμορός ἐστιν Ἑρμιόνη. οἰκιστὴν δὲ τῆς ἀρχαίας πόλεως Ἑρμιονεῖς γενέσθαι φασὶν Ἑρμίονα Εὔρωπος. τὸν δὲ Εὔρωπα —ἦν γὰρ δὴ Φορωνέως—Ἡροφάνης ὁ Τροιζήνιος ἔφασκεν εἶναι νόθον· οὐ γὰρ δή ποτε ἐς Ἄργον τὸν Νιόβης θυγατριδοῦν ὄντα Φορωνέως τὴν ἐν Ἄργει περιελθεῖν ⟨ἂν⟩ ἀρχὴν παρόντος Φορωνεῖ γνησίου παιδός.", "st": "2.34"}, {"sp": "N", "t": "ἐγὼ δέ, εἰ καὶ γνήσιον ὄντα Εὔρωπα πρότερον τὸ χρεὼν ἢ Φορωνέα ἐπέλαβεν, εὖ οἶδα ὡς οὐκ ἔμελλεν ὁ παῖς αὐτῷ Νιόβης παιδὶ ἴσα οἴσεσθαι Διός γε εἶναι δοκοῦντι. ἐπῴκησαν δὲ καὶ Ἑρμιόνα ὕστερον Δωριεῖς οἱ ἐξ Ἄργους· πόλεμον δὲ οὐ δοκῶ γενέσθαι σφίσιν, ἐλέγετο γὰρ ἂν ὑπὸ Ἀργείων.", "st": "2.34"}, {"sp": "N", "t": "ἔστι δὲ ὁδὸς ἔς Ἑρμιόνα ἐκ Τροιζῆνος κατὰ τὴν πέτραν ἣ πρότερον μὲν ἐκαλεῖτο Σθενίου Διὸς βωμός, μετὰ δὲ Θησέα ἀνελόμενον τὰ γνωρίσματα ὀνομάζουσιν οἱ νῦν Θησέως αὐτήν. κατὰ ταύτην οὖν τὴν πέτραν ἰοῦσιν ὀρεινὴν ὁδόν, ἔστι μὲν Ἀπόλλωνος ἐπίκλησιν Πλατανιστίου ναός, ἔστι δὲ Εἰλεοὶ χωρίον, ἐν δὲ αὐτῷ Δήμητρος καὶ Κόρης τῆς Δήμητρος ἱερά· τὰ δὲ πρὸς θάλασσαν ἐν ὅροις τῆς Ἑρμιονίδος ἱερὸν Δήμητρός ἐστιν ἐπίκλησιν Θερμασίας.", "st": "2.34"}, {"sp": "N", "t": "σταδίους δὲ ὀγδοήκοντα ἀπέχει μάλιστα ἄκρα Σκυλλαῖον ἀπὸ τῆς Νίσου καλουμένη θυγατρός. ὡς γὰρ δὴ τὴν Νίσαιαν ὁ Μίνως καὶ τὰ Μέγαρα εἷλεν ἐκείνης προδούσης, οὔτε γυναῖκα ἕξειν αὐτὴν ἔτι ἔφασκε καὶ προσέταξε τοῖς Κρησὶν ἐκβάλλειν τῆς νεώς· ἀποθανοῦσαν δὲ ἀπέρριψεν ἐς τὴν ἄκραν ταύτην ὁ κλύδων. τάφον δὲ οὐκ ἀποφαίνουσιν αὐτῆς, ἀλλὰ περιοφθῆναι τὸν νεκρόν φασι διαφορηθέντα ὑπὸ τῶν ἐκ θαλάσσης ὀρνίθων.", "st": "2.34"}, {"sp": "N", "t": "ἀπὸ δὲ Σκυλλαίου πλέοντι ὡς ἐπὶ τὴν πόλιν ἄκρα τέ ἐστιν ἑτέρα Βουκέφαλα καὶ μετὰ τὴν ἄκραν νῆσοι, πρώτη μὲν Ἁλιοῦσσα—παρέχεται δὲ αὕτη λιμένα ἐνορμίσασθαι ναυσὶν ἐπιτήδειον—, μετὰ δὲ Πιτυοῦσσα, τρίτη δὲ ἣν Ἀριστερὰν ὀνομάζουσι. ταύτας δὲ παραπλεύσαντί ἐστιν αὖθις ἄκρα Κωλυεργία ἀνέχουσα ἐκ τῆς ἠπείρου, μετὰ δὲ αὐτὴν νῆσος Τρίκρανα καλουμένη καὶ ὄρος ἐς θάλασσαν ἀπὸ τῆς Πελοποννήσου προβεβλημένον Βούπορθμος. ἐν Βουπόρθμῳ δὲ πεποίηται μὲν ἱερὸν Δήμητρος καὶ τῆς παιδός, πεποίηται δὲ Ἀθηνᾶς·", "st": "2.34"}, {"sp": "N", "t": "ἐπίκλησις δέ ἐστι τῇ θεῷ Προμαχόρμα. πρόκειται δὲ Βουπόρθμου νῆσος Ἀπεροπία καλουμένη, τῆς δὲ Ἀπεροπίας ἀφέστηκεν οὐ πολὺ ἑτέρα νῆσος Ὑδρέα. μετὰ ταύτην αἰγιαλός τε παρήκει τῆς ἠπείρου μηνοειδὴς καὶ ἀκτὴ μετὰ τὸν αἰγιαλὸν ἐπὶ Ποσείδιον, ἐκ θαλάσσης μὲν ἀρχομένη τῆς πρὸς ἀνατολάς, προήκουσα δὲ ὡς ἐπὶ τὴν ἑσπέραν· ἔχει δὲ καὶ λιμένας ἐν αὑτῇ. μῆκος μὲν δὴ τῆς ἀκτῆς ἐστιν ἑπτά που στάδια, πλάτος δὲ ᾗ πλατυτάτη σταδίων τριῶν οὐ πλέον.", "st": "2.34"}, {"sp": "N", "t": "ἐνταῦθα ἡ προτέρα πόλις τοῖς Ἑρμιονεῦσιν ἦν. ἔστι δέ σφισι καὶ νῦν ἔτι ἱερὰ αὐτόθι, Ποσειδῶνος μὲν ἐπὶ τῆς ἀκτῆς τῇ ἀρχῇ, προελθοῦσι δὲ ἀπὸ θαλάσσης ἐς τὰ μετέωρα ναὸς Ἀθηνᾶς, παρὰ δὲ αὐτῷ σταδίου θεμέλια· ἐν δὲ αὐτῷ τοὺς Τυνδάρεω παῖδας ἀγωνίσασθαι λέγουσιν. ἔστι δὲ καὶ ἕτερον οὐ μέγα τῆς Ἀθηνᾶς ἱερόν, ὁ δὲ ὄροφος κατερρύηκεν αὐτῷ. καὶ Ἡλίῳ ναὸς καὶ ἄλλος Χάρισιν, ὁ δὲ Σαράπιδι ᾠκοδόμηται καὶ Ἴσιδι· καὶ περίβολοι μεγάλων λίθων λογάδων εἰσίν, ἐντὸς δὲ αὐτῶν ἱερὰ δρῶσιν ἀπόρρητα Δήμητρι.", "st": "2.34"}, {"sp": "N", "t": "τοσαῦτα μὲν Ἑρμιονεῦσίν ἐστιν ἐνταῦθα· ἡ δὲ ἐφ’ ἡμῶν πόλις ἀπέχει μὲν τῆς ἄκρας, ἐφ’ ᾗ τοῦ Ποσειδῶνος τὸ ἱερόν, τέσσαρας μάλιστα σταδίους, κειμένη δὲ ἐν ὁμαλῷ τὰ πρῶτα ἠρέμα ἐς πρόσαντες ἄνεισι, τὸ δέ ἐστιν ἤδη τοῦ Πρωνός· Πρῶνα γὰρ τὸ ὄρος τοῦτο ὀνομάζουσι. τεῖχος μὲν δὴ περὶ πᾶσαν τὴν Ἑρμιόνα ἕστηκε· τὰ δὲ ἐς συγγραφὴν καὶ ἄλλα παρείχετο καὶ ὧν αὐτὸς ποιήσασθαι μάλιστα ἠξίωσα μνήμην. Ἀφροδίτης ναός ἐστιν ἐπίκλησιν Ποντίας καὶ Λιμενίας τῆς αὐτῆς, ἄγαλμα δὲ λευκοῦ λίθου μεγέθει τε μέγα καὶ ἐπὶ τῇ τέχνῃ θέας ἄξιον.", "st": "2.34"}, {"sp": "N", "t": "καὶ ναὸς ἕτερός ἐστιν Ἀφροδίτης· αὕτη καὶ ἄλλας ἔχει παρὰ Ἑρμιονέων τιμάς, καὶ ταῖς παρθένοις καὶ ἢν γυνὴ χηρεύουσα παρὰ ἄνδρα μέλλῃ φοιτᾶν, ἁπάσαις πρὸ γάμου θύειν καθέστηκεν ἐνταῦθα. Δήμητρος δὲ ἱερὰ πεποίηται Θερμασίας, τὸ μὲν ἐπὶ τοῖς πρὸς τὴν Τροιζηνίαν ὅροις, ὡς ἐστὶν εἰρημένον ἤδη μοι, τὸ δὲ καὶ ἐν αὐτῇ τῇ πόλει.", "st": "2.34"}, {"sp": "N", "t": "πλησίον δὲ αὐτοῦ Διονύσου ναὸς Μελαναίγιδος· τούτῳ μουσικῆς ἀγῶνα κατὰ ἔτος ἕκαστον ἄγουσι, καὶ ἁμίλλης κολύμβου καὶ πλοίων τιθέασιν ἆθλα· καὶ Ἀρτέμιδος ἐπίκλησιν Ἰφιγενείας ἐστὶν ἱερὸν καὶ Ποσειδῶν χαλκοῦς τὸν ἕτερον πόδα ἔχων ἐπὶ δελφῖνος. παρελθοῦσι δὲ ἐς τὸ τῆς Ἑστίας, ἄγαλμα μέν ἐστιν οὐδέν, βωμὸς δέ·", "st": "2.35"}, {"sp": "N", "t": "καὶ ἐπ’ αὐτοῦ θύουσιν Ἑστίᾳ. Ἀπόλλωνος δέ εἰσι ναοὶ τρεῖς καὶ ἀγάλματα τρία· καὶ τῷ μὲν οὐκ ἔστιν ἐπίκλησις, τὸν δὲ Πυθαέα [οὕτως] ὀνομάζουσι, καὶ Ὅριον τὸν τρίτον. τὸ μὲν δὴ τοῦ Πυθαέως ὄνομα μεμαθήκασι παρὰ Ἀργείων· τούτοις γὰρ Ἑλλήνων πρώτοις ἀφικέσθαι Τελέσιλλά φησι τὸν Πυθαέα ἐς τὴν χώραν Ἀπόλλωνος παῖδα ὄντα· τὸν δὲ Ὅριον ἐφ’ ὅτῳ καλοῦσιν, σαφῶς μὲν οὐκ ἂν ἔχοιμι εἰπεῖν, τεκμαίρομαι δὲ περὶ γῆς ὅρων πολέμῳ σφᾶς ἢ δίκῃ νικήσαντας ἐπὶ τῷδε τιμὰς Ἀπόλλωνι Ὁρίῳ νεῖμαι.", "st": "2.35"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τῆς Τύχης νεώτατον μὲν λέγουσιν Ἑρμιονεῖς τῶν παρά σφισιν εἶναι, λίθου δὲ Παρίου κολοσσὸς ἕστηκεν. κρήνας δὲ τὴν μὲν σφόδρα ἔχουσιν ἀρχαίαν, ἐς δὲ αὐτὴν οὐ φανερῶς τὸ ὕδωρ κάτεισιν, ἐπιλείποι δὲ οὐκ ἄν ποτε, οὐδ’ εἰ πάντες καταβάντες ὑδρεύοιντο ἐξ αὐτῆς· τὴν δὲ ἐφ’ ἡμῶν πεποιήκασιν, ὄνομα δέ ἐστιν τῷ χωρίῳ Λειμών, ὅθεν ῥεῖ τὸ ὕδωρ ἐς αὐτήν.", "st": "2.35"}, {"sp": "N", "t": "τὸ δὲ λόγου μάλιστα ἄξιον ἱερὸν Δήμητρός ἐστιν ἐπὶ τοῦ Πρωνός. τοῦτο τὸ ἱερὸν Ἑρμιονεῖς μὲν Κλύμενον Φορωνέως παῖδα καὶ ἀδελφὴν Κλυμένου Χθονίαν τοὺς ἱδρυσαμένους φασὶν εἶναι. Ἀργεῖοι δέ, ὅτε ἐς τὴν Ἀργολίδα ἦλθε Δημήτηρ, τότε Ἀθέραν μὲν λέγουσι καὶ Μύσιον ὡς ξενίαν παράσχοιεν τῇ θεῷ, Κολόνταν δὲ οὔτε οἴκῳ δέξασθαι τὴν θεὸν οὔτε ἀπονεῖμαί τι ἄλλο ἐς τιμήν· ταῦτα δὲ οὐ κατὰ γνώμην Χθονίᾳ τῇ θυγατρὶ ποιεῖν αὐτόν. Κολόνταν μὲν οὖν φασιν ἀντὶ τούτων συγκαταπρησθῆναι τῇ οἰκίᾳ, Χθονίαν δὲ κομισθεῖσαν ἐς Ἑρμιόνα ὑπὸ Δήμητρος Ἑρμιονεῦσι ποιῆσαι τὸ ἱερόν.", "st": "2.35"}, {"sp": "N", "t": "Χθονία δ’ οὖν ἡ θεός τε αὐτὴ καλεῖται καὶ Χθόνια ἑορτὴν κατὰ ἔτος ἄγουσιν ὥρᾳ θέρους, ἄγουσι δὲ οὕτως. ἡγοῦνται μὲν αὐτοῖς τῆς πομπῆς οἵ τε ἱερεῖς τῶν θεῶν καὶ ὅσοι τὰς ἐπετείους ἀρχὰς ἔχουσιν, ἕπονται δὲ καὶ γυναῖκες καὶ ἄνδρες. τοῖς δὲ καὶ παισὶν ἔτι οὖσι καθέστηκεν ἤδη τὴν θεὸν τιμᾶν τῇ πομπῇ· οὗτοι λευκὴν ἐσθῆτα καὶ ἐπὶ ταῖς κεφαλαῖς ἔχουσι στεφάνους. πλέκονται δὲ οἱ στέφανοί σφισιν ἐκ τοῦ ἄνθους ὃ καλοῦσιν οἱ ταύτῃ κοσμοσάνδαλον, ὑάκινθον ἐμοὶ δοκεῖν ὄντα καὶ μεγέθει καὶ χρόᾳ· ἔπεστι δέ οἱ καὶ τὰ ἐπὶ τῷ θρήνῳ γράμματα.", "st": "2.35"}, {"sp": "N", "t": "τοῖς δὲ τὴν πομπὴν πέμπουσιν ἕπονται τελείαν ἐξ ἀγέλης βοῦν ἄγοντες διειλημμένην δεσμοῖς τε καὶ ὑβρίζουσαν ἔτι ὑπὸ ἀγριότητος. ἐλάσαντες δὲ πρὸς τὸν ναὸν οἱ μὲν ἔσω φέρεσθαι τὴν βοῦν ἐς τὸ ἱερὸν ἀνῆκαν ἐκ τῶν δεσμῶν, ἕτεροι δὲ ἀναπεπταμένας ἔχοντες τέως τὰς θύρας, ἐπειδὰν τὴν βοῦν ἴδωσιν ἐντὸς τοῦ ναοῦ, προσέθεσαν τὰς θύρας.", "st": "2.35"}, {"sp": "N", "t": "τέσσαρες δὲ ἔνδον ὑπολειπόμεναι γρᾶες, αὗται τὴν βοῦν εἰσιν αἱ κατεργαζόμεναι· δρεπάνῳ γὰρ ἥτις ἂν τύχῃ τὴν φάρυγγα ὑπέτεμε τῆς βοός. μετὰ δὲ αἱ θύραι τε ἠνοίχθησαν καὶ προσελαύνουσιν οἷς ἐπιτέτακται βοῦν [δὲ] δευτέραν καὶ τρίτην ἐπὶ ταύτῃ καὶ ἄλλην τετάρτην. κατεργάζονταί τε δὴ πάσας κατὰ ταὐτὰ αἱ γρᾶες καὶ τόδε ἄλλο πρόσκειται τῇ θυσίᾳ θαῦμα· ἐφ’ ἥντινα γὰρ ἂν πέσῃ τῶν πλευρῶν ἡ πρώτη βοῦς, ἀνάγκη πεσεῖν καὶ πάσας.", "st": "2.35"}, {"sp": "N", "t": "θυσία μὲν δρᾶται τοῖς Ἑρμιονεῦσι τὸν εἰρημένον τρόπον· πρὸ δὲ τοῦ ναοῦ γυναικῶν ἱερασαμένων τῇ Δήμητρι εἰκόνες ἑστήκασιν οὐ πολλαί, καὶ παρελθόντι ἔσω θρόνοι τέ εἰσιν, ἐφ’ ὧν αἱ γρᾶες ἀναμένουσιν ἐσελαθῆναι καθ’ ἑκάστην τῶν βοῶν, καὶ ἀγάλματα οὐκ ἄγαν ἀρχαῖα Ἀθηνᾶ καὶ Δημήτηρ. αὐτὸ δὲ ὃ σέβουσιν ἐπὶ πλέον ἢ τἄλλα, ἐγὼ μὲν οὐκ εἶδον, οὐ μὴν οὐδὲ ἀνὴρ ἄλλος οὔτε ξένος οὔτε Ἑρμιονέων αὐτῶν· μόναι δὲ ὁποῖόν τί ἐστιν αἱ γρᾶες ἴστωσαν.", "st": "2.35"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος ναός· εἰκόνες δὲ περὶ πάντα ἑστήκασιν αὐτόν. οὗτος ὁ ναός ἐστιν ἀπαντικρὺ τοῦ τῆς Χθονίας, καλεῖται δὲ Κλυμένου, καὶ τῷ Κλυμένῳ θύουσιν ἐνταῦθα. Κλύμενον δὲ οὐκ ἄνδρα Ἀργεῖον ἐλθεῖν ἔγωγε ἐς Ἑρμιόνα ἡγοῦμαι, τοῦ θεοῦ δέ ἐστιν ἐπίκλησις, ὅντινα ἔχει λόγος βασιλέα ὑπὸ γῆν εἶναι.", "st": "2.35"}, {"sp": "N", "t": "παρὰ μὲν δὴ τοῦτόν ἐστιν ἄλλος ναὸς καὶ ἄγαλμα Ἄρεως, τοῦ δὲ τῆς Χθονίας ἐστὶν ἱεροῦ στοὰ κατὰ τὴν δεξιάν, Ἠχοῦς ὑπὸ τῶν ἐπιχωρίων καλουμένη· φθεγξαμένῳ δὲ ἀνδρὶ τὰ ὀλίγιστα ἐς τρὶς ἀντιβοῆσαι πέφυκεν. ὄπισθεν δὲ τοῦ ναοῦ τῆς Χθονίας χωρία ἐστὶν ἃ καλοῦσιν Ἑρμιονεῖς τὸ μὲν Κλυμένου, τὸ δὲ Πλούτωνος, τὸ τρίτον δὲ αὐτῶν λίμνην Ἀχερουσίαν. περιείργεται μὲν δὴ πάντα θριγκοῖς λίθων, ἐν δὲ τῷ τοῦ Κλυμένου καὶ γῆς χάσμα· διὰ τούτου δὲ Ἡρακλῆς ἀνῆγε τοῦ Ἅιδου τὸν κύνα κατὰ τὰ λεγόμενα ὑπὸ Ἑρμιονέων.", "st": "2.35"}, {"sp": "N", "t": "πρὸς δὲ τῇ πύλῃ, καθ’ ἣν ὁδὸς εὐθεῖά ἐστιν ἄγουσα ἐπὶ Μάσητα, Εἰλειθυίας ἐστὶν ἐντὸς τοῦ τείχους ἱερόν. ἄλλως μὲν δὴ κατὰ ἡμέραν ἑκάστην καὶ θυσίαις καὶ θυμιάμασι μεγάλως τὴν θεὸν ἱλάσκονται καὶ ἀναθήματα δίδοται πλεῖστα τῇ Εἰλειθυίᾳ· τὸ δὲ ἄγαλμα οὐδενὶ πλὴν εἰ μὴ ἄρα ταῖς ἱερείαις ἔστιν ἰδεῖν.", "st": "2.35"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐπὶ Μάσητα εὐθεῖαν προελθοῦσιν ἑπτά που σταδίους καὶ ἐς ἀριστερὰν ἐκτραπεῖσιν, ἐς Ἁλίκην ἐστὶν ὁδός. ἡ δὲ Ἁλίκη τὰ μὲν ἐφ’ ἡμῶν ἐστιν ἔρημος, ᾠκεῖτο δὲ καὶ αὕτη ποτέ, καὶ Ἁλικῶν λόγος ἐν στήλαις ἐστὶ ταῖς Ἐπιδαυρίων αἳ τοῦ Ἀσκληπιοῦ τὰ ἰάματα ἐγγεγραμμένα ἔχουσιν· ἄλλο δὲ σύγγραμμα οὐδὲν οἶδα ἀξιόχρεων, ἔνθα ἢ πόλεως Ἁλίκης ἢ ἀνδρῶν ἐστιν Ἁλικῶν μνήμη. ἔστι δ’ οὖν ὁδὸς καὶ ἐς ταύτην, τοῦ τε Πρωνὸς μέση καὶ ὄρους ἑτέρου Θόρνακος καλουμένου τὸ ἀρχαῖον· ἀπὸ δὲ τῆς Διὸς ἐς κόκκυγα τὸν ὄρνιθα ἀλλαγῆς λεγομένης ἐνταῦθα γενέσθαι μετονομασθῆναι τὸ ὄρος φασίν.", "st": "2.36"}, {"sp": "N", "t": "ἱερὰ δὲ καὶ ἐς τόδε ἐπὶ ἄκρων τῶν ὀρῶν, ἐπὶ μὲν τῷ Κοκκυγίῳ Διός, ἐν δὲ τῷ Πρωνί ἐστιν Ἥρας· καὶ τοῦ γε Κοκκυγίου πρὸς τοῖς πέρασι ναός ἐστι, θύραι δὲ οὐκ ἐφεστήκασιν οὐδὲ ὄροφον εἶχεν οὐδέ οἵ τι ἐνῆν ἄγαλμα· εἶναι δὲ ἐλέγετο ὁ ναὸς Ἀπόλλωνος. παρὰ δὲ αὐτὸν ὁδός ἐστιν ἐπὶ Μάσητα τοῖς ἐκτραπεῖσιν ἐκ τῆς εὐθείας. Μάσητι δὲ οὔσῃ πόλει τὸ ἀρχαῖον, καθὰ καὶ Ὅμηρος ἐν Ἀργείων καταλόγῳ πεποίηκεν, ἐπινείῳ καθ’ ἡμᾶς ἐχρῶντο Ἑρμιονεῖς.", "st": "2.36"}, {"sp": "N", "t": "ἀπὸ Μάσητος δὲ ὁδὸς ἐν δεξιᾷ ἐστιν ἐπὶ ἄκραν καλουμένην Στρουθοῦντα. στάδιοι δὲ ἀπὸ τῆς ἄκρας ταύτης κατὰ τῶν ὀρῶν τὰς κορυφὰς πεντήκοντά εἰσι καὶ διακόσιοι ἐς Φιλανόριόν τε καλούμενον καὶ ἐπὶ Βολεούς· οἱ δὲ Βολεοὶ οὗτοι λίθων εἰσὶ σωροὶ λογάδων. χωρίον δὲ ἕτερον, ὃ Διδύμους ὀνομάζουσι, στάδια εἴκοσιν αὐτόθεν ἀφέστηκεν· ἐνταῦθα ἔστι μὲν ἱερὸν Ἀπόλλωνος, ἔστι δὲ Ποσειδῶνος, ἐπὶ δὲ αὐτοῖς Δήμητρος, ἀγάλματα δὲ ὀρθὰ λίθου λευκοῦ.", "st": "2.36"}, {"sp": "N", "t": "τὸ δὲ ἐντεῦθέν ἐστιν Ἀργείων ἥ ποτε Ἀσιναία καλουμένη, καὶ Ἀσίνης ἐστὶν ἐρείπια ἐπὶ θαλάσσῃ. Λακεδαιμονίων δὲ καὶ τοῦ βασιλέως Νικάνδρου τοῦ Χαρίλλου τοῦ Πολυδέκτου τοῦ Εὐνόμου τοῦ Πρυτάνιδος τοῦ Εὐρυπῶντος ἐς τὴν Ἀργολίδα ἐσβαλόντων στρατιᾷ συνεσέβαλόν σφισιν οἱ Ἀσιναῖοι, καὶ ἐδῄωσαν σὺν ἐκείνοις τῶν Ἀργείων τὴν γῆν. ὡς δὲ ὁ στόλος τῶν Λακεδαιμονίων ἀπῆλθεν οἴκαδε, στρατεύουσιν ἐπὶ τὴν Ἀσίνην οἱ Ἀργεῖοι καὶ ὁ βασιλεὺς αὐτῶν Ἔρατος.", "st": "2.36"}, {"sp": "N", "t": "καὶ χρόνον μέν τινα ἀπὸ τοῦ τείχους ἠμύναντο οἱ Ἀσιναῖοι καὶ ἀποκτείνουσιν ἄλλους τε καὶ Λυσίστρατον ἐν τοῖς δοκιμωτάτοις ὄντα Ἀργείων· ἁλισκομένου δὲ τοῦ τείχους οὗτοι μὲν γυναῖκας ἐς τὰ πλοῖα ἐνθέμενοι καὶ παῖδας ἐκλείπουσι τὴν αὑτῶν, Ἀργεῖοι δὲ ἐς ἔδαφος καταβαλόντες τὴν Ἀσίνην καὶ τὴν γῆν προσορισάμενοι τῇ σφετέρᾳ Πυθαέως τε Ἀπόλλωνος ὑπελίποντο ⟨τὸ⟩ ἱερὸν—καὶ νῦν ἔτι δῆλόν ἐστι—καὶ τὸν Λυσίστρατον πρὸς αὐτῷ θάπτουσιν.", "st": "2.36"}, {"sp": "N", "t": "ἀπέχει δὲ Ἀργείων τῆς πόλεως τεσσαράκοντα καὶ οὐ πλείω στάδια ἡ κατὰ Λέρναν θάλασσα. κατιόντων δὲ ἐς Λέρναν πρῶτον μὲν καθ’ ὁδόν ἐστιν ὁ Ἐρασῖνος, ἐκδίδωσι δὲ ἐς τὸν Φρίξον, ὁ Φρίξος δὲ ἐς τὴν θάλασσαν τὴν μεταξὺ Τημενίου καὶ Λέρνης. ἀπὸ δὲ Ἐρασίνου τραπεῖσιν ἐς ἀριστερὰ σταδίους ὅσον ὀκτώ, Διοσκούρων ἱερόν ἐστιν Ἀνάκτων· πεποίηται δέ σφισι κατὰ ταὐτὰ καὶ ἐν τῇ πόλει τὰ ξόανα.", "st": "2.36"}, {"sp": "N", "t": "ἀναστρέψας δὲ ἐς τὴν εὐθεῖαν τόν τε Ἐρασῖνον διαβήσῃ καὶ ἐπὶ τὸν Χείμαρρον ποταμὸν ἀφίξῃ. πλησίον δὲ αὐτοῦ περίβολός ἐστι λίθων, καὶ τὸν Πλούτωνα ἁρπάσαντα ὡς λέγεται Κόρην τὴν Δήμητρος καταβῆναι ταύτῃ φασὶν ἐς τὴν ὑπόγεων νομιζομένην ἀρχήν. ἡ δὲ Λέρνα ἐστίν, ὡς καὶ τὰ πρότερα ἔχει μοι τοῦ λόγου, πρὸς θαλάσσῃ, καὶ τελετὴν Λερναίᾳ ἄγουσιν ἐνταῦθα Δήμητρι.", "st": "2.36"}, {"sp": "N", "t": "ἔστι δὲ ἄλσος ἱερὸν ἀρχόμενον μὲν ἀπὸ ὄρους ὃ καλοῦσι Ποντῖνον, τὸ δὲ ὄρος ὁ Ποντῖνος οὐκ ἐᾷ τὸ ὕδωρ ἀπορρεῖν τὸ ἐκ τοῦ θεοῦ, ἀλλὰ ἐς αὑτὸ καταδέχεται· ῥεῖ δὲ καὶ ποταμὸς ἀπ’ αὐτοῦ Ποντῖνος. καὶ ἐπὶ κορυφῇ τοῦ ὄρους ἱερόν τε Ἀθηνᾶς Σαΐτιδος, ἐρείπια ἔτι μόνα, καὶ θεμέλια οἰκίας ἐστὶν Ἱππομέδοντος, ὃς Πολυνείκει τῷ Οἰδίποδος τιμωρήσων ἦλθεν ἐς Θήβας.", "st": "2.36"}, {"sp": "N", "t": "ἀπὸ δὴ τοῦ ὄρους τούτου τὸ ἄλσος ἀρχόμενον πλατάνων τὸ πολὺ ἐπὶ τὴν θάλασσαν καθήκει. ὅροι δὲ αὐτοῦ τῇ μὲν ποταμὸς ὁ Ποντῖνος, τῇ δὲ ἕτερος ποταμός· Ἀμυμώνη δὲ ἀπὸ τῆς Δαναοῦ θυγατρὸς ὄνομα τῷ ποταμῷ. ἐντὸς δὲ τοῦ ἄλσους ἀγάλματα ἔστι μὲν Δήμητρος Προσύμνης, ἔστι δὲ Διονύσου, καὶ Δήμητρος καθήμενον ἄγαλμα οὐ μέγα·", "st": "2.37"}, {"sp": "N", "t": "ταῦτα μὲν λίθου πεποιημένα, ἑτέρωθι δ’ ἐν ναῷ Διόνυσος Σαώτης καθήμενον ξόανον καὶ Ἀφροδίτης ἄγαλμα ἐπὶ θαλάσσῃ λίθου· ἀναθεῖναι δὲ αὐτὸ τὰς θυγατέρας λέγουσι τὰς Δαναοῦ, Δαναὸν δὲ αὐτὸν τὸ ἱερὸν ἐπὶ Ποντίνῳ ποιῆσαι τῆς Ἀθηνᾶς. καταστήσασθαι δὲ τῶν Λερναίων τὴν τελετὴν Φιλάμμωνά φασι. τὰ μὲν οὖν λεγόμενα ἐπὶ τοῖς δρωμένοις δῆλά ἐστιν οὐκ ὄντα ἀρχαῖα·", "st": "2.37"}, {"sp": "N", "t": "ἃ δὲ ἤκουσα ἐπὶ τῇ καρδίᾳ γεγράφθαι τῇ πεποιημένῃ τοῦ ὀρειχάλκου, οὐδὲ ταῦτα ὄντα Φιλάμμωνος Ἀρριφῶν εὗρε, τὸ μὲν ἀνέκαθεν Τρικωνιεὺς τῶν ἐν Αἰτωλίᾳ, τὰ δὲ ἐφ’ ἡμῶν Λυκίων τοῖς μάλιστα ὁμοίως δόκιμος, δεινὸς δὲ ἐξευρεῖν ἃ μή τις πρότερον εἶδε, καὶ δὴ καὶ ταῦτα φωράσας ἐπὶ τῷδε. τὰ ἔπη, καὶ ὅσα οὐ μετὰ μέτρου μεμιγμένα ἦν τοῖς ἔπεσι, τὰ πάντα Δωριστὶ ἐπεποίητο· πρὶν δὲ Ἡρακλείδας κατελθεῖν ἐς Πελοπόννησον, τὴν αὐτὴν ἠφίεσαν Ἀθηναίοις οἱ Ἀργεῖοι φωνήν· ἐπὶ δὲ Φιλάμμωνος οὐδὲ τὸ ὄνομα τῶν Δωριέων ἐμοὶ δοκεῖν ἐς ἅπαντας ἠκούετο Ἕλληνας.", "st": "2.37"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἀπέφαινεν οὕτως ἔχοντα, τῆς δὲ Ἀμυμώνης πέφυκεν ἐπὶ τῇ πηγῇ πλάτανος· ὑπὸ ταύτῃ τὴν ὕδραν τραφῆναι τῇ πλατάνῳ φασίν. ἐγὼ δὲ τὸ θηρίον πείθομαι τοῦτο καὶ μεγέθει διενεγκεῖν ὑδρῶν ἄλλων καὶ τὸν ἰὸν οὕτω δή τι ἔχειν ἀνίατον ὡς τὸν Ἡρακλέα ἀπὸ τῆς χολῆς αὐτοῦ τὰς ἀκίδας φαρμακεῦσαι τῶν ὀιστῶν· κεφαλὴν δὲ εἶχεν ἐμοὶ δοκεῖν μίαν καὶ οὐ πλείονας, Πείσανδρος δὲ ὁ Καμιρεύς, ἵνα τὸ θηρίον τε δοκοίη φοβερώτερον καὶ αὐτῷ γίνηται ἡ ποίησις ἀξιόχρεως μᾶλλον, ἀντὶ τούτων τὰς κεφαλὰς ἐποίησε τῇ ὕδρᾳ τὰς πολλάς.", "st": "2.37"}, {"sp": "N", "t": "εἶδον δὲ καὶ πηγὴν Ἀμφιαράου καλουμένην καὶ τὴν Ἀλκυονίαν λίμνην, δι’ ἧς φασιν Ἀργεῖοι Διόνυσον ἐς τὸν Ἅιδην ἐλθεῖν Σεμέλην ἀνάξοντα, τὴν δὲ ταύτῃ κάθοδον δεῖξαί οἱ Πόλυμνον. τῇ δὲ Ἀλκυονίᾳ πέρας τοῦ βάθους οὐκ ἔστιν οὐδέ τινα οἶδα ἄνθρωπον ἐς τὸ τέρμα αὐτῆς οὐδεμιᾷ μηχανῇ καθικέσθαι δυνηθέντα, ὅπου καὶ Νέρων σταδίων πολλῶν κάλους ποιησάμενος καὶ συνάψας ἀλλήλοις, ἀπαρτήσας δὲ καὶ μόλυβδον ἀπ’ αὐτῶν καὶ εἰ δή τι χρήσιμον ἄλλο ἐς τὴν πεῖραν, οὐδὲ οὗτος οὐδένα ἐξευρεῖν ἐδυνήθη ὅρον τοῦ βάθους.", "st": "2.37"}, {"sp": "N", "t": "καὶ τόδε ἤκουσα ἄλλο· τὸ ὕδωρ τῆς λίμνης ὡς ἰδόντα εἰκάσαι γαληνόν ἐστι καὶ ἠρεμαῖον, παρεχόμενον δὲ ὄψιν τοιαύτην διανήχεσθαι τολμήσαντα πάντα τινὰ καθέλκειν πέφυκε καὶ ἐς βυθὸν ὑπολαβὸν ἀπήνεγκε. περίοδος δὲ τῆς λίμνης ἐστὶν οὐ πολλή, ἀλλὰ ὅσον τε σταδίου τρίτον· ἐπὶ δὲ τοῖς χείλεσιν αὐτῆς πόα καὶ σχοῖνοι πεφύκασι. τὰ δὲ ἐς αὐτὴν Διονύσῳ δρώμενα ἐν νυκτὶ κατὰ ἔτος ἕκαστον οὐχ ὅσιον ἐς ἅπαντας ἦν μοι γράψαι.", "st": "2.37"}, {"sp": "N", "t": "ἐκ Λέρνης δὲ ἰοῦσιν ἐς Τημένιον—τὸ δὲ Τημένιόν ἐστιν Ἀργείων, ὠνομάσθη δὲ ἀπὸ Τημένου τοῦ Ἀριστομάχου· καταλαβὼν γὰρ καὶ ἐχυρωσάμενος τὸ χωρίον ἐπολέμει σὺν τοῖς Δωριεῦσιν αὐτόθεν τὸν πρὸς Τισαμενὸν καὶ Ἀχαιοὺς πόλεμον—ἐς τοῦτο οὖν τὸ Τημένιον ἰοῦσιν ὅ τε Φρίξος ποταμὸς ἐκδίδωσιν ἐς θάλασσαν καὶ Ποσειδῶνος ἱερὸν ἐν Τημενίῳ πεποίηται καὶ Ἀφροδίτης ἕτερον καὶ μνῆμά ἐστι Τημένου τιμὰς ἔχον παρὰ Δωριέων τῶν ἐν Ἄργει.", "st": "2.38"}, {"sp": "N", "t": "Τημενίου δὲ ἀπέχει Ναυπλία πεντήκοντα ἐμοὶ δοκεῖν σταδίους, τὰ μὲν ἐφ’ ἡμῶν ἔρημος, οἰκιστὴς δὲ ἐγένετο αὐτῆς Ναύπλιος Ποσειδῶνος λεγόμενος καὶ Ἀμυμώνης εἶναι. λείπεται δὲ καὶ τειχῶν ἔτι ἐρείπια, καὶ Ποσειδῶνος ἱερὸν καὶ λιμένες εἰσὶν ἐν Ναυπλίᾳ καὶ πηγὴ Κάναθος καλουμένη· ἐνταῦθα τὴν Ἥραν φασὶν Ἀργεῖοι κατὰ ἔτος λουμένην παρθένον γίνεσθαι.", "st": "2.38"}, {"sp": "N", "t": "οὗτος μὲν δή σφισιν ἐκ τελετῆς, ἣν ἄγουσι τῇ Ἥρᾳ, λόγος τῶν ἀπορρήτων ἐστίν· τὰ δὲ ὑπὸ τῶν ἐν Ναυπλίᾳ λεγόμενα ἐς τὸν ὄνον, ὡς ἐπιφαγὼν ἀμπέλου κλῆμα ἀφθονώτερον ἐς τὸ μέλλον ἀπέφηνε τὸν καρπόν—καὶ ὄνος σφίσιν ἐν πέτρᾳ πεποιημένος διὰ τοῦτό ἐστιν ἅτε ἀμπέλων διδάξας τομήν—, παρίημι οὐκ ἀξιόλογα ἡγούμενος.", "st": "2.38"}, {"sp": "N", "t": "ἔστι δὲ ἐκ Λέρνης καὶ ἑτέρα παρ’ αὐτὴν ὁδὸς τὴν θάλασσαν ἐπὶ χωρίον ὃ Γενέσιον ὀνομάζουσι· πρὸς θαλάσσῃ δὲ τοῦ Γενεσίου Ποσειδῶνος ἱερόν ἐστιν οὐ μέγα. τούτου δ’ ἔχεται χωρίον ἄλλο Ἀπόβαθμοι· γῆς δὲ ἐνταῦθα πρῶτον τῆς Ἀργολίδος Δαναὸν σὺν ταῖς παισὶν ἀποβῆναι λέγουσιν. ἐντεῦθεν διελθοῦσιν Ἀνιγραῖα καλούμενα ὁδὸν καὶ στενὴν καὶ ἄλλως δύσβατον, ἔστιν ἐν ἀριστερᾷ μὲν καθήκουσα ἐπὶ θάλασσαν καὶ δένδρα—ἐλαίας μάλιστα—ἀγαθὴ τρέφειν γῆ, ἰόντι", "st": "2.38"}, {"sp": "N", "t": "δὲ ἄνω πρὸς τὴν ἤπειρον ⟨ἀπ’⟩ αὐτῆς χωρίον ἐστίν, ἔνθα δὴ ἐμαχέσαντο ὑπὲρ τῆς γῆς ταύτης λογάδες Ἀργείων τριακόσιοι πρὸς ἄνδρας Λακεδαιμονίων ἀριθμόν τε ἴσους καὶ ἐπιλέκτους ὁμοίως. ἀποθανόντων δὲ ἁπάντων πλὴν ἑνὸς Σπαρτιάτου καὶ δυοῖν Ἀργείων, τοῖς μὲν ἀποθανοῦσιν ἐχώσθησαν ἐνταῦθα οἱ τάφοι, τὴν χώραν δὲ οἱ Λακεδαιμόνιοι γενομένου πανδημεί σφισιν ἀγῶνος πρὸς Ἀργείους κρατήσαντες βεβαίως αὐτοί τε παραυτίκα ἐκαρποῦντο καὶ ὕστερον Αἰγινήταις ἔδοσαν ἐκπεσοῦσιν ὑπὸ Ἀθηναίων ἐκ τῆς νήσου. τὰ δὲ ἐπ’ ἐμοῦ τὴν Θυρεᾶτιν ἐνέμοντο Ἀργεῖοι· φασὶ δὲ ἀνασώσασθαι δίκῃ νικήσαντες.", "st": "2.38"}, {"sp": "N", "t": "ἀπὸ δὲ τῶν πολυανδρίων ἰόντι Ἀ⟨ν⟩θήνη τέ ἐστιν, [ἐς] ἣν Αἰγινῆταί ποτε ᾤκησαν, καὶ ἑτέρα κώμη Νηρίς, τρίτη δὲ Εὔα μεγίστη τῶν κωμῶν· καὶ ἱερὸν τοῦ Πολεμοκράτους ἐστὶν ἐν ταύτῃ. ὁ δὲ Πολεμοκράτης ἐστὶ καὶ οὗτος Μαχάονος υἱός, ἀδελφὸς δὲ Ἀλεξάνορος, καὶ ἰᾶται τοὺς ταύτῃ καὶ τιμὰς παρὰ τῶν προσοίκων ἔχει.", "st": "2.38"}, {"sp": "N", "t": "ἀνατείνει δὲ ὑπὲρ τὰς κώμας ὄρος Πάρνων, καὶ Λακεδαιμονίων ἐπ’ αὐτοῦ πρὸς Ἀργείους ὅροι καὶ Τεγεάτας εἰσίν· ἑστήκασι δὲ ἐπὶ τοῖς ὅροις Ἑρμαῖ λίθου, καὶ τοῦ χωρίου τὸ ὄνομά ἐστιν ἀπ’ αὐτῶν. ποταμὸς δὲ καλούμενος Τάναος—εἷς γὰρ δὴ οὗτος ἐκ τοῦ Πάρνωνος κάτεισι—ῥέων διὰ τῆς Ἀργείας [καὶ] ἐκδίδωσιν ἐς τὸν Θυρεάτην κόλπον.", "st": "2.38"}], []);})();
